/* Guía de Rumi en pt. La arma modelo/armar_guia_idiomas.js. */
window.RUMI_GUIA=[{"t":"Acidose","x":"Acontece quando comem muito grão de uma vez. Sinais: o consumo cai, diarreia com cheiro ácido, mancadeiras e animais abatidos. Para evitar: adapte ao concentrado em 2 a 3 semanas, mantenha pelo menos 8 a 10 % de forragem, sirva sempre no mesmo horário e não deixe o cocho vazio por horas. Se vir vários casos, chame seu veterinário.","a":"sanidad"},{"t":"Timpanismo","x":"O rúmen incha do lado esquerdo por gás ou espuma. Costuma vir de grãos moídos muito finos ou mudanças bruscas. Moa o grão mais grosso, dê fibra e mude a dieta aos poucos. Um animal inchado e com dificuldade para respirar é uma urgência: chame o veterinário imediatamente.","a":"sanidad"},{"t":"Pneumonia ou febre do transporte","x":"É a doença mais comum nas primeiras 2 a 4 semanas depois da chegada. Sinais: tosse, muco no nariz, orelhas caídas, respiração rápida e não comem. Ajuda: transporte curto e tranquilo, água e feno na chegada, currais ventilados e sem poeira, e revisar os animais duas vezes ao dia. Trate cedo com indicação do seu veterinário.","a":"sanidad"},{"t":"Recepção de animais novos","x":"Na chegada: água limpa e feno de boa qualidade, descanso de 12 a 24 horas antes de manejá-los, depois pesar, identificar, vacinar e vermifugar. Comece com uma ração alta em forragem e adapte ao concentrado aos poucos. Observe-os de manhã e à tarde nas primeiras três semanas.","a":"manejo"},{"t":"Calor","x":"O calor baixa o consumo e o ganho. Dê sombra de 2 a 4 m² por animal, água fresca à vontade e sirva mais alimento nas horas frescas, cedo e no fim da tarde. Não os maneje ao meio-dia. No menu do Rumi, Calculadoras, Índice de calor, eu digo o risco com sua temperatura e umidade.","a":"manejo"},{"t":"Água","x":"Um novilho bebe de 30 a 60 litros por dia, mais com calor. Limpe os bebedouros toda semana e deixe uns 30 cm de bebedouro para cada 10 animais. Se bebem pouca água, comem pouco.","a":"nutricion"},{"t":"Ureia","x":"Fornece proteína barata, mas com cuidado: não mais de 1 % da matéria seca da dieta, bem misturada e nunca na água. Introduza aos poucos. Se vir tremores, babeira ou cambaleio depois de comer, pode ser intoxicação: chame o veterinário imediatamente.","a":"nutricion"},{"t":"Armazenar alimento","x":"Guarde o grão seco, sobre paletes e longe da parede. Não use milho com mofo: as aflatoxinas baixam o ganho e adoecem. Use primeiro o que entrou primeiro.","a":"nutricion"},{"t":"Silagem","x":"Corte o milho com o grão leitoso a pastoso, pique fino, compacte muito bem e cubra sem ar. Ao abrir, retire uma face uniforme a cada dia e descarte o podre ou com mofo.","a":"nutricion"},{"t":"Implantes","x":"Aumentam o ganho, mas revise a regulação do seu país e o que seu comprador aceita: alguns mercados não os permitem. Registre sempre produto e data em Sanidade.","a":"sanidad"},{"t":"Peso de entrada","x":"No confinamento em curral o comum é comprar entre 250 e 350 kg. Mais leves demoram mais e convertem melhor; mais pesados saem rápido, mas comem mais por dia. Compare com o preço: no menu do Rumi, Dinheiro e vendas, Preço máximo de compra.","a":"negocio"},{"t":"Quebra no transporte","x":"Na viagem perdem de 3 a 8 % do peso, conforme as horas e o calor. Pese depois que descansarem e beberem água, ou desconte essa quebra. Transporte nas horas frescas e sem sobrecarregar o caminhão.","a":"manejo"},{"t":"A cada quanto pesar","x":"A cada 21 a 28 dias é suficiente. Pese sempre no mesmo horário, de preferência de manhã antes de servir. Assim os ganhos são comparáveis.","a":"manejo"},{"t":"Moscas e parasitas","x":"Retire o esterco com frequência, evite poças e controle as moscas nos cochos. Vermifugue na entrada e repita conforme indicar seu veterinário.","a":"sanidad"},{"t":"Diarreia","x":"Pode vir de mudanças bruscas de dieta, excesso de grão, alimento com mofo ou infecções. Revise a ração e a água. Se houver sangue, febre ou vários animais, chame o veterinário.","a":"sanidad"},{"t":"Mancadeiras","x":"Podem vir de acidose, pisos com pedras ou barro. Mantenha o curral seco e sem objetos cortantes. Um animal manco come menos: separe e examine.","a":"sanidad"},{"t":"Manejo tranquilo","x":"Mova os animais devagar, sem gritos nem paus. Um animal estressado come menos e adoece mais. Trabalhe em grupos pequenos e nas horas frescas.","a":"manejo"},{"t":"Minerais","x":"Inclua núcleo mineral na mistura, de 1,5 a 2 % da matéria seca. Assim você cobre cálcio, fósforo, sal e microminerais sem depender de saleiros.","a":"nutricion"},{"t":"Fibra e rúmen","x":"Mesmo que a dieta seja de terminação, deixe de 8 a 15 % de forragem efetiva. Se vir que não ruminam ou o consumo cai, falta fibra.","a":"nutricion"},{"t":"Manejo de cochos","x":"Revise o cocho antes de cada entrega. Vazio por mais de 2 horas: suba a ração 3 a 5 %. Sobra muito: baixe 3 a 5 %. Limpe o velho ou molhado. Anote a leitura em cada entrega e eu aviso você.","a":"nutricion"},{"t":"Como melhorar a margem","x":"O que mais pesa: comprar bem (preço e peso), uma ração barata que cumpra o necessário, boa conversão, pouca mortalidade e vender no peso certo. Veja seu custo por quilo ganho: deve ficar abaixo do preço de venda por quilo. No menu do Rumi, Alimentação, Formular uma dieta, eu busco uma mistura mais barata.","a":"negocio"},{"t":"Por que anotar tudo","x":"Sem registros você não sabe qual lote ganha e qual perde. Anotar o alimento todo dia e pesar a cada três semanas é suficiente para eu calcular conversão, custos e margem.","a":"conceptos"},{"t":"Conversão","x":"São os quilos de alimento que um animal precisa para ganhar um quilo de peso. Se diz 7 para 1, comeu 7 kg de alimento para cada quilo que subiu. Quanto mais baixa, melhor. No confinamento com concentrado o normal está entre 6 e 8.","a":"conceptos"},{"t":"Ganho diário","x":"São os quilos que cada animal sobe por dia. Calcula-se entre uma pesagem e a seguinte. No confinamento em curral, de 1,2 a 1,6 kg por dia é um bom ritmo.","a":"conceptos"},{"t":"Margem","x":"É o que sobra depois de subtrair todos os custos, incluída a compra dos animais, do que você recebe pela venda. O app a estima para cada lote ao chegar ao peso meta.","a":"conceptos"},{"t":"Carência","x":"São os dias que devem passar depois de aplicar um medicamento para poder vender o animal ao frigorífico. Quando você registra sanidade com dias de carência, o app avisa e não deixa você esquecer ao vender.","a":"sanidad"},{"t":"Leitura de cocho","x":"É como você encontra o cocho antes de servir. Vazio várias vezes seguidas: suba a ração. Sobra: baixe. Limpo é o ideal.","a":"nutricion"},{"t":"Ração","x":"É a mistura de alimento que você dá: por exemplo milho, polpa, feno e núcleo. No app você anota o nome e quanto custa o quilo, assim ele calcula seus custos.","a":"nutricion"},{"t":"Lote","x":"É um grupo de animais que entraram juntos e são manejados juntos até a venda. Tudo no app se anota por lote.","a":"conceptos"},{"t":"Consumo","x":"São os quilos de alimento que cada animal come por dia. Se cai de repente, pode haver um problema de saúde, água ou qualidade do alimento; o app avisa.","a":"nutricion"},{"t":"Backup","x":"É um arquivo com todos os seus dados. Se o celular se perder ou estragar, com esse arquivo você recupera tudo. Baixe toda semana em Mais, em Seus dados. As fotos dos animais ficam no celular e não vão no backup.","a":"app"},{"t":"Dias de confinamento","x":"São os dias desde que o lote entrou. Servem para comparar lotes e planejar a venda.","a":"conceptos"},{"t":"Onde fica Gráficos","x":"Toque em Gráficos embaixo. Em cima você escolhe um lote ou todos, e o período. Desça para ver peso, ganho, consumo, conversão, custos, margem e mais.","a":"app"},{"t":"Onde fica o Backup","x":"Toque em Mais embaixo à direita. Entre em Seus dados e toque em Baixar backup. Guarde o arquivo no Drive ou mande para você pelo WhatsApp.","a":"app"},{"t":"Onde fica Baixar para Excel","x":"Toque em Mais. Em Seus dados, em Baixar para Excel, escolha o que quer: lotes, alimento, pesagens e mais.","a":"app"},{"t":"Onde ficam as Configurações","x":"Toque em Mais e depois em Configurações. Ali você muda o preço de venda, o peso meta, o ganho esperado, os horários de entrega, os avisos e a unidade de peso. Toque em Salvar configurações.","a":"app"},{"t":"Onde fica Aparência","x":"Toque em Mais. Em Aparência escolha Claro, Escuro ou Automático e a paleta de cores que mais gostar.","a":"app"},{"t":"Onde corrigir um registro","x":"Toque em Registrar. Embaixo, em Seus últimos registros, toque na lixeira do registro errado. Você também pode entrar no lote e apagar pelo Histórico. Depois anote de novo corretamente.","a":"app"},{"t":"Onde editar um lote","x":"Toque em Lotes e entre no lote. Desça até Dados do lote e toque em Editar.","a":"app"},{"t":"Onde fica Lotes","x":"Toque em Lotes embaixo para ver seus lotes em confinamento e os vendidos.","a":"app"},{"t":"Onde fica Hoje","x":"Toque em Hoje embaixo à esquerda.","a":"app"},{"t":"Tela Hoje","x":"Aqui começa tudo. Você vê quantos animais tem, quanto devem comer hoje e o que precisa da sua atenção.","a":"app"},{"t":"Tela Lotes","x":"Um lote é um grupo de animais que você comprou juntos. Toque num lote para ver seus animais, quanto pesam e quando saem para a venda.","a":"app"},{"t":"Tela Registrar","x":"Este botão serve para anotar tudo: a comida que você dá, quando pesa, as vacinas, as vendas, as mortes e os gastos. Se você anota, o app faz as contas sozinho.","a":"app"},{"t":"Tela Gráficos","x":"São desenhos que mostram se seus animais estão ganhando peso e se você está ganhando dinheiro. Cada desenho traz sua explicação.","a":"app"},{"t":"Tela Mais","x":"Um menu com: Configurações, Rações e dietas, Depósito de ração, Despesas gerais, Agenda, Seus dados (backup e Excel), Aparência, Ajuda e Opções avançadas.","a":"app"},{"t":"Tela Rumi","x":"Se você se perder, toque no Rumi e escolha no menu o que precisa: seus números de hoje, anotar, alimentação, saúde, calculadoras, dinheiro, o guia de confinamento ou como usar o app.","a":"app"},{"t":"Bicheira (Cochliomyia)","x":"É a larva de uma mosca que come a carne viva em feridas, umbigos, castrações ou descornas. Revise diariamente qualquer ferida, trate e proteja com um produto contra bicheira. Se encontrar larvas, avise o SENASA: é uma praga de notificação obrigatória em Honduras.","a":"sanidad"},{"t":"Tristeza parasitária (anaplasma e babesia)","x":"É transmitida por carrapatos e moscas. Sinais: febre, fraqueza, mucosas pálidas ou amarelas e, na babesia, urina cor de café ou vermelha. O animal atrasa ou morre se não for tratado a tempo. Controle os carrapatos, não use a mesma agulha em vários animais e chame o veterinário no primeiro caso.","a":"sanidad"},{"t":"Carbúnculo sintomático e clostridioses","x":"São bactérias do solo que causam mortes rápidas, às vezes sem sinais. No carbúnculo sintomático uma perna incha e crepita pelo gás ao tocar. Previnem-se com vacina clostridial na entrada e seu reforço, conforme o rótulo e seu veterinário.","a":"sanidad"},{"t":"Morte súbita e antraz","x":"Se um animal morre de repente e sangra pelo nariz, boca ou ânus, não o abra: pode ser antraz, que passa para as pessoas. Avise o SENASA e seu veterinário. Em qualquer morte, enterre o corpo fundo, com cal, longe de rios e poços, e anote a baixa no app.","a":"sanidad"},{"t":"Monensina e ionóforos","x":"Melhoram a conversão e ajudam a prevenir acidose e timpanismo. Use só na quantidade do fabricante e muito bem misturados. São mortais para cavalos, burros e cães: que nunca comam dessa mistura.","a":"nutricion"},{"t":"Vitaminas na entrada","x":"Muitos confinamentos aplicam vitaminas A, D e E na entrada porque os animais chegam estressados. Use conforme o rótulo e seu veterinário, e anote em Sanidade.","a":"sanidad"},{"t":"Vacinas na entrada","x":"O básico na entrada: vacina clostridial com seu reforço e, conforme sua região, raiva e respiratórias. Seu veterinário diz quais se aplicam onde você está. Anote cada vacina em Sanidade para levar o controle.","a":"sanidad"},{"t":"Quarentena de animais comprados","x":"Mantenha os animais novos separados dos que você já tem por duas a três semanas. Assim você vê se trazem doenças ou parasitas antes de misturá-los.","a":"sanidad"},{"t":"Como escolher animais para comprar","x":"Procure animais alertas, de olhos brilhantes, sem muco nem tosse, que caminhem bem e com bom esqueleto. Evite os muito magros ou barrigudos. Pese-os na balança, peça os papéis de trânsito e pergunte que vacinas e vermífugos receberam.","a":"negocio"},{"t":"Raças para confinamento","x":"No trópico o Brahman e seus cruzamentos aguentam melhor o calor e os carrapatos. Os cruzamentos com Simental, Charolês ou Angus costumam ganhar mais peso e dar melhor carcaça. Os machos de leite ganham bem, mas rendem menos de carcaça.","a":"manejo"},{"t":"Estimar peso com fita","x":"A fita mede o tórax e estima o peso, mas pode errar 5 a 10 %. Use para ter uma ideia; para comprar, vender e calcular ganhos use balança.","a":"manejo"},{"t":"Farelo de trigo e de arroz","x":"Fornecem energia e proteína média a bom preço. Têm muito fósforo, então a ração precisa de cálcio para evitar cálculos urinários. O formulador do app balanceia por você.","a":"nutricion"},{"t":"Farelo de soja","x":"É a fonte de proteína mais usada. É cara, então a quantidade certa importa: o formulador do app calcula o necessário conforme o peso e o ganho que você busca.","a":"nutricion"},{"t":"Milho e sorgo","x":"São a base de energia do confinamento. Quebre ou moa grosso: muito fino aumenta o risco de acidose e timpanismo. O sorgo rende um pouco menos que o milho e convém quando está mais barato.","a":"nutricion"},{"t":"Cama de frango","x":"É barata, mas pode trazer resíduos de medicamentos e bactérias, e muitos compradores e países a restringem. Antes de usar, consulte o SENASA e seu veterinário.","a":"nutricion"},{"t":"Capim de corte","x":"Corte antes que fique lenhoso, mais ou menos a cada 45 a 60 dias conforme a chuva. Pique curto para desperdiçar menos. Aduba depois de cada corte para manter o rendimento.","a":"forrajes"},{"t":"Leucena e bancos de proteína","x":"As leguminosas como leucena e gliricídia dão proteína barata. A leucena não deve passar de um terço do que comem porque tem uma substância que em excesso faz mal.","a":"forrajes"},{"t":"Feno e fardos","x":"O feno dá a fibra que o rúmen precisa. Que esteja seco, verde e com bom cheiro; se cheira a mofo, não dê. Guarde sob teto e sobre paletes.","a":"forrajes"},{"t":"Preparar a seca","x":"Planeje a forragem antes que chegue a seca: silagem, feno ou cana. Calcule quanto vai precisar por mês e compre o grão quando estiver barato. No menu do Rumi, Alimentação, Alimento para o mês, eu calculo com seus lotes.","a":"forrajes"},{"t":"Barro e chuva no curral","x":"O barro baixa o ganho e traz mancadeiras. Dê declive ao curral, limpe o esterco, faça montes secos para que deitem e proteja os cochos da chuva.","a":"instalaciones"},{"t":"Tamanho do curral e do cocho","x":"Como guia: uns 12 m² de curral por animal em piso de terra, 30 cm de cocho por animal e 3 m² de sombra. No menu do Rumi, Calculadoras, Espaço de curral e cocho, eu calculo para suas cabeças.","a":"instalaciones"},{"t":"Plantas tóxicas","x":"Com fome, sobretudo na seca, comem plantas que normalmente deixam. Percorra os pastos e currais, arranque o suspeito e não coloque animais famintos num pasto desconhecido. Se vários adoecerem de uma vez, chame o veterinário. Na América Central são comuns a samambaia, a lantana (cambará) e a crotalária (guizo-de-cascavel).","a":"sanidad"},{"t":"Hematomas e pancadas antes da venda","x":"As pancadas se perdem como carne aparada no frigorífico. Carregue devagar, com rampa, sem paus e sem encher demais o caminhão. Os animais com chifres se machucam mais.","a":"manejo"},{"t":"Descornar","x":"É melhor fazer quando jovens, com pouca dor e com a ferida protegida contra moscas e bicheira. Assim há menos pancadas no curral e no transporte.","a":"manejo"},{"t":"Custos do confinamento","x":"Depois da compra dos animais, o alimento é o que mais pesa: quase sempre mais de dois terços do custo de engordar. Por isso uma ração barata e uma boa conversão fazem a diferença.","a":"negocio"},{"t":"Preço de venda","x":"Não sei o preço do mercado de hoje. Você o coloca em Mais, em Configurações, e com ele eu calculo sua margem, o preço mínimo para não perder e quanto você pode pagar na compra.","a":"negocio"},{"t":"Anotar alimento","x":"Toque em Registrar e depois em Ração, escolha o lote, a ração e os quilos. Também pode abrir pelo menu do Rumi, em Anotar.","a":"app"},{"t":"Anotar uma pesagem","x":"Toque em Registrar e depois em Pesagem, escolha o lote e coloque o peso de cada animal ou a média do grupo. Também pode abrir pelo menu do Rumi, em Anotar.","a":"app"},{"t":"Anotar uma venda","x":"Toque em Registrar e depois em Venda, escolha o lote, as cabeças, os quilos e o preço. Também pode abrir pelo menu do Rumi, em Anotar.","a":"app"},{"t":"Anotar sanidade","x":"Toque em Registrar e depois em Sanidade. Coloque o produto, quantas cabeças, o custo e os dias de carência. O app avisa se você quiser vender antes de terminar a carência.","a":"app"},{"t":"Criar um lote","x":"Toque em Registrar e depois em Novo lote. Coloque os dados do lote e cada animal com seu brinco, peso, raça, cor e foto. O preço de compra pode ser uma média para todo o lote ou um por animal.","a":"app"},{"t":"Animais com brinco","x":"Se você pesa cada animal com seu brinco, o app guarda sua história: pesos, ganho, foto e se está atrasando. Entre no lote e toque em Animais.","a":"app"},{"t":"Rumi sem internet","x":"Tudo funciona sem internet: seus dados e as fotos dos seus animais ficam no celular, e o Rumi calcula aqui mesmo. Só precisa de internet para mandar seu backup ao Drive ou WhatsApp.","a":"app"},{"t":"Quem é o Rumi","x":"Sou o Rumi, o ajudante do Rumentis. Trabalho com um menu: você escolhe uma área e eu mostro o que posso fazer ali, com seus próprios dados. Posso errar: para medicamentos e decisões grandes confirme com seu veterinário.","a":"app"},{"t":"Dados no celular","x":"Seus dados ficam no seu celular. Não os mando para lugar nenhum; só saem se você baixar o backup ou o Excel e compartilhar.","a":"app"},{"t":"Trocar de celular","x":"Baixe o backup em Mais, passe para o celular novo, instale o Rumentis e em Mais toque em Restaurar backup.","a":"app"},{"t":"Ganho baixo","x":"Revise nesta ordem: que tenham água limpa de sobra, que o cocho não fique vazio, a ração e sua qualidade, parasitas, doenças e calor. Pesar no mesmo horário evita erros. Veja o ganho de cada lote em Gráficos.","a":"manejo"},{"t":"Sal mineral no pasto","x":"No pasto ofereça sal mineral à vontade em saleiros cobertos. O sal branco sozinho não cobre fósforo nem microminerais. No curral, o núcleo mineral vai dentro da mistura.","a":"forrajes"},{"t":"Vermifugar","x":"Vermifugue na entrada e repita conforme indicar seu veterinário. Rotacione os produtos para que não fiquem resistentes. Para a dose por peso, no menu do Rumi entre em Saúde, Dose de um medicamento.","a":"sanidad"},{"t":"Mosca-dos-chifres e moscas-dos-estábulos","x":"As moscas incomodam, baixam o consumo e transmitem doenças. Retire o esterco com frequência, evite alimento espalhado e molhado, e use armadilhas ou produtos conforme seu veterinário.","a":"sanidad"},{"t":"Carência antes de vender","x":"Não venda ao frigorífico um animal que ainda está em carência por um medicamento. O app conta os dias de carência do que você anotou em Sanidade e avisa.","a":"sanidad"},{"t":"Duração do confinamento","x":"Depende do peso de entrada e da meta. Com uma boa ração de curral sobem de 1,2 a 1,6 kg por dia, então um novilho de 300 kg chega a 450 kg em uns 100 a 125 dias. No menu do Rumi, Meu confinamento, Projetar um lote, eu dou a data do seu lote.","a":"manejo"},{"t":"Confinar nas chuvas ou na seca","x":"No curral se pode o ano todo; na seca o desafio é a forragem e o calor, e nas chuvas o barro. O que mais importa é comprar bem e que o custo por quilo ganho fique abaixo do preço de venda.","a":"manejo"},{"t":"Tamanho do confinamento","x":"Não há um número fixo: depende dos seus custos fixos, mão de obra e espaço. Com poucos animais, os gastos gerais pesam mais por cabeça. No menu do Rumi, Dinheiro e vendas, Preço máximo de compra, você vê se os números fecham.","a":"manejo"},{"t":"Começar um confinamento","x":"Comece com um lote que consiga manejar: curral com sombra, água e cocho, uma ração formulada e um plano sanitário de entrada com seu veterinário. No app crie o lote e anote alimento e pesagens. No menu do Rumi, Usar o app, Por onde começo, eu guio você.","a":"manejo"},{"t":"Morte de bezerros","x":"As causas mais comuns são diarreias, problemas respiratórios, umbigo infeccionado e pouco leite ou colostro. Isso exige examinar o animal: chame seu veterinário e anote cada baixa no app para ver se há um padrão.","a":"sanidad"},{"t":"Pata quebrada","x":"Separe, não force a caminhar e chame seu veterinário. Se não tiver conserto, ele dirá como sacrificá-lo sem sofrimento. Anote a baixa no app.","a":"sanidad"},{"t":"Olho branco","x":"É a infecção do olho que o deixa vermelho, lacrimejante e depois com uma mancha branca. É transmitida por moscas, poeira e pasto alto. Controle as moscas e consulte o veterinário para tratar cedo.","a":"sanidad"},{"t":"Verrugas","x":"As verrugas são causadas por um vírus e quase sempre caem sozinhas em alguns meses. Evite compartilhar agulhas e equipamentos entre animais. Se forem muitas ou sangrarem, consulte seu veterinário.","a":"sanidad"},{"t":"Brucelose","x":"É uma doença que causa abortos em fêmeas e passa para as pessoas pelo leite cru e contato com fetos. No confinamento de machos é menos comum, mas se você maneja fêmeas, faça os testes que o SENASA pedir.","a":"sanidad"},{"t":"Tuberculose bovina","x":"É uma doença dos pulmões que avança devagar e passa para as pessoas. Os animais emagrecem e tossem. Se suspeitar, avise seu veterinário e o SENASA para os testes.","a":"sanidad"},{"t":"Febre aftosa","x":"É uma doença muito contagiosa que dá bolhas na boca e nas patas. Na América Central não está presente, e por isso qualquer suspeita se notifica imediatamente ao SENASA.","a":"sanidad"},{"t":"Febre","x":"Meça a temperatura no reto com um termômetro: o normal está entre 38 e 39,5 graus. Acima de 39,5 tem febre. Se além disso não come ou está abatido, chame o veterinário.","a":"sanidad"},{"t":"Esterco como sinal","x":"O esterco normal forma uma torta que se assenta. Muito solto pode ser excesso de grão ou doença; muito duro e seco pode ser falta de água ou muita fibra seca. Use como sinal de como vai a ração.","a":"sanidad"},{"t":"Quanto comem","x":"Um novilho em confinamento come mais ou menos de 2,3 a 2,8 % do seu peso vivo em matéria seca por dia. No início e com calor come menos. O app estima o consumo de cada lote: veja no menu do Rumi, Alimentação, Quanto comem.","a":"nutricion"},{"t":"Pão velho","x":"O pão velho dá energia, mas é como grão muito moído: em excesso causa acidose. Use em pouca quantidade, dentro da ração, sem mofo nem plástico, e adapte aos poucos.","a":"nutricion"},{"t":"Casca de banana","x":"Sim, em pouca quantidade e fresca, como complemento. Tem pouca proteína e muita água, então não substitui a ração. Evite que apodreça no cocho.","a":"nutricion"},{"t":"Mandioca","x":"A mandioca dá boa energia, mas crua e fresca pode ter um composto tóxico. Use seca ou picada e arejada, em quantidade moderada, e equilibre a proteína com outra fonte.","a":"nutricion"},{"t":"Matéria seca","x":"É o que sobra do alimento se você tira a água. Usa-se para comparar alimentos, porque um quilo de silagem traz muita água e um quilo de milho quase nada. O formulador do app trabalha em matéria seca.","a":"nutricion"},{"t":"Misturar a ração","x":"Misture primeiro os ingredientes pequenos, como núcleo e ureia, com uma parte do grão, e depois acrescente ao resto. Assim cada animal come por igual e não passa de nada.","a":"nutricion"},{"t":"Brigas no cocho","x":"Dê espaço suficiente, uns 30 cm por animal, sirva no mesmo horário e distribua o alimento ao longo de todo o cocho. Separe os muito dominantes ou os muito pequenos.","a":"manejo"},{"t":"Agrupar por tamanho","x":"Melhor não misturar: os grandes não deixam os pequenos comerem e o lote fica desigual. Agrupe por peso parecido, assim também é mais fácil planejar a venda.","a":"manejo"},{"t":"Animais atrasados","x":"Separe-os num grupo próprio, examine se têm doença ou parasitas e dê espaço para comer. Se você pesa por brinco, o app diz quais estão atrasando.","a":"manejo"},{"t":"Animais que montam","x":"Às vezes acontece com tourinhos ou animais estressados, e pode machucar o montado. Separe o que monta ou o que é montado, revise o espaço e o manejo.","a":"manejo"},{"t":"Poeira no curral","x":"Um pouco de tosse com poeira pode acontecer, mas se há muco, febre, orelhas caídas ou não comem, pode ser pneumonia. Molhe o curral para baixar a poeira e vigie-os de manhã e à tarde.","a":"instalaciones"},{"t":"Peso de venda","x":"Depende do que seu comprador paga melhor; muitos confinamentos vendem perto de 450 a 500 kg. Coloque seu peso meta em Mais e o app calcula quando cada lote chega.","a":"negocio"},{"t":"Mão de obra","x":"Depende do tamanho e de se você mistura à mão ou com máquina. Anote a folha como gasto no app: assim vê quanto custa por cabeça por dia.","a":"negocio"},{"t":"Financiamento","x":"Isso depende do seu banco ou cooperativa. O que eu posso é ajudar a saber se o negócio compensa: no menu do Rumi, Dinheiro e vendas, veja o preço máximo de compra e o preço mínimo para não perder, e baixe seus dados para Excel em Mais.","a":"negocio"},{"t":"A lua","x":"Não há provas de que a lua mude o ganho de peso. O que influi é a ração, a água, o calor e a sanidade. Melhor focar nisso.","a":"negocio"},{"t":"Sal com cinza","x":"A cinza não fornece o que falta e pode trazer sujeira. Use sal mineral ou núcleo mineral, que cobrem cálcio, fósforo e microminerais.","a":"nutricion"},{"t":"Água verde no bebedouro","x":"O verde são algas pelo sol e pela sujeira. Esvazie e escove o bebedouro toda semana e, se puder, dê sombra. A água limpa faz que bebam mais e comam mais.","a":"nutricion"},{"t":"Comem terra","x":"Comer terra pode ser sinal de falta de minerais ou de fibra. Verifique se a ração leva núcleo mineral e forragem suficiente.","a":"nutricion"},{"t":"Comem pelo","x":"Pode ser falta de fibra ou de minerais, ou tédio no curral. Revise a forragem e o núcleo mineral da ração.","a":"nutricion"},{"t":"Alimento molhado","x":"Tire o molhado do cocho antes de servir, porque fermenta e dá mofo. Se puder, coloque teto no cocho e sirva quantidades que sejam comidas no dia.","a":"nutricion"},{"t":"Animal que chega fraco","x":"O melhor na chegada é água limpa à vontade e feno de boa qualidade. Se vier muito fraco, seu veterinário pode dar eletrólitos ou soro.","a":"manejo"},{"t":"Ganho no pasto","x":"No pasto o ganho é menor e muda muito com a época: nas chuvas com bom pasto podem ganhar mais de meio quilo por dia, e na seca sem suplemento às vezes nada. No curral com boa ração ganham de 1,2 a 1,6 kg.","a":"forrajes"},{"t":"Semiconfinamento","x":"É quando os animais pastejam parte do dia e no curral recebem suplemento ou ração. Ganha mais que só o pastejo e custa menos que o curral completo.","a":"forrajes"},{"t":"Fêmeas para confinamento","x":"As novilhas engordam mais devagar e acumulam gordura antes que os machos, e às vezes pagam menos por elas. Podem compensar se você as compra barato; faça a conta com \"quanto posso pagar\".","a":"manejo"},{"t":"Desmame","x":"É separar o bezerro da mãe antes do normal. Isso é da cria, não do confinamento: no app focamos em novilhos que já entraram para engordar.","a":"manejo"},{"t":"Anotar uma morte ou baixa","x":"Toque em Registrar e depois em Baixa: escolha o lote, quantas cabeças e a causa. Assim a mortalidade e os custos ficam certos. Também pode abrir pelo menu do Rumi, em Anotar.","a":"app"},{"t":"Anotar um gasto","x":"Toque em Registrar e depois em Despesa: coloque o valor, a categoria (mão de obra, frete, medicamentos, manutenção, luz e água) e se é de um lote ou geral. Também pode abrir pelo menu do Rumi, em Anotar.","a":"app"},{"t":"Criar uma ração","x":"Entre em Mais e toque em Rações e dietas. Dê um nome e o custo por quilo (ou por libra). Depois você a escolhe cada vez que anota alimento. Se a formular com Formular dieta, guarda com um toque.","a":"app"},{"t":"Anotar animais com brinco","x":"Ao criar o lote você coloca cada animal com seu brinco, peso, raça, cor e foto. Depois, ao pesar por brinco, o app acompanha cada animal e diz quem está atrasando.","a":"app"},{"t":"Tela Formular dieta","x":"Em Mais toque em Formular dieta. Coloque o peso dos animais e o ganho que você busca, escolha os ingredientes e o app calcula a mistura mais barata que cobre o que precisam. Pode guardá-la como ração.","a":"app"},{"t":"Como o Rumentis calcula","x":"Em Mais, em Ajuda, Como o Rumentis calcula, está explicado cada número: ganho diário entre pesagens, conversão com o alimento anotado, custo por quilo ganho, projeção ao peso meta e margem. Tudo sai do que você anota.","a":"app"},{"t":"Tour pelo app","x":"No menu do Rumi, Usar o app, toque em Me mostre o tour, ou entre em Mais, Ajuda, Tour pelo app. Eu mostro cada tela passo a passo.","a":"app"},{"t":"Quilos ou libras","x":"Você pode trabalhar em quilos ou em libras. Mude em Mais, em Configurações. O app converte tudo sozinho.","a":"app"},{"t":"Moeda do app","x":"A moeda se muda em Mais, em Configurações. Você pode escolher a moeda do seu país ou digitar outra.","a":"app"},{"t":"Peso meta do lote","x":"Cada lote pode ter seu peso meta: entre no lote e edite. Com isso o app calcula a data de saída e a margem.","a":"app"},{"t":"Projeções","x":"No menu do Rumi, Meu confinamento, Projetar um lote: você escolhe o lote e os dias, e eu digo quanto vai pesar e quanto deixaria. Uso o ganho real das pesagens.","a":"app"},{"t":"Comparar lotes","x":"No menu do Rumi, Meu confinamento, Meu melhor lote, eu mostro o ganho, a conversão e a margem de cada lote lado a lado.","a":"app"},{"t":"Simular um negócio","x":"No menu do Rumi, Dinheiro e vendas, você pode ver o preço máximo de compra conforme o peso e o que acontece com sua margem se o alimento subir. Uso seus custos reais.","a":"app"},{"t":"Avisos do app","x":"O app avisa em Hoje quando falta dar alimento, o consumo cai, um lote está há tempo sem pesar, um animal atrasa ou há carências ativas. Toque neles para ir resolver.","a":"app"},{"t":"Restaurar backup","x":"Em Mais toque em Restaurar backup e escolha o arquivo que baixou. Seus lotes e registros voltam tal como estavam.","a":"app"},{"t":"Lotes vendidos","x":"Em Lotes você vê os ativos e os vendidos. Os vendidos guardam seus números finais para comparar com os novos.","a":"app"},{"t":"Histórico do lote","x":"Entre no lote e desça até Histórico: ali estão todos os registros. Dali também pode apagar um errado.","a":"app"},{"t":"Horários de entrega","x":"Em Mais, em Configurações, você coloca quantas entregas faz por dia e a que horas. Assim a tela Hoje diz quanto falta dar.","a":"app"},{"t":"Usar o app sem saber muito de celular","x":"Fique tranquilo: toque no Rumi e escolha no menu. Não precisa escrever nada; eu levo você a cada formulário e explico cada tela.","a":"app"},{"t":"Rampa de embarque","x":"A rampa deve ficar na altura do piso do caminhão, sem vãos, com piso antiderrapante e proteções dos lados. Como guia usam-se uns 80 cm de largura, paredes de 1,60 m e degraus de 10 cm de altura por 30 a 45 cm de largura. Uns pneus no final ajudam a encostar o caminhão sem batê-lo. (Guia da OIRSA)","a":"instalaciones"},{"t":"Medidas do brete","x":"Um brete de trabalho costuma ter mais de 8 m de comprimento, 1,50 m de altura, uns 45 cm de largura embaixo e 85 cm em cima, com paredes fechadas para que o animal não veja fora. Uma passarela a uns 55 a 60 cm do chão permite trabalhar ao longo. O curral de espera antes do brete funciona bem redondo, de 3 a 3,5 m de raio. (Guia da OIRSA)","a":"instalaciones"},{"t":"Zona de fuga e ponto de equilíbrio","x":"A zona de fuga é a distância que o animal deixa você chegar antes de se mover. Para que avance, entre na borda dessa zona atrás do ponto de equilíbrio, que fica na altura da paleta; para que pare, saia dela. Não fique atrás da cauda, que é seu ponto cego. O gado manejado com calma tem uma zona de fuga menor e é mais fácil de trabalhar.","a":"manejo"},{"t":"Como o gado enxerga","x":"O gado enxerga quase ao redor, mas foca mal de perto e se assusta com movimentos bruscos e com contrastes de luz e sombra. Prefere caminhar em direção ao iluminado. Por isso convém manejar devagar, sem gritos, e retirar objetos que se movem ou brilham no brete.","a":"manejo"},{"t":"Conduzir sem ferrão","x":"Melhor conduzir em grupos, a passo lento, com bandeiras, chocalhos ou raquetes. O choque elétrico quase não deveria ser usado; se for preciso com um animal adulto que não avança, só nos quartos traseiros, menos de um segundo e quando tiver espaço para avançar. Nunca pancadas, chutes nem puxar a cauda.","a":"manejo"},{"t":"Separar no transporte","x":"No caminhão separe animais de tamanhos muito diferentes, com e sem chifres, e os que brigam. Assim há menos pancadas e hematomas.","a":"manejo"},{"t":"Condições do caminhão","x":"O caminhão deve estar limpo, sem pregos nem lascas, com piso antiderrapante, ventilação e altura suficiente. Nunca totalmente fechado: a fumaça do motor pode asfixiá-los. Viaje nas horas frescas e sem paradas longas.","a":"manejo"},{"t":"Animais que não devem viajar","x":"Não transporte animais doentes, mancos ou feridos, salvo lesões leves ou com indicação do veterinário. Um animal fraco pode cair e morrer no caminhão. Castrados ou descornados devem viajar com a ferida já cicatrizada.","a":"manejo"},{"t":"Papéis da viagem","x":"Em cada viagem leve os documentos que mostrem de onde vêm os animais e de quem são, o local e a data de saída, o destino e os papéis sanitários que o SENASA pedir.","a":"normas"},{"t":"Farinhas de origem animal","x":"Não dê a ruminantes farinhas de carne, de osso, de sangue nem outras proteínas de origem animal: são proibidas pelo risco de doenças como a \"vaca louca\" e fecham mercados. A ureia e o melaço são permitidos.","a":"nutricion"},{"t":"Micotoxinas e aflatoxinas","x":"Os fungos do grão e da forragem produzem toxinas como a aflatoxina, que adoece, baixa as defesas e o ganho e deixa resíduos. Guarde o alimento seco e ventilado e jogue fora o que tiver mofo: não se \"conserta\" misturando.","a":"nutricion"},{"t":"Sobra de alimento no cocho","x":"Retire todo dia o alimento que sobrou do dia anterior, sobretudo se estiver molhado ou fermentado. Verifique que a ração esteja fresca e sem lixo, pedras nem fungos antes de servir.","a":"nutricion"},{"t":"Armazém organizado","x":"Empilhe os sacos sobre paletes e afastados da parede, num armazém coberto, seco e com tela nas janelas. Use primeiro o que entrou primeiro e guarde os químicos e venenos em outro lugar, nunca junto ao alimento.","a":"instalaciones"},{"t":"Bebedouros na sombra","x":"Coloque os bebedouros sob teto e, se puder, de cores claras: a água fresca é mais bebida. Os melhores são compridos, pouco fundos e com boia, porque se lavam fácil e a água se renova.","a":"nutricion"},{"t":"Análise e cloração da água","x":"Analise a água de poço ou córrego pelo menos uma vez por ano. Se tiver bactérias, pode-se clorar na quantidade que a autoridade indicar. Cerque os poços e não deixe o gado entrar na fonte de água.","a":"nutricion"},{"t":"Recepção sanitária completa","x":"Ao recebê-los, revise um por um, hidrate (água limpa e, se vierem muito cansados, eletrólitos), e aplique vitaminas, minerais, vermífugo e as vacinas que seu veterinário indicar. Depois observe-os por várias semanas.","a":"sanidad"},{"t":"Iluminação do curral","x":"Uma luz nos currais permite revisar os animais à noite, detectar doentes ou problemas com a água e evitar roubos.","a":"instalaciones"},{"t":"Enfermaria longe do vento","x":"Coloque o curral de enfermaria afastado e contra a direção do vento que sopra para os demais currais, para que não leve doenças ao resto.","a":"sanidad"},{"t":"Cova para animais mortos","x":"Enterre os animais mortos num local marcado, a mais de 30 m dos currais e a mais de 250 m de poços ou fontes de água, numa cova funda (recomendam-se uns 4 m), cobertos com cal e depois com terra. Nunca venda um animal morto. (Guia da OIRSA)","a":"sanidad"},{"t":"Compostagem de esterco","x":"Amontoe o esterco longe dos currais e fontes de água: em monte ele esquenta e morrem muitos micróbios. Depois serve como adubo para pastos. Também pode ser usado para biogás.","a":"instalaciones"},{"t":"Resíduos veterinários","x":"As agulhas usadas, frascos de remédio e embalagens de químicos não vão para o lixo comum. Guarde em recipientes separados e marcados e entregue a quem os recolha ou enterre num lugar afastado e sinalizado.","a":"sanidad"},{"t":"Tamanho da agulha","x":"Para animais de mais de 300 kg usam-se agulhas calibre 16 a 18; mais grossas se o produto for espesso. Para intramuscular, de 1 a 1,5 polegada; para subcutânea, mais curtas, de meia a três quartos de polegada. Troque com frequência. (Guia da OIRSA)","a":"sanidad"},{"t":"Tudo dentro, tudo fora","x":"O ideal é que um curral receba um lote completo e se esvazie completo na venda. Entre lotes, retire o esterco, deixe secar ao sol e conserte. Assim você corta a passagem de doenças de um lote para o seguinte.","a":"manejo"},{"t":"Tempo de adaptação","x":"A adaptação ao grão leva de 15 a 21 dias. Uma forma prática é subir o grão em degraus a cada 4 ou 5 dias (por exemplo 30, 40, 50, 60 % e depois a ração final), desde que o cocho fique limpo e não haja diarreia.","a":"nutricion"},{"t":"Quantas vezes servir por dia","x":"Dividir a ração em 2 ou 3 entregas por dia torna o consumo mais uniforme, reduz o desperdício e baixa o risco de acidose em relação a encher o cocho uma só vez.","a":"nutricion"},{"t":"Tamanho dos lotes no curral","x":"Monte lotes uniformes em peso e idade. Lotes muito grandes, de mais de 200 animais, trazem mais brigas e consumo desigual. Em currais pequenos, o importante é respeitar o espaço de cocho e de curral por animal.","a":"manejo"},{"t":"Declive do curral","x":"O piso do curral precisa de caimento para escoar a água: entre 2 e 4 % na terra, afastando-se do cocho. No cimento, de 4 a 6 % e com ranhuras para que não escorreguem. Com menos declive empoça; com muito, sofre erosão.","a":"instalaciones"},{"t":"Espaço de curral conforme o clima","x":"Onde chove muito convém dar mais espaço por animal para que o curral seque: de 12 até 20 m² ou mais. Em regiões secas e com boa drenagem pode-se usar menos. Sempre com sombra para todos.","a":"instalaciones"},{"t":"Conversão conforme o animal","x":"Os animais jovens e leves convertem melhor: precisam de menos alimento por quilo ganho. Ao avançar o confinamento e engordurar, a conversão piora. Em novilhos de curral é comum ver de 6 a 8 kg de alimento por quilo ganho.","a":"negocio"},{"t":"Confinamento com silagem","x":"Uma ração baseada quase só em silagem de planta inteira dá ganhos moderados, cerca de 0,7 a 0,9 kg por dia. Para ganhar mais, a silagem é combinada com grão e uma fonte de proteína.","a":"nutricion"},{"t":"Registros por três anos","x":"Guarde os registros de alimento, sanidade e movimentações pelo menos três anos: são pedidos em auditorias e mercados de exportação. O app os guarda e você pode baixá-los em Excel ou backup.","a":"normas"},{"t":"Confinamento intensivo com cana e subprodutos","x":"Num estudo de Zamorano numa fazenda da Guatemala, mais de 2.000 animais confinados com cana picada, farelo de soja, subproduto de milho, torta de palmiste, ureia e melaço ganharam entre 1,45 e 2,06 kg por dia. Começou-se oferecendo cerca de 1,5 % do peso em matéria seca e subiu-se até perto de 2,8 %. A compra de animais e o alimento foram 97 % dos custos variáveis.","a":"nutricion"},{"t":"Vacas de descarte para engorda","x":"As vacas de descarte bem alimentadas podem ganhar peso rápido em confinamentos curtos, de umas 6 semanas, e às vezes deixam bom lucro porque são compradas baratas. No estudo de Zamorano na Guatemala ganharam entre 1,45 e 1,89 kg por dia. Verifique que estejam sadias e sem carências de medicamentos.","a":"manejo"},{"t":"Época para comprar e vender","x":"O confinamento tem época: na seca muita gente vende gado magro por falta de pasto e o preço de compra cai, e o gado gordo fica escasso e é mais bem pago alguns meses depois. Planeje suas compras com tempo e tenha o dinheiro pronto para gado e alimento.","a":"negocio"},{"t":"Cobertura sobre os cochos","x":"Um teto ou sombrite sobre os cochos protege o alimento do sol e da chuva e o mantém fresco e apetitoso. Sirva a maior parte nas horas frescas, quando mais comem.","a":"instalaciones"},{"t":"Peso vivo e peso de carcaça","x":"O peso vivo é o que pesa o animal inteiro; a carcaça é a carne com osso depois do abate, sem cabeça, patas, couro nem vísceras. A carcaça costuma ser de 54 a 58 % do peso vivo em novilhos de confinamento.","a":"conceptos"},{"t":"Matéria seca e como oferecido","x":"Como oferecido é o alimento com sua água; matéria seca é sem água. As exigências e a conversão se calculam em matéria seca para comparar alimentos diferentes.","a":"conceptos"},{"t":"Ganho médio diário","x":"É quanto cada animal sobe por dia em média entre duas pesagens: a diferença de peso dividida pelos dias. O app calcula por lote e por animal.","a":"conceptos"},{"t":"Custo do quilo de mistura","x":"É o que custa um quilo da ração já misturada, somando os ingredientes na sua proporção. Com ele e a conversão você tira o custo de alimento por quilo ganho.","a":"conceptos"},{"t":"Custo de alimento por quilo ganho","x":"É o custo do quilo de mistura multiplicado pela conversão. Por exemplo, se o quilo de mistura custa 8 e a conversão é 7 para 1, cada quilo ganho custa 56 em alimento.","a":"conceptos"},{"t":"Ponto de equilíbrio em preço","x":"É o preço de venda por quilo com o qual você recupera exatamente o investido no lote. Abaixo você perde, acima ganha.","a":"conceptos"},{"t":"Registro da fazenda","x":"Ter a fazenda registrada nas autoridades facilita obter guias de trânsito, participar de programas sanitários e vender a compradores que exigem rastreabilidade. Consulte o SENASA e sua prefeitura.","a":"normas"},{"t":"Compra de medicamentos","x":"Compre em casas agropecuárias estabelecidas, verifique que o produto tenha registro, validade vigente e embalagem em bom estado. Não use produtos vencidos nem de origem duvidosa.","a":"normas"},{"t":"Orçamento do confinamento","x":"Some a compra dos animais, o alimento de todos os dias de confinamento, sanidade, mão de obra, transporte e uma reserva para imprevistos. A compra e o alimento são quase tudo. No menu do Rumi, Dinheiro e vendas, Preço máximo de compra, você vê se os números fecham.","a":"negocio"},{"t":"Custo do quilo ganho vs preço de venda","x":"Enquanto cada quilo que ganham custar menos do que pagam por quilo, convém continuar. Quando o custo se aproxima do preço, é hora de vender. O app mostra por lote.","a":"negocio"},{"t":"Custos fixos e variáveis","x":"Os variáveis crescem com cada animal (compra, alimento, sanidade). Os fixos se pagam igual com poucos ou muitos (salários, luz, manutenção). Com mais animais, o custo fixo por cabeça baixa. No app você anota os gerais em Despesas.","a":"negocio"},{"t":"Fluxo de caixa","x":"No confinamento você gasta todos os dias e recebe no final. Planeje quanto precisa para alimento até a venda e considere vender por partes ou escalonar a entrada de lotes.","a":"negocio"},{"t":"Escalonar lotes","x":"Colocar lotes a intervalos reparte o trabalho, o uso dos currais e o risco de preço, e dá vendas mais seguidas.","a":"negocio"},{"t":"Risco de preço","x":"O preço de venda pode cair durante o confinamento. Negocie com compradores antes, não dependa de um só e revise o preço mínimo para não perder de cada lote.","a":"negocio"},{"t":"Compradores e contratos","x":"Ter compradores fixos ou um acordo de preço antes de terminar o confinamento reduz o risco. Deixe claro como pesam, que descontos aplicam e quando pagam.","a":"negocio"},{"t":"Descontos na venda","x":"Os compradores costumam descontar uma porcentagem do peso pelo enchimento, além de castigos por pancadas ou animais fora do peso. Pergunte antes e anote em Mais para que as margens saiam reais.","a":"negocio"},{"t":"Qualidade da carne","x":"Os animais jovens, bem alimentados até o final e manejados sem estresse dão carne mais macia e com melhor gordura. O estresse antes do abate dá carne escura e dura.","a":"negocio"},{"t":"Matadouros e frigoríficos","x":"Em Honduras você pode vender a matadouros municipais, frigoríficos ou intermediários. Os frigoríficos grandes costumam pagar por rendimento e qualidade; pergunte suas condições antes de vender.","a":"negocio"},{"t":"Exportação de gado e carne","x":"Parte do gado da América Central é exportada em pé ou como carne. Esses compradores exigem rastreabilidade, sanidade em dia e respeito às carências. Levar seus registros no app ajuda a cumprir.","a":"normas"},{"t":"SENASA","x":"O SENASA é a autoridade de sanidade animal em Honduras. Controla o trânsito de gado, as doenças de notificação obrigatória, o registro de medicamentos e a rastreabilidade. Diante de qualquer doença estranha ou mortes em massa, avise-os.","a":"normas"},{"t":"Trânsito de gado","x":"Para mover gado entre fazendas ou para a venda são necessários os documentos de trânsito que o SENASA e a prefeitura pedem. Na compra, exija esses papéis: assim evita animais roubados ou doentes.","a":"normas"},{"t":"Rastreabilidade","x":"A rastreabilidade permite saber de onde vem cada animal. Baseia-se em brincos oficiais e registros. Cada vez mais compradores e mercados de exportação a exigem.","a":"normas"},{"t":"Marca a ferro","x":"A marca identifica o dono e deve estar registrada na sua prefeitura. Marque onde menos danifique o couro e com boa técnica para evitar infecções.","a":"normas"},{"t":"Medicamentos registrados","x":"Use só produtos veterinários registrados, comprados em casas agropecuárias autorizadas. Os produtos sem registro podem ser falsos ou deixar resíduos na carne.","a":"normas"},{"t":"Substâncias proibidas","x":"Substâncias como o clembuterol são proibidas porque seus resíduos na carne adoecem as pessoas. Usá-las pode fechar mercados e trazer sanções. O Rumi não dá informação para usá-las.","a":"normas"},{"t":"Resíduos na carne","x":"Se você vende um animal antes de terminar a carência de um medicamento, a carne leva resíduos. Respeite sempre os dias de carência do rótulo; o app avisa com o que você anotou em Sanidade.","a":"normas"},{"t":"Roubo de gado","x":"Para se proteger: marque e coloque brinco nos seus animais, mantenha registros, revise cercas, coordene com vizinhos e denuncie à polícia e à prefeitura. Na compra, exija papéis de trânsito.","a":"normas"},{"t":"Assistência técnica","x":"Um técnico ou zootecnista pode ajudar com rações, pastos e instalações, e o veterinário com a sanidade. Instituições como a SAG, escolas agrícolas e cooperativas oferecem capacitações.","a":"normas"},{"t":"Meio ambiente","x":"Não acumule esterco perto de rios ou poços, faça compostagem e use como adubo. Enterre os animais mortos longe da água. Assim evita multas e problemas com os vizinhos.","a":"normas"},{"t":"Quanto capim de corte plantar","x":"Calcule os quilos de capim fresco por animal por dia, vezes os animais e os dias, e compare com o que seu capim rende por corte. Uma área bem adubada e com água rende muito mais que uma descuidada.","a":"forrajes"},{"t":"Idade de corte e qualidade","x":"O capim novo tem mais proteína e se digere melhor, mas rende menos quilos; o velho rende mais, mas alimenta menos. Busque o ponto médio: antes de florescer e ficar lenhoso.","a":"forrajes"},{"t":"Capins que aguentam seca","x":"Algumas braquiárias, o capim Mombaça e o Colonião aguentam melhor a seca que outros, mas nenhum produz igual sem água. Guarde forragem para a seca mesmo que tenha capins resistentes.","a":"forrajes"},{"t":"Renovar um pasto","x":"Um pasto com muita planta daninha e pouco capim precisa de descanso, controle de daninhas, adubo e às vezes ressemear. Faça no início das chuvas.","a":"forrajes"},{"t":"Plantas daninhas no pasto","x":"As daninhas competem com o capim e algumas são tóxicas. Controle roçando antes que sementem e com bom manejo do pastejo; o superpastejo as favorece.","a":"forrajes"},{"t":"Milho para silagem","x":"Plante variedades de bom rendimento de planta e grão, com boa densidade e adubo. A silagem de milho dá energia; complete com proteína na ração.","a":"forrajes"},{"t":"Vedação do silo","x":"Cubra o silo com plástico grosso sem furos e coloque peso em cima (pneus, sacos de terra). Revise e remende os furos: por onde entra ar, apodrece.","a":"forrajes"},{"t":"Abrir o silo","x":"Espere pelo menos 3 a 4 semanas antes de abrir. Retire de uma só face, por igual, pelo menos uns 15 a 20 cm por dia para que não esquente. Volte a cobrir o que não usar.","a":"forrajes"},{"t":"Feno de boa qualidade","x":"O bom feno é verde, com folhas, cheiro agradável e sem pó nem mofo. Se está amarelo, com muitos talos ou cheira a umidade, alimenta pouco ou faz mal.","a":"forrajes"},{"t":"Cana: quando cortar","x":"A cana para forragem se corta madura, quando tem mais açúcar, e se pica fresca todo dia. Picada velha fermenta e perde valor.","a":"forrajes"},{"t":"Bancos forrageiros","x":"Um banco forrageiro é uma área de capim de corte ou arbustos como leucena, gliricídia ou amoreira perto dos currais, para cortar e dar fresco. Economiza concentrado e dá proteína barata.","a":"forrajes"},{"t":"Amoreira e outros arbustos","x":"A amoreira, o nacedero (Trichanthera) e outros arbustos forrageiros dão folhas com boa proteína. Cortam-se e dão-se picados. Use como complemento, não como a única comida.","a":"forrajes"},{"t":"Cocho e bebedouro juntos ou separados","x":"Coloque o bebedouro perto, mas não colado ao cocho, para que não caia comida na água nem se suje. Que o animal não precise caminhar muito entre um e outro.","a":"instalaciones"},{"t":"Largura do cocho","x":"Um cocho linear costuma ter uns 60 a 70 cm de largura e 30 a 40 cm de profundidade, com a borda do lado do animal na altura do peito. Liso por dentro para limpar fácil.","a":"instalaciones"},{"t":"Barreira do cocho","x":"Um tubo ou cabo sobre o cocho, na altura do pescoço, evita que os animais entrem ou sujem a comida e reduz o desperdício.","a":"instalaciones"},{"t":"Corredor de alimentação","x":"Um corredor firme atrás dos cochos permite servir com carrinho de mão ou caminhão sem entrar no curral, com menos trabalho e mais higiene.","a":"instalaciones"},{"t":"Materiais baratos para currais","x":"Madeira tratada, tubo usado, cercas vivas e sombrite podem baratear o curral. O que não pode faltar: cercas firmes, piso com drenagem, sombra, água e cochos limpos.","a":"instalaciones"},{"t":"Armazenar água","x":"Uma caixa-d'água elevada permite dar água por gravidade mesmo se a bomba falhar. Calcule vários dias de reserva para todo o gado, mais na seca.","a":"instalaciones"},{"t":"Energia e bombeamento","x":"Uma bomba solar ou de vento pode dar água onde não há luz elétrica. Revise filtros e boias toda semana: um bebedouro seco num dia quente é muito grave.","a":"instalaciones"},{"t":"Cercas elétricas","x":"A cerca elétrica é barata para dividir pastos. Mantenha o eletrificador bem aterrado e limpe o mato que toca o arame para que não perca força.","a":"instalaciones"},{"t":"Orientação do curral","x":"Se puder, oriente os telhados de sombra de norte a sul para que a sombra se mova durante o dia e o piso seque, e aproveite o vento para refrescar.","a":"instalaciones"},{"t":"Projeto do curral de confinamento","x":"Um bom curral tem declive de 2 a 4 % para escoar, cocho na parte alta com piso de cimento na frente, bebedouro entre currais, sombra e cercas firmes. Deixe corredores para servir sem entrar no curral.","a":"instalaciones"},{"t":"Piso na frente do cocho","x":"Uma faixa de cimento de uns 3 metros na frente do cocho evita o barro onde mais ficam em pé. É onde mais se nota o investimento na época de chuva.","a":"instalaciones"},{"t":"Tipos de cocho","x":"O cocho deve ser liso, fácil de limpar e na altura do peito do animal, uns 50 a 70 cm. Os de cimento duram mais. Evite cantos onde se acumule alimento velho.","a":"instalaciones"},{"t":"Sombra artificial","x":"Coloque uns 3 m² de sombra por animal, a 3,5 ou 4 metros de altura para que o ar circule. O sombrite serve, mas o telhado de chapa protege também da chuva.","a":"instalaciones"},{"t":"Árvores no curral","x":"As árvores dão boa sombra e baixam o calor. Proteja o tronco com cerca para que não o danifiquem e evite árvores com frutos tóxicos.","a":"instalaciones"},{"t":"Cercas do curral","x":"As cercas devem ser firmes e sem pontas: tubo, réguas de madeira ou cabo. Evite arame farpado dentro do curral porque machuca o couro.","a":"instalaciones"},{"t":"Balança para gado","x":"Sem balança você não sabe quanto ganham nem quanto pagar ou cobrar. Uma balança individual ou de grupo se paga sozinha com melhores compras e vendas.","a":"instalaciones"},{"t":"Misturador de ração","x":"Um misturador dá uma ração uniforme e economiza trabalho. Se você mistura à mão, faça sobre piso limpo, em camadas e virando várias vezes.","a":"instalaciones"},{"t":"Picadeira de capim","x":"Picar o capim de corte em 2 a 5 cm reduz o desperdício e permite misturá-lo com o concentrado. Afie as facas: um picado desigual faz que escolham.","a":"instalaciones"},{"t":"Silo trincheira e silo bolsa","x":"O silo trincheira ou de superfície serve para volumes grandes; o de bolsa, para pequenos produtores. Em qualquer um, o chave é picar fino, compactar bem e cobrir sem ar.","a":"forrajes"},{"t":"Capins de corte em Honduras","x":"Os mais usados são King grass, Taiwan, Camerún, CT-115, Cuba 22 e Maralfalfa. Rendem muito com água e adubo. Corte antes que fiquem lenhosos para que tenham boa proteína.","a":"forrajes"},{"t":"Capins para pastejo","x":"Braquiária (brizantha, decumbens, híbridos), Mombaça e grama-estrela são comuns no trópico. Aguentam o pastejo se forem rotacionados e não sobrecarregados.","a":"forrajes"},{"t":"Silagem: perdas","x":"A silagem se perde pelo ar: mal compactada, mal coberta ou retirando pouco por dia. Retire uma face uniforme todos os dias e descarte o quente, podre ou com mofo.","a":"forrajes"},{"t":"Silagem: quanto fazer","x":"Calcule os quilos de silagem por animal por dia, vezes os dias de seca e as cabeças, e some uns 20 % de perdas. No menu do Rumi, Alimentação, Alimento para o mês, eu dou os quilos que seus lotes consomem.","a":"forrajes"},{"t":"Feno: como fazer","x":"Corte o capim antes que espigue muito, deixe secar ao sol virando, e enfarde quando estiver seco, mas sem que as folhas quebrem. Um feno úmido embolorece e esquenta.","a":"forrajes"},{"t":"Amonização de restolhos","x":"Tratar restolho ou palha com ureia sob plástico melhora sua digestibilidade e proteína. Deve ser feito com a receita de um técnico e arejado antes de fornecer.","a":"forrajes"},{"t":"Rotação de pastos","x":"Divida o terreno em vários piquetes e rotacione o gado para que cada um descanse umas 3 a 5 semanas conforme a chuva. O capim rebrota melhor e alimenta mais animais.","a":"forrajes"},{"t":"Lotação no pasto","x":"Depende do capim, da chuva e do adubo. Sobrecarregar acaba com o pasto e os animais ganham menos. Ajuste a lotação na seca ou suplemente. Uma unidade animal são 450 kg de peso vivo.","a":"forrajes"},{"t":"Cercas vivas","x":"As cercas vivas de gliricídia ou almácega dão postes baratos, sombra e, no caso da gliricídia, forragem. Pode para que não façam sombra demais ao pasto.","a":"forrajes"},{"t":"Cana com ureia","x":"A cana picada com um pouco de ureia é uma forragem de seca usada no trópico. A ureia deve ir bem misturada, em pouca quantidade e com adaptação gradual, seguindo a receita de um técnico.","a":"forrajes"},{"t":"Dia de chegada","x":"Desembarque os animais com calma por uma rampa, leve-os a um curral com sombra, água limpa e feno, e deixe descansar. Não faça o manejo no mesmo dia se vierem de uma viagem longa.","a":"manejo"},{"t":"Primeiras três semanas","x":"É o período de mais risco: doenças respiratórias, pouco consumo e mudanças de dieta. Revise duas vezes ao dia, adapte ao concentrado aos poucos e trate cedo os doentes.","a":"manejo"},{"t":"Identificação com brincos","x":"Coloque brinco em cada animal na entrada. Permite seguir seu peso e sua sanidade e cumprir a rastreabilidade. No app você pode pesar por brinco e ver quem atrasa.","a":"manejo"},{"t":"Pesagem na balança","x":"Pese em balança calibrada, no mesmo horário e antes de servir. Confira a balança com um peso conhecido de vez em quando: um erro de poucos quilos muda seus cálculos de ganho.","a":"manejo"},{"t":"Pesagem por grupo","x":"Se não tiver balança individual, pese o grupo inteiro numa balança de caminhão ou de grupo e divida pelas cabeças. No app você anota o peso médio do lote.","a":"manejo"},{"t":"Jejum antes de pesar","x":"Um animal cheio de comida e água pesa vários quilos a mais. Para comparar, pese sempre nas mesmas condições, de preferência de manhã antes de servir.","a":"manejo"},{"t":"Brete e tronco","x":"Um brete com funil, corredor e tronco de contenção torna o manejo mais seguro e rápido: vacinar, pesar e revisar sem pancadas. É um dos melhores investimentos do confinamento.","a":"manejo"},{"t":"Estresse no manejo","x":"Cada manejo brusco baixa o consumo por um ou dois dias. Agrupe os trabalhos para manejá-los poucas vezes, nas horas frescas e sem gritos nem ferrão.","a":"manejo"},{"t":"Uso do choque elétrico","x":"Use o mínimo possível e nunca na cara nem no ânus. Um animal machucado ou assustado come menos e dá carne com hematomas. Melhor bandeira ou raquete e paciência.","a":"manejo"},{"t":"Castração no confinamento","x":"Castrar animais grandes ao entrar no confinamento os estressa e baixa o ganho por várias semanas. Se for castrar, faça jovens, com higiene e vigiando moscas e bicheira.","a":"manejo"},{"t":"Densidade do curral","x":"Com animais demais por curral há mais barro, brigas, doenças e menos consumo. Como guia, uns 12 m² por animal na terra e 30 cm de cocho por cabeça.","a":"manejo"},{"t":"Registros diários","x":"Todo dia anote o alimento entregue e a leitura de cocho. A cada 3 a 4 semanas, a pesagem. Anote também sanidade, mortes, gastos e vendas. Com isso o app calcula tudo.","a":"manejo"},{"t":"Animais que não comem no início","x":"Muitos animais de pasto não conhecem o cocho. Coloque feno em cima do concentrado e o cocho perto da água. Em poucos dias aprendem a comer.","a":"manejo"},{"t":"Aspersão e ventilação","x":"Molhar os animais com aspersores nas horas de calor, com boa ventilação, ajuda a baixar a temperatura. Molhe o corpo, não só o chão, e evite formar barro.","a":"manejo"},{"t":"Consumo noturno","x":"Com muito calor, parte do consumo passa para a noite. Garanta comida no cocho no fim da tarde e água a noite toda.","a":"manejo"},{"t":"Transporte para a venda","x":"Embarque nas horas frescas, sem sobrecarregar o caminhão, com piso antiderrapante e sem pancadas. Uma viagem ruim baixa o peso e deixa hematomas que o frigorífico desconta.","a":"manejo"},{"t":"Jejum antes da venda","x":"Muitos compradores aplicam um desconto ou quebra pelo enchimento. Pergunte ao seu comprador como pesa e desconta e coloque nos seus cálculos: em Mais você ajusta o desconto de venda.","a":"manejo"},{"t":"Cães no curral","x":"Os cães assustam o gado e podem transmitir doenças. Mantenha-os fora dos currais e do depósito de ração.","a":"manejo"},{"t":"Segurança dos trabalhadores","x":"Trabalhe com brete e tronco, nunca sozinho com animais bravos, e use luvas ao tratar feridas ou tocar animais doentes ou mortos. Várias doenças do gado passam para as pessoas.","a":"manejo"},{"t":"Plano de trabalho semanal","x":"Todo dia: alimento, água, leitura de cochos e revisar doentes. Toda semana: limpar bebedouros e cochos, revisar cercas e armazém. A cada 3 a 4 semanas: pesagem. No menu do Rumi, Meu confinamento, O que faço hoje, eu digo o pendente.","a":"manejo"},{"t":"Saída escalonada","x":"Nem todos chegam ao peso ao mesmo tempo. Vender primeiro os mais pesados e deixar os demais algumas semanas a mais pode melhorar o preço médio. No app você pode anotar vendas parciais.","a":"manejo"},{"t":"Rotina diária do curral","x":"Cedo: leitura de cochos, primeira entrega e revisão de doentes. Meio da manhã: revisar água e sombra. Tarde: segunda entrega e outra revisão. Anote tudo no app na hora para não esquecer.","a":"manejo"},{"t":"Sinais de um lote que vai bem","x":"Cochos limpos na hora de servir, animais ruminando deitados, esterco em torta, pouca tosse, pelo brilhante e ganho uniforme entre pesagens. Se algo disso mudar, revise ração, água e sanidade.","a":"manejo"},{"t":"Pesar para decidir","x":"Pesar não é só para saber quanto pesam: diz se a ração funciona, se há animais atrasados e quando vender. Pese a cada 21 a 28 dias e compare o ganho de cada animal no app.","a":"manejo"},{"t":"Animal que não ganha peso","x":"Se um animal não sobe enquanto o lote sim, examine: dentes, patas, parasitas, doença ou que não o deixem comer. Separe se necessário; se não melhorar, considere vendê-lo antes para não perder mais.","a":"manejo"},{"t":"Animais velhos ou com dentes ruins","x":"Os animais com dentes gastos ou faltando comem e aproveitam menos. Na compra, revise a boca; no confinamento, dê ração mais picada ou venda antes.","a":"manejo"},{"t":"Mansidão e temperamento","x":"Os animais nervosos comem menos, se machucam e dão carne de pior qualidade. Na compra, observe como reagem no brete; no curral, maneje com calma para que amansem.","a":"manejo"},{"t":"Gado de diferentes procedências","x":"Juntar animais de várias fazendas aumenta o risco de doenças e brigas. Se não houver outra opção, receba com quarentena, vacinas e boa observação nas primeiras semanas.","a":"manejo"},{"t":"Tourinhos que brigam","x":"Os inteiros de origens diferentes brigam ao serem juntados. Agrupe-os no início, com espaço suficiente, vários pontos de água e cocho comprido. Separe os muito agressivos.","a":"manejo"},{"t":"Castração com faca, elástico ou burdizzo","x":"Qualquer método deve ser feito jovem, com higiene, controle de moscas e alívio da dor conforme seu veterinário. Em animais grandes o estresse e a perda de peso são maiores.","a":"manejo"},{"t":"Marcar a ferro","x":"Marque num só lugar, com o ferro na temperatura certa, uns segundos e com o animal bem contido. Evite a perna: danifica o couro de mais valor. Trate e vigie a ferida contra a bicheira.","a":"manejo"},{"t":"Brincos: como colocar","x":"Coloque o brinco no centro da orelha, entre as veias grandes, com o aplicador limpo e desinfetado. Evite a época de mais moscas ou trate a ferida. Anote o número no app.","a":"manejo"},{"t":"Brinco perdido","x":"Se um animal perde o brinco, identifique-o de novo o quanto antes com um brinco novo e anote no app que é o mesmo animal (editar brinco), para não perder seu histórico de pesos.","a":"manejo"},{"t":"Registrar raça e cor","x":"Anotar raça e cor de cada animal ajuda a identificá-lo e a comparar que tipo de animal rende mais. No app se anota por animal ao criar o lote.","a":"manejo"},{"t":"Comparar tipos de animais","x":"Com os registros por animal você pode ver se ganham mais os cruzados ou os Brahman, os inteiros ou os castrados, os comprados de um fornecedor ou de outro. Assim compra melhor na próxima vez.","a":"manejo"},{"t":"Embarque e desembarque sem estresse","x":"Use a rampa, mova grupos pequenos, sem gritos nem paus, e deixe que os animais vejam o caminho. Com boa luz e sem sombras estranhas entram sozinhos.","a":"manejo"},{"t":"Viagens longas","x":"Em viagens de muitas horas, saia nas horas frescas, não sobrecarregue, revise os animais nas paradas e na chegada dê água, feno e descanso antes do manejo.","a":"manejo"},{"t":"Receber animais à noite","x":"Se chegarem à noite, desembarque com luz, dê água e feno e deixe descansar. O manejo sanitário faça no dia seguinte, com luz e calma.","a":"manejo"},{"t":"Observar os recém-chegados","x":"Nos primeiros 21 dias observe de manhã e à tarde: que comam, bebam água, ruminem e não tussam. Anote os que ficam atrás do cocho: costumam ser os primeiros doentes.","a":"manejo"},{"t":"Animais que não bebem água","x":"Alguns animais de pasto não conhecem o bebedouro de boia. Deixe o bebedouro transbordar um pouco nos primeiros dias para que escutem a água, ou coloque um tanque aberto.","a":"manejo"},{"t":"Dar nomes ou grupos","x":"Nomear os lotes pela data de entrada ou pelo fornecedor facilita acompanhá-los. No app cada lote tem nome, tipo, raça, fornecedor e ração.","a":"manejo"},{"t":"Saúde dos trabalhadores","x":"Quem maneja o gado deve ter suas vacinas (tétano), usar luvas com animais doentes, lavar as mãos e não comer nos currais. Um trabalhador treinado cuida melhor do gado.","a":"manejo"},{"t":"Treinar o pessoal","x":"Explique aos seus trabalhadores como ler o cocho, revisar doentes, anotar no app e manejar com calma. Um bom vaqueiro evita mortes, pancadas e desperdício de alimento.","a":"manejo"},{"t":"Manejo na época de chuvas","x":"Com chuva: limpe o esterco com mais frequência, cuide da drenagem, proteja o alimento da água, revise as patas e vigie pneumonias e parasitas.","a":"manejo"},{"t":"Manejo na época seca","x":"Na seca: garanta água de sobra, sombra, forragem guardada (silagem, feno, cana) e controle a poeira molhando os currais. É boa época para comprar animais magros.","a":"manejo"},{"t":"Desmame antes do confinamento","x":"Os bezerros desmamados de uma vez e enviados ao confinamento no mesmo dia adoecem mais. O ideal é que cheguem desmamados, vacinados e acostumados ao cocho algumas semanas antes.","a":"manejo"},{"t":"Como se ganha no confinamento","x":"Você ganha se o que pagam pelo animal gordo supera o que você pagou por ele mais tudo o que gastou para engordá-lo. As três alavancas são: comprar bem, produzir o quilo barato e vender bem.","a":"negocio"},{"t":"Preço por lote ou por animal","x":"Na compra de um lote costuma-se pagar um preço médio para todos. No app você pode anotar o preço de todo o lote (repartido por igual entre os animais) ou o preço de cada animal se comprou um por um.","a":"negocio"},{"t":"Custo de compra por animal","x":"Se você comprou o lote a preço médio, cada animal carrega a mesma parte do custo. Se comprou separados, cada um leva seu próprio preço. Isso muda a margem de cada animal, não a do lote.","a":"negocio"},{"t":"Comparar preço por quilo e por cabeça","x":"Para comparar ofertas, leve tudo a preço por quilo: divida o preço por cabeça pelo peso real. Um animal barato por cabeça pode sair caro por quilo se pesar pouco.","a":"negocio"},{"t":"Frete e comissões","x":"O frete, as comissões e os gastos da compra fazem parte do custo do lote. Anote ao criar o lote; um frete alto pode comer a margem de animais leves.","a":"negocio"},{"t":"Margem por cabeça","x":"É o que sobra por animal no final: preço de venda menos compra, alimento, sanidade e gastos. O app estima por lote ao chegar à meta e calcula ao vender.","a":"negocio"},{"t":"Vender por peso ou no olho","x":"Vender no olho quase sempre favorece o comprador experiente. Pese na balança e negocie por quilo ou libra. Se não tiver balança, peça para pesar numa confiável.","a":"negocio"},{"t":"Quando o negócio não compensa","x":"Se o preço de compra mais o custo de engordar supera o que vão pagar, não compre esse lote ou mude de estratégia: animais mais leves, ração mais barata ou vender em outra época.","a":"negocio"},{"t":"Economia em alimento","x":"Pequenas economias na ração se multiplicam: baixar o custo do quilo de mistura uns centavos, em centenas de animais por meses, é muito dinheiro. Revise preços e formule com frequência.","a":"negocio"},{"t":"Mortes e seu custo","x":"Cada animal morto leva o que custou mais tudo o que comeu. Uma mortalidade baixa, menor que 1 a 2 %, é chave para a margem. Investir em recepção e sanidade se paga sozinho.","a":"negocio"},{"t":"Levar as contas do confinamento","x":"Anote todas as compras, alimento, sanidade, gastos e vendas no app. Com isso você vê o custo real por quilo ganho e a margem de cada lote, e pode decidir com números.","a":"negocio"},{"t":"Comparar lotes vendidos","x":"Ao fechar cada lote, compare seu ganho diário, conversão, custo por quilo e margem com os anteriores. Assim você vê que compras, rações e épocas funcionam melhor.","a":"negocio"},{"t":"Preços em libras e quilos","x":"Em Honduras muito gado se negocia por libra em pé. Um preço por libra se converte a quilo multiplicando por 2,2. O app trabalha na unidade que você escolher em Mais.","a":"negocio"},{"t":"Rendimento e preço por carcaça","x":"Se pagam por carcaça, o preço por quilo é maior, mas sobre menos quilos (54 a 58 % do peso vivo). Compare: preço por carcaça × rendimento deve superar o preço em pé para convir.","a":"negocio"},{"t":"Plano de compras","x":"Decida quantos animais, de que peso e em que mês vai comprar, quanto alimento vai precisar e quando vai vender. Ter o plano evita comprar às pressas e caro.","a":"negocio"},{"t":"Farelo e caroço de algodão","x":"O farelo de algodão dá proteína mais barata que a soja e o caroço de algodão fornece gordura e fibra. Têm gossipol, que em excesso faz mal, sobretudo a animais jovens e touros reprodutores. Em novilhos de confinamento use em quantidades moderadas e o formulador diz quanto.","a":"nutricion"},{"t":"Grãos secos de destilaria (DDGS)","x":"São o que sobra do milho depois de tirar o etanol: trazem proteína, energia e fibra digestível. Têm muito fósforo e enxofre, então não passe de um terço da ração sem assessoria e cuide do cálcio para evitar cálculos urinários.","a":"nutricion"},{"t":"Palmiste","x":"A torta de palmiste é barata na costa norte e fornece fibra e um pouco de proteína e gordura. É pouco apetitosa no início: misture bem e suba aos poucos. Serve para baratear a ração, não para substituir toda a soja.","a":"nutricion"},{"t":"Casca de arroz","x":"Quase não alimenta: é fibra dura e com muita sílica. Só serve como enchimento de fibra em pouca quantidade. Não use como forragem principal.","a":"nutricion"},{"t":"Restolho e palhada de milho","x":"O restolho de milho é fibra barata para a seca, mas com pouca proteína e energia. Pique e complete com uma fonte de proteína. Serve como forragem efetiva na ração de confinamento.","a":"nutricion"},{"t":"Palha e sabugo","x":"O sabugo moído é fibra de pouca qualidade. A espiga inteira moída (grão com sabugo) é bom alimento: fornece energia e um pouco de fibra, com menos risco de acidose que o grão sozinho.","a":"nutricion"},{"t":"Sorgo forrageiro e sorgo vassoura","x":"O sorgo forrageiro serve para corte ou silagem e aguenta mais a seca que o milho. Quando novo ou estressado pela seca pode ter um tóxico (ácido cianídrico): não dê muito jovem nem recém-rebrotado sem assessoria.","a":"nutricion"},{"t":"Silagem de sorgo","x":"Rende bem onde chove pouco. Corta-se com o grão pastoso e ensila-se igual ao milho: picado fino, bem compactado e coberto sem ar. Tem um pouco menos de energia que a de milho.","a":"nutricion"},{"t":"Energia da ração","x":"A energia é o que mais determina quanto ganham por dia. Vem sobretudo de grãos como milho e sorgo, e de subprodutos como polpa ou casca de soja. O formulador do app usa energia líquida para manutenção e para ganho.","a":"nutricion"},{"t":"Proteína da ração","x":"No confinamento busca-se de 12 a 14 % de proteína na matéria seca. Com pouca proteína ganham menos; com muita você gasta dinheiro a mais. As fontes comuns são soja, farelo de algodão, DDGS e ureia com cuidado.","a":"nutricion"},{"t":"Cálcio e fósforo","x":"As rações com muito grão ou farelo trazem pouco cálcio e muito fósforo. É preciso acrescentar calcário para que haja mais ou menos o dobro de cálcio que de fósforo. Isso previne cálculos urinários.","a":"nutricion"},{"t":"Calcário (carbonato de cálcio)","x":"É a fonte barata de cálcio para a ração. Normalmente vai em pouca quantidade, cerca de 1 % da mistura. O formulador do app o acrescenta sozinho.","a":"nutricion"},{"t":"Sal na ração","x":"No curral o sal vai na mistura ou no núcleo mineral, cerca de meio por cento. Também ajuda a que bebam mais água, o que previne cálculos urinários.","a":"nutricion"},{"t":"Microminerais","x":"Zinco, cobre, selênio, cobalto e iodo são necessários em pouca quantidade, mas são chave para crescer e se defender de doenças. Um bom núcleo mineral os traz. Não acrescente selênio por conta própria: em excesso é tóxico.","a":"nutricion"},{"t":"Bicarbonato de sódio","x":"Alguns confinamentos o acrescentam como tamponante do rúmen em rações com muito grão, sobretudo na adaptação. Não substitui uma boa adaptação nem forragem suficiente.","a":"nutricion"},{"t":"Gordura na ração","x":"Um pouco de gordura sobe a energia, mas mais de 5 a 6 % de gordura total na ração prejudica a digestão da fibra no rúmen. Não acrescente óleo sem assessoria.","a":"nutricion"},{"t":"Tamanho de partícula","x":"Moa ou quebre o grão grosso: muito fino fermenta rápido e dá acidose e timpanismo. A forragem picada de 2 a 5 cm ajuda a ruminar. Evite que escolham: uma mistura uniforme é comida por igual.","a":"nutricion"},{"t":"Mistura úmida e fermentação","x":"Uma mistura com silagem, polpa ou melaço esquenta e estraga em um ou dois dias. Misture o que será comido no dia e limpe as sobras do cocho.","a":"nutricion"},{"t":"Mudar de ração","x":"Qualquer mudança de ração faça em 5 a 7 dias, misturando a velha com a nova. As mudanças bruscas causam diarreia, acidose ou que parem de comer.","a":"nutricion"},{"t":"Horário de alimentação","x":"Sirva no mesmo horário todos os dias, de preferência duas vezes: cedo e no fim da tarde. A constância mantém o rúmen estável. No app você coloca os horários de entrega em Mais.","a":"nutricion"},{"t":"Ração balanceada comercial","x":"O concentrado comercial é prático, mas quase sempre mais caro que misturar seus próprios ingredientes. Compare o custo por quilo ganho. No app você o anota como uma ração com seu preço.","a":"nutricion"},{"t":"Preços dos ingredientes","x":"O formulador usa os preços da sua lista de ingredientes. Atualize quando comprar para que a dieta mais barata seja de fato a mais barata.","a":"nutricion"},{"t":"Suplementação no pasto","x":"No pasto, um suplemento com proteína e energia na seca evita que percam peso. Os blocos multinutricionais são práticos, mas verifique que não comam tudo de uma vez se tiverem ureia.","a":"nutricion"},{"t":"Blocos multinutricionais","x":"São blocos com melaço, ureia, minerais e fibra que o animal lambe. Servem no pasto na seca. Se tiverem ureia, não dê a animais com fome sem adaptação.","a":"nutricion"},{"t":"Água e consumo","x":"Se bebem pouca água, comem pouco e ganham pouco. O bebedouro deve estar limpo, perto do cocho e com boa vazão para que vários bebam ao mesmo tempo.","a":"nutricion"},{"t":"Qualidade da água","x":"A água com muito sal, sulfatos ou contaminação baixa o consumo e o ganho. Se tiver dúvidas do poço ou do rio, faça uma análise de água.","a":"nutricion"},{"t":"O que um novilho precisa na ração","x":"Água, energia (grãos, melaço, subprodutos), proteína (soja, farelo de algodão, DDGS, ureia com cuidado), fibra efetiva (capim, feno, restolho), minerais e vitaminas. Se faltar um, os demais não rendem. O formulador do app balanceia tudo por você.","a":"nutricion"},{"t":"Forragem efetiva","x":"É a fibra longa que faz o animal ruminar: capim picado de 2 a 5 cm, feno ou restolho. Mesmo que a ração seja de terminação, deixe de 8 a 15 % de forragem; com menos aumenta o risco de acidose e timpanismo.","a":"nutricion"},{"t":"Rações para as etapas do confinamento","x":"No início, mais forragem e proteína para adaptar e crescer; no crescimento, mais grão; na terminação, a ração com mais energia para engordurar. Troque de uma para outra de forma gradual, em 5 a 7 dias.","a":"nutricion"},{"t":"Terminação","x":"É a última etapa, em que o animal completa o peso e engordura. Precisa de uma ração com muita energia e cuidados para não provocar acidose. Dura conforme o peso de venda e o que seu comprador paga pela gordura.","a":"nutricion"},{"t":"Ganho esperado com diferentes rações","x":"Como guia: no pasto sem suplemento, de 0,3 a 0,6 kg por dia conforme a época; sobretudo com silagem, de 0,7 a 0,9; com ração de curral bem balanceada, de 1,2 a 1,6 ou mais. Depende muito da raça, do peso e da sanidade.","a":"nutricion"},{"t":"Subprodutos da agroindústria","x":"Polpa cítrica, casca de soja, farelo, DDGS, palmiste, melaço, banana de descarte e resíduos de padaria podem baratear a ração. Revise umidade, preço por quilo de matéria seca, disponibilidade o ano todo e que não tragam fungos nem lixo.","a":"nutricion"},{"t":"Preço por matéria seca","x":"Compare alimentos pelo custo em matéria seca, não por quilo como vem. Um alimento muito úmido pode parecer barato e sair caro. Divida o preço por quilo pela fração de matéria seca.","a":"nutricion"},{"t":"Farelo de coco","x":"O farelo de coco (copra) fornece proteína média e gordura; é usado em rações de confinamento na América Central. Use em quantidades moderadas e cuide que não esteja rançoso nem com mofo.","a":"nutricion"},{"t":"Banana de descarte","x":"A banana ou o plátano verde de descarte dá energia barata, mas traz muita água e pouca proteína. Pique, dê fresco e complete com proteína e fibra. Suba aos poucos para evitar diarreias.","a":"nutricion"},{"t":"Casca de abacaxi e frutas","x":"Os resíduos de frutas podem dar energia, mas trazem muita água, fermentam rápido e às vezes vêm com químicos. Use frescos, em pouca quantidade, sem mofo, e consulte seu técnico antes de torná-los parte fixa da ração.","a":"nutricion"},{"t":"Milho inteiro ou moído","x":"Muitos confinamentos dão o milho inteiro para baixar custos e reduzir a acidose; perde-se um pouco de grão no esterco. Quebrado grosso é mais bem aproveitado. Moído muito fino aumenta o risco de acidose. O sorgo sim deve ser processado.","a":"nutricion"},{"t":"Grão úmido e silagem de grão","x":"O grão colhido úmido e ensilado se conserva e se digere bem, mas precisa de boa compactação e vedação. Mal feito embolorece. Introduza aos poucos como qualquer grão.","a":"nutricion"},{"t":"Minerais no pasto e no curral","x":"No pasto, sal mineral à vontade em saleiros cobertos. No curral, o núcleo mineral vai misturado na ração, normalmente de 1,5 a 2 % da matéria seca. Assim você cobre cálcio, fósforo, sal e microminerais.","a":"nutricion"},{"t":"Vitamina A na seca","x":"O pasto seco da seca traz pouca vitamina A. Animais que vêm de uma seca longa podem precisar de vitaminas na entrada ou de um núcleo que as traga. Consulte seu veterinário.","a":"nutricion"},{"t":"Água na ração","x":"As rações com silagem ou polpa trazem muita água e os animais bebem menos no bebedouro. Mesmo assim, a água limpa sempre deve estar disponível. Com calor podem beber o dobro.","a":"nutricion"},{"t":"Quanta água por quilo de alimento","x":"Como guia, um bovino bebe de 3 a 5 litros de água para cada quilo de matéria seca que come, mais com calor. Se o consumo de água cair de repente, revise o bebedouro antes de tudo.","a":"nutricion"},{"t":"Ração que se separa","x":"Se no cocho sobram só partes da mistura, os animais estão escolhendo. Pique a forragem mais uniforme, umedeça um pouco a mistura (por exemplo com melaço diluído) e sirva mais vezes ao dia.","a":"nutricion"},{"t":"Cocho vazio por horas","x":"Se o cocho fica vazio muitas horas, ao servir comem com desespero e aumenta o risco de acidose. Suba a ração 3 a 5 % ou sirva uma entrega a mais.","a":"nutricion"},{"t":"Sobra muito alimento","x":"Se sobra muito, baixe a ração 3 a 5 %, tire o velho e verifique se o alimento mudou, está molhado ou com mofo, ou se os animais estão doentes ou com calor.","a":"nutricion"},{"t":"Alimento com cheiro estranho","x":"Um alimento com cheiro forte de vinagre, podre ou de mofo pode estar fermentado ou contaminado. Não sirva: pode causar diarreia, rejeição ou intoxicação.","a":"nutricion"},{"t":"Aditivos: quais valem a pena","x":"Os ionóforos como a monensina melhoram a conversão e ajudam contra a acidose quando bem usados. Outros aditivos têm efeitos pequenos ou variáveis. Use só na dose do fabricante e com a assessoria do seu técnico, e respeite o que seu comprador pedir.","a":"nutricion"},{"t":"Pré-mistura e núcleo","x":"A pré-mistura traz minerais e vitaminas concentrados em pouca quantidade; o núcleo costuma trazer também sal e às vezes proteína ou aditivos. Ambos devem ser muito bem misturados: primeiro com uma parte do grão e depois com o resto.","a":"nutricion"},{"t":"Formular com preços reais","x":"A ração mais barata muda com os preços. Atualize os preços dos seus ingredientes no formulador cada vez que comprar e formule de novo: às vezes um ingrediente novo baixa muito o custo por quilo ganho.","a":"nutricion"},{"t":"Alimentar ao amanhecer e ao entardecer","x":"O gado come mais nas horas frescas. Servir cedo e no fim da tarde, com o cocho pronto antes do calor, melhora o consumo em climas quentes.","a":"nutricion"},{"t":"Consumo no início do confinamento","x":"Nos primeiros dias comem pouco: de 1,5 a 2 % do peso em matéria seca. Em duas a três semanas sobem até 2,5 a 2,8 %. Não force; suba a ração à medida que deixam o cocho limpo.","a":"nutricion"},{"t":"Aflatoxinas no milho","x":"O milho danificado por chuva, insetos ou má secagem pode trazer aflatoxinas que não se veem. Compre grão seco, sadio e de fornecedores confiáveis, e guarde com menos de 13 a 14 % de umidade.","a":"nutricion"},{"t":"Silagem: umidade na colheita","x":"O milho ou sorgo para silagem se corta com uns 30 a 35 % de matéria seca (grão leitoso a pastoso). Muito úmido escorre e apodrece; muito seco não se compacta e embolorece.","a":"nutricion"},{"t":"Aditivos para silagem","x":"Melaço ou inoculantes podem melhorar a fermentação da silagem, sobretudo com capins de pouco açúcar. Não substituem o básico: picar bem, compactar muito e vedar sem ar.","a":"nutricion"},{"t":"Complexo respiratório bovino","x":"É a soma de estresse, vírus e bactérias que ataca os pulmões, sobretudo nas primeiras semanas do confinamento. Previne-se com bom transporte, recepção tranquila, vacinas que seu veterinário indicar e currais ventilados. Trate cedo: um animal tratado tarde fica atrasado.","a":"sanidad"},{"t":"Como revisar animais doentes","x":"Percorra o curral de manhã e à tarde. Observe os que não se aproximam do cocho, têm orelhas caídas, olhos fundos, muco, tosse, respiram rápido, mancam ou têm a barriga funda. Separe, meça a temperatura e avise o veterinário.","a":"sanidad"},{"t":"Curral de enfermaria","x":"Tenha um curral à parte, com sombra, água e boa forragem, para os doentes. Assim você trata fácil, comem sem competir e não contagiam o resto.","a":"sanidad"},{"t":"Desidratação","x":"Sinais: olhos fundos, pele que demora a voltar ao ser beliscada, focinho seco e abatimento. Dê água limpa à vontade e sombra. Se não bebe ou está muito fraco, o veterinário pode dar soro.","a":"sanidad"},{"t":"Pneumonia intersticial","x":"Alguns animais no final do confinamento respiram com muito esforço e a boca aberta, sem febre alta. É uma urgência: mova-o pouco, dê sombra e chame o veterinário.","a":"sanidad"},{"t":"Pododermatite ou podridão do casco","x":"É uma infecção entre as unhas: a pata incha, cheira mal e o animal manca muito. Vem do barro e das feridas. Trata-se com o veterinário e previne-se com currais secos.","a":"sanidad"},{"t":"Abscessos","x":"São caroços com pus, muitas vezes por injeções sujas ou feridas. Use agulhas limpas, injete no pescoço e não na perna. O veterinário os abre e limpa se necessário.","a":"sanidad"},{"t":"Onde injetar","x":"Injete no pescoço, à frente da paleta, nunca na perna nem na garupa: ali se danifica a carne mais cara. Use agulha limpa e do calibre adequado, e troque de agulha com frequência.","a":"sanidad"},{"t":"Agulhas e seringas","x":"Troque a agulha a cada poucos animais ou se entortar ou sujar. Usar a mesma agulha em todo o lote passa doenças como a tristeza parasitária. Lave e guarde limpas as seringas.","a":"sanidad"},{"t":"IBR e BVD","x":"São vírus que atacam as vias respiratórias e a digestão e baixam as defesas. Fazem parte do complexo respiratório. Existem vacinas; seu veterinário diz se convêm para seu confinamento.","a":"sanidad"},{"t":"Edema maligno","x":"É uma infecção clostridial em feridas ou injeções sujas: inchaço que avança rápido, febre e morte. Previne-se com a vacina clostridial e com higiene ao injetar, castrar ou descornar.","a":"sanidad"},{"t":"Enterotoxemia","x":"É uma clostridiose que mata rápido animais que comem muito alimento rico de uma vez. Previne-se com vacina clostridial e com mudanças de ração graduais.","a":"sanidad"},{"t":"Hemoglobinúria bacilar","x":"É uma clostridiose que dá urina vermelha e morte rápida. A vacina clostridial completa a previne; pergunte ao seu veterinário se a sua a inclui.","a":"sanidad"},{"t":"Fascíola ou baratinha do fígado","x":"É um parasita do fígado comum em regiões úmidas com caramujos. Os animais emagrecem e o fígado é condenado no frigorífico. Trata-se com produtos específicos como o closantel, conforme seu veterinário.","a":"sanidad"},{"t":"Berne","x":"É a larva de uma mosca que entra sob a pele e forma caroços com um furo. Danifica o couro e baixa o ganho. Controla-se com produtos para moscas e larvas conforme seu veterinário.","a":"sanidad"},{"t":"Resistência a vermífugos","x":"Se um vermífugo deixa de funcionar, pode haver resistência. Rotacione grupos de produtos, use a dose completa pelo peso real e vermifugue só quando necessário.","a":"sanidad"},{"t":"Resistência a carrapaticidas","x":"Se depois do banho continuam muitos carrapatos, pode haver resistência. Prepare bem a dose, molhe todo o corpo, rotacione produtos e peça ao veterinário um teste de resistência.","a":"sanidad"},{"t":"Biossegurança","x":"Controle quem entra nos currais, limpe botas e equipamento, mantenha a quarentena de animais novos e não deixe os caminhões de outras fazendas entrarem até os currais.","a":"normas"},{"t":"Controle de ratos","x":"Os ratos comem e sujam o alimento e transmitem doenças como a leptospirose. Mantenha o armazém limpo, o grão sobre paletes e use armadilhas ou iscas longe do alcance do gado.","a":"sanidad"},{"t":"Doenças de notificação ao SENASA","x":"Você deve avisar o SENASA se suspeitar de raiva, antraz, bicheira, febre aftosa, tuberculose, brucelose ou qualquer morte em massa sem explicação. Avisar a tempo protege toda a região.","a":"normas"},{"t":"Intoxicação por nitratos","x":"Acontece com pastos ou sorgo muito adubados ou estressados pela seca. Sinais: respiram com dificuldade, tremem, mucosas escuras e morrem rápido. Chame o veterinário imediatamente.","a":"sanidad"},{"t":"Sinais vitais normais","x":"Num bovino adulto sadio: temperatura de 38 a 39,5 °C, de 10 a 30 respirações por minuto em repouso e sem calor, pulso de 60 a 80 por minuto e de 1 a 2 movimentos do rúmen por minuto ao pressionar o flanco esquerdo. Se estiver muito longe disso, algo vai mal.","a":"sanidad"},{"t":"Como medir a temperatura","x":"Use um termômetro digital no reto, lubrificado e apoiado contra a parede do reto, por um minuto. Faça com o animal contido no brete, na sombra e antes de movimentá-lo muito: o exercício e o sol a sobem.","a":"sanidad"},{"t":"Revisar as mucosas","x":"Levante a pálpebra ou olhe as gengivas: devem estar rosadas. Pálidas ou brancas indicam anemia (parasitas, tristeza parasitária); amarelas, problemas do fígado ou tristeza; roxas ou azuladas, falta de oxigênio. Qualquer uma dessas é para chamar o veterinário.","a":"sanidad"},{"t":"Ruminação e movimentos do rúmen","x":"Um animal sadio passa várias horas por dia ruminando, sobretudo deitado. Se para de ruminar, o rúmen não se move ou faz pouco barulho, pode ter acidose, indigestão ou febre. Examine e pergunte ao veterinário.","a":"sanidad"},{"t":"Animal deitado que não se levanta","x":"Um animal que não se levanta pode ter fratura, pancada, doença metabólica, intoxicação ou estar muito fraco. Não o arraste. Dê sombra, água e comida ao alcance, mude-o de lado a cada poucas horas se puder e chame o veterinário.","a":"sanidad"},{"t":"Animal que tosse","x":"A tosse com muco, febre ou respiração rápida costuma ser pneumonia. A tosse seca e isolada pode ser poeira ou vermes do pulmão. Separe, meça a temperatura e consulte o veterinário; em recém-chegados, aja rápido.","a":"sanidad"},{"t":"Pneumonia: tratar a tempo","x":"Na pneumonia cada dia conta: um animal tratado no primeiro dia se recupera muito melhor que um tratado no terceiro. Revise os recém-chegados de manhã e à tarde e tenha um acordo com seu veterinário para agir logo. Anote cada tratamento e sua carência.","a":"sanidad"},{"t":"Ceratite por poeira e sol","x":"A poeira, os espinhos do capim e o sol forte irritam os olhos. Se vir lacrimejamento, baixe a poeira molhando o curral e controle as moscas. Se aparecer uma mancha branca, consulte o veterinário.","a":"sanidad"},{"t":"Feridas no curral","x":"Pregos, arames, tábuas quebradas e cochos com quinas causam feridas que infeccionam e atraem a bicheira. Percorra o curral toda semana, conserte o que corta e trate toda ferida no mesmo dia.","a":"sanidad"},{"t":"Tratar uma ferida","x":"Lave a ferida com água limpa e sabão, retire a sujeira, aplique um antisséptico e um produto que repila moscas e bicheira. Revise diariamente até fechar. Se estiver inchada, quente ou cheirar mal, chame o veterinário.","a":"sanidad"},{"t":"Inchaço no pescoço ou na perna","x":"Um inchaço no local de uma injeção pode ser um abscesso ou uma reação ao produto. Se cresce rápido, crepita ao tocar ou o animal tem febre, pode ser edema maligno: é urgência veterinária.","a":"sanidad"},{"t":"Prolapso retal","x":"Se sair parte do reto, proteja de pancadas e moscas, mantenha limpo e úmido e chame o veterinário logo. Costuma vir de tosse forte, diarreia ou esforço.","a":"sanidad"},{"t":"Hérnia de umbigo","x":"Um caroço mole no umbigo que entra ao ser empurrado costuma ser uma hérnia. Se for pequena, pode não dar problemas; se crescer, ficar dura ou dolorida, o veterinário deve examiná-la. Evite comprar animais com hérnias grandes.","a":"sanidad"},{"t":"Picadas de cobra","x":"O animal picado costuma ter um inchaço grande e doloroso, muitas vezes na cara ou nas patas, e pode sangrar. Mantenha quieto e na sombra e chame o veterinário; não corte nem chupe a ferida.","a":"sanidad"},{"t":"Raio e eletrocussão","x":"Se vários animais aparecem mortos juntos depois de uma tempestade, perto de uma árvore ou de uma cerca de arame, pode ter sido um raio. Mesmo assim, avise o veterinário para descartar antraz ou intoxicações antes de mover os corpos.","a":"sanidad"},{"t":"Leptospirose na fazenda","x":"Controle ratos, evite que o gado beba de poças e águas paradas e use luvas ao manejar urina, fetos ou animais doentes. Seu veterinário dirá se convém vacinar na sua região.","a":"sanidad"},{"t":"Vermes do pulmão","x":"Alguns vermes vivem nos pulmões e causam tosse, sobretudo em animais jovens que vêm de pastos úmidos. Os vermífugos de amplo espectro costumam controlá-los; consulte o veterinário se a tosse continuar depois de vermifugar.","a":"sanidad"},{"t":"Exame de fezes","x":"Um exame de fezes em laboratório conta os ovos de parasitas e diz se é preciso vermifugar e com quê. Serve para não gastar com vermífugos a mais e para detectar resistência.","a":"sanidad"},{"t":"Vacinas: como conservá-las","x":"As vacinas se guardam refrigeradas, entre 2 e 8 °C, sem congelar e sem sol. Leve ao curral em caixa térmica, use o frasco aberto no mesmo dia e não misture produtos na mesma seringa. Uma vacina mal guardada não protege.","a":"sanidad"},{"t":"Vacinar bem","x":"Vacine animais sadios e descansados, no pescoço, com agulha limpa e a dose do rótulo. Respeite o reforço, porque muitas vacinas não protegem com uma só aplicação. Anote produto, lote do frasco e data.","a":"sanidad"},{"t":"Reações depois de vacinar","x":"É comum um pouco de inchaço ou abatimento por um ou dois dias. Se um animal treme, respira mal ou incha muito minutos depois, pode ser uma reação alérgica: chame o veterinário imediatamente.","a":"sanidad"},{"t":"Tratamentos: seguir as indicações","x":"Termine o tratamento completo que o veterinário indicou mesmo que o animal melhore antes, respeite os dias entre doses e anote cada aplicação em Sanidade. Parar antes favorece recaídas e resistência.","a":"sanidad"},{"t":"Quando chamar o veterinário","x":"Chame logo se houver mortes sem explicação, vários doentes ao mesmo tempo, febre alta, animais que não se levantam, respiração com a boca aberta, inchaço rápido, sangramento pelo nariz ou boca, ou sintomas nervosos. Melhor uma ligação a mais que um animal perdido.","a":"sanidad"},{"t":"Necropsia: por que fazer","x":"Quando morre um animal sem causa clara, a necropsia feita pelo veterinário diz o que aconteceu e ajuda a salvar os demais. Nunca abra um cadáver que sangra pelo nariz, boca ou ânus: pode ser antraz.","a":"sanidad"},{"t":"Abscessos no fígado","x":"São frequentes em confinamentos com muito grão e acidose: baixam o ganho e o frigorífico condena o fígado. Previnem-se com boa adaptação ao concentrado, forragem suficiente e cochos que não fiquem vazios por horas.","a":"sanidad"},{"t":"Mancadeira por piso duro ou pedras","x":"Os currais pedregosos ou com cimento áspero machucam os cascos. Mantenha o piso uniforme, sem pedras soltas, e separe os mancos num curral macio para que se recuperem.","a":"sanidad"},{"t":"Estresse e defesas baixas","x":"Transporte, jejuns, mistura de lotes, calor e manejo brusco baixam as defesas, e aí aparecem as doenças. Por isso a recepção tranquila, a água e a boa comida valem tanto quanto as vacinas.","a":"sanidad"},{"t":"Registro de tratamentos","x":"Para cada tratamento anote animal ou lote, produto, dose, via, data e dias de carência. No app você faz isso em Registrar, Sanidade, e ele avisa se você quiser vender antes de terminar a carência.","a":"sanidad"},{"t":"Carência com vários produtos","x":"A carência é o tempo desde a última aplicação até o animal poder ir ao frigorífico, e muda conforme o produto: leia sempre no rótulo. Se aplicou vários produtos, respeite a carência mais longa.","a":"sanidad"}];
window.RUMI_FICHAS=[{"t":"Bicheira (Cochliomyia): a emergência desde 2023","a":"actualidad","r":"A bicheira do gado (Cochliomyia hominivorax), erradicada da América do Norte e Central por décadas com a liberação de moscas estéreis, voltou a aparecer no Panamá em 2023 e se espalhou por toda a América Central até o México. É a ameaça sanitária mais importante da região nestes anos.","s":[{"h":"O que aconteceu","p":["Durante anos, a barreira de moscas estéreis no Darién (Panamá) conteve a praga.","Desde 2023 os casos aumentaram no Panamá e depois na Costa Rica, Nicarágua, Honduras, El Salvador, Guatemala e Belize.","No fim de 2024 chegou ao México e em 2025 continuou avançando para o norte.","Também houve casos em pessoas, principalmente com feridas expostas."]},{"h":"Por que é grave","p":["A mosca põe ovos em qualquer ferida, até no umbigo ou onde um carrapato foi arrancado.","As larvas comem carne viva e o animal pode morrer em poucos dias.","Também afeta cães, cavalos, porcos, animais silvestres e pessoas."]},{"h":"O que fazer na sua fazenda","p":["Revise todo dia feridas, umbigos, castrações, descornas e marcações.","Trate toda ferida com um produto larvicida e repelente autorizado.","Evite castrar, descornar e marcar nos meses com mais moscas, ou proteja bem as feridas.","Informe os casos ao serviço veterinário oficial: é doença de notificação obrigatória."]},{"h":"Para o negócio","p":["A praga provocou fechamentos temporários de fronteiras ao trânsito de gado.","Confira os requisitos vigentes antes de comprar ou vender gado entre países."]}],"rel":["Bicheira (Cochliomyia)","Técnica do inseto estéril","Feridas e curativos","Doenças de notificação obrigatória"]},{"t":"Técnica do inseto estéril","a":"actualidad","r":"Para acabar com a bicheira, milhões de moscas são criadas em fábricas, esterilizadas com radiação e soltas de pequenos aviões. Ao acasalar com as fêmeas selvagens não nascem larvas, e a população cai.","s":[{"h":"Como funciona","p":["A fêmea da bicheira acasala uma única vez na vida.","Se acasala com um macho estéril, seus ovos não eclodem.","Soltando muito mais moscas estéreis do que selvagens, a praga desaparece em algumas gerações."]},{"h":"História","p":["Com essa técnica, EUA, México e América Central eliminaram a praga entre os anos 1950 e 2000.","A planta do Panamá (COPEG) mantinha a barreira no Darién.","Após o ressurgimento, EUA e México anunciaram novas plantas e centros de dispersão para aumentar a produção de moscas."]},{"h":"Seu papel","p":["A técnica só funciona se, além disso, as feridas forem tratadas e os casos informados.","Colabore com os técnicos do programa quando visitarem sua região."]}],"rel":["Bicheira (Cochliomyia): a emergência desde 2023","Programas oficiais de sanidade"]},{"t":"Fronteiras e comércio de gado","a":"actualidad","r":"As doenças mudam o comércio de gado de um dia para o outro. O caso mais recente foi o fechamento dos EUA ao gado em pé do México por causa da bicheira em 2024 e 2025, com efeitos nos preços de toda a região.","s":[{"h":"O que aconteceu","p":["O México exportava cerca de um milhão de bezerros por ano para os EUA.","Com a chegada da bicheira ao México, os EUA suspenderam as importações em novembro de 2024; reabriram brevemente e voltaram a suspender em 2025.","Isso baixou o preço do gado de exportação no México e mudou os fluxos de gado na América Central."]},{"h":"Lição","p":["A sanidade da região é um bem de todos: um surto fecha mercados.","O trânsito ilegal de gado entre países espalha doenças."]},{"h":"No seu confinamento","p":["Compre gado com guia de trânsito e documentos em ordem.","Acompanhe as notícias do serviço veterinário oficial antes de comprar ou vender em outra região."]}],"rel":["Bicheira (Cochliomyia): a emergência desde 2023","Guia de trânsito e rastreabilidade","Preços do gado e ciclo pecuário"]},{"t":"Preços do gado e ciclo pecuário","a":"actualidad","r":"Os preços do gado sobem e descem em ciclos de vários anos. Em 2024 e 2025 o preço do gado nos EUA bateu recordes porque o rebanho estava no nível mais baixo em uns 70 anos, e isso puxou os preços na região.","s":[{"h":"Como funciona o ciclo","p":["Com preços altos, os criadores seguram as fêmeas para cria: sai menos gado e o preço sobe mais.","Anos depois há mais bezerros, a oferta cresce e o preço cai.","As secas aceleram a venda de vacas e alteram o ciclo."]},{"h":"Situação recente","p":["As secas de 2020 a 2023 nos EUA reduziram o rebanho.","Com menos gado e a fronteira com o México fechada, o preço do bezerro e do novilho subiu a máximos históricos.","Os preços altos do bezerro também encarecem a compra para quem engorda."]},{"h":"No seu confinamento","p":["Com bezerro caro, a margem depende de engordar com eficiência e vender bem.","Use a calculadora de preço máximo de compra antes de cada compra.","Não aposte tudo que o preço vai continuar subindo."]}],"rel":["Sazonalidade de preços","Preço máximo de compra","Margem de compra e venda","Riscos do confinamento"]},{"t":"Resistência aos antimicrobianos","a":"actualidad","r":"Cada vez mais bactérias resistem aos antibióticos. A Organização Mundial da Saúde a considera uma das maiores ameaças à saúde. O uso em animais é parte do problema e parte da solução.","s":[{"h":"O que está acontecendo","p":["Infecções que antes se curavam fácil agora não respondem.","A abordagem 'Saúde Única' une saúde humana, animal e ambiental.","Muitos países proibiram os antibióticos como promotores de crescimento e exigem receita veterinária."]},{"h":"Antibióticos críticos","p":["Alguns antibióticos são reservados para pessoas, como certas cefalosporinas de última geração e a colistina.","Seu uso em animais é restrito em muitos países."]},{"h":"No seu confinamento","p":["Use antibióticos só com diagnóstico e na dose correta.","Previna com vacinas, boa recepção e biossegurança.","Registre cada tratamento no app: os compradores pedem isso cada vez mais."]}],"rel":["Uso responsável de antibióticos","Micróbios e antibióticos","Receita e uso de medicamentos veterinários"]},{"t":"Resistência dos carrapatos aos carrapaticidas","a":"actualidad","r":"Os carrapatos do gado na América Central ficaram resistentes a muitos produtos: piretroides, organofosforados, amitraz e, em algumas regiões, ivermectina e fipronil. Banhar com mais frequência não resolve: piora o problema.","s":[{"h":"Como a resistência se forma","p":["Cada banho deixa vivos os carrapatos mais resistentes, que se reproduzem.","Doses baixas, misturas caseiras e banhos muito frequentes aceleram a resistência.","Usar sempre o mesmo grupo químico também."]},{"h":"O que fazer","p":["Faça um teste de resistência em laboratório para saber o que funciona na sua fazenda.","Rode os grupos químicos por temporada, não a cada banho.","Banhe só quando for necessário e com a dose e o volume corretos.","Combine com rotação de pastos e animais mais resistentes."]},{"h":"No seu confinamento","p":["No curral, os carrapatos se controlam muito melhor do que no pasto.","Registre cada banho no app para respeitar as carências da carne."]}],"rel":["Carrapatos","Genética e resistência a carrapatos","Carências e resíduos"]},{"t":"Resistência dos parasitas aos vermífugos","a":"actualidad","r":"Os vermes do estômago e do intestino também ficaram resistentes, sobretudo às ivermectinas. Muitas fazendas vermifugam sem saber se o produto ainda funciona.","s":[{"h":"Sinais","p":["Animais vermifugados que continuam com pelo opaco e pouco ganho.","Contagem de ovos nas fezes que não cai depois do tratamento."]},{"h":"O que fazer","p":["Faça a contagem de ovos antes e 10 a 14 dias depois de vermifugar: se não cair mais de 90 %, há resistência.","Vermifugue conforme exames, não por calendário fixo.","Dose pelo peso real do animal, não no olho.","Não use ivermectina de longa ação em todo o rebanho sem necessidade."]},{"h":"No seu confinamento","p":["Na chegada, o tratamento com dois grupos diferentes (por exemplo um benzimidazol e uma lactona macrocíclica) é uma prática recomendada por muitos veterinários.","Pese ou estime bem o peso para não subdosar."]}],"rel":["Vermifugação e resistência","Parasitas internos","Parasitas e nutrição"]},{"t":"Metano entérico e como reduzi-lo","a":"actualidad","r":"O metano que o gado arrota é um gás de efeito estufa muito mais potente que o CO2, embora dure menos na atmosfera. Reduzi-lo é ao mesmo tempo um desafio ambiental e uma oportunidade, porque o metano é energia perdida.","s":[{"h":"Dados principais","p":["A pecuária produz uma parte importante do metano de origem humana.","O metano aquece cerca de 80 vezes mais que o CO2 em 20 anos, mas se decompõe em uns 12 anos.","Reduzi-lo tem efeito rápido no clima."]},{"h":"O que o reduz","p":["Pastagens de melhor qualidade e leguminosas.","Engordas mais curtas e eficientes: menos dias de vida por quilo de carne.","Menos mortalidade e animais saudáveis.","Aditivos como ionóforos, gorduras e outros novos."]},{"h":"No seu confinamento","p":["Tudo o que melhora a conversão reduz o metano por quilo de carne.","Alguns compradores e programas já pagam ou premiam práticas de baixa emissão."]}],"rel":["Metano e arroto","Aditivos que reduzem o metano","Pegada de carbono da carne"]},{"t":"Aditivos que reduzem o metano","a":"actualidad","r":"Nos últimos anos foram aprovados e testados aditivos que reduzem o metano do arroto. O mais estudado é o 3-NOP; também há algas marinhas, óleos e taninos.","s":[{"h":"3-NOP","p":["Bloqueia a enzima que as arqueias usam para produzir metano.","Reduz o metano cerca de 30 % em vacas leiteiras e mais em gado confinado.","Aprovado na União Europeia em 2022 e nos EUA em 2024, entre outros países."]},{"h":"Algas e outros","p":["A alga vermelha Asparagopsis reduz muito o metano em testes, mas sua produção e segurança ainda estão em estudo.","Taninos de leguminosas e árvores, óleos essenciais e gorduras também ajudam um pouco."]},{"h":"No seu confinamento","p":["Hoje quase não são usados na América Central por custo e disponibilidade.","O que você tem à mão: boa ração, ionóforos e leguminosas."]}],"rel":["Metano entérico e como reduzi-lo","Ionóforos","Leguminosas e árvores forrageiras"]},{"t":"Pegada de carbono da carne","a":"actualidad","r":"A pegada de carbono mede os gases de efeito estufa emitidos por quilo de carne produzida. Inclui metano do animal, óxido nitroso do esterco e dos fertilizantes, e CO2 da energia e da mudança de uso da terra.","s":[{"h":"Dados principais","p":["A FAO estima que a pecuária como um todo emite entre 12 e 15 % dos gases de origem humana.","A maior parte, na carne bovina, vem do metano do arroto.","Desmatar floresta para pasto dispara a pegada."]},{"h":"O que a reduz","p":["Mais quilos de carne por hectare e por animal.","Engordas eficientes e animais saudáveis.","Árvores nos pastos, que armazenam carbono.","Pastagens bem manejadas que acumulam carbono no solo."]},{"h":"No seu confinamento","p":["Melhorar o ganho diário e reduzir a mortalidade reduz a pegada.","Seus registros no app servem de base se um dia você precisar de uma certificação."]}],"rel":["Metano entérico e como reduzi-lo","Sistemas silvipastoris","Pecuária livre de desmatamento"]},{"t":"Pecuária livre de desmatamento","a":"actualidad","r":"Grandes compradores e alguns países exigem cada vez mais que a carne não venha de terras desmatadas. A União Europeia aprovou um regulamento que inclui a carne bovina, cuja aplicação vem sendo adiada.","s":[{"h":"O que exigem","p":["Demonstrar com mapas ou coordenadas que a fazenda não desmatou depois de uma data de corte.","Rastreabilidade do animal desde o nascimento.","Cumprir as leis ambientais e trabalhistas do país."]},{"h":"Por que importa na América Central","p":["Parte da carne da região é exportada.","Os compradores de exportação repassam essas exigências aos frigoríficos e aos pecuaristas."]},{"h":"No seu confinamento","p":["Não desmate para fazer pasto: além de ser ilegal em muitos lugares, pode fechar mercados para você.","Guarde notas de compra, guias e registros de origem dos seus animais."]}],"rel":["Rastreabilidade digital e certificações","Pegada de carbono da carne","Ambiente e manejo de resíduos"]},{"t":"Pecuária regenerativa","a":"actualidad","r":"A pecuária regenerativa busca produzir carne enquanto melhora o solo, a água e a biodiversidade. Usa pastejo planejado, árvores e menos químicos.","s":[{"h":"Práticas","p":["Pastejo rotacionado com descansos suficientes.","Sistemas silvipastoris e cercas vivas.","Proteger nascentes e margens de rios.","Reduzir o uso de fertilizantes químicos e queimadas."]},{"h":"Benefícios","p":["Mais pasto e mais estável na seca.","Solos que guardam mais água e carbono.","Melhor imagem e acesso a mercados especiais."]},{"h":"No seu confinamento","p":["Se você engorda a pasto, essas práticas baixam custos no longo prazo.","Programas de pagamento por serviços ambientais podem apoiar parte do investimento."]}],"rel":["Sistemas silvipastoris","Pastejo rotacionado","Recuperar um pasto degradado"]},{"t":"Brincos eletrônicos e RFID","a":"actualidad","r":"Os brincos eletrônicos (RFID) têm um chip com um número único que é lido com um leitor ou uma balança. Tornam a rastreabilidade e a pesagem muito mais rápidas e sem erros de anotação.","s":[{"h":"Como funcionam","p":["O brinco não tem bateria: o leitor o ativa por rádio ao se aproximar.","O número é lido em segundos e salvo junto com o peso ou o tratamento.","Vários países da região os usam em seus sistemas oficiais de rastreabilidade."]},{"h":"Vantagens","p":["Menos erros ao anotar brincos.","Histórico completo de cada animal.","Requisito cada vez mais comum para exportar."]},{"h":"No seu confinamento","p":["Se seu país os fornece ou exige, coloque o número do brinco no app.","No app você pode usar o brinco visual; se um dia usar leitor, o número é o mesmo."]}],"rel":["Identificação de animais","Registros e rastreabilidade","Rastreabilidade digital e certificações"]},{"t":"Pesagem automática e sensores","a":"actualidad","r":"As balanças automáticas pesam os animais quando vão beber água, sem levá-los ao tronco. Junto com outros sensores, dão dados diários de cada animal.","s":[{"h":"Tecnologias","p":["Balanças de passagem junto ao bebedouro com leitor de brincos.","Sensores de atividade e ruminação em coleiras ou brincos.","Câmeras que estimam peso e condição corporal."]},{"h":"O que você ganha","p":["Ver a curva de peso sem estressar o gado.","Detectar doentes antes que pareçam mal.","Decidir o dia certo de venda."]},{"h":"No seu confinamento","p":["Ainda são caras para fazendas pequenas, mas baixam de preço a cada ano.","Enquanto isso, pesar a cada 3 a 4 semanas com balança comum e anotar no app dá quase a mesma informação."]}],"rel":["Pesagem","Balança","Brincos eletrônicos e RFID"]},{"t":"Cercas virtuais, drones e satélites","a":"actualidad","r":"Novas tecnologias permitem manejar piquetes sem arame, contar gado pelo ar e medir o pasto do espaço.","s":[{"h":"Cercas virtuais","p":["Coleiras com GPS que avisam com som e um estímulo leve quando o animal se aproxima do limite.","Já são usadas em alguns países de pastejo; na América Central ainda são raras."]},{"h":"Drones","p":["Servem para contar gado, revisar cercas e aguadas e procurar animais perdidos.","É preciso respeitar as normas de voo do país."]},{"h":"Satélites","p":["Imagens gratuitas mostram quanto pasto verde há em cada piquete.","Ajudam a planejar a lotação e a época seca."]},{"h":"No seu confinamento","p":["Comece pelo simples: registros em dia no app e um bom plano de piquetes.","A tecnologia serve mais quando você já tem dados organizados."]}],"rel":["Lotação e amostragem de forragem","Contar o gado","Plano forrageiro para a seca"]},{"t":"Dados e apps na engorda","a":"actualidad","r":"Levar os números no celular mudou a forma de engordar: saber quanto cada animal ganha, quanto custa o quilo e quando vender, em vez de adivinhar.","s":[{"h":"O que se consegue","p":["Ver o ganho real de cada lote e compará-lo com a meta.","Saber o custo por quilo ganho e a margem antes de vender.","Lembrar tratamentos, carências, pesagens e compras de ração."]},{"h":"Boas práticas","p":["Anotar no mesmo dia, mesmo que seja pouco.","Pesar com regularidade: sem pesos, os números são estimados.","Fazer backup dos dados toda semana."]},{"h":"No Rumentis","p":["Tudo funciona sem internet e fica salvo no seu celular.","O clima precisa de internet só para se atualizar.","Rumi ajuda você a ler seus números e decidir."]}],"rel":["Registros econômicos","Backup e restaurar","Indicadores-chave do confinamento"]},{"t":"El Niño, La Niña e o Corredor Seco","a":"actualidad","r":"El Niño e La Niña são mudanças na temperatura do Oceano Pacífico que alteram as chuvas na América Central. El Niño costuma trazer seca ao Corredor Seco; La Niña, mais chuva.","s":[{"h":"El Niño","p":["Menos chuva e veranico mais longo na vertente do Pacífico.","O forte El Niño de 2023 e 2024 causou secas e perdas de pasto e de colheitas na região."]},{"h":"La Niña","p":["Mais chuvas, inundações e mais umidade.","Mais parasitas, carrapatos, mancas e lama nos currais."]},{"h":"O Corredor Seco","p":["Faixa que vai da Guatemala à Costa Rica, com secas frequentes.","Inclui boa parte do sul e do oeste de Honduras."]},{"h":"No seu confinamento","p":["Acompanhe as previsões oficiais do seu país para a temporada.","Com alerta de El Niño: guarde silagem e feno, e compre menos animais.","Com alerta de La Niña: prepare drenagens e currais secos."]}],"rel":["Época seca","Época de chuvas","Plano forrageiro para a seca","Ondas de calor mais frequentes"]},{"t":"Ondas de calor mais frequentes","a":"actualidad","r":"Os últimos anos estão entre os mais quentes já registrados no mundo, e as ondas de calor na América Central são mais frequentes e intensas. O estresse por calor já é um custo permanente da engorda.","s":[{"h":"Efeitos no gado","p":["Caem o consumo e o ganho diário.","Sobe a mortalidade em currais sem sombra.","Piora a qualidade da carne."]},{"h":"Adaptar-se","p":["Sombra para todos os animais: natural ou de tela.","Água abundante e fresca, com bebedouros na sombra.","Comida ao entardecer e de madrugada.","Genética adaptada: zebu, cruzamentos e pelo curto (slick)."]},{"h":"No seu confinamento","p":["Veja no Rumi o clima de hoje e o índice de calor.","Planeje o embarque e o trabalho no tronco para as horas frescas."]}],"rel":["Estresse por calor","Resfriamento noturno","Sombra","Índice de calor"]},{"t":"Influenza aviária em vacas leiteiras","a":"actualidad","r":"Em 2024 o vírus da influenza aviária H5N1 foi detectado pela primeira vez em vacas leiteiras dos EUA. Espalhou-se por muitos rebanhos leiteiros daquele país. É um caso de estudo de como um vírus pode saltar de espécie.","s":[{"h":"O que se sabe","p":["Afeta sobretudo vacas em lactação: o leite cai e muda de aspecto.","O vírus está no leite cru; a pasteurização o destrói.","Houve alguns casos leves em pessoas que trabalhavam com vacas."]},{"h":"Gado de corte","p":["Os casos em gado de corte foram muito raros.","A carne bem cozida não é considerada um risco."]},{"h":"No seu confinamento","p":["Mantenha aves silvestres e de quintal longe dos cochos e bebedouros.","Informe ao veterinário oficial qualquer doença estranha em vários animais ao mesmo tempo."]}],"rel":["Quarentena e biossegurança","Doenças que passam para as pessoas","Doenças de notificação obrigatória"]},{"t":"Dermatose nodular contagiosa","a":"actualidad","r":"A dermatose nodular contagiosa é uma doença viral dos bovinos que causa nódulos na pele, febre e grandes perdas. Espalhou-se pela Ásia e em 2025 chegou à Itália e à França. Não está nas Américas.","s":[{"h":"O que causa","p":["Nódulos duros na pele de todo o corpo.","Febre, perda de peso e couros danificados.","É transmitida por insetos que picam."]},{"h":"Por que importa para você","p":["Mostra como as doenças exóticas avançam com o comércio e o clima.","Se chegasse às Américas, fecharia mercados na hora."]},{"h":"O que fazer","p":["Informe ao serviço oficial qualquer animal com muitos nódulos na pele e febre.","Não importe animais nem produtos sem autorização."]}],"rel":["Febre aftosa e doenças exóticas","Doenças de notificação obrigatória","Quarentena e biossegurança"]},{"t":"Febre aftosa nas Américas","a":"actualidad","r":"A América Central está livre de febre aftosa, e na América do Sul a maioria dos países já a controlou. Em 2025 a Organização Mundial de Saúde Animal reconheceu o Brasil como livre de aftosa sem vacinação.","s":[{"h":"Situação","p":["América Central, México, EUA e Canadá estão livres sem vacinação.","A América do Sul avançou muito nas últimas décadas.","Em 2025 houve surtos na Europa (Alemanha, Hungria e Eslováquia), que lembram que nenhum país está a salvo."]},{"h":"Por que importa","p":["Ser livre de aftosa permite exportar carne para os melhores mercados.","Um único surto fecha todas as exportações."]},{"h":"No seu confinamento","p":["Informe imediatamente bolhas na boca e nas patas, baba e manqueira em vários animais.","Não compre gado nem produtos de contrabando."]}],"rel":["Febre aftosa e doenças exóticas","Programas oficiais de sanidade","Doenças de notificação obrigatória"]},{"t":"Carne cultivada e proteínas alternativas","a":"actualidad","r":"Nos últimos anos surgiram carnes feitas de plantas e carne cultivada em laboratório a partir de células. Até agora sua participação no mercado é muito pequena frente à carne bovina.","s":[{"h":"O que são","p":["Carnes vegetais: feitas com soja, ervilha e óleos, com sabor e textura parecidos com carne.","Carne cultivada: células de animal multiplicadas em tanques; aprovada em poucos países e com produção muito pequena.","Alguns estados dos EUA proibiram a venda de carne cultivada."]},{"h":"O que acontece com a demanda","p":["O consumo mundial de carne bovina continua crescendo em países de renda média.","As vendas de carnes vegetais cresceram e depois estagnaram em vários países."]},{"h":"No seu confinamento","p":["A carne bovina natural, produzida com boas práticas e com história, continua muito valorizada.","Conte a história da sua produção: é uma vantagem frente aos produtos de fábrica."]}],"rel":["Valor nutritivo da carne","Bem-estar animal: o que os mercados exigem"]},{"t":"Bem-estar animal: o que os mercados exigem","a":"actualidad","r":"Supermercados, restaurantes e países importadores exigem cada vez mais que o gado seja criado com bom trato: sem dor desnecessária, com sombra, água e manejo tranquilo.","s":[{"h":"O que mais se pede","p":["Castração e descorna precoces e com controle da dor.","Transporte com tempos e cargas razoáveis.","Abate com insensibilização efetiva.","Nada de choque elétrico como ferramenta habitual."]},{"h":"As cinco liberdades","p":["Livre de fome e sede.","Livre de desconforto.","Livre de dor, ferimentos e doenças.","Livre de medo e estresse.","Livre para expressar seu comportamento normal."]},{"h":"No seu confinamento","p":["O bom trato também dá mais ganho e melhor carne.","Guarde registros de manejo: são a prova diante de um comprador exigente."]}],"rel":["Bem-estar animal","Bem-estar na lei e no mercado","Dor no bovino"]},{"t":"Rastreabilidade digital e certificações","a":"actualidad","r":"Poder acompanhar cada animal desde o nascimento até o prato já é requisito para muitos mercados. Os países da região avançam em registros oficiais com brincos e bases de dados.","s":[{"h":"O que inclui","p":["Registro da fazenda e do proprietário.","Identificação única de cada animal.","Registro de trânsitos com guias.","Registro de tratamentos e vacinas."]},{"h":"Certificações","p":["Boas práticas agropecuárias.","Livre de desmatamento.","Bem-estar animal.","Produção orgânica ou a pasto em alguns mercados."]},{"h":"No seu confinamento","p":["Mantenha em dia suas guias, brincos oficiais e registros de tratamentos.","O app guarda o histórico de cada lote e você pode exportá-lo para o Excel."]}],"rel":["Registros e rastreabilidade","Guia de trânsito e rastreabilidade","Brincos eletrônicos e RFID","Baixar para o Excel"]},{"t":"Custos de insumos e volatilidade","a":"actualidad","r":"Desde 2021 os preços de grãos, fertilizantes e combustíveis tiveram altas e baixas fortes por causa da guerra na Ucrânia, do clima e do transporte. Isso bate direto no custo da engorda.","s":[{"h":"O que mudou","p":["O milho e a soja subiram muito em 2021 e 2022 e depois caíram.","Os fertilizantes tiveram preços recorde em 2022.","O frete marítimo e o combustível subiram em vários momentos."]},{"h":"Como se proteger","p":["Compre ração antecipadamente quando o preço estiver baixo, se tiver um depósito seguro.","Procure subprodutos locais como alternativa.","Calcule o custo da ração cada vez que um preço mudar."]},{"h":"No seu confinamento","p":["O app recalcula o custo por quilo ganho com seus preços.","Use o depósito para saber quanta ração você tem e para quantos dias dá."]}],"rel":["Custo da ração","Subprodutos para a ração","Depósito de ração no app","Análise de sensibilidade"]},{"t":"Demanda de carne na região","a":"actualidad","r":"Na América Central o consumo de carne bovina cresce com a população e o turismo, e vários países exportam carne. A Nicarágua é um dos maiores exportadores de carne bovina da região.","s":[{"h":"Tendências","p":["Mais consumo nas cidades, supermercados e restaurantes.","Mais exigência de qualidade, cortes e apresentação.","Exportações para os EUA, México, Caribe e outros mercados."]},{"h":"Oportunidades","p":["Novilhos jovens e bem terminados para cortes de qualidade.","Carne com história: a pasto, de fazenda, com bom trato.","Vendas diretas e marcas locais."]},{"h":"No seu confinamento","p":["Converse com seu frigorífico e seus compradores sobre qual animal pagam melhor.","Ajuste sua engorda a esse mercado."]}],"rel":["Canais de venda","Contratos com compradores","Qualidade da carcaça"]},{"t":"Produtos proibidos que continuam aparecendo","a":"actualidad","r":"Ainda se vendem ilegalmente substâncias para engordar como o clembuterol. São um perigo para a saúde das pessoas e podem fechar mercados inteiros.","s":[{"h":"Clembuterol","p":["É proibido em animais de consumo em praticamente todo o mundo.","Seus resíduos na carne podem causar tremores, taquicardia e problemas graves em pessoas.","Há casos de intoxicação humana na região."]},{"h":"Outros","p":["A ractopamina é proibida em muitos mercados, como a União Europeia e a China.","Hormônios sem registro, antibióticos como promotores e produtos sem rótulo."]},{"h":"No seu confinamento","p":["Nunca use produtos sem registro nem recomendações de vendedores sem receita.","Os frigoríficos fazem testes de resíduos: um positivo pode levar a sanções."]}],"rel":["Produtos proibidos na alimentação","Carências e resíduos","Inocuidade da carne"]},{"t":"Ciência recente sobre a nutrição do zebu","a":"actualidad","r":"Nas últimas décadas, sobretudo no Brasil, a nutrição do Nelore e seus cruzamentos foi muito estudada. Hoje se sabe que o zebu tem necessidades um pouco diferentes das raças europeias.","s":[{"h":"Descobertas","p":["A exigência de mantença do zebu é um pouco menor que a das raças europeias.","Responde muito bem à suplementação a pasto na época seca.","As tabelas brasileiras BR-CORTE reúnem esses dados."]},{"h":"Aplicação","p":["Rações ajustadas ao zebu evitam gastar demais.","A suplementação proteica na seca e energética nas chuvas dá muito bom resultado."]},{"h":"No seu confinamento","p":["As calculadoras do Rumi levam em conta que seu gado é principalmente zebu e cruzados."]}],"rel":["Exigências: tabelas modernas","Suplementação no pasto","Adaptação do zebu ao trópico"]},{"t":"Usar o menu do Rumi","a":"app","r":"Rumi trabalha com um menu: você escolhe uma área e ele mostra tudo o que pode fazer ali com seus dados.","s":[{"h":"Como usar","p":["Toque no botão do Rumi embaixo à direita.","Escolha uma área: Meu confinamento, Meus lotes, Anotar, Alimentação, Saúde, O que meu animal tem?, Calculadoras, Dinheiro e vendas, Guia de engorda ou Usar o app.","Dentro da área, toque no que você quer saber ou fazer.","O botão Menu leva de volta às áreas e a seta volta um passo."]},{"h":"Temas do guia","p":["Cada tema abre com um resumo e suas partes: o que é, sinais, o que fazer, prevenção, números e erros comuns.","Toque em Ver todo o tema para ler completo ou em uma parte para ir direto.","No final aparecem temas relacionados."]},{"h":"Calculadoras","p":["Pedem só os números necessários.","Usam sua unidade de peso e sua moeda."]}],"rel":["Tela Hoje e avisos","Projeções no app"]},{"t":"Criar um lote no app","a":"app","r":"Um lote é um grupo de animais que entrou junto. Ele é criado uma vez e depois recebe as anotações de ração, pesagens e todo o resto.","s":[{"h":"Passos","p":["Toque em Registrar e depois em Novo lote.","Passo 1: nome, data de entrada, peso meta, tipo, fornecedor e ração.","Passo 2: cada animal com brinco, peso, raça, cor e foto.","Passo 3: preço de compra e frete.","Toque em Criar lote."]},{"h":"Preço de compra","p":["Preço do lote: um preço para todos (por quilo ou o total). O custo é dividido igualmente entre os animais.","Preço por animal: você escreve o que pagou por cada um na sua linha."]},{"h":"Dicas","p":["Enter passa ao próximo campo e adiciona linhas sozinho.","Você pode colar uma lista de pesos de uma vez.","A raça do animal anterior é copiada na linha nova."]}],"rel":["Animais e fotos","Pesar no app"]},{"t":"Animais e fotos","a":"app","r":"Cada animal tem sua ficha com foto, peso, ganho, raça, cor, custo e histórico.","s":[{"h":"Ver os animais","p":["Entre no lote e toque na aba Animais.","Ordene por brinco, mais pesado, melhor ou pior ganho.","Toque em um animal para ver sua ficha."]},{"h":"Fotos","p":["Ao criar o lote, toque no quadro Foto de cada linha.","Na ficha, toque na foto para vê-la ou para tirá-la se não houver.","Em Editar você pode trocá-la ou removê-la.","As fotos ficam salvas no celular."]},{"h":"Editar","p":["Na ficha toque em Editar para mudar brinco, peso de entrada, raça, cor, preço ou nota.","Remover este animal o tira do lote."]}],"rel":["Criar um lote no app","Pesar no app"]},{"t":"Anotar ração no app","a":"app","r":"Anotar a ração de cada trato permite calcular consumo, conversão e custos reais.","s":[{"h":"Passos","p":["Toque em Registrar e depois em Ração, ou no botão do trato que falta em Hoje.","Escolha o lote e a ração.","Escreva os quilos (ou libras) fornecidos.","Você pode anotar a leitura de cocho."]},{"h":"Dicas","p":["Anote na hora para não esquecer.","Se você dá a mesma quantidade a vários lotes, anote todos na mesma tela.","Configure seus horários em Configuração para que Hoje lembre você."]}],"rel":["Leitura de cochos","Tela Hoje e avisos"]},{"t":"Pesar no app","a":"app","r":"As pesagens são a base do ganho, das projeções e dos animais atrasados.","s":[{"h":"Por animal","p":["Toque em Registrar, Pesagem e escolha o lote.","Escreva o peso de cada brinco; Enter passa ao próximo. Use a lupa para achar um brinco.","O app marca em vermelho os pesos estranhos."]},{"h":"Por grupo","p":["Se você não pesa por brinco, pode anotar o peso médio ou total do grupo."]},{"h":"Depois","p":["O app atualiza o ganho, a data de saída e os atrasados.","Veja no lote a aba Animais."]}],"rel":["Pesagem","Animais atrasados"]},{"t":"Sanidade e carências no app","a":"app","r":"Anotar cada tratamento com sua carência protege você de vender animais com resíduos.","s":[{"h":"Passos","p":["Toque em Registrar, Sanidade.","Escolha o lote ou os animais tratados.","Tipo, produto, cabeças, custo e dias de carência."]},{"h":"Avisos","p":["Hoje mostra os lotes em carência.","Ao vender um lote em carência, o app avisa você."]}],"rel":["Carências e resíduos","Vacinação"]},{"t":"Registrar uma venda","a":"app","r":"A venda fecha o lote e calcula a margem real.","s":[{"h":"Passos","p":["Toque em Registrar, Venda.","Escolha o lote, as cabeças (ou os brincos), os quilos e o preço.","Informe o comprador."]},{"h":"Depois","p":["Se você vendeu tudo, o lote passa para vendidos com seus números finais.","Compare a margem com outros lotes em Gráficos."]}],"rel":["Preparar a venda","Registros econômicos"]},{"t":"Registrar uma morte","a":"app","r":"Anotar as mortes com a causa mantém certas as cabeças e os custos e ajuda a encontrar problemas.","s":[{"h":"Passos","p":["Toque em Registrar, Morte.","Escolha o lote, quantas cabeças ou o brinco, e a causa."]},{"h":"Por que importa","p":["A mortalidade e seu custo aparecem no lote.","Se uma causa se repete, você vê rápido."]}],"rel":["Morte de um animal","Mortalidade e seu custo"]},{"t":"Despesas no app","a":"app","r":"As despesas de um lote ou gerais fazem o custo por quilo e a margem serem reais.","s":[{"h":"Passos","p":["Toque em Registrar, Despesa.","Valor, categoria e se é de um lote ou geral.","Detalhe opcional."]},{"h":"Ver e apagar","p":["As despesas gerais aparecem em Mais, Despesas gerais.","As do lote, no Histórico do lote."]}],"rel":["Estrutura de custos","Registros econômicos"]},{"t":"Rações e formular dieta","a":"app","r":"As rações guardam o custo por quilo de cada mistura. Formular dieta calcula a mais barata com seus preços.","s":[{"h":"Criar uma ração","p":["Em Mais, Rações e dietas, Nova ração.","Nome, custo por quilo e ingredientes opcionais."]},{"h":"Formular","p":["Em Mais, Formular dieta, ou pelo Rumi, Alimentação.","Informe o peso e o ganho, ative seus ingredientes e corrija os preços.","Toque em Formular e salve o resultado como ração."]}],"rel":["Formular uma ração","Custo da ração"]},{"t":"Tela Hoje e avisos","a":"app","r":"Hoje é seu resumo do dia: ração pendente, avisos e como vão seus lotes.","s":[{"h":"O que mostra","p":["Cabeças, ganho, conversão e custo por quilo.","Os tratos do dia.","Atenção: animais atrasados, consumo baixo, lotes sem pesar, carências, mortes.","Próximo passo recomendado. Feche-o com o X quando já o tiver feito."]},{"h":"Uso","p":["Toque em qualquer aviso para ir resolvê-lo."]}],"rel":["Anotar ração no app","Usar o menu do Rumi"]},{"t":"Gráficos no app","a":"app","r":"Todos os seus números em gráficos para ver tendências e comparar lotes.","s":[{"h":"O que há","p":["Peso, ganho diário, consumo, conversão, custos e margem.","Por lote ou todos, e por período."]},{"h":"Dica","p":["Revise os gráficos depois de cada pesagem."]}],"rel":["Indicadores-chave do confinamento","Comparar lotes no app"]},{"t":"Backup e restaurar","a":"app","r":"O backup é um arquivo com todos os seus dados. Com ele você recupera tudo se perder ou trocar de celular.","s":[{"h":"Baixar","p":["Em Mais, Seus dados, Baixar backup.","Guarde no Drive ou envie para você pelo WhatsApp.","Faça isso toda semana."]},{"h":"Restaurar","p":["Em Mais, Seus dados, Restaurar, e escolha o arquivo.","Seus lotes e registros voltam como estavam."]},{"h":"Fotos","p":["As fotos dos animais ficam no celular e não vão no backup."]}],"rel":["Baixar para o Excel","Dados sem internet"]},{"t":"Baixar para o Excel","a":"app","r":"Você pode tirar seus dados em arquivos que o Excel abre para analisá-los ou compartilhá-los.","s":[{"h":"Passos","p":["Em Mais, Seus dados, escolha o que baixar: lotes, ração, pesagens, sanidade, vendas e mortes, despesas."]},{"h":"Usos","p":["Mostrar seu histórico ao banco ou a um sócio.","Análises próprias."]}],"rel":["Backup e restaurar","Registros econômicos"]},{"t":"Sua fazenda e ajustes","a":"app","r":"Em Mais, Configuração, você define os dados que o app usa para calcular.","s":[{"h":"O que se configura","p":["Primeiro: idioma, país, unidade de peso (libras ou quilos), moeda e como se cotiza o gado e a ração.","Nome e localização.","Preço de venda.","Peso meta geral, ganho esperado e quebra.","Horários de trato e aviso de dias sem pesar.","Avisos no celular, widget e voz do Rumi."]},{"h":"Dica","p":["Atualize o preço de venda quando o mercado mudar: as margens dependem dele."]}],"rel":["Quilos ou libras no app","Quebra (desbaste)"]},{"t":"Quilos ou libras no app","a":"app","r":"O app trabalha na unidade que você preferir e converte tudo sozinho.","s":[{"h":"Mudar","p":["Em Mais, Configuração, Idioma, moeda e unidades: Libras ou Quilos."]},{"h":"O que muda","p":["Pesos, ganhos, consumos e preços são mostrados e escritos nessa unidade.","Seus dados salvos não mudam."]}],"rel":["Unidades de peso e medida","Sua fazenda e ajustes"]},{"t":"Aparência e cores","a":"app","r":"Você pode escolher modo claro, escuro ou automático e a paleta de cores que mais gostar.","s":[{"h":"Mudar","p":["Em Mais, Aparência.","Tema: Automático, Claro ou Escuro.","Paleta: Clássica, Pradaria, Oceano, Terracota ou Grafite."]}],"rel":["Sua fazenda e ajustes"]},{"t":"Corrigir um registro","a":"app","r":"Se você anotou algo errado, apague e anote de novo corretamente.","s":[{"h":"Passos","p":["Toque em Registrar: embaixo, em O último que você anotou, toque na lixeira.","Ou entre no lote, aba Histórico, e apague por lá.","Anote de novo com os dados corretos."]},{"h":"Lotes e animais","p":["Edite um lote pela aba de dados.","Edite um animal pela ficha dele."]}],"rel":["Backup e restaurar"]},{"t":"Projeções no app","a":"app","r":"O app estima quanto cada lote vai pesar e quando chega à meta com o ganho real.","s":[{"h":"Onde vê-las","p":["Em cada lote: data estimada de saída.","Rumi, Meus lotes, escolha um lote, Projetar seu peso: você escolhe os dias."]},{"h":"Como calcula","p":["Usa o ganho das últimas pesagens, ou o esperado se não houver.","Projeta a ração e a margem desses dias."]}],"rel":["Dias até a meta","Quando vender"]},{"t":"Comparar lotes no app","a":"app","r":"Comparar lotes mostra quais compras, rações e manejos funcionam melhor para você.","s":[{"h":"Onde","p":["Rumi, Meu confinamento, Meu melhor lote.","Gráficos, escolhendo vários lotes.","Os lotes vendidos guardam seus números finais."]},{"h":"O que comparar","p":["Ganho diário, conversão, custo por quilo, mortalidade e margem por cabeça e por dia."]}],"rel":["Indicadores-chave do confinamento","Registros econômicos"]},{"t":"Dados sem internet","a":"app","r":"O Rumentis funciona completo sem internet. Seus dados e fotos ficam salvos no celular.","s":[{"h":"O que precisa de internet","p":["Só enviar o backup ou o Excel pelo Drive, e-mail ou WhatsApp, e atualizar o clima."]},{"h":"Privacidade","p":["Seus dados não são enviados a lugar nenhum, a não ser que você compartilhe o backup ou o Excel."]},{"h":"Trocar de celular","p":["Baixe o backup, passe para o celular novo, instale o Rumentis e restaure."]}],"rel":["Backup e restaurar"]},{"t":"Agenda de tarefas","a":"app","r":"A Agenda monta sozinha o que precisa ser feito com seus dados: tratos, pesagens, reforços de vacina, carências, vendas, depósito e backup.","s":[{"h":"Onde fica","p":["Em Hoje, cartão Agenda de hoje.","Em Mais, Agenda.","No Rumi, Meu confinamento, Minha agenda."]},{"h":"O que inclui","p":["Tratos pendentes do dia.","Lotes que precisam ser pesados conforme seus dias de aviso.","Reforço de vacina 21 a 30 dias depois da primeira dose.","Revisão diária dos recém-chegados nas primeiras 3 semanas.","Quando cada lote sai da carência de medicamentos.","Lotes prontos para vender ou perto da meta.","Ração acabando no depósito.","Backup se você não baixa um há mais de uma semana.","Seus próprios lembretes."]},{"h":"Como usar","p":["Toque em Fazer para ir direto ao formulário.","Toque no visto para marcá-la como feita.","Adicione lembretes próprios com data."]}],"rel":["Tela Hoje e avisos","Depósito de ração no app"]},{"t":"Depósito de ração no app","a":"app","r":"Controle o estoque da sua ração e o app diz para quantos dias dá com o que seus lotes realmente comem.","s":[{"h":"Começar","p":["Em Estoque, Ração, Depósito.","Toque em Adicionar minhas rações e ingredientes, ou adicione produtos um por um.","Anote quanto há hoje com Contar o depósito."]},{"h":"Dia a dia","p":["Cada compra se anota com Anotar compra.","O consumo é descontado sozinho com os tratos que você anota.","Se uma ração tem ingredientes com porcentagens, cada ingrediente é descontado na sua proporção.","De vez em quando conte o depósito para corrigir diferenças."]},{"h":"Avisos","p":["Quando um produto dá para menos dias do que você escolheu, aparece na Agenda para comprá-lo."]}],"rel":["Armazenamento do alimento","Agenda de tarefas"]},{"t":"Compartilhar o relatório de um lote","a":"app","r":"Mande pelo WhatsApp ou onde quiser um resumo do lote: cabeças, peso, ganho, conversão, custos, margem e data de saída.","s":[{"h":"Como","p":["Entre no lote e toque em Compartilhar relatório.","Ou no Rumi, Meus lotes, escolha o lote e toque em Compartilhar relatório.","Escolha WhatsApp, e-mail ou outro app."]},{"h":"Para quê","p":["Informar um sócio ou o dono do gado.","Mostrar números ao banco ou ao comprador.","Guardar um registro do lote."]}],"rel":["Registros econômicos","Engorda em parceria ou por serviço"]},{"t":"Como ler os gráficos","a":"app","r":"Cada gráfico diz o que você está vendo e, embaixo, o que seus números dizem em palavras.","s":[{"h":"Acima do gráfico","p":["O que você está vendo: o que representa cada linha, barra ou coluna."]},{"h":"Abaixo do gráfico","p":["O que seus números dizem: o melhor e o pior lote, alertas e comparações com valores normais.","Ponto verde: vai bem. Ponto vermelho: revise. Ponto azul: dado para sua informação."]},{"h":"Ganho esperado ou real","p":["O ganho esperado da Configuração só é usado em lotes sem pesagens.","Assim que você pesa, os gráficos usam o ganho real entre pesagens."]}],"rel":["Gráficos no app","Indicadores-chave do confinamento"]},{"t":"Buscar no menu do Rumi","a":"app","r":"No menu do Rumi há uma busca: escreva uma palavra como carrapato, ração ou o nome de um lote e ele mostra os temas, cálculos e sintomas que coincidem.","s":[{"h":"Como usar","p":["Abra o Rumi com o botão da vaca.","Toque na barra que diz Buscar tema, cálculo, sintoma ou lote.","Escreva uma ou duas palavras.","Toque no resultado que você quer."]},{"h":"O que encontra","p":["Temas do guia, com sua área.","Calculadoras.","Sintomas de O que meu animal tem?","Seus lotes pelo nome."]},{"h":"Dica","p":["Palavras curtas encontram mais: calor, tosse, preço, silagem.","O X da barra apaga a busca."]}],"rel":["Usar o menu do Rumi"]},{"t":"Ocultar as opções do Rumi","a":"app","r":"Quando o Rumi dá uma resposta longa, as opções se escondem sozinhas para você ler tudo. Você pode ocultá-las ou mostrá-las quando quiser.","s":[{"h":"Como usar","p":["Toque na seta ao lado de Em que posso ajudar? para ocultar as opções.","Toque em Ver opções para que voltem a aparecer."]},{"h":"Dica","p":["Com as opções ocultas você vê a resposta completa sem mover a tela."]}],"rel":["Usar o menu do Rumi","Buscar no menu do Rumi"]},{"t":"Ouvir o Rumi","a":"app","r":"O Rumi pode ler em voz alta suas respostas e os passos do tour, com a voz mais natural que seu celular tiver no idioma do app.","s":[{"h":"Como usar","p":["Toque no botão do alto-falante no balão do Rumi para ouvir essa mensagem.","Toque de novo para calá-lo.","No tour do app, toque em Ouvir e cada passo é lido sozinho."]},{"h":"Escolher a voz","p":["Vá em Mais, Configuração, Voz do Rumi.","Toque em Testar para ouvir cada voz e escolha a que gostar.","A primeira da lista é a mais natural que seu celular tem."]},{"h":"Vozes mais naturais","p":["Toque em Instalar vozes mais naturais: abrem-se os ajustes de voz do celular.","Em Serviços de fala do Google, instale seu idioma e baixe as vozes de alta qualidade.","Volte ao app e escolha a nova voz."]},{"h":"Se não tocar","p":["Aumente o volume do celular.","Verifique se o celular tem uma voz instalada no seu idioma."]}],"rel":["Usar o menu do Rumi","Tour do app"]},{"t":"O clima no app","a":"app","r":"Abaixo da data, em Hoje, você vê o clima da sua região. As cores e enfeites do app mudam com a hora e com o clima: sol, nuvens, chuva ou estrelas.","s":[{"h":"De onde vem","p":["Do serviço Open-Meteo pela internet, com a localização aproximada do celular naquele momento.","Abaixo do clima você vê o nome do lugar, para saber de onde é o dado.","Se você não der permissão de localização, usa o lugar que você pôs em Mais, Configuração, Localização.","Atualiza a cada 15 minutos quando há internet."]},{"h":"O que você pode fazer","p":["Toque no clima para o Rumi explicar o risco de calor para o gado, hora por hora.","O Rumi avisa se vem chuva nas próximas horas.","Sem internet, o app continua funcionando e mostra a época do ano."]},{"h":"Privacidade","p":["Só a localização aproximada é enviada para pedir o clima.","Seus dados da engorda não saem do celular."]}],"rel":["Sua fazenda e ajustes","Dados sem internet"]},{"t":"Tour do app","a":"app","r":"O tour mostra passo a passo para que serve cada parte do app. Aparece na primeira vez e você pode repeti-lo quando quiser.","s":[{"h":"Como ver de novo","p":["Vá em Mais, Ajuda e toque em Tour pelo app.","Ou abra o Rumi, Usar o app, Mostre-me o app: há um tutorial curto para cada página."]},{"h":"Durante o tour","p":["Toque em Próximo para avançar e Sair para terminar.","Toque em Ouvir para o Rumi ler cada passo para você."]}],"rel":["Ouvir o Rumi","Usar o menu do Rumi"]},{"t":"Boas-vindas e cores do dia","a":"app","r":"Cada vez que você abre o app vê as boas-vindas com fotos de gado e uma saudação conforme a hora. As cores do app mudam suavemente com a manhã, o meio-dia, a tarde e a noite.","s":[{"h":"O que mostra","p":["Sua saudação e o nome da sua fazenda.","O clima ou a época do ano.","Toque na tela para entrar mais rápido."]},{"h":"Cores e fotos","p":["As fotos do cabeçalho mudam sozinhas a cada poucos segundos.","Se chover na sua região, você verá chuva no cabeçalho."]}],"rel":["O clima no app","Aparência e cores"]},{"t":"Do músculo à carne","a":"carne","r":"Depois do abate o músculo continua trabalhando sem oxigênio: gasta sua reserva de açúcar (glicogênio), produz ácido lático e fica rígido. Esse processo decide a cor, a maciez e a duração da carne.","s":[{"h":"As primeiras 24 horas","p":["O glicogênio do músculo se transforma em ácido lático.","O pH cai de cerca de 7 para cerca de 5,5.","O músculo fica rígido (rigor mortis) e depois vai amolecendo."]},{"h":"Por que o pH final importa","p":["pH 5,4 a 5,7: carne vermelha brilhante, que dura e vende bem.","pH acima de 6: carne escura, firme e seca, que estraga mais rápido.","O pH final depende do glicogênio que o animal tinha ao morrer."]},{"h":"No seu confinamento","p":["Um animal bem alimentado e tranquilo chega com glicogênio suficiente.","Estresse, brigas, jejum longo e viagens duras antes do frigorífico gastam o glicogênio e dão carne escura."]}],"rel":["Carne escura (corte escuro, DFD)","Maciez da carne","Preparar a venda","Estresse de transporte"]},{"t":"Carne escura (corte escuro, DFD)","a":"carne","r":"A carne escura, firme e seca aparece quando o animal chega ao abate sem reservas de glicogênio por estresse. É castigada no preço porque tem má aparência e dura menos.","s":[{"h":"Causas","p":["Estresse longo antes do abate: viagens longas, calor, jejum, mistura de lotes.","Touros inteiros que brigam e montam.","Animais nervosos e maltratados.","Mudanças bruscas de clima."]},{"h":"Como se vê","p":["Cor vermelho-escura ou quase roxa que não clareia com o ar.","Superfície seca e pegajosa.","Estraga mais rápido porque seu pH é alto."]},{"h":"Como evitar","p":["Não misturar lotes desconhecidos no embarque nem nos currais do frigorífico.","Viajar nas horas frescas e sem demoras.","Manejo tranquilo, sem choque elétrico nem gritos.","Água disponível antes do embarque."]},{"h":"No seu confinamento","p":["Se seu comprador relatar cortes escuros, revise o embarque e os touros inteiros.","Um bom embarque protege o preço de meses de trabalho."]}],"rel":["Do músculo à carne","Planejar o embarque","Animais que montam (buller)","Manejo tranquilo do gado"]},{"t":"Maciez da carne","a":"carne","r":"A maciez depende das enzimas que amolecem o músculo depois do abate, do colágeno do tecido que une as fibras, da gordura e de como a carne foi resfriada e maturada.","s":[{"h":"As enzimas","p":["As calpaínas amaciam a carne nos dias após o abate.","A calpastatina as freia.","O zebu tem mais calpastatina: sua carne costuma ser um pouco mais dura."]},{"h":"O colágeno","p":["Com a idade, o colágeno fica mais resistente.","Animais jovens dão carne mais macia.","Cortes das pernas e do pescoço têm mais colágeno que o lombo."]},{"h":"O que a melhora","p":["Abater animais jovens e bem terminados.","Maturar a carne no frio de 7 a 21 dias.","Estimulação elétrica da carcaça no frigorífico.","Genética: há testes de DNA para maciez."]},{"h":"No seu confinamento","p":["Engordas curtas com animais jovens dão carne mais macia.","Um bom manejo pré-abate evita carne dura e escura."]}],"rel":["Maturação da carne","Adaptação do zebu ao trópico","Marmoreio e qualidade","Genética da qualidade da carne"]},{"t":"Maturação da carne","a":"carne","r":"Maturar a carne é guardá-la no frio, entre 0 e 4 °C, por vários dias para que suas enzimas a amaciem e melhorem o sabor.","s":[{"h":"Tipos","p":["Maturação úmida: a vácuo, em saco; a mais comum.","Maturação a seco: a peça ao ar em câmaras controladas; perde peso mas ganha sabor.","O maior amaciamento acontece nos primeiros 14 dias."]},{"h":"Cuidados","p":["Frio constante: sem cortes de energia nem câmaras abertas.","Higiene total para que não cresçam bactérias.","Carne com pH alto (escura) não matura bem e estraga."]},{"h":"No seu confinamento","p":["Se você vende carne própria ou para restaurantes, a maturação permite cobrar mais.","É valor agregado que depende da qualidade do animal que você produz."]}],"rel":["Maciez da carne","Cadeia de frio","Vender em pé ou por carcaça"]},{"t":"Marmoreio e qualidade","a":"carne","r":"O marmoreio são os veios de gordura dentro do músculo. Em muitos mercados é a base da classificação de qualidade porque dá suculência e sabor.","s":[{"h":"Como se classifica","p":["Avalia-se no corte entre a 12ª e a 13ª costela.","Nos EUA as classes são Prime, Choice e Select conforme o marmoreio e a idade.","Japão e Austrália têm escalas próprias."]},{"h":"Na América Central","p":["A maioria do gado é vendida sem pagamento por marmoreio.","Alguns frigoríficos e redes de restaurantes pagam mais por novilhos com cruzamentos europeus bem terminados."]},{"h":"No seu confinamento","p":["Pergunte ao seu comprador como classifica e paga.","Não gaste com marmoreio se não pagarem por ele; foque em peso, rendimento e acabamento."]}],"rel":["Formação do marmoreio","Qualidade da carcaça","Grau de acabamento"]},{"t":"Cor da carne","a":"carne","r":"A cor da carne vem da mioglobina, uma proteína do músculo. Muda com o oxigênio: vermelho brilhante com ar, roxa sem ar e marrom quando oxida.","s":[{"h":"As três cores","p":["Roxa: carne recém-cortada ou embalada a vácuo. É normal.","Vermelho-cereja: após uns 30 minutos em contato com o ar. É a que o cliente procura.","Marrom: carne velha ou oxidada; o cliente rejeita."]},{"h":"O que a afeta","p":["Idade: animais velhos têm carne mais escura.","pH alto por estresse: carne escura.","Vitamina E na dieta: a cor vermelha dura mais na vitrine."]},{"h":"Cor da gordura","p":["Branca em animais terminados com grão.","Amarela em animais a pasto, pelo caroteno do capim, ou em animais velhos.","Alguns compradores castigam a gordura amarela."]},{"h":"No seu confinamento","p":["Terminar com grão algumas semanas clareia a gordura.","Um bom manejo no embarque evita carne escura."]}],"rel":["Carne escura (corte escuro, DFD)","Gordura da carne e ômega 3","Do músculo à carne"]},{"t":"Rendimento: o que aumenta e o que diminui","a":"carne","r":"O rendimento de carcaça é o peso da carcaça dividido pelo peso vivo. Em novilhos do trópico costuma ir de 50 a 58 %. Alguns pontos de diferença valem muito dinheiro.","s":[{"h":"O que aumenta","p":["Mais gordura e músculo: animais bem terminados.","Menos conteúdo digestivo: jejum correto antes do abate.","Machos, boa musculatura e cruzamentos de corte.","Rações com grão em vez de só forragem."]},{"h":"O que diminui","p":["Barriga cheia de capim: um animal de pasto rende menos.","Couro grosso, chifres, barro grudado.","Animais magros ou leiteiros."]},{"h":"Exemplo","p":["Novilho de 450 kg a 52 %: carcaça de 234 kg.","O mesmo a 56 %: carcaça de 252 kg.","São 18 kg a mais de carcaça, sem mudar o peso vivo."]},{"h":"No seu confinamento","p":["Se você vende por carcaça, um bom acabamento e um jejum correto pagam muito.","Anote o rendimento de cada venda no app para comparar lotes."]}],"rel":["Rendimento de carcaça","Vender em pé ou por carcaça","Quebra (desbaste)","Grau de acabamento"]},{"t":"Cortes da carcaça","a":"carne","r":"A carcaça se divide em quartos dianteiros e traseiros, e depois em cortes. O traseiro tem os cortes mais caros; por isso os animais com bom traseiro valem mais.","s":[{"h":"Quarto traseiro","p":["Filé-mignon: o corte mais macio.","Contrafilé e filé de costela (bifes, T-bone).","Pernil: coxão mole, picanha e alcatra, patinho, lagarto.","Representa cerca de 45 a 48 % da carcaça e a maior parte do seu valor."]},{"h":"Quarto dianteiro","p":["Paleta, peito, pescoço e costela.","Cortes para cozidos, moer e assar devagar.","Têm mais colágeno e custam menos."]},{"h":"No seu confinamento","p":["Uma boa engorda enche o traseiro e o lombo.","Evite injetar na perna: as lesões danificam os cortes mais caros."]}],"rel":["Lesões por injeções","Qualidade da carcaça","Rendimento: o que aumenta e o que diminui"]},{"t":"Lesões por injeções","a":"carne","r":"Uma injeção mal aplicada deixa um caroço, cicatriz ou abscesso dentro do músculo que o frigorífico precisa aparar. Se foi na perna, perde-se carne dos cortes mais caros.","s":[{"h":"Onde injetar","p":["Na tábua do pescoço, na frente da paleta.","Subcutânea (sob a pele) sempre que o produto permitir.","Nunca na perna nem na garupa."]},{"h":"Boas práticas","p":["Máximo de 10 ml por ponto de injeção no músculo.","Separe cada injeção uns 10 cm.","Agulhas limpas, afiadas e do tamanho certo; troque a agulha a cada 10 a 15 animais ou se entortar."]},{"h":"No seu confinamento","p":["Peça ao vaqueiro para sempre usar o pescoço.","Anote no app cada tratamento com data para respeitar a carência."]}],"rel":["Aplicação de injeções","Cortes da carcaça","Carências e resíduos"]},{"t":"Pancadas e hematomas","a":"carne","r":"Os hematomas na carcaça são aparados e descartados. Quase todos vêm do manejo nos últimos dias: embarque, transporte e currais do frigorífico.","s":[{"h":"Causas","p":["Paus, ferrões e pancadas no tronco.","Caminhões superlotados ou com saliências.","Chifres de outros animais.","Pisos escorregadios e quedas."]},{"h":"Quanto se perde","p":["Cada hematoma pode custar de meio quilo a vários quilos de carne.","Além disso, baixa a classificação da carcaça."]},{"h":"No seu confinamento","p":["Embarcadouro com boa rampa e piso antiderrapante.","Carga de animais conforme o tamanho do caminhão.","Bandeiras ou sacos em vez de paus para tocar o gado."]}],"rel":["Embarcadouro","Transporte de gado","Manejo tranquilo do gado","Planejar o embarque"]},{"t":"Valor nutritivo da carne","a":"carne","r":"A carne bovina é uma das melhores fontes de proteína completa, ferro, zinco e vitamina B12 para as pessoas.","s":[{"h":"O que fornece","p":["Cerca de 20 a 22 g de proteína a cada 100 g de carne magra crua.","Ferro heme, que se absorve muito melhor que o das plantas.","Zinco, vitamina B12, niacina e selênio."]},{"h":"Gordura","p":["Os cortes magros têm menos de 5 % de gordura.","A gordura bovina tem gordura saturada e também monoinsaturada, como a do abacate."]},{"h":"Para sua família e seus clientes","p":["É especialmente valiosa para crianças, gestantes e idosos.","Comer carne com verduras em porções razoáveis faz parte de uma dieta saudável."]}],"rel":["Gordura da carne e ômega 3","Qualidade da carcaça"]},{"t":"Gordura da carne e ômega 3","a":"carne","r":"A gordura da carne muda conforme o que o animal come. Os animais a pasto têm um pouco mais de ômega 3 e CLA; os de grão têm mais marmoreio e gordura branca.","s":[{"h":"Pasto","p":["Mais ômega 3, CLA e vitamina E.","Gordura mais amarela pelo caroteno.","Menos marmoreio e sabor mais intenso."]},{"h":"Grão","p":["Mais marmoreio e suculência.","Gordura branca.","Menos ômega 3."]},{"h":"O importante","p":["As duas são nutritivas; as diferenças de ômega 3 são pequenas na dieta humana.","Alguns mercados pagam mais por carne a pasto certificada."]}],"rel":["Gordura no rúmen","Cor da carne","Marmoreio e qualidade"]},{"t":"Cadeia de frio","a":"carne","r":"A carne se conserva se for mantida fria, entre 0 e 4 °C, do frigorífico até a mesa. Cada vez que esquenta, as bactérias crescem e a vida útil encurta.","s":[{"h":"As regras","p":["Resfriar a carcaça rápido: menos de 7 °C no centro nas primeiras 24 horas.","Transportar em caminhões refrigerados.","Vender em vitrines refrigeradas e congelar o que não se vende logo."]},{"h":"Vida útil aproximada","p":["Carne fresca na vitrine: 3 a 5 dias.","A vácuo e no frio: 4 a 8 semanas.","Congelada a -18 °C: meses."]},{"h":"No seu confinamento","p":["Se você vende carne direto, invista em frio antes de qualquer outra coisa.","Uma carcaça com pH normal dura muito mais que uma escura."]}],"rel":["Maturação da carne","Carne escura (corte escuro, DFD)","Abate autorizado"]},{"t":"Inocuidade da carne","a":"carne","r":"Carne inócua é carne que não faz mal a quem a come: sem bactérias perigosas, sem resíduos de medicamentos e sem contaminantes. A inocuidade começa na fazenda.","s":[{"h":"Perigos","p":["Bactérias como Salmonella e E. coli das fezes.","Resíduos de antibióticos, vermífugos e hormônios.","Substâncias proibidas como o clembuterol.","Metais pesados e agrotóxicos."]},{"h":"O que você faz","p":["Respeitar a carência de cada medicamento.","Não usar produtos proibidos.","Animais limpos e sem barro no embarque.","Registros de tratamentos: o app os guarda."]},{"h":"Por que convém a você","p":["Um achado de resíduos pode cancelar a venda ou fechar o mercado inteiro.","Compradores sérios exigem registros."]}],"rel":["Carências e resíduos","Produtos proibidos na alimentação","Registros e rastreabilidade","Boas práticas pecuárias"]},{"t":"Abate e bem-estar","a":"carne","r":"Um abate bem feito é rápido, sem dor e sem estresse. Além de ser o correto, dá carne melhor.","s":[{"h":"Boas práticas","p":["Descanso e água nos currais do frigorífico.","Condução sem pancadas nem ferrões.","Insensibilização efetiva na primeira tentativa antes da sangria."]},{"h":"Efeito na carne","p":["Menos carne escura e menos hematomas.","Melhor sangria e melhor conservação."]},{"h":"No seu confinamento","p":["Venda para frigoríficos autorizados que cumpram as normas.","Sua reputação e seu preço também dependem de onde seus animais terminam."]}],"rel":["Abate autorizado","Bem-estar na lei e no mercado","Carne escura (corte escuro, DFD)"]},{"t":"Classificação de carcaças","a":"carne","r":"Os frigoríficos classificam as carcaças para pagar diferente conforme a qualidade. Os critérios mais usados são idade, sexo, conformação, gordura e peso.","s":[{"h":"Critérios comuns","p":["Idade pelos dentes: novilho jovem vale mais que animal velho.","Sexo: machos castrados, inteiros ou fêmeas.","Conformação: quão cheios estão o pernil e o lombo.","Gordura de cobertura: nem muito pouca nem demais.","Peso da carcaça."]},{"h":"No seu confinamento","p":["Peça ao seu frigorífico a tabela de classificação.","Compare o que pagaram com o que o app projetou.","Ajuste a idade de compra e o acabamento conforme o que pagam."]}],"rel":["Qualidade da carcaça","Idade pelos dentes","Grau de acabamento","Vender em pé ou por carcaça"]},{"t":"Perdas por resfriamento","a":"carne","r":"A carcaça perde água enquanto esfria na câmara. Essa quebra, de 1 a 3 %, faz a carcaça fria pesar menos que a quente.","s":[{"h":"Por que acontece","p":["A superfície da carcaça seca com o ar frio.","Carcaças com pouca gordura de cobertura perdem mais."]},{"h":"Na venda","p":["Veja se pagam por carcaça quente ou fria.","A diferença pode ser de 3 a 7 kg por animal."]},{"h":"No seu confinamento","p":["Boa cobertura de gordura protege a carcaça e reduz a quebra.","Anote no app o tipo de carcaça com que pagam você."]}],"rel":["Rendimento de carcaça","Vender em pé ou por carcaça","Grau de acabamento"]},{"t":"Couro e subprodutos","a":"carne","r":"Além da carne, o animal dá couro, vísceras, sebo e farinha de ossos. Seu valor ajuda a pagar o frigorífico e às vezes se desconta ou se soma ao preço.","s":[{"h":"O couro","p":["Estraga-se com carrapatos, berne, marcas grandes e arame farpado.","Um couro limpo vale mais para o curtume."]},{"h":"Outros subprodutos","p":["Fígado, coração, língua e bucho para consumo.","Sebo, sangue e ossos para a indústria e ração animal."]},{"h":"No seu confinamento","p":["Controlar carrapatos e berne também cuida do couro.","Coloque a marca no lugar indicado e do tamanho necessário."]}],"rel":["Carrapatos","Berne","Registro de marca e fazenda"]},{"t":"Carne de touro, novilho e vaca","a":"carne","r":"O sexo e a idade mudam a carne. O novilho castrado jovem dá a carne mais uniforme; o touro, mais magra; a vaca de descarte, mais gorda e mais dura.","s":[{"h":"Novilho castrado","p":["Bom equilíbrio entre músculo e gordura.","Marmoreia mais que o touro.","Carne mais macia e cor uniforme."]},{"h":"Touro inteiro","p":["Mais carne magra e melhor conversão na engorda.","Carne mais escura e firme; mais risco de corte escuro.","Alguns mercados pagam menos por ele."]},{"h":"Vaca de descarte","p":["Carne mais escura e dura pela idade.","Gordura amarela se veio do pasto.","Engordá-la algumas semanas melhora o preço."]}],"rel":["Inteiros ou castrados","Fêmeas no confinamento","Maciez da carne"]},{"t":"pH da carne","a":"carne","r":"O pH da carne 24 horas após o abate é o melhor indicador de sua qualidade: diz se vai ficar vermelha, se vai durar e se será macia.","s":[{"h":"Valores","p":["5,4 a 5,7: normal, boa qualidade.","5,8 a 6,0: intermediário, um pouco escura.","Acima de 6,0: corte escuro, é castigada."]},{"h":"Como se mede","p":["Com um medidor de pH de ponta no lombo, na câmara fria.","Muitos frigoríficos o medem para classificar."]},{"h":"No seu confinamento","p":["Pergunte ao frigorífico se mede pH e peça seus resultados.","Se saírem altos, revise o manejo dos últimos dias."]}],"rel":["Do músculo à carne","Carne escura (corte escuro, DFD)"]},{"t":"Ganho médio diário","a":"conceptos","r":"Quantos quilos cada animal sobe por dia em média. É o primeiro número para saber se a engorda vai bem.","s":[{"h":"Como se calcula","p":["Ganho diário = (peso final − peso inicial) ÷ dias entre as duas pesagens.","Para o lote: use a média dos animais vivos."]},{"h":"Exemplo","p":["Entrou com 300 kg e aos 28 dias pesa 340 kg: 40 ÷ 28 = 1,43 kg por dia."]},{"h":"Valores de referência","p":["Confinamento com boa ração: 1,2 a 1,8 kg por dia.","Semiconfinamento: 0,8 a 1,2 kg.","Pasto com suplemento: 0,6 a 1 kg.","Só pasto: 0,3 a 0,7 kg."]},{"h":"Cuidados ao medir","p":["Pese na mesma hora e nas mesmas condições.","Os ganhos das primeiras semanas após a viagem incluem água recuperada.","Períodos menores que 14 dias dão números pouco confiáveis."]},{"h":"No app","p":["É calculado sozinho com suas pesagens, por lote e por animal."]}],"rel":["Pesagem","Dias até a meta","Indicadores-chave do confinamento"]},{"t":"Rendimento de carcaça","a":"conceptos","r":"Que parte do peso vivo fica como carcaça (carne com osso) depois do abate.","s":[{"h":"Como se calcula","p":["Rendimento = peso da carcaça ÷ peso vivo × 100."]},{"h":"Exemplo","p":["Um novilho de 480 kg dá uma carcaça de 269 kg: 269 ÷ 480 = 56 %."]},{"h":"Valores de referência","p":["Novilhos de engorda bem acabados: 54 a 58 %.","Animais magros ou leiteiros: 48 a 52 %.","Animais com muito músculo e bom acabamento: até 60 % ou mais."]},{"h":"O que o afeta","p":["Enchimento do rúmen ao pesar (por isso a quebra).","Acabamento de gordura.","Raça e musculatura.","Sexo: inteiros costumam render mais."]},{"h":"No Rumi","p":["Calculadoras, Rendimento de carcaça: dá o peso esperado da carcaça."]}],"rel":["Vender em pé ou por carcaça","Quebra (desbaste)","Qualidade da carcaça"]},{"t":"Quebra (desbaste)","a":"conceptos","r":"O peso que um animal perde ao esvaziar o rúmen e a bexiga, por jejum ou transporte. É descontado na venda.","s":[{"h":"O que é","p":["Um animal cheio pesa mais pela água e comida no rúmen.","O comprador desconta esse peso para pagar o peso real."]},{"h":"Valores de referência","p":["3 a 5 % em jejuns curtos ou pesagem na fazenda.","O NRC usa 4 % como referência.","Viagens longas podem causar perdas maiores."]},{"h":"Exemplo","p":["Pesa 500 kg na fazenda com 4 % de quebra: pagam 480 kg."]},{"h":"No app","p":["Você define a quebra em Mais, Configuração, e ela é usada ao calcular vendas e margens."]}],"rel":["Preparar a venda","Rendimento de carcaça","Negociar com o comprador"]},{"t":"Unidade animal","a":"conceptos","r":"Medida que iguala animais de pesos diferentes para calcular quanta forragem ou espaço precisam.","s":[{"h":"O que é","p":["Uma unidade animal equivale a 450 kg de peso vivo."]},{"h":"Como se calcula","p":["Unidades animais = peso vivo total ÷ 450."]},{"h":"Exemplo","p":["40 novilhos de 300 kg = 12.000 kg = 26,7 unidades animais."]},{"h":"Usos","p":["Lotação de pastos: unidades animais por hectare ou manzana.","Orçamentos de forragem e água."]}],"rel":["Lotação e amostragem de forragem","Pastejo rotacionado"]},{"t":"Índice de calor","a":"conceptos","r":"Número que combina temperatura e umidade para dizer quanto calor o animal sente.","s":[{"h":"O que é","p":["Também chamado de índice de temperatura e umidade (ITU).","Na mesma temperatura, com mais umidade o animal se refresca pior."]},{"h":"Faixas","p":["Menos de 72: sem estresse.","72 a 78: alerta.","79 a 83: perigo.","84 ou mais: emergência."]},{"h":"O que fazer em cada faixa","p":["Alerta: revise água e sombra, trate mais tarde.","Perigo: não trabalhe o gado, mais água, molhe o piso.","Emergência: molhe os animais, não os mova, vigie os gordos e os escuros."]},{"h":"No Rumi","p":["Calculadoras, Índice de calor: você informa temperatura e umidade."]}],"rel":["Estresse por calor","Golpe de calor","Sombra"]},{"t":"Dias até a meta","a":"conceptos","r":"Quantos dias faltam para um lote chegar ao peso de venda com o ganho que tem.","s":[{"h":"Como se calcula","p":["Dias = (peso meta − peso atual) ÷ ganho diário."]},{"h":"Exemplo","p":["Pesa 400 kg, meta 480 kg, ganha 1,4 kg: 80 ÷ 1,4 = 57 dias."]},{"h":"Usos","p":["Planejar a venda e o próximo lote.","Calcular a ração que falta.","Projetar a margem."]},{"h":"No app","p":["Cada lote mostra a data estimada de saída.","Rumi, Análise do Rumi, Quando me convém vender?"]}],"rel":["Ganho médio diário","Quando vender","Planejamento do confinamento"]},{"t":"Giros por ano","a":"conceptos","r":"Quantos lotes um curral pode engordar em um ano. Mais giros diluem melhor os custos fixos.","s":[{"h":"Como se calcula","p":["Giros = 365 ÷ (dias de engorda + dias vazios entre lotes)."]},{"h":"Exemplo","p":["Engorda de 110 dias e 10 dias de limpeza: 365 ÷ 120 = 3 giros."]},{"h":"Como aumentá-los","p":["Melhor ganho diário.","Comprar animais mais pesados.","Ter o próximo lote pronto quando o anterior sai."]}],"rel":["Planejamento do confinamento","Escala do confinamento"]},{"t":"Consumo como porcentagem do peso","a":"conceptos","r":"Forma simples de estimar quanto um animal come: uma porcentagem do seu peso vivo.","s":[{"h":"Valores","p":["Matéria seca: 2,2 a 2,8 % do peso vivo na engorda.","Ração como fornecida: depende da sua umidade."]},{"h":"Exemplo","p":["Animal de 400 kg a 2,5 %: 10 kg de matéria seca por dia.","Se a ração tem 85 % de matéria seca: 10 ÷ 0,85 = 11,8 kg como fornecida."]},{"h":"No Rumi","p":["Calculadoras, Consumo pelo peso."]}],"rel":["Matéria seca e consumo","Leitura de cochos"]},{"t":"Nutrientes digestíveis totais","a":"conceptos","r":"NDT é uma forma de medir a energia de um alimento: que parte é digerida.","s":[{"h":"O que é","p":["Porcentagem do alimento que o animal digere e aproveita como energia."]},{"h":"Valores de referência","p":["Milho: 85 a 90 %.","Sorgo: 80 a 84 %.","Feno de boa qualidade: 55 a 60 %.","Pasto maduro: 45 a 50 %.","Ração de terminação: 72 a 80 %."]},{"h":"Uso","p":["Comparar ingredientes pela energia.","Formular rações: o app usa esses valores."]}],"rel":["Energia na ração","Formular uma ração"]},{"t":"Margem bruta e margem líquida","a":"conceptos","r":"A margem bruta mede o que o lote deixa; a líquida, o que sobra depois de todas as despesas da fazenda.","s":[{"h":"Margem bruta","p":["Vendas − compra de animais − ração − sanidade − despesas diretas do lote."]},{"h":"Margem líquida","p":["Margem bruta − despesas gerais (salários fixos, energia, depreciação, juros)."]},{"h":"Por cabeça e por dia","p":["Margem por cabeça = margem ÷ cabeças vendidas.","Margem por dia = margem por cabeça ÷ dias de engorda: serve para comparar lotes de duração diferente."]},{"h":"No app","p":["O app calcula a margem de cada lote ao vender e a estimada na meta."]}],"rel":["Registros econômicos","Depreciação e investimentos"]},{"t":"Preço por quilo ou por cabeça","a":"conceptos","r":"Para comparar ofertas é preciso sempre levá-las a preço por quilo.","s":[{"h":"Como converter","p":["Preço por quilo = preço por cabeça ÷ peso do animal.","Preço por cabeça = preço por quilo × peso."]},{"h":"Exemplo","p":["Animal a 18.000 por cabeça que pesa 290 kg: 62 por quilo.","Outro a 19.000 que pesa 320 kg: 59 por quilo. O segundo é mais barato por quilo."]},{"h":"Regra","p":["Compre e venda por quilo, com balança."]}],"rel":["Comprar gado para engorda","Preço máximo de compra"]},{"t":"Eficiência alimentar","a":"conceptos","r":"É a conversão ao contrário: quantos quilos o animal ganha por cada quilo de ração.","s":[{"h":"Como se calcula","p":["Eficiência = quilos ganhos ÷ quilos de ração."]},{"h":"Exemplo","p":["Conversão de 7 para 1 equivale a eficiência de 0,14 (ganhou 0,14 kg por kg de ração)."]},{"h":"Uso","p":["Alguns técnicos e programas usam este número em vez da conversão.","Mais alto é melhor."]}],"rel":["Conversão alimentar"]},{"t":"Unidades de peso e medida","a":"conceptos","r":"No campo se misturam libras, quilos, quintais, arrobas e manzanas. Saber converter evita erros caros.","s":[{"h":"Peso","p":["1 quilo = 2,2 libras.","1 libra = 0,454 quilo.","1 quintal = 100 libras = 45,4 quilos.","1 arroba (América Central) = 25 libras = 11,3 quilos; no Brasil a arroba é de 15 kg."]},{"h":"Área","p":["1 manzana = 0,7 hectare = 7.000 m².","1 hectare = 1,43 manzana = 10.000 m²."]},{"h":"Preços","p":["Preço por quilo = preço por libra × 2,2.","Preço por libra = preço por quilo ÷ 2,2."]},{"h":"No Rumi","p":["Calculadoras, Converter: libras, quilos, quintais, arrobas, manzanas e hectares."]}],"rel":["Quilos ou libras no app"]},{"t":"Custo por animal por dia","a":"conceptos","r":"O que custa manter um animal um dia na engorda. Ajuda a decidir se vale a pena esperar para vender.","s":[{"h":"Como se calcula","p":["(Ração do dia + parte de sanidade, mão de obra e despesas) ÷ cabeças."]},{"h":"Uso","p":["Se um dia a mais custa mais do que valem os quilos ganhos nesse dia, convém vender."]},{"h":"Exemplo","p":["Custa 90 por dia e ganha 1,2 kg a 60 = 72: cada dia você perde 18."]}],"rel":["Quando vender","Custo por quilo ganho"]},{"t":"Retorno do investimento","a":"conceptos","r":"Mede quanto rende o dinheiro investido no lote. Permite comparar a engorda com outras opções.","s":[{"h":"Como se calcula","p":["Retorno = margem ÷ dinheiro investido × 100.","Anualizado = retorno × 365 ÷ dias de engorda."]},{"h":"Exemplo","p":["Você investiu 500.000 e ganhou 40.000 em 120 dias: 8 % no período, uns 24 % ao ano."]},{"h":"Uso","p":["Compare com a taxa de um empréstimo ou de um depósito.","Se o retorno anual for menor que a taxa do empréstimo, não convém se endividar."]}],"rel":["Financiamento e crédito","Margem bruta e margem líquida"]},{"t":"Peso meta","a":"conceptos","r":"O peso com que você planeja vender. Define a duração da engorda e a margem.","s":[{"h":"Como escolher","p":["O que seu comprador pede ou paga melhor.","O acabamento que seus animais alcançam nesse peso.","O ponto em que os quilos extras começam a custar mais do que valem."]},{"h":"Valores comuns","p":["Muitos confinamentos da região vendem entre 430 e 520 kg (950 a 1.150 libras).","Depende da raça, do sexo e do mercado."]},{"h":"No app","p":["Você define um peso meta geral em Configuração e um próprio para cada lote."]}],"rel":["Dias até a meta","Quando vender","Grau de acabamento"]},{"t":"Fibra em detergente neutro e ácido","a":"conceptos","r":"FDN e FDA são análises de laboratório que medem a fibra da forragem. Dizem quanto o animal vai comer e quanto vai digerir.","s":[{"h":"FDN","p":["Mede toda a fibra da parede da planta.","Mais FDN: o animal se enche antes e come menos.","Pastos jovens: 55 a 65 %; pastos velhos: mais de 70 %."]},{"h":"FDA","p":["A parte mais dura da fibra.","Mais FDA: menos digestível."]},{"h":"Uso","p":["Comparar forragens e decidir a idade de corte.","Formular com precisão a forragem da ração."]}],"rel":["Qualidade da forragem e idade de corte","Análise de ingredientes","Fibra e forragem na ração"]},{"t":"Relação cálcio e fósforo","a":"conceptos","r":"O cálcio e o fósforo devem estar na proporção certa na ração. Senão aparecem problemas de ossos e cálculos urinários.","s":[{"h":"Quanto","p":["Relação de 1,5 a 2 partes de cálcio para 1 de fósforo."]},{"h":"Problema comum","p":["As rações com muito grão e farelo têm muito fósforo e pouco cálcio.","Corrige-se com carbonato de cálcio."]},{"h":"Consequências de um mau equilíbrio","p":["Cálculos urinários em machos.","Menor crescimento ósseo."]}],"rel":["Minerais principais","Cálculos urinários"]},{"t":"Acidez do rúmen (pH ruminal)","a":"conceptos","r":"O pH mede quão ácido está o rúmen. Quando cai demais, aparece a acidose.","s":[{"h":"Valores","p":["Normal com pasto: 6,2 a 6,8.","Engorda com grão: 5,8 a 6,2 é aceitável.","Menos de 5,6 por várias horas ao dia: acidose subaguda.","Menos de 5,0: acidose aguda."]},{"h":"O que o baixa","p":["Muito grão fermentável de uma vez.","Pouca fibra efetiva e pouca ruminação.","Refeições grandes depois de jejum."]},{"h":"O que o sobe","p":["Ruminação e saliva.","Fibra longa.","Tamponantes como o bicarbonato."]}],"rel":["Acidose ruminal","Fibra e forragem na ração","Aditivos na ração"]},{"t":"Peso cheio e peso vazio","a":"conceptos","r":"O mesmo animal pode pesar diferente conforme quanta água e comida tem no rúmen. É a base da quebra.","s":[{"h":"Peso cheio","p":["Com o rúmen cheio de água e comida.","Pode ser 5 a 8 % maior que o peso vazio."]},{"h":"Peso em jejum","p":["Depois de 12 a 16 horas sem comida e água.","É o mais parecido com o peso real do animal."]},{"h":"Uso prático","p":["Pese sempre nas mesmas condições para comparar.","Na venda, combine qual peso se usa e a quebra."]}],"rel":["Quebra (desbaste)","Pesagem"]},{"t":"Mortalidade","a":"conceptos","r":"A porcentagem de animais que morrem dos que entraram. É um indicador-chave de sanidade e manejo.","s":[{"h":"Como se calcula","p":["Mortalidade = animais mortos ÷ animais que entraram × 100."]},{"h":"Referências","p":["Bom confinamento: menos de 1 a 2 %.","Mais de 3 %: revisar compra, recepção e sanidade."]},{"h":"No app","p":["É calculada por lote e no total com as baixas que você anota."]}],"rel":["Mortalidade e seu custo","Morte de um animal"]},{"t":"Dias de engorda","a":"conceptos","r":"O tempo desde que o lote entra até ser vendido. Define quantos lotes cabem em um ano e o custo fixo de cada animal.","s":[{"h":"Como se calcula","p":["Data de venda − data de entrada."]},{"h":"Referências","p":["Confinamento: 90 a 150 dias conforme o peso de entrada.","Semiconfinamento: 150 a 250 dias.","Pasto: um ano ou mais."]},{"h":"Como encurtá-lo sem perder","p":["Melhor ganho diário com boa ração e sanidade.","Comprar mais pesado se o preço permitir.","Vender ao chegar à meta."]}],"rel":["Giros por ano","Dias até a meta"]},{"t":"Matéria seca e matéria verde","a":"conceptos","r":"A matéria seca é o que sobra da comida quando se tira toda a água. As exigências e as rações se calculam em matéria seca porque a água não alimenta.","s":[{"h":"Exemplos","p":["Pasto verde: 15 a 25 % de matéria seca (75 a 85 % é água).","Silagem: 25 a 35 %.","Feno e grãos: 85 a 90 %."]},{"h":"Como converter","p":["Quilos de matéria seca = quilos de comida × % de matéria seca ÷ 100.","Exemplo: 30 kg de pasto a 20 % são 6 kg de matéria seca."]},{"h":"No seu confinamento","p":["Por isso um animal precisa de tanto pasto verde: a maior parte é água.","O app calcula em matéria seca quando você formula uma ração."]}],"rel":["Matéria seca e consumo","Formular uma ração","Consumo como porcentagem do peso"]},{"t":"Proteína bruta","a":"conceptos","r":"A proteína bruta é o nitrogênio da comida multiplicado por 6,25. Inclui proteína verdadeira e nitrogênio não proteico como a ureia.","s":[{"h":"Valores comuns","p":["Milho: 8 a 9 %.","Farelo de soja: 44 a 48 %.","Pasto novo: 8 a 14 %; pasto velho: 3 a 6 %.","Ureia: equivale a uns 280 % de proteína bruta."]},{"h":"Limitações","p":["Não diz quanto é degradado no rúmen.","Não diz a qualidade dos aminoácidos."]}],"rel":["Proteína na ração","Proteína metabolizável","Ureia na ração"]},{"t":"Ganho compensatório","a":"conceptos","r":"É o ganho extra que um animal que passou fome faz quando volta a comer bem. Aproveita-se comprando animais magros, mas sadios.","s":[{"h":"Em números","p":["Nos primeiros 2 a 3 meses podem ganhar 10 a 30 % mais que animais que sempre comeram bem.","Nem sempre recuperam todo o atraso."]},{"h":"Quando não funciona","p":["Se o animal passou fome muito jovem ou por muito tempo.","Se o animal magro está doente ou tem parasitas."]}],"rel":["Crescimento compensatório","Condição corporal","Comprar gado para engorda"]},{"t":"Índice de temperatura e umidade (ITU)","a":"conceptos","r":"O ITU junta temperatura e umidade em um só número que indica o estresse por calor do gado. O Rumi o calcula com o clima da sua região.","s":[{"h":"Fórmula","p":["ITU = (1,8 × T + 32) − (0,55 − 0,0055 × UR) × (1,8 × T − 26), com T em °C e UR a umidade em %.","Você não precisa calculá-lo: o app faz isso."]},{"h":"Níveis para gado de corte","p":["74 ou menos: normal.","75 a 78: alerta.","79 a 83: perigo.","84 ou mais: emergência."]},{"h":"Atenção","p":["O zebu aguenta mais que as raças europeias.","O sol direto, o vento e as noites quentes mudam o risco real."]}],"rel":["Índice de calor","Estresse por calor","Zona de conforto térmico"]},{"t":"Precocidade","a":"conceptos","r":"Um animal precoce chega jovem ao peso e à gordura de venda. A precocidade depende da raça, do tamanho adulto e da alimentação.","s":[{"h":"O que a favorece","p":["Raças britânicas e seus cruzamentos.","Frame moderado.","Boa alimentação desde o desmame."]},{"h":"Por que importa","p":["Carne mais macia de animais jovens.","Menos dias de mantença.","Melhor classificação pelos dentes."]}],"rel":["Tamanho adulto e frame","Grau de acabamento","Idade pelos dentes"]},{"t":"Lotação por hectare","a":"conceptos","r":"A lotação é quantos animais (ou unidades animais) cada hectare de pasto tem. Uma lotação maior do que o pasto suporta degrada o pasto e baixa o ganho.","s":[{"h":"Referências no trópico","p":["Pasto nativo sem manejo: 0,5 a 1 unidade animal por hectare.","Pasto melhorado com rotação: 2 a 3.","Pasto melhorado, adubado e irrigado: 4 ou mais."]},{"h":"No seu confinamento","p":["Ajuste a lotação na seca: menos animais ou mais suplemento.","O Rumi calcula a lotação com seus piquetes e seus animais."]}],"rel":["Lotação e amostragem de forragem","Unidade animal","Pastejo rotacionado"]},{"t":"Eficiência biológica e econômica","a":"conceptos","r":"Uma engorda pode ser muito eficiente em converter comida em carne e mesmo assim perder dinheiro, ou o contrário. É preciso olhar as duas eficiências.","s":[{"h":"Biológica","p":["Conversão alimentar, ganho diário, mortalidade."]},{"h":"Econômica","p":["Custo por quilo ganho, margem por animal, retorno do investimento."]},{"h":"No seu confinamento","p":["O melhor lote é o que deixa mais margem por dia e por animal, nem sempre o que mais ganha peso."]}],"rel":["Eficiência alimentar","Retorno do investimento","Indicadores-chave do confinamento"]},{"t":"Os quatro estômagos do bovino","a":"fisiologia","r":"O bovino tem um estômago com quatro partes: rúmen (pança), retículo (barrete), omaso (folhoso) e abomaso (coagulador). Cada parte faz um trabalho diferente para aproveitar o pasto.","s":[{"h":"Rúmen ou pança","p":["É a parte maior: num novilho de 450 kg cabem uns 100 a 150 litros.","É uma panela de fermentação: ali vivem bilhões de micróbios que desfazem o pasto.","Movimenta-se uma ou duas vezes por minuto para misturar a comida."]},{"h":"Retículo ou barrete","p":["Fica colado ao rúmen e tem forma de favo de mel.","Separa o que já está moído do que ainda falta ruminar.","Ali caem pregos e arames que o animal engole; por isso se fala em 'reticulite traumática'."]},{"h":"Omaso ou folhoso","p":["Parece um livro com muitas folhas.","Retira água e minerais da comida antes de passá-la ao abomaso.","Deixa passar só as partículas pequenas."]},{"h":"Abomaso ou coagulador","p":["É o estômago verdadeiro, como o das pessoas.","Tem ácido forte (pH 2 a 3) e enzimas que digerem a proteína dos micróbios e da comida.","Dali a comida passa ao intestino delgado, onde é absorvida."]},{"h":"No seu confinamento","p":["Se você cuida do rúmen, cuida do animal inteiro: mudanças bruscas de comida o adoecem.","Um rúmen saudável se nota na ruminação tranquila, fezes bem formadas e bom consumo."]}],"rel":["Como funciona o rúmen","Ruminação e saliva","Micróbios do rúmen","Acidez do rúmen (pH ruminal)"]},{"t":"Micróbios do rúmen","a":"fisiologia","r":"No rúmen vivem bactérias, protozoários, fungos e arqueias. Eles, não a vaca, digerem a fibra. Na verdade o pecuarista alimenta os micróbios e os micróbios alimentam o animal.","s":[{"h":"Quem são","p":["Bactérias: são a maioria; em cada mililitro de líquido ruminal há bilhões.","Protozoários: comem bactérias e amido, e ajudam a que o rúmen não fique tão ácido.","Fungos: rompem a fibra mais dura do pasto.","Arqueias metanogênicas: produzem o gás metano que o animal arrota."]},{"h":"O que fazem","p":["Rompem a celulose do pasto, que o animal sozinho não consegue digerir.","Produzem ácidos graxos voláteis, a principal fonte de energia do bovino.","Fabricam proteína com o nitrogênio da comida e até com ureia.","Produzem vitaminas do complexo B e vitamina K."]},{"h":"Tipos conforme a comida","p":["Com pasto dominam as bactérias que comem fibra, que trabalham devagar e precisam de pH perto de 6,5.","Com grão dominam as que comem amido, que trabalham rápido e baixam o pH.","Os micróbios levam de 2 a 3 semanas para se adaptar a uma comida nova."]},{"h":"No seu confinamento","p":["Por isso as mudanças de ração se fazem aos poucos, em 2 a 3 semanas.","Um animal que deixa de comer vários dias perde parte dos seus micróbios e custa a voltar a arrancar.","Dar a comida no mesmo horário mantém estável a população de micróbios."]}],"rel":["Os quatro estômagos do bovino","Ácidos graxos voláteis","Adaptação ao concentrado","Proteína microbiana"]},{"t":"Ácidos graxos voláteis","a":"fisiologia","r":"Os micróbios do rúmen transformam o pasto e o grão em três ácidos: acético, propiônico e butírico. O animal os absorve pela parede do rúmen e deles tira entre 60 e 80 % da sua energia.","s":[{"h":"Ácido acético","p":["Vem sobretudo da fibra do pasto.","É usado para fazer gordura e como combustível dos músculos.","Em dietas só de pasto é 65 a 70 % dos ácidos."]},{"h":"Ácido propiônico","p":["Vem sobretudo do amido do grão.","O fígado o converte em glicose (açúcar), porque o bovino quase não absorve açúcar direto.","É o mais eficiente: menos energia se perde como metano. Por isso o grão engorda mais rápido."]},{"h":"Ácido butírico","p":["É produzido em menor quantidade.","A parede do rúmen o usa como alimento e ele ajuda a crescer as papilas."]},{"h":"No seu confinamento","p":["Mais concentrado = mais propiônico = mais ganho e melhor conversão, mas mais risco de acidose.","Os ionóforos como a monensina aumentam o propiônico e melhoram a conversão.","O equilíbrio é dar fibra suficiente para que o rúmen não acidifique."]}],"rel":["Micróbios do rúmen","Energia na ração","Ionóforos","Glicose no ruminante"]},{"t":"Ruminação e saliva","a":"fisiologia","r":"Ruminar é voltar a comida à boca para mastigá-la de novo. Enquanto rumina, o animal produz muita saliva, que é o antiácido natural do rúmen.","s":[{"h":"Como é a ruminação","p":["Um bovino rumina de 6 a 10 horas por dia, principalmente deitado e à noite.","Cada bolo é mastigado de 40 a 70 vezes.","Rumina mais com pasto e feno; menos com rações de muito grão moído."]},{"h":"A saliva","p":["Um bovino adulto produz de 100 a 180 litros de saliva por dia.","Tem bicarbonato e fosfato que neutralizam os ácidos do rúmen.","Menos ruminação = menos saliva = rúmen mais ácido."]},{"h":"Sinais para vigiar","p":["Em um lote sadio, mais da metade dos animais deitados deve estar ruminando.","Se poucos ruminam, falta fibra efetiva ou há acidose.","Um animal que para de ruminar está doente: examine-o."]},{"h":"No seu confinamento","p":["Deixe sempre alguma fibra longa (capim picado de 2 a 5 cm, feno ou palhada).","Não moa a forragem fina demais: perde o efeito de fazer ruminar.","Cochos com espaço e animais tranquilos ruminam melhor."]}],"rel":["Fibra e forragem na ração","Acidez do rúmen (pH ruminal)","Acidose ruminal","Fibra efetiva"]},{"t":"Proteína microbiana","a":"fisiologia","r":"Os micróbios do rúmen crescem, se multiplicam e depois passam ao abomaso, onde o animal os digere. Essa proteína de micróbios cobre entre metade e quatro quintos da proteína que o bovino precisa.","s":[{"h":"Como se forma","p":["Os micróbios pegam nitrogênio (da proteína da comida ou da ureia) e o transformam em amônia.","Com energia (amido, açúcar, fibra) e essa amônia fabricam seu próprio corpo.","Sem energia suficiente, a amônia é desperdiçada e sai pela urina."]},{"h":"Por que é tão boa","p":["Tem aminoácidos de muito boa qualidade, parecida com a da carne.","É a proteína mais barata: é feita com pasto, melaço e ureia.","Uma engorda bem balanceada aproveita ao máximo os micróbios."]},{"h":"Sincronia","p":["Energia e nitrogênio devem chegar ao rúmen ao mesmo tempo.","Por isso a ureia se mistura com melaço ou grão, nunca sozinha.","Dividir a comida em vários tratos melhora a sincronia."]},{"h":"No seu confinamento","p":["Pastos secos com pouca proteína (menos de 7 %) não alimentam os micróbios: o animal come pouco.","Uma pequena quantidade de proteína ou ureia com melaço desperta os micróbios e sobe o consumo de pasto."]}],"rel":["Proteína na ração","Ureia na ração","Proteína de escape (by-pass)","Reciclagem de ureia"]},{"t":"Reciclagem de ureia","a":"fisiologia","r":"O bovino tem um truque: parte da ureia que o fígado faz volta ao rúmen pela saliva e pela parede do rúmen, e os micróbios a usam de novo para fazer proteína.","s":[{"h":"Como funciona","p":["A amônia que sobra no rúmen passa ao sangue.","O fígado a converte em ureia, que é menos tóxica.","Uma parte sai na urina e outra volta ao rúmen com a saliva."]},{"h":"Quando importa","p":["Na época seca, com pastos pobres, a reciclagem ajuda a sobreviver.","O zebu recicla ureia com mais eficiência que as raças europeias.","Quanto menos proteína tem a dieta, mais ureia o animal recicla."]},{"h":"Custo","p":["Converter amônia em ureia custa energia ao fígado.","Se há proteína demais na ração, o animal gasta energia para eliminá-la e polui com nitrogênio."]},{"h":"No seu confinamento","p":["Não gaste demais com proteína: passada a exigência, você só paga urina cara.","O nitrogênio ureico no sangue, medido em laboratório, diz se sobra ou falta proteína."]}],"rel":["Proteína microbiana","Ureia na ração","O fígado do bovino"]},{"t":"Glicose no ruminante","a":"fisiologia","r":"Diferente das pessoas e dos porcos, o bovino quase não absorve açúcar da comida: os micróbios o comem primeiro. O animal fabrica sua própria glicose no fígado, sobretudo a partir do ácido propiônico.","s":[{"h":"De onde vem","p":["Do ácido propiônico que os micróbios fazem com o amido.","De alguns aminoácidos da proteína.","Do amido que escapa do rúmen e é digerido no intestino."]},{"h":"Para que a usa","p":["O cérebro, os glóbulos vermelhos e o feto dependem da glicose.","Na engorda é usada para formar a gordura do marmoreio.","A insulina sobe quando há mais propiônico e favorece guardar gordura."]},{"h":"No seu confinamento","p":["As rações com grão dão mais propiônico e mais glicose: o animal engorda mais rápido.","O milho bem processado fornece mais propiônico que o pasto.","Um animal em jejum longo queima gordura e pode ter cetose, embora em novilhos seja raro."]}],"rel":["Ácidos graxos voláteis","O fígado do bovino","Formação do marmoreio"]},{"t":"O fígado do bovino","a":"fisiologia","r":"O fígado é a fábrica química do animal: faz glicose, converte a amônia em ureia, guarda vitaminas e minerais e limpa toxinas e medicamentos.","s":[{"h":"Trabalhos principais","p":["Converte o ácido propiônico em glicose.","Transforma a amônia tóxica em ureia.","Guarda vitamina A, cobre, ferro e outras reservas.","Destrói toxinas de plantas, fungos e medicamentos."]},{"h":"Problemas comuns","p":["Abscessos por acidose: bactérias passam do rúmen danificado para o fígado.","Fasciola: um parasita que vive nos ductos do fígado.","Intoxicações por plantas ou aflatoxinas do milho estragado."]},{"h":"Carência de medicamentos","p":["O fígado vai eliminando os medicamentos aos poucos.","Por isso cada produto tem dias de carência antes de vender ao frigorífico.","O fígado e o rim guardam resíduos por mais tempo que a carne."]},{"h":"No seu confinamento","p":["No frigorífico, peça para ver os fígados: se muitos tiverem abscessos, revise a adaptação ao grão.","Não use milho mofado: as aflatoxinas danificam o fígado e baixam o ganho."]}],"rel":["Abscessos de fígado","Fascíola ou baratinha do fígado","Micotoxinas no alimento","Carências e resíduos"]},{"t":"Digestão no intestino","a":"fisiologia","r":"Depois do abomaso, a comida passa ao intestino delgado, onde se absorvem proteínas, gorduras, amido que escapou do rúmen, vitaminas e minerais. O intestino grosso faz uma segunda fermentação.","s":[{"h":"Intestino delgado","p":["Mede uns 40 metros em um bovino adulto.","O pâncreas e a bile ajudam a digerir.","Absorvem-se aminoácidos, gorduras, glicose, cálcio, fósforo e outros minerais."]},{"h":"Intestino grosso","p":["O ceco e o cólon têm micróbios que fermentam o que não foi digerido.","Ali se reabsorve água.","Se chega muito amido ao intestino grosso, fermenta de uma vez e dá diarreia com bolhas."]},{"h":"Sinais nas fezes","p":["Fezes com grãos inteiros: o grão não foi bem processado ou passa rápido demais.","Fezes muito líquidas e ácidas: excesso de amido ou acidose.","Fezes com muco ou sangue: possível coccidiose ou outra infecção."]},{"h":"No seu confinamento","p":["Quebrar ou moer o grão melhora muito sua digestão.","As fezes são uma janela para o que acontece por dentro: revise-as todo dia."]}],"rel":["Como ler as fezes","Amido e processamento de grãos","Diarreia no confinamento"]},{"t":"Taxa de passagem e enchimento","a":"fisiologia","r":"A comida leva de um a três dias para percorrer todo o tubo digestivo. Quanto mais rápido passa, mais o animal pode comer, mas menos tempo os micróbios têm para digeri-la.","s":[{"h":"O que limita o consumo","p":["Com pasto e forragem: o enchimento do rúmen. O animal para de comer porque está cheio.","Com rações de muito grão: a energia. O animal para de comer porque já cobriu sua necessidade.","O calor, o estresse e as doenças também baixam o consumo."]},{"h":"Como acelerar a passagem","p":["Picar a forragem menor.","Dar pastos mais novos e digestíveis.","Dar proteína suficiente para os micróbios trabalharem rápido."]},{"h":"O equilíbrio","p":["Se a forragem está moída demais, passa rápido mas não faz ruminar.","Pasto velho e duro fica dias no rúmen: o animal come pouco e ganha pouco."]},{"h":"No seu confinamento","p":["A qualidade do pasto importa mais que a quantidade: um pasto velho enche mas não engorda.","Corte os pastos no ponto: costumam ser 35 a 60 dias conforme a espécie e a época."]}],"rel":["Matéria seca e consumo","Qualidade da forragem e idade de corte","Consumo como porcentagem do peso"]},{"t":"Metano e arroto","a":"fisiologia","r":"As arqueias do rúmen produzem metano para se livrar do hidrogênio que sobra da fermentação. O animal o elimina arrotando. É energia perdida: entre 2 e 12 % da energia da comida.","s":[{"h":"Por que se forma","p":["A fermentação da fibra libera hidrogênio.","As arqueias juntam hidrogênio e carbono e fazem metano.","Assim o rúmen não se enche de hidrogênio e os micróbios continuam trabalhando."]},{"h":"Quanto se perde","p":["Com pastos maduros e pobres: 6 a 10 % da energia.","Com rações de engorda com grão: 3 a 4 %.","Um novilho produz uns 150 a 250 gramas de metano por dia conforme a dieta."]},{"h":"O arroto","p":["O animal arrota a cada um ou dois minutos.","Se não consegue arrotar, o rúmen incha: isso é o timpanismo.","É preciso deixar o animal de pé ou em declive com a cabeça para cima para que arrote."]},{"h":"No seu confinamento","p":["Menos metano = mais energia para ganhar peso.","Boa forragem, grão, ionóforos e leguminosas baixam o metano por quilo de carne.","Terminar a engorda mais rápido baixa o metano total de cada animal."]}],"rel":["Timpanismo (rúmen inchado)","Metano entérico e como reduzi-lo","Ácidos graxos voláteis"]},{"t":"Gordura no rúmen","a":"fisiologia","r":"Os micróbios do rúmen transformam as gorduras insaturadas da comida em gorduras saturadas. Por isso a gordura bovina é mais dura que a do porco ou do frango, mesmo que coma óleos vegetais.","s":[{"h":"Bio-hidrogenação","p":["As gorduras do pasto e das sementes chegam ao rúmen como óleos insaturados.","Os micróbios lhes acrescentam hidrogênio e as tornam saturadas.","No caminho se formam ácidos especiais como o CLA, presente na carne e no leite."]},{"h":"Limite","p":["Mais de 6 a 7 % de gordura total na matéria seca da ração prejudica os micróbios da fibra.","O animal come menos e digere pior a forragem.","Por isso o óleo se adiciona em pouca quantidade ou como gordura protegida."]},{"h":"No seu confinamento","p":["Um pouco de gordura sobe a energia da ração sem risco de acidose.","Caroço de algodão, palmiste ou gordura protegida são fontes comuns.","A carne de animais a pasto tem um pouco mais de ômega 3 e CLA."]}],"rel":["Gorduras e óleos na ração","Gordura protegida","Gordura da carne e ômega 3"]},{"t":"Papilas do rúmen","a":"fisiologia","r":"A parede do rúmen é coberta de papilas, pequenos dedos que aumentam a superfície para absorver os ácidos. Crescem ou encolhem conforme a dieta.","s":[{"h":"Como mudam","p":["Com dietas de energia, os ácidos butírico e propiônico as fazem crescer.","Com pasto pobre ficam curtas e absorvem menos.","Levam de 4 a 6 semanas para crescer depois de mudar a dieta."]},{"h":"Por que importa","p":["Se há muitos ácidos e poucas papilas, os ácidos se acumulam e baixam o pH.","Por isso um animal que vem do pasto precisa de adaptação lenta ao concentrado.","As papilas danificadas pela acidose deixam passar bactérias ao fígado."]},{"h":"No seu confinamento","p":["Adapte ao concentrado em 2 a 3 semanas: dê tempo para as papilas crescerem.","Nos primeiros dias dê mais forragem e suba o grão aos poucos."]}],"rel":["Adaptação ao concentrado","Ácidos graxos voláteis","Abscessos de fígado"]},{"t":"Crescimento dos tecidos","a":"fisiologia","r":"O animal não cresce por igual: primeiro forma osso, depois músculo e por último gordura. Por isso, ao se aproximar do peso adulto, cada quilo que ganha tem mais gordura e custa mais comida.","s":[{"h":"A ordem","p":["Primeiro o sistema nervoso e os ossos.","Depois o músculo: o animal jovem ganha sobretudo carne magra.","Por último a gordura: primeiro nas vísceras, depois entre músculos, depois sob a pele e por fim dentro do músculo (marmoreio)."]},{"h":"Por que a gordura custa mais","p":["Um quilo de tecido magro tem uns 70 a 75 % de água; forma-se com pouca energia.","Um quilo de gordura tem muito pouca água e muita energia: custa de 2 a 3 vezes mais comida.","Por isso a conversão piora no final da engorda."]},{"h":"Curva de crescimento","p":["O ganho sobe na juventude, chega a um máximo e depois cai.","Animais maiores quando adultos (frame alto) chegam mais tarde à fase de engordar.","Machos inteiros formam mais músculo e menos gordura que os castrados."]},{"h":"No seu confinamento","p":["Não engorde demais: passado o grau de acabamento que seu comprador paga, você perde dinheiro.","Animais jovens convertem melhor; animais velhos ou magros engordam rápido no começo pelo crescimento compensatório."]}],"rel":["Grau de acabamento","Tamanho adulto e frame","Crescimento compensatório","Conversão alimentar"]},{"t":"Músculo: como cresce","a":"fisiologia","r":"Depois do nascimento o número de fibras musculares quase não muda: o músculo cresce porque cada fibra fica mais comprida e mais grossa, graças a células de reserva chamadas satélite.","s":[{"h":"Fibras e células satélite","p":["O número de fibras se define antes de nascer; a nutrição da mãe na prenhez importa.","Depois, as células satélite fornecem núcleos novos para cada fibra crescer.","O crescimento precisa de proteína, energia e hormônios como o do crescimento e o IGF-1."]},{"h":"Renovação da proteína","p":["O músculo é formado e destruído o tempo todo.","Ganhar músculo é formar mais do que se destrói.","O estresse e as doenças aumentam a destruição: o animal perde peso."]},{"h":"O que o favorece","p":["Boa proteína na ração, sobretudo em animais jovens.","Machos inteiros, pela testosterona.","Implantes hormonais onde são legais.","Genética de boa musculatura."]},{"h":"No seu confinamento","p":["Um animal doente perde músculo e leva semanas para recuperá-lo.","Nos primeiros meses de engorda, não economize proteína."]}],"rel":["Crescimento dos tecidos","Hormônios do crescimento","Inteiros ou castrados","Promotores de crescimento e implantes"]},{"t":"Formação do marmoreio","a":"fisiologia","r":"O marmoreio é a gordura que se forma dentro do músculo, em veios finos. É a última gordura a se depositar e dá suculência e sabor à carne.","s":[{"h":"Como se forma","p":["As células de gordura dentro do músculo se formam desde bezerro.","Crescem sobretudo quando o animal tem energia de sobra e glicose do grão.","É a última gordura a encher; por isso precisa de tempo de engorda."]},{"h":"O que o aumenta","p":["Genética: Angus e Wagyu marmoreiam muito; o zebu pouco.","Dietas com grão e dias suficientes de engorda.","Castrados e fêmeas marmoreiam mais que touros inteiros.","Evitar que o bezerro passe fome nos primeiros meses."]},{"h":"No trópico","p":["O Brahman e o Nelore têm pouco marmoreio por natureza.","Os cruzamentos com raças europeias melhoram o marmoreio.","Na América Central quase não se paga por marmoreio; paga-se por peso, idade e acabamento."]},{"h":"No seu confinamento","p":["Se seu comprador não paga marmoreio, não prolongue a engorda por ele.","Se você vende para um mercado de qualidade, planeje cruzamentos e engorda com grão."]}],"rel":["Crescimento dos tecidos","Marmoreio e qualidade","Raças para engorda no trópico","Grau de acabamento"]},{"t":"Hormônios do crescimento","a":"fisiologia","r":"O crescimento é dirigido por hormônios: o do crescimento, o IGF-1, a insulina, os hormônios sexuais, os da tireoide e o cortisol do estresse.","s":[{"h":"Os que fazem crescer","p":["Hormônio do crescimento: sai do cérebro e manda o fígado produzir IGF-1.","IGF-1: faz crescer músculo e osso; sobe com boa comida.","Insulina: guarda energia como gordura e músculo; sobe com comida rica em energia.","Testosterona: faz mais músculo; por isso o touro inteiro cresce mais rápido."]},{"h":"Os do metabolismo","p":["Hormônios da tireoide: marcam a velocidade do motor do corpo.","Com calor caem: o animal produz menos calor, mas também cresce menos.","Leptina: é produzida pela gordura e avisa o cérebro que já há reservas."]},{"h":"O do estresse","p":["Cortisol: sobe com o transporte, o medo, o calor e a dor.","Destrói músculo para tirar energia e baixa as defesas.","Por isso os animais estressados adoecem e perdem peso."]},{"h":"No seu confinamento","p":["Bom trato e boa comida mantêm altos os hormônios do crescimento.","Os implantes imitam os hormônios sexuais; só onde são legais e respeitando carências."]}],"rel":["Músculo: como cresce","Estresse e defesas","Promotores de crescimento e implantes","Inteiros ou castrados"]},{"t":"Energia de mantença","a":"fisiologia","r":"Antes de ganhar um só quilo, o animal gasta energia só para viver: respirar, bombear sangue, manter a temperatura e renovar tecidos. É a mantença, e leva entre 40 e 60 % do que come um novilho em engorda.","s":[{"h":"Quanto é","p":["Calcula-se com o peso metabólico: o peso elevado à potência 0,75.","Um novilho de 400 kg precisa de umas 6 a 7 megacalorias de energia líquida por dia só para se manter.","O zebu gasta cerca de 10 % menos que as raças europeias."]},{"h":"O que a aumenta","p":["Caminhar muito em piquetes grandes ou com água longe.","Frio ou calor fora da zona de conforto.","Doenças, parasitas e estresse.","Animais nervosos gastam mais."]},{"h":"Por que importa","p":["Tudo o que come acima da mantença vira ganho.","Se o animal come apenas para se manter, passa meses sem subir: você perde dinheiro a cada dia.","Engordar rápido dilui o custo da mantença."]},{"h":"No seu confinamento","p":["Água perto, sombra e animais tranquilos baixam a mantença.","Por isso a engorda lenta sai cara mesmo que a comida seja barata."]}],"rel":["Peso metabólico","Energia metabolizável e líquida","Custo por animal por dia","Estresse por calor"]},{"t":"Zona de conforto térmico","a":"fisiologia","r":"Cada animal tem uma faixa de temperatura em que não gasta energia para se refrescar nem se aquecer. No trópico o problema quase sempre é o calor.","s":[{"h":"Os limites","p":["As raças europeias começam a sofrer com o calor acima de uns 25 °C com umidade alta.","O zebu aguenta até uns 32 a 35 °C antes de baixar muito o consumo.","A umidade piora tudo: o animal não consegue evaporar o suor."]},{"h":"Como perde calor","p":["Suando: o zebu tem mais glândulas de suor e maiores.","Ofegando: respira rápido para eliminar calor.","Pela pele: mais pele solta (barbela, umbigo) dá mais superfície.","Buscando sombra, água e vento."]},{"h":"Temperatura normal","p":["Temperatura do corpo: 38,0 a 39,3 °C.","Respiração em repouso: 20 a 40 por minuto.","Com mais de 80 respirações por minuto e boca aberta, o animal está com problemas."]},{"h":"No seu confinamento","p":["Cada grau acima do limite baixa o consumo e o ganho.","A comida mais forte convém dar cedo ou ao entardecer.","O índice de temperatura e umidade (ITU) diz o risco do dia: o Rumi o calcula com o clima da sua região."]}],"rel":["Estresse por calor","Índice de calor","Golpe de calor","Sombra","Adaptação do zebu ao trópico"]},{"t":"Adaptação do zebu ao trópico","a":"fisiologia","r":"O zebu (Bos indicus: Brahman, Nelore, Gir, Guzerá) vem da Índia e é feito para o calor, os carrapatos e os pastos pobres. Por isso é a base do gado de corte no trópico.","s":[{"h":"Contra o calor","p":["Mais glândulas de suor e maiores.","Pelo curto e brilhante que reflete o sol; pele escura que protege dos raios.","Pele solta, barbela e cupim: mais superfície para eliminar calor.","Produz menos calor interno pelo metabolismo mais lento."]},{"h":"Contra pragas e pastos pobres","p":["Mais resistente a carrapatos: sua pele se mexe e ele os lambe.","Recicla melhor a ureia: aguenta melhor a seca.","Caminha mais e busca comida em pastos difíceis."]},{"h":"Suas desvantagens","p":["Cresce um pouco mais devagar que as raças europeias quando a comida é muito boa.","Carne um pouco menos macia por ter mais calpastatina, uma proteína que freia o amaciamento.","Temperamento mais nervoso; precisa de manejo tranquilo."]},{"h":"No seu confinamento","p":["Os cruzamentos zebu com europeu (F1) juntam rusticidade e crescimento: têm vigor híbrido.","No confinamento com sombra e boa comida, os cruzados rendem muito bem."]}],"rel":["Raças para engorda no trópico","Vigor híbrido ou heterose","Zona de conforto térmico","Maciez da carne"]},{"t":"Consumo de água e regulação","a":"fisiologia","r":"A água é o nutriente mais importante. Um bovino aguenta semanas sem comer, mas só alguns dias sem água. O consumo sobe muito com o calor e com rações secas ou salgadas.","s":[{"h":"Quanto bebe","p":["Uns 3 a 4 litros por quilo de matéria seca que come em clima temperado.","Com calor pode chegar a 8 a 10 % do peso: um novilho de 400 kg pode beber 50 a 70 litros por dia.","Rações com muito sal, proteína ou forragem seca aumentam a sede."]},{"h":"O que a água faz","p":["Refresca o corpo com o suor e a respiração ofegante.","Leva nutrientes e tira resíduos pela urina.","Mantém o rúmen úmido para os micróbios trabalharem."]},{"h":"Sinais de falta","p":["Olhos fundos, pele que demora a voltar ao ser beliscada, fezes secas.","Queda do consumo de comida: sem água não há consumo.","Brigas no bebedouro."]},{"h":"No seu confinamento","p":["Água limpa, fresca e à vontade.","Bebedouros com espaço para 10 % do lote ao mesmo tempo.","Menos água = menos comida = menos ganho, mesmo que a ração seja boa."]}],"rel":["Água de bebida","Bebedouros","Desidratação e soros","Água: fontes, caixas e qualidade"]},{"t":"Sistema imune do bovino","a":"fisiologia","r":"As defesas do bovino têm duas linhas: a imunidade inata, que reage rápido a tudo, e a adquirida, que aprende a reconhecer cada micróbio e se lembra dele. As vacinas treinam a segunda.","s":[{"h":"Primeira linha","p":["Pele, muco do nariz, pelos do sistema respiratório e ácido do estômago.","Células que comem os micróbios.","Febre: o corpo sobe a temperatura para frear os micróbios."]},{"h":"Segunda linha","p":["Anticorpos: proteínas que grudam em um micróbio específico.","Células de memória: lembram do micróbio por meses ou anos.","Leva de 10 a 21 dias para se armar na primeira vez."]},{"h":"O que a enfraquece","p":["Estresse de transporte, desmame, mistura de lotes e calor: o cortisol baixa as defesas.","Falta de energia, proteína, zinco, cobre, selênio e vitaminas A e E.","Parasitas e doenças anteriores como a diarreia viral bovina."]},{"h":"No seu confinamento","p":["Por isso os primeiros 45 dias depois da compra são os de mais doença.","Vacine quando o animal estiver tranquilo e bem alimentado, e aplique a segunda dose.","Um bom manejo na chegada vale mais que muitos remédios."]}],"rel":["Vacinação","Estresse e defesas","Recepção de gado","Como funcionam as vacinas"]},{"t":"Como funcionam as vacinas","a":"fisiologia","r":"Uma vacina mostra ao corpo um micróbio morto, enfraquecido ou uma parte dele, para que aprenda a se defender sem adoecer. A proteção não é imediata.","s":[{"h":"Tipos","p":["Vivas modificadas: micróbios enfraquecidos; protegem rápido e forte, às vezes com uma só dose.","Inativadas ou mortas: mais seguras, mas quase sempre precisam de duas doses.","Toxoides: contra as toxinas, como as de clostrídios e tétano."]},{"h":"Primeira dose e reforço","p":["A primeira dose prepara o corpo.","O reforço, 2 a 4 semanas depois, dispara a proteção forte.","Sem reforço, muitas vacinas mortas protegem muito pouco."]},{"h":"Cuidar da vacina","p":["Guardar entre 2 e 8 °C, nunca congelada nem ao sol.","As vacinas vivas se usam na primeira hora depois de misturadas.","Não limpar a agulha com álcool se a vacina for viva."]},{"h":"No seu confinamento","p":["Vacinar um animal já doente ou muito estressado protege pouco.","Anote a data e o lote da vacina no app para saber quando reforçar."]}],"rel":["Vacinação","Sistema imune do bovino","Doenças clostridiais","Aplicação de injeções"]},{"t":"Febre: o que é e o que fazer","a":"fisiologia","r":"A febre é a temperatura do corpo acima do normal. No bovino, mais de 39,5 °C em repouso e à sombra é sinal de infecção ou de golpe de calor.","s":[{"h":"Como medir","p":["Termômetro no reto, por pelo menos um minuto.","Meça de manhã e com o animal tranquilo: o calor e a correria sobem a temperatura.","Compare com dois ou três animais sadios do mesmo lote."]},{"h":"O que significa","p":["39,5 a 40 °C: febre leve, vigie.","Mais de 40 °C: febre, quase sempre infecção (pneumonia, anaplasma, babesia).","Mais de 41 °C: grave, ou golpe de calor."]},{"h":"O que fazer","p":["Separe o animal na sombra com água e comida.","Chame o veterinário para saber a causa antes de dar antibióticos.","Anote a temperatura e o tratamento no app."]}],"rel":["Sinais vitais e como medi-los","Pneumonia ou complexo respiratório","Golpe de calor","Curral de doentes"]},{"t":"Comportamento natural do gado","a":"fisiologia","r":"O bovino é um animal de presa e de rebanho. Entender como vê, ouve e reage permite manejá-lo com menos pancadas, menos estresse e mais ganho.","s":[{"h":"Como vê","p":["Vê quase tudo ao redor, menos bem atrás dele.","Enxerga mal a profundidade: uma sombra ou uma poça parecem um buraco.","Assusta-se com contrastes fortes, objetos que se mexem e roupas penduradas."]},{"h":"Como ouve","p":["Ouve melhor que as pessoas os sons agudos.","Gritos, assobios e batidas de metal o estressam.","Fale baixo e evite ruídos fortes no tronco."]},{"h":"O rebanho","p":["Sente-se seguro em grupo; um animal sozinho fica nervoso e perigoso.","Tem hierarquia: os dominantes comem primeiro.","Misturar lotes causa brigas por vários dias."]},{"h":"Zona de fuga e ponto de equilíbrio","p":["A zona de fuga é a distância em que o animal se afasta de você.","O ponto de equilíbrio fica na altura da paleta: se você passa por trás, ele avança; pela frente, recua.","Trabalhe na borda da zona de fuga, sem entrar de repente."]},{"h":"No seu confinamento","p":["Animais manejados com calma comem mais e ganham mais.","Cuide para que os animais de baixo na hierarquia alcancem o cocho."]}],"rel":["Manejo tranquilo do gado","Trabalho no tronco","Bem-estar animal","Temperamento e ganho"]},{"t":"Temperamento e ganho","a":"fisiologia","r":"Os animais nervosos ganham menos peso, adoecem mais e dão carne mais dura. O temperamento é em parte herdado e também se educa com bom manejo.","s":[{"h":"Como medi-lo","p":["Velocidade de saída do tronco: os que saem correndo são mais nervosos.","Nota no tronco: de 1 (tranquilo) a 5 (muito agitado).","A distância em que foge quando você se aproxima."]},{"h":"O que causa","p":["Mais cortisol no sangue: menos defesas e mais gasto de energia.","Menos consumo: passam mais tempo alerta e menos comendo.","Carne mais dura e mais casos de carne escura."]},{"h":"O que fazer","p":["Compre animais tranquilos quando puder.","Acostume o lote à sua presença caminhando calmamente entre eles.","Se um animal é muito bravo e põe em risco as pessoas ou o lote, separe-o ou venda-o."]}],"rel":["Comportamento natural do gado","Animais bravos","Carne escura (corte escuro, DFD)"]},{"t":"Sono e descanso","a":"fisiologia","r":"Um bovino passa deitado de 10 a 14 horas por dia. Deitado rumina melhor, descansa as patas e economiza energia. Um curral que não permite deitar baixa o ganho.","s":[{"h":"Quanto descansa","p":["Dorme de verdade só alguns minutos por vez; o resto é descanso e ruminação.","Rumina melhor deitado sobre o peito.","Se o piso está molhado, com lama ou muito duro, deita menos."]},{"h":"O que precisa","p":["Piso seco e firme, com drenagem.","Espaço para deitar sem se pisarem.","Sombra nas horas de calor."]},{"h":"No seu confinamento","p":["Se muitos animais estão de pé na lama, o curral precisa de conserto.","Calcule pelo menos 10 a 15 m² por animal em curral de terra; mais na época de chuvas."]}],"rel":["Pisos e drenagem","Espaço por animal","Ruminação e saliva"]},{"t":"Sangue e circulação","a":"fisiologia","r":"O sangue leva oxigênio, nutrientes, hormônios e defesas a todo o corpo. Um bovino tem uns 8 litros de sangue a cada 100 kg de peso.","s":[{"h":"Componentes","p":["Glóbulos vermelhos: levam oxigênio; o anaplasma e a babésia os destroem.","Glóbulos brancos: são as defesas.","Plaquetas: ajudam a coagular.","Plasma: o líquido que leva nutrientes e resíduos."]},{"h":"Sinais de anemia","p":["Mucosas do olho ou da vulva pálidas ou amarelas.","Cansaço, respiração rápida e fraqueza.","Causas comuns: anaplasmose, babesiose, parasitas que chupam sangue e fasciola."]},{"h":"Pulso normal","p":["De 60 a 80 batimentos por minuto em repouso.","Mede-se embaixo da cauda, na artéria coccígea.","Sobe com febre, dor, calor e excitação."]},{"h":"No seu confinamento","p":["Revise a cor das mucosas quando um animal estiver abatido.","Uma amostra de sangue ao laboratório confirma a anemia e sua causa."]}],"rel":["Anaplasmose","Babesiose (tristeza parasitária)","Sinais vitais e como medi-los","Coletar amostras para laboratório"]},{"t":"Respiração e pulmões","a":"fisiologia","r":"Os pulmões do bovino são pequenos para seu tamanho e divididos em lobos. Por isso as pneumonias o afetam muito e deixam sequelas que baixam o ganho.","s":[{"h":"Particularidades","p":["Têm pouca capacidade de reserva: qualquer dano se nota.","Os lobos não se comunicam bem entre si: a infecção fica presa.","Os pelos e o muco do nariz prendem poeira e micróbios, mas o estresse os enfraquece."]},{"h":"O que os danifica","p":["Poeira do curral na época seca.","Amônia de currais sujos e fechados.","Vírus que abrem a porta para bactérias, como no complexo respiratório."]},{"h":"No seu confinamento","p":["Molhe o curral ou coloque cortinas contra a poeira no verão.","Ventilação em galpões cobertos.","Um animal que teve pneumonia grave pode ganhar 50 a 100 gramas menos por dia pelo resto da engorda."]}],"rel":["Pneumonia ou complexo respiratório","Galpão ou confinamento coberto","Doenças virais respiratórias e BVD"]},{"t":"Rins e urina","a":"fisiologia","r":"Os rins filtram o sangue, retiram resíduos como a ureia e controlam a água e o sal do corpo. A urina conta muito da saúde do animal.","s":[{"h":"O que fazem","p":["Eliminam ureia, excesso de minerais e medicamentos.","Guardam água quando o animal tem sede.","Ajudam a manter o equilíbrio ácido do corpo."]},{"h":"Sinais na urina","p":["Urina vermelha ou marrom: possível babésia, leptospira ou planta tóxica.","Urina em gotas ou com esforço: possível cálculo urinário em machos.","Urina muito escura e pouca: falta de água."]},{"h":"No seu confinamento","p":["Cálculos urinários: vigie a relação cálcio e fósforo e dê água e sal suficientes.","Machos castrados jovens têm a uretra mais estreita e mais risco."]}],"rel":["Cálculos urinários","Urina vermelha ou escura","Relação cálcio e fósforo"]},{"t":"Pele e pelo","a":"fisiologia","r":"A pele é a primeira barreira contra o sol, os insetos e os micróbios. No trópico, o tipo de pelo e de pele decide quanto calor um animal aguenta.","s":[{"h":"O pelo","p":["Pelo curto, liso e brilhante reflete o sol e deixa suar.","Pelo longo e lanoso guarda calor: ruim no trópico.","Cores claras absorvem menos calor; pele escura protege do sol."]},{"h":"Gene do pelo curto (slick)","p":["Algumas raças crioulas e o Senepol têm o gene 'slick' de pelo muito curto.","Os animais com esse gene aguentam melhor o calor.","Está sendo usado em cruzamentos para o trópico."]},{"h":"Problemas comuns","p":["Carrapatos, berne, moscas e bicheira.","Fungos, sarna, dermatofilose e verrugas.","Fotossensibilização por plantas ou pastos em pele branca."]},{"h":"No seu confinamento","p":["Um pelo opaco e arrepiado costuma indicar parasitas, deficiência de minerais ou doença.","Trocar o pelo de inverno a tempo é sinal de boa nutrição."]}],"rel":["Problemas de pele","Adaptação do zebu ao trópico","Carrapatos","Gene do pelo curto (slick)"]},{"t":"Minerais no corpo","a":"fisiologia","r":"Os minerais formam os ossos, movem os músculos, fazem as enzimas trabalharem e fortalecem as defesas. Faltam com frequência nos pastos tropicais.","s":[{"h":"Macrominerais","p":["Cálcio e fósforo: ossos, músculos e energia. O fósforo é o que mais falta nos pastos tropicais.","Sódio e cloro (sal): água do corpo e apetite.","Magnésio e potássio: nervos e músculos.","Enxofre: para os micróbios fazerem proteína."]},{"h":"Microminerais","p":["Zinco: pele, cascos e defesas.","Cobre: pelo, sangue e defesas; o molibdênio e o enxofre o bloqueiam.","Selênio: defesas e músculo, junto com a vitamina E.","Cobalto: os micróbios o usam para fazer vitamina B12.","Iodo: tireoide e metabolismo."]},{"h":"Sinais de falta","p":["Comer terra, ossos, madeira ou lamber paredes (pica).","Pelo opaco, descolorido ou com 'óculos' ao redor dos olhos.","Pouco ganho sem razão clara."]},{"h":"No seu confinamento","p":["Sal mineral sempre disponível ou misturado na ração.","Escolha um sal mineral feito para sua região e seu tipo de pasto."]}],"rel":["Minerais principais","Microminerais e vitaminas","Sal mineral e blocos","Deficiências de minerais"]},{"t":"Vitaminas no bovino","a":"fisiologia","r":"Os micróbios do rúmen fabricam as vitaminas B e K. O animal precisa receber de fora as vitaminas A, D e E.","s":[{"h":"Vitamina A","p":["Vem do caroteno do pasto verde.","Na época seca, com pasto seco, acaba em 2 a 4 meses.","Sua falta causa cegueira noturna, olhos lacrimejantes, pouco ganho e mais doenças."]},{"h":"Vitamina D","p":["Forma-se na pele com o sol.","Animais ao sol raramente têm falta.","Ajuda a absorver cálcio e fósforo."]},{"h":"Vitamina E","p":["Vem do pasto verde; o grão armazenado tem pouca.","Trabalha junto com o selênio nas defesas e no músculo.","É adicionada em rações de confinamento e na chegada de animais estressados."]},{"h":"Vitaminas B","p":["Os micróbios as fabricam; raramente faltam.","A tiamina (B1) pode faltar em acidose ou com excesso de enxofre: causa polioencefalomalácia."]},{"h":"No seu confinamento","p":["Na época seca ou no confinamento sem forragem verde, dê vitaminas A, D e E no sal ou injetadas.","A injeção de vitaminas na chegada é uma prática comum e barata."]}],"rel":["Microminerais e vitaminas","Vitaminas A, D e E na época seca","Polioencefalomalácia","Selênio e vitamina E"]},{"t":"Estresse oxidativo","a":"fisiologia","r":"Quando o animal sofre calor, estresse ou doença, formam-se em seu corpo moléculas prejudiciais chamadas radicais livres. Os antioxidantes como a vitamina E e o selênio os controlam.","s":[{"h":"O que o causa","p":["Calor forte e prolongado.","Transporte, desmame, mistura de lotes.","Infecções e crescimento muito rápido."]},{"h":"O que provoca","p":["Dano às células de defesa e ao músculo.","Mais doenças e pior recuperação."]},{"h":"Antioxidantes","p":["Vitamina E, selênio, zinco, cobre e manganês.","O pasto verde tem antioxidantes naturais.","Alguns aditivos vegetais também ajudam."]},{"h":"No seu confinamento","p":["Na época de calor e ao receber animais, garanta vitamina E e selênio.","Não exagere no selênio: é tóxico em excesso. Siga a dose do rótulo."]}],"rel":["Selênio e vitamina E","Estresse e defesas","Estresse por calor"]},{"t":"Cascos e patas","a":"fisiologia","r":"Um bovino carrega todo o seu peso sobre oito unhas. Se doem, caminha pouco, come pouco e deixa de ganhar peso.","s":[{"h":"Como são","p":["Cada pata tem duas unhas principais e duas rudimentares.","O casco cresce uns 5 milímetros por mês.","O casco é de queratina, como as unhas, e precisa de zinco e biotina."]},{"h":"O que os danifica","p":["Lama permanente: amolece o casco e deixa entrar bactérias.","Pedras, pisos ásperos e cimento escorregadio.","Acidose: causa laminite, inflamação dentro do casco."]},{"h":"No seu confinamento","p":["Currais secos e caminhos sem pedras soltas.","Um animal que manca ganha menos: examine-o no tronco.","Pedilúvio com sulfato de cobre ou zinco ajuda na época de chuvas."]}],"rel":["Mancadeiras e problemas de casco","Pedilúvio","Acidose ruminal","Pisos e drenagem"]},{"t":"Dentes e idade","a":"fisiologia","r":"O bovino não tem dentes de cima na frente: corta o pasto apertando-o com a língua contra uma almofada. Os dentes de baixo mudam com a idade e servem para calculá-la.","s":[{"h":"A dentição","p":["Na frente embaixo: 8 incisivos. Em cima: uma almofada dura.","Atrás: molares grandes para moer.","A língua comprida e áspera enrola o pasto."]},{"h":"Troca de dentes","p":["Dentes de leite até cerca de 18 a 24 meses.","Dois dentes permanentes: cerca de 2 anos.","Quatro dentes: cerca de 2,5 a 3 anos; seis: 3 a 3,5; oito: 4 anos ou mais.","O zebu pode trocar um pouco mais tarde."]},{"h":"No seu confinamento","p":["O frigorífico e o comprador usam os dentes para classificar a carcaça.","Animais com menos dentes permanentes costumam valer mais.","Pastos muito duros e terra desgastam os dentes de animais velhos."]}],"rel":["Idade pelos dentes","Qualidade da carcaça","Comprar gado para engorda"]},{"t":"Digestibilidade","a":"fisiologia","r":"A digestibilidade é a parte da comida que o animal aproveita e não sai nas fezes. Um pasto com 60 % de digestibilidade deixa ao animal 60 % do que comeu.","s":[{"h":"Exemplos","p":["Grão de milho bem processado: 85 a 90 %.","Pasto novo bem manejado: 60 a 70 %.","Pasto velho ou palhada: 40 a 50 %."]},{"h":"O que a baixa","p":["Idade da planta: mais velha, mais lignina, menos digestível.","Pouca proteína: os micróbios trabalham devagar.","Calor: as plantas tropicais fazem mais fibra com calor."]},{"h":"Por que importa em dobro","p":["Uma comida pouco digestível entrega menos energia.","Além disso, fica mais tempo no rúmen e o animal come menos.","Por isso um pasto velho engorda muito menos que um novo."]},{"h":"No seu confinamento","p":["A análise de laboratório mede a digestibilidade.","Cortar os pastos na hora certa é a forma mais barata de aumentá-la."]}],"rel":["Qualidade da forragem e idade de corte","Taxa de passagem e enchimento","Fibra em detergente neutro e ácido","Nutrientes digestíveis totais"]},{"t":"Pastos tropicais e temperados","a":"fisiologia","r":"Os pastos tropicais (tipo C4) crescem muito com calor e sol, mas fazem mais fibra e menos proteína que os pastos temperados. Por isso um novilho no trópico ganha menos a pasto do que em regiões frias.","s":[{"h":"Diferenças","p":["Pastos tropicais: mais produção por hectare, mais fibra, menos proteína.","Digestibilidade típica: 50 a 65 %, contra 65 a 80 % dos temperados.","Amadurecem rápido: em poucas semanas perdem qualidade."]},{"h":"Consequência","p":["Em bom pasto tropical, um novilho ganha 0,4 a 0,7 kg por dia.","Com suplemento pode subir para 0,8 a 1 kg.","No confinamento com ração balanceada pode ganhar 1,2 a 1,6 kg."]},{"h":"No seu confinamento","p":["Maneje o pastejo para comer o pasto novo.","Suplemente proteína na seca e energia nas chuvas quando buscar mais ganho.","As leguminosas e árvores forrageiras aumentam a proteína do pasto."]}],"rel":["Capins para pastagem no trópico","Suplementação no pasto","Leguminosas e árvores forrageiras","Digestibilidade"]},{"t":"Peso metabólico","a":"fisiologia","r":"Os animais grandes gastam menos energia por quilo que os pequenos. Por isso as exigências não se calculam com o peso normal, mas com o peso metabólico: o peso elevado à potência 0,75.","s":[{"h":"Como se calcula","p":["Peso metabólico = peso vivo elevado a 0,75.","Exemplo: 400 kg dá uns 89 kg de peso metabólico; 200 kg dá uns 53.","O animal de 400 kg pesa o dobro, mas sua mantença é só 1,7 vez maior."]},{"h":"Para que serve","p":["Calcular a energia de mantença.","Comparar animais de tamanhos diferentes.","Entender por que os animais grandes convertem diferente."]},{"h":"No seu confinamento","p":["As calculadoras do Rumi usam o peso metabólico para estimar o que seu lote precisa.","Você não precisa fazer a conta: só informe o peso."]}],"rel":["Energia de mantença","Energia metabolizável e líquida","Consumo e peso do animal"]},{"t":"Energia metabolizável e líquida","a":"fisiologia","r":"Nem toda a energia da comida vira carne. Perde-se nas fezes, na urina, no metano e como calor. O que sobra para manter e ganhar peso é a energia líquida.","s":[{"h":"A escada da energia","p":["Energia bruta: toda a que a comida tem se for queimada.","Energia digestível: a bruta menos a que sai nas fezes.","Energia metabolizável: a digestível menos a que sai na urina e no metano.","Energia líquida: a metabolizável menos o calor produzido ao digerir e usar a comida."]},{"h":"Dois tipos de energia líquida","p":["Energia líquida de mantença (ELm): a que cobre o gasto para viver.","Energia líquida de ganho (ELg): a que se converte em peso.","A mesma comida vale menos para ganhar do que para manter, porque formar tecido gasta mais."]},{"h":"Valores típicos por quilo de matéria seca","p":["Milho moído: ELm perto de 2,0 e ELg perto de 1,4 megacaloria.","Pasto tropical bom: ELm perto de 1,2 e ELg perto de 0,6.","Pasto velho: ELm perto de 0,9 e ELg quase nada."]},{"h":"No seu confinamento","p":["As tabelas modernas de exigências usam este sistema.","O formulador de dietas do app ajuda a balancear a energia sem fazer essas contas à mão."]}],"rel":["Energia na ração","Energia líquida e proteína degradável","Exigências: tabelas modernas","Formular uma ração"]},{"t":"Proteína metabolizável","a":"fisiologia","r":"A proteína metabolizável é a que de verdade chega ao intestino e o animal absorve: a proteína dos micróbios mais a proteína da comida que escapou do rúmen.","s":[{"h":"De onde vem","p":["Proteína microbiana: os micróbios a fazem com proteína degradável ou ureia e energia.","Proteína de escape (by-pass): a parte da comida que não se degrada no rúmen.","As duas são digeridas no abomaso e no intestino."]},{"h":"Por que a proteína bruta não basta","p":["A proteína bruta do rótulo não diz quanto chega ao intestino.","Duas rações com 13 % de proteína podem dar resultados diferentes.","Animais jovens e de crescimento rápido precisam de mais proteína de escape."]},{"h":"No seu confinamento","p":["Primeiro garanta proteína degradável para os micróbios; é a mais barata.","Depois, em animais leves que crescem rápido, adicione fontes de escape como farelo de soja tostado, DDGS ou farelos de sementes."]}],"rel":["Proteína na ração","Proteína microbiana","Proteína de escape (by-pass)","Energia líquida e proteína degradável"]},{"t":"Exigências: tabelas modernas","a":"fisiologia","r":"Os nutricionistas usam tabelas científicas para saber quanta energia, proteína e minerais cada animal precisa. As mais usadas são as da Academia Nacional de Ciências dos EUA (edição de 2016) e, para zebu e trópico, as brasileiras BR-CORTE.","s":[{"h":"O que dizem","p":["Quanta energia líquida um animal precisa conforme peso, sexo, raça e ganho.","Quanta proteína metabolizável e quantos minerais e vitaminas.","Quanto vai comer conforme o peso e a qualidade da comida."]},{"h":"Por que a raça importa","p":["O zebu tem uma mantença um pouco menor que as raças europeias.","As tabelas brasileiras foram feitas com Nelore e cruzados, mais parecidos com o gado da América Central.","As tabelas dos EUA foram feitas sobretudo com raças europeias."]},{"h":"Exemplo prático","p":["Um novilho de 350 kg que ganha 1 kg por dia come uns 8 a 9 kg de matéria seca.","Precisa de cerca de 11 a 12 % de proteína bruta na ração.","E de uma ração com umas 1,1 a 1,2 megacaloria de ELg por quilo de matéria seca."]},{"h":"No seu confinamento","p":["As calculadoras do Rumi usam valores dessas tabelas ajustados ao trópico. Veja Rumi, Alimentação, Exigências por raça e clima.","Pesar na hora certa diz se seu lote ganha o que a ração promete."]}],"rel":["Energia metabolizável e líquida","Proteína metabolizável","Formular uma ração","Matéria seca e consumo"]},{"t":"Aminoácidos limitantes","a":"fisiologia","r":"A proteína é feita de aminoácidos. Se faltar um, o animal não consegue formar músculo mesmo que sobrem os demais. Em bovinos de engorda os que mais costumam faltar são a metionina e a lisina.","s":[{"h":"Como funciona","p":["O corpo monta a proteína como um colar: se falta uma conta, o colar fica incompleto.","O aminoácido que falta primeiro se chama limitante.","A proteína microbiana tem um bom equilíbrio de aminoácidos."]},{"h":"Quando importa","p":["Em animais jovens que crescem muito rápido.","Em rações com muito milho e DDGS, que têm pouca lisina.","Na maioria das engordas tropicais, primeiro é preciso cobrir a proteína total."]},{"h":"No seu confinamento","p":["O farelo de soja tem boa lisina.","Existem aminoácidos protegidos para ruminantes, mas são caros e raramente se justificam na engorda."]}],"rel":["Proteína metabolizável","Farelo de soja e outras proteínas","Grãos de destilaria (DDGS)"]},{"t":"Fome e saciedade","a":"fisiologia","r":"O animal decide quanto comer por sinais do rúmen, do sangue e do cérebro: quão cheio está o rúmen, quanta energia tem e como se sente.","s":[{"h":"Sinais que freiam","p":["Rúmen cheio: com forragem, o animal para quando não cabe mais.","Ácido propiônico no fígado: com grão, avisa que já há energia suficiente.","Leptina da gordura: os animais gordos comem menos por quilo.","Calor, dor e doença."]},{"h":"Sinais que estimulam","p":["Comida fresca no cocho: o animal come mais quando é servido.","O sabor doce do melaço.","Estar em grupo: comem mais quando veem outros comerem."]},{"h":"No seu confinamento","p":["Tratar 2 ou 3 vezes por dia estimula o consumo.","Empurre a comida para perto do animal várias vezes ao dia.","Se cai o consumo do lote inteiro, procure calor, comida estragada, água ou doença."]}],"rel":["Consumo baixo","Horários de alimentação","Leitura de cochos","Taxa de passagem e enchimento"]},{"t":"Balanço de energia e condição corporal","a":"fisiologia","r":"Se o animal come mais energia do que gasta, guarda a sobra como músculo e gordura; se come menos, gasta suas reservas. A condição corporal reflete esse balanço.","s":[{"h":"Balanço positivo","p":["Come mais do que gasta: sobe de peso.","Primeiro faz músculo; se sobra muito, faz gordura.","É a meta da engorda."]},{"h":"Balanço negativo","p":["Come menos do que gasta: perde peso.","Gasta gordura e depois músculo.","Acontece com seca, doença, calor forte ou estresse."]},{"h":"No seu confinamento","p":["Pese com frequência: o peso é o melhor espelho do balanço.","O app marca em vermelho os lotes que perdem ou não sobem de peso."]}],"rel":["Condição corporal","Energia de mantença","Ganho médio diário"]},{"t":"Condição corporal","a":"fisiologia","r":"A condição corporal é uma nota que se dá a cada animal conforme sua gordura, olhando e apalpando costelas, coluna, quadril e base da cauda.","s":[{"h":"Escala de 1 a 9","p":["1 a 3: magro, veem-se costelas, coluna e ossos do quadril.","4 a 5: moderado, mal se veem as últimas costelas.","6 a 7: bem coberto, costelas não se veem e se sentem com pressão.","8 a 9: muito gordo, gordura na base da cauda e no peito."]},{"h":"Onde olhar","p":["Costelas: quantas se veem.","Coluna e ponta do quadril.","Base da cauda e peito (gordura no peito = animal terminado)."]},{"h":"No seu confinamento","p":["Ao comprar: animais com condição 4 a 5 aproveitam o crescimento compensatório.","Ao vender: a maioria dos compradores quer 6 a 7.","Passar de 7 é gastar comida em gordura que não pagam."]}],"rel":["Grau de acabamento","Balanço de energia e condição corporal","Comprar gado para engorda","Crescimento compensatório"]},{"t":"Tamanho adulto e frame","a":"fisiologia","r":"O frame ou estrutura é quão alto e comprido é um animal para sua idade. Anuncia o tamanho que terá adulto e com que peso estará terminado.","s":[{"h":"O que significa","p":["Frame alto: animal grande, cresce mais e termina com mais peso.","Frame baixo: animal pequeno, engorda antes e termina com menos peso.","Mede-se pela altura na garupa conforme a idade."]},{"h":"Por que importa","p":["No mesmo peso, o animal de frame baixo está mais gordo.","Se você engorda um frame alto até um peso baixo, vende magro.","Se você engorda um frame baixo até um peso alto, gasta em gordura."]},{"h":"No seu confinamento","p":["Forme lotes parelhos em frame.","Ajuste a meta de peso do lote ao frame dos animais.","No app você pode colocar uma meta diferente para cada lote."]}],"rel":["Crescimento dos tecidos","Formar lotes","Peso meta","Uniformidade do lote"]},{"t":"Consumo alimentar residual (eficiência individual)","a":"fisiologia","r":"O consumo residual compara o que um animal come com o que deveria comer conforme seu peso e ganho. Os animais eficientes comem menos para ganhar o mesmo.","s":[{"h":"Como se entende","p":["Consumo residual negativo: come menos do que o esperado; é eficiente.","Positivo: come mais do que o esperado; é ineficiente.","Entre animais do mesmo lote pode haver 10 a 20 % de diferença."]},{"h":"Por que acontece","p":["Diferenças na mantença, na atividade, no temperamento e nos micróbios do rúmen.","É em parte herdado: touros eficientes dão filhos eficientes."]},{"h":"No seu confinamento","p":["Medi-lo exige cochos que pesam o que cada animal come; é para centros de pesquisa e genética.","Você pode ver algo parecido: animais do mesmo lote que ganham muito menos que a média com a mesma comida."]}],"rel":["Conversão alimentar","Eficiência alimentar","Herdabilidade"]},{"t":"Resfriamento noturno","a":"fisiologia","r":"Depois de um dia de calor, o animal precisa que a noite refresque para eliminar o calor que guardou. Se a noite é quente, começa o dia seguinte já com calor e o estresse se acumula.","s":[{"h":"Por que é chave","p":["O corpo guarda calor de dia e o elimina à noite.","São necessárias várias horas com temperaturas mais frescas.","As ondas de calor com noites quentes são as mais perigosas."]},{"h":"O que fazer","p":["Dar a maior parte da comida ao entardecer: o calor da digestão chega à noite.","Não manejar nem embarcar nas horas de mais calor.","Molhar pisos ou animais em ondas de calor fortes, com boa drenagem."]},{"h":"No seu confinamento","p":["Veja o clima da sua região no Rumi: se a noite não baixa de 24 °C e há muita umidade, tome precauções."]}],"rel":["Estresse por calor","Zona de conforto térmico","Alimentação com calor","Ondas de calor mais frequentes"]},{"t":"Estresse de transporte","a":"fisiologia","r":"A viagem é das coisas mais duras para um bovino: medo, jejum, sede, pancadas, calor e mistura com desconhecidos. Tudo isso sobe o cortisol, baixa as defesas e faz perder peso.","s":[{"h":"O que acontece com o corpo","p":["Perde entre 3 e 10 % do peso: primeiro o conteúdo do rúmen, depois água dos tecidos.","Os micróbios do rúmen mudam pelo jejum.","As defesas caem de 1 a 3 semanas."]},{"h":"Como recuperá-lo","p":["Água limpa na chegada e forragem de boa qualidade.","Deixar descansar antes de trabalhar no tronco, se possível.","Recuperar o peso da viagem pode levar 1 a 3 semanas."]},{"h":"No seu confinamento","p":["Por isso o ganho do primeiro mês parece baixo.","O peso de entrada ideal é o tomado depois de 1 a 3 dias de descanso.","Viagens à noite ou nas horas frescas reduzem o dano."]}],"rel":["Transporte de gado","Recepção de gado","Quebra (desbaste)","Estresse e defesas"]},{"t":"Dor no bovino","a":"fisiologia","r":"O bovino sente dor como outros animais, mas a esconde porque é animal de presa. A dor baixa o consumo e o ganho.","s":[{"h":"Sinais de dor","p":["Cabeça baixa, orelhas caídas e olhos apagados.","Afasta-se do grupo, range os dentes, chuta a barriga.","Manqueira, postura encurvada ou deita e levanta muito."]},{"h":"Dor de manejo","p":["Castração e descorna doem, mais em animais grandes.","Fazer jovem e com anestesia local e anti-inflamatório reduz a dor e a perda de peso.","Os mercados pedem cada vez mais essas práticas."]},{"h":"No seu confinamento","p":["Peça ao veterinário um plano com anti-inflamatório para castrações e cirurgias.","Os animais que se recuperam rápido da dor voltam a comer antes."]}],"rel":["Castração","Corte de pontas e descorna","Bem-estar animal","Mancadeiras e problemas de casco"]},{"t":"Parasitas e nutrição","a":"fisiologia","r":"Os parasitas não só roubam comida: danificam o intestino, provocam perda de proteína e tiram o apetite. Um animal com parasitas pode comer o mesmo e ganhar muito menos.","s":[{"h":"Como roubam","p":["Os vermes do abomaso danificam a parede e o animal digere pior.","Alguns chupam sangue e causam anemia.","O corpo gasta proteína para reparar o dano e se defender."]},{"h":"Efeito na engorda","p":["Perdas de ganho de 10 a 30 % em infestações moderadas sem sinais claros.","Pelo opaco, barriga grande e diarreia em casos fortes."]},{"h":"No seu confinamento","p":["Vermifugue na chegada conforme exames de fezes e o conselho do veterinário.","Uma boa nutrição ajuda o animal a tolerar melhor os parasitas.","Evite a resistência: não vermifugue demais nem com doses baixas."]}],"rel":["Parasitas internos","Vermifugação e resistência","Resistência dos parasitas aos vermífugos"]},{"t":"Puberdade e comportamento sexual","a":"fisiologia","r":"Os machos inteiros chegam à puberdade entre 12 e 18 meses, e o zebu um pouco mais tarde. A partir daí montam, brigam e gastam energia, mas também formam mais músculo.","s":[{"h":"Em machos inteiros","p":["Crescem 5 a 15 % mais rápido e convertem melhor que os castrados.","Fazem menos gordura e menos marmoreio.","Montam e brigam, com risco de pancadas e carne escura."]},{"h":"Em fêmeas","p":["Entram no cio a cada 21 dias e montam umas nas outras, perdendo peso.","Fêmeas prenhes na compra podem abortar ou parir no curral."]},{"h":"No seu confinamento","p":["Não misture fêmeas com machos inteiros.","Forme lotes parelhos de inteiros e não acrescente animais novos.","Verifique prenhez ao comprar fêmeas para engorda."]}],"rel":["Inteiros ou castrados","Animais que montam (buller)","Fêmeas no confinamento"]},{"t":"Laminite","a":"fisiologia","r":"A laminite é a inflamação das lâminas que unem o casco ao osso da pata. Na engorda quase sempre vem de acidose por excesso de grão.","s":[{"h":"Como se produz","p":["A acidose libera toxinas e histamina no sangue.","Essas substâncias danificam os vasos sanguíneos do casco.","O casco amolece, dói e cresce deformado."]},{"h":"Sinais","p":["Animal que anda como se pisasse em ovos, com o lombo arqueado.","Passa muito tempo deitado.","Meses depois: cascos compridos, com anéis e deformados."]},{"h":"No seu confinamento","p":["Adaptação lenta ao grão e fibra suficiente.","Evitar mudanças bruscas ou dias sem comida seguidos de comida em excesso."]}],"rel":["Acidose ruminal","Cascos e patas","Mancadeiras e problemas de casco"]},{"t":"Composição do corpo","a":"fisiologia","r":"Um novilho é feito de água, proteína, gordura e minerais. À medida que engorda, a proporção de gordura sobe e a de água cai.","s":[{"h":"Um novilho típico","p":["Jovem e magro: uns 60 a 65 % de água, 18 a 20 % de proteína, 10 a 15 % de gordura.","Terminado: uns 50 a 55 % de água, 16 a 17 % de proteína, 25 a 30 % de gordura.","Minerais: 4 a 5 %, quase tudo nos ossos."]},{"h":"O que se vê e o que não","p":["Parte do peso é conteúdo digestivo: de 10 a 20 % do peso vivo.","Por isso o peso muda tanto antes e depois de comer e beber."]},{"h":"No seu confinamento","p":["Pesar sempre na mesma hora e com o mesmo manejo torna os dados comparáveis.","O rendimento de carcaça sobe quando o animal tem mais gordura e menos conteúdo digestivo."]}],"rel":["Peso cheio e peso vazio","Rendimento de carcaça","Crescimento dos tecidos"]},{"t":"Micróbios e antibióticos","a":"fisiologia","r":"Os antibióticos não só matam as bactérias que adoecem: também afetam os micróbios bons do rúmen e do intestino, e o mau uso cria bactérias resistentes.","s":[{"h":"Efeitos no rúmen","p":["Alguns antibióticos dados pela boca mudam a fermentação.","Os ionóforos se usam justamente para mudar os micróbios de forma útil.","Doses altas e longas podem causar diarreia e baixo consumo."]},{"h":"Resistência","p":["Cada uso dá vantagem às bactérias resistentes.","Essas bactérias podem passar às pessoas pela carne, pela água ou pelo contato.","Por isso muitos países limitam os antibióticos como promotores de crescimento."]},{"h":"No seu confinamento","p":["Use antibióticos só com diagnóstico e receita.","Termine o tratamento completo e respeite as carências.","Previna com bom manejo, vacinas e biossegurança."]}],"rel":["Uso responsável de antibióticos","Resistência aos antimicrobianos","Ionóforos"]},{"t":"Olfato, paladar e preferências","a":"fisiologia","r":"O bovino escolhe o que come pelo cheiro, pelo sabor e pela textura. Rejeita o mofado, o amargo e o que cheira a fezes, e prefere o doce e o fresco.","s":[{"h":"O que gosta","p":["Sabor doce: melaço, cana, cítricos.","Comida fresca e recém-servida.","Sal na quantidade certa."]},{"h":"O que rejeita","p":["Comida mofada, fermentada demais ou quente.","Pasto perto das próprias fezes.","Sabores amargos de algumas plantas e remédios."]},{"h":"No seu confinamento","p":["Limpe os cochos: a comida velha no fundo baixa o consumo.","Introduza ingredientes novos aos poucos, misturados com os conhecidos.","O melaço ajuda a aceitarem rações novas ou medicadas."]}],"rel":["Leitura de cochos","Melaço","Armazenamento do alimento"]},{"t":"Como o bovino pasta","a":"fisiologia","r":"O bovino enrola o pasto com a língua e o arranca. Pasta de 7 a 10 horas por dia, sobretudo ao amanhecer e ao entardecer, e escolhe as folhas mais tenras.","s":[{"h":"Como come","p":["Dá entre 30.000 e 40.000 bocados por dia.","Não corta rente: precisa de pasto de pelo menos 10 a 15 cm para encher a boca.","Se o pasto está muito baixo, o bocado é pequeno e o animal não consegue se encher."]},{"h":"Quando come","p":["Picos ao amanhecer e à tarde.","Com calor, pasta à noite e descansa de dia na sombra.","Rumina sobretudo à noite."]},{"h":"Seleção","p":["Escolhe folhas antes de talos, e verde antes de seco.","Evita o pasto junto às próprias fezes.","Por isso deixa manchas sem comer em piquetes grandes."]},{"h":"No seu confinamento","p":["Pasto na altura certa = bocados grandes = mais consumo.","Piquetes pequenos com rotação fazem com que comam mais por igual."]}],"rel":["Pastejo rotacionado","Lotação e amostragem de forragem","Ritmo do dia do bovino"]},{"t":"Ritmo do dia do bovino","a":"fisiologia","r":"O bovino segue um ritmo diário: come, descansa, rumina e volta a comer. Respeitar esse ritmo com horários fixos melhora o consumo e o ganho.","s":[{"h":"Um dia típico","p":["Come forte ao amanhecer e ao entardecer.","Descansa e rumina nas horas de calor.","À noite alterna ruminação, descanso e um pouco de comida."]},{"h":"Por que os horários importam","p":["Os micróbios do rúmen se acostumam a receber comida no mesmo horário.","Mudar o horário de um dia para outro baixa o consumo.","Atrasos longos fazem com que comam com ansiedade e acidifiquem."]},{"h":"No seu confinamento","p":["Sirva a comida no mesmo horário todos os dias, com diferença de menos de 30 minutos.","Coloque seus horários de trato em Mais, Configuração: o app lembra você de cada trato."]}],"rel":["Horários de alimentação","Fome e saciedade","Micróbios do rúmen"]},{"t":"Escala de ofegação","a":"fisiologia","r":"Contar respirações e observar a ofegação é a forma mais simples de medir o estresse por calor no curral.","s":[{"h":"Pontuações","p":["0: respiração normal, menos de 40 por minuto.","1: respiração rápida, boca fechada, 40 a 70.","2: ofegação com um pouco de baba, boca fechada, 70 a 120.","3: boca aberta, muita baba, 120 a 160.","4: língua para fora, cabeça esticada, mais de 160: emergência."]},{"h":"Como contar","p":["Olhe o flanco do animal 15 segundos e multiplique por 4.","Conte em 5 a 10 animais do lote nas horas de mais calor."]},{"h":"O que fazer","p":["Pontuação 2 em vários animais: água extra e sombra, não manejá-los.","Pontuação 3 ou 4: molhar, refrescar e chamar o veterinário se algum cair."]}],"rel":["Estresse por calor","Zona de conforto térmico","Golpe de calor"]},{"t":"Por que o animal doente deixa de comer","a":"fisiologia","r":"Quando o corpo combate uma infecção, libera substâncias que dão febre, sono e tiram a fome. É uma defesa, mas na engorda custa dias de ganho.","s":[{"h":"O que acontece por dentro","p":["As defesas liberam citocinas que agem no cérebro.","Baixam o apetite, sobem a temperatura e o animal se isola.","O corpo usa proteína do músculo para fabricar defesas."]},{"h":"Por que importa","p":["Um animal que não come por 2 ou 3 dias perde peso e seus micróbios do rúmen.","A queda do consumo aparece antes da tosse ou da febre alta."]},{"h":"No seu confinamento","p":["Observe quem não se aproxima do cocho quando você serve: é o primeiro sinal.","Separe e meça a temperatura dos que não comem."]}],"rel":["Revisão diária dos animais","Febre: o que é e o que fazer","Sistema imune do bovino"]},{"t":"Movimentos do rúmen","a":"fisiologia","r":"O rúmen se contrai de 1 a 3 vezes por minuto para misturar a comida. Escutá-lo com o ouvido ou um estetoscópio no lado esquerdo diz se funciona bem.","s":[{"h":"Como escutar","p":["Ponha o ouvido ou o estetoscópio na fossa do flanco esquerdo.","Escute 2 minutos: deve ouvir ruídos como de trovoada distante, de 2 a 6 vezes."]},{"h":"O que significa","p":["Sem ruídos: o rúmen está parado; pode ser acidose, febre, dor ou bloqueio.","Flanco esquerdo muito inchado e tenso: timpanismo.","Movimentos lentos: animal doente ou com comida de má qualidade."]},{"h":"No seu confinamento","p":["Examine o rúmen de todo animal que não come.","Um veterinário pode indicar tratamento para reativá-lo."]}],"rel":["Os quatro estômagos do bovino","Timpanismo (rúmen inchado)","Sinais vitais e como medi-los"]},{"t":"Mucosas: o que suas cores dizem","a":"fisiologia","r":"A cor das gengivas, do olho e da vulva mostra como está o sangue do animal. Revisá-las leva segundos e dá muita informação.","s":[{"h":"Cores","p":["Rosado: normal.","Pálido ou branco: anemia (anaplasma, babésia, parasitas, hemorragia).","Amarelo: icterícia, problema de fígado ou destruição de glóbulos vermelhos.","Roxo ou azulado: falta de oxigênio, grave.","Muito vermelho: febre, golpe de calor ou intoxicação."]},{"h":"Como revisá-las","p":["Baixe um pouco a pálpebra inferior e olhe o branco do olho e sua borda.","Revise as gengivas se puder abrir a boca com segurança.","Compare com um animal sadio do lote."]}],"rel":["Sangue e circulação","Anaplasmose","Sinais vitais e como medi-los"]},{"t":"Linfonodos","a":"fisiologia","r":"Os linfonodos são filtros das defesas. Quando há infecção por perto, incham. Alguns podem ser apalpados sob a pele.","s":[{"h":"Onde apalpá-los","p":["Na frente da paleta (pré-escapulares).","No flanco, na frente da coxa (pré-femorais).","Embaixo da mandíbula."]},{"h":"O que significa se estão grandes","p":["Infecção na região que drenam: feridas, abscessos, carrapatos.","Se estão grandes no corpo todo: doença geral, como tripanossomíase ou leucose."]},{"h":"No seu confinamento","p":["Revise-os em animais que não ganham peso ou têm febre.","Um veterinário pode colher amostra se suspeitar de uma doença séria."]}],"rel":["Sistema imune do bovino","Inchaços: o que podem ser","Tripanossomose"]},{"t":"Nitrogênio, esterco e ambiente","a":"fisiologia","r":"O bovino só guarda no corpo uma parte pequena do nitrogênio que come; o resto sai na urina e nas fezes. Esse nitrogênio pode adubar seus pastos ou contaminar a água.","s":[{"h":"Dados","p":["Um novilho em engorda retém cerca de 10 a 20 % do nitrogênio que come.","A maior parte do excesso sai como ureia na urina e vira amônia.","A amônia dá mau cheiro e se perde no ar."]},{"h":"O que fazer","p":["Não dar mais proteína que o necessário.","Recolher e compostar o esterco do curral.","Usar o esterco como adubo nos capins de corte."]}],"rel":["Reciclagem de ureia","Manejo do esterco","Ambiente e manejo de resíduos"]},{"t":"Crescimento do osso","a":"fisiologia","r":"O osso cresce em comprimento por cartilagens nas pontas. Quando essas cartilagens se fecham, o animal para de crescer em altura; isso acontece dos 2 aos 4 anos conforme o osso e a raça.","s":[{"h":"O que precisa","p":["Cálcio, fósforo, vitamina D e proteína.","Energia suficiente na juventude."]},{"h":"Por que importa na engorda","p":["Um animal que passou fome jovem fica com menos estrutura.","Animais com bom esqueleto podem carregar mais músculo.","Os ossos são parte do peso que não se vende como carne."]}],"rel":["Crescimento dos tecidos","Tamanho adulto e frame","Relação cálcio e fósforo"]},{"t":"Sombra e radiação solar","a":"fisiologia","r":"O sol direto aquece o animal tanto quanto o ar. Uma boa sombra pode baixar a carga de calor que recebe em até 30 % ou mais.","s":[{"h":"O que a sombra faz","p":["Tira a radiação direta do sol.","Baixa a temperatura da pele e a respiração.","As árvores, além disso, refrescam pela umidade das folhas."]},{"h":"Quanto é necessário","p":["Uns 2 a 4 m² de sombra por animal no curral.","Altura de 3 a 4 m para o ar circular.","Orientada para que a sombra se mova e seque o piso."]},{"h":"No seu confinamento","p":["A sombra é dos investimentos que mais se pagam no trópico.","Os animais pretos ou de raças europeias precisam mais dela."]}],"rel":["Sombra","Estresse por calor","Sistemas silvipastoris"]},{"t":"Consumo e peso do animal","a":"fisiologia","r":"Um novilho come de 2 a 3 % do seu peso em matéria seca. Os leves comem mais por quilo de peso que os pesados.","s":[{"h":"Valores de referência","p":["200 kg: cerca de 2,6 a 3 % (5 a 6 kg de matéria seca).","350 kg: cerca de 2,3 a 2,6 % (8 a 9 kg).","450 kg: cerca de 2 a 2,3 % (9 a 10 kg)."]},{"h":"O que o muda","p":["Qualidade da comida: pasto velho baixa o consumo.","Calor: pode cair 10 a 30 %.","Gordura do animal: os muito gordos comem menos."]},{"h":"No seu confinamento","p":["O app estima o consumo esperado com o peso dos seus lotes.","Se comem muito menos que o esperado, procure a causa."]}],"rel":["Consumo como porcentagem do peso","Matéria seca e consumo","Fome e saciedade"]},{"t":"Crescimento de machos e fêmeas","a":"fisiologia","r":"Com a mesma idade e comida, os machos inteiros crescem mais rápido, depois os castrados e por último as fêmeas. As fêmeas engordam antes e terminam com menos peso.","s":[{"h":"Diferenças típicas","p":["Touros inteiros: o maior ganho e a melhor conversão.","Novilhos castrados: ganho intermediário, mais marmoreio.","Fêmeas: ganho menor e terminam com 50 a 80 kg menos que os novilhos."]},{"h":"No seu confinamento","p":["Não misture sexos no mesmo lote.","Ajuste a meta de peso conforme o sexo: o app permite uma meta por lote."]}],"rel":["Inteiros ou castrados","Fêmeas no confinamento","Peso meta"]},{"t":"Capins para pastagem no trópico","a":"forrajes","r":"Escolher o capim certo para seu solo e clima define quanta carne cada hectare produz.","s":[{"h":"Braquiárias","p":["Brizantha (Marandu, Xaraés/Toledo), Decumbens, Humidícola e híbridos como Mulato II e Cayman.","Aguentam solos pobres e seca moderada.","Alguns suportam encharcamento (Humidícola, Cayman).","Boa produção com adubação."]},{"h":"Panicum (capim-colonião)","p":["Mombaça, Tanzânia, Massai.","Muito produtivos e de boa qualidade em solos férteis.","Precisam de bom manejo da altura de pastejo."]},{"h":"Estrelas e outros","p":["Grama-estrela-africana, Transvala, Bermuda: bons em solos férteis e com adubação.","Pastos nativos ou naturalizados (grama): baixa produção."]},{"h":"Como escolher","p":["Olhe seu solo (fertilidade, drenagem) e a chuva da sua região.","Pergunte aos vizinhos e ao técnico da região o que funciona.","Combine variedades em piquetes diferentes para dividir o risco."]}],"rel":["Formar um pasto","Pastejo rotacionado","Adubar pastos"]},{"t":"Capins de corte","a":"forrajes","r":"Os capins de corte produzem muita forragem por hectare para dar picada no curral ou fazer silagem.","s":[{"h":"Variedades","p":["Capim-elefante (King grass, Cameroon), Cuba OM-22, Maralfalfa, Taiwan, CT-115, Capiaçu.","Algumas variedades novas têm menos pelos e mais folha."]},{"h":"Manejo","p":["Plante por colmos ou estacas em sulcos no início das chuvas.","Corte aos 50 a 70 dias nas chuvas e aos 70 a 90 dias na seca.","Corte a 10 a 15 cm do solo.","Aduba com nitrogênio depois de cada corte."]},{"h":"Produção","p":["Com bom manejo, de 100 a mais de 200 toneladas de forragem verde por hectare por ano.","Uma área bem manejada pode alimentar muitos animais no confinamento."]},{"h":"Erros comuns","p":["Cortar muito velho: muito talo lenhoso e pouca qualidade.","Não adubar: o rendimento cai ano a ano.","Picar e deixar de um dia para o outro."]}],"rel":["Feno e capim de corte na ração","Qualidade da forragem e idade de corte","Adubar pastos"]},{"t":"Formar um pasto","a":"forrajes","r":"Plantar bem desde o início poupa anos de pasto ralo e mato.","s":[{"h":"Preparo","p":["Análise de solo para saber se precisa de calcário e adubo.","Controle do mato antes de plantar.","Preparo do solo conforme a declividade: cultivo mínimo nas encostas."]},{"h":"Plantio","p":["No início das chuvas.","Semente certificada na quantidade que o fornecedor indica.","Cubra pouco a semente pequena (1 a 2 cm).","Em capins de colmo, sulcos com material fresco."]},{"h":"Primeiros meses","p":["Controle do mato à mão ou com herbicida seletivo.","Primeiro pastejo leve quando o capim estiver bem enraizado (puxar uma planta não a arranca).","Adubação de formação."]}],"rel":["Análise de solo e calagem","Controle de plantas daninhas","Capins para pastagem no trópico"]},{"t":"Adubar pastos","a":"forrajes","r":"O pasto é uma lavoura. Sem adubo, a cada ano produz menos e o mato ganha.","s":[{"h":"Nutrientes","p":["Nitrogênio: o que mais aumenta a produção.","Fósforo: para as raízes; muito escasso em solos tropicais.","Potássio: para resistência e rebrota.","Calcário: corrige a acidez do solo."]},{"h":"Quando","p":["No início e no meio da época de chuvas.","Depois do pastejo ou do corte.","Nunca com solo seco."]},{"h":"Esterco","p":["O esterco compostado do curral é um bom adubo para pastos e capins de corte.","Use-o compostado para não espalhar sementes de mato nem parasitas."]},{"h":"Números","p":["O adubo deve se pagar: calcule quanta forragem a mais dá e quantos quilos de carne produz.","A análise de solo evita gastar no que não é necessário."]}],"rel":["Análise de solo e calagem","Manejo do esterco","Capins de corte"]},{"t":"Pastejo rotacionado","a":"forrajes","r":"Dividir a área e rodar os animais deixa o pasto descansar. Produz mais forragem e de melhor qualidade.","s":[{"h":"Como funciona","p":["O pasto é dividido em vários piquetes.","Os animais pastam um por poucos dias e passam ao seguinte.","Cada piquete descansa até se recuperar."]},{"h":"Tempos de referência","p":["Ocupação de 1 a 3 dias por piquete.","Descanso de 25 a 35 dias nas chuvas e 35 a 50 dias na seca, conforme o capim.","Entre quando o capim estiver na altura recomendada e saia antes de deixá-lo rapado."]},{"h":"Alturas de exemplo","p":["Brachiaria brizantha: entrar com 30 a 40 cm, sair com 15 a 20 cm.","Mombaça: entrar com 80 a 90 cm, sair com 30 a 40 cm."]},{"h":"Benefícios","p":["Mais animais por hectare.","Menos mato.","Melhor qualidade do pasto.","Corta o ciclo de alguns parasitas."]}],"rel":["Lotação e amostragem de forragem","Cercas","Engorda a pasto"]},{"t":"Lotação e amostragem de forragem","a":"forrajes","r":"A lotação é quantos animais um pasto aguenta. A amostragem mede quanto pasto há para calculá-la.","s":[{"h":"Unidade animal","p":["Uma unidade animal é 450 kg de peso vivo.","Um novilho de 300 kg é 0,67 unidade animal."]},{"h":"Como amostrar","p":["Jogue um quadro de 1 m² em vários pontos ao acaso.","Corte o pasto na altura que o animal deixaria e pese.","Tire a média e multiplique pela área: quilos de forragem verde disponível."]},{"h":"Calcular a lotação","p":["Um animal consome uns 10 a 12 % do seu peso em forragem verde por dia (conforme a matéria seca do pasto).","Use só 50 a 60 % da forragem disponível para não superpastejar.","Cabeças = forragem aproveitável por dia ÷ consumo por animal.","A calculadora do Rumi ajuda você com a lotação."]},{"h":"Sinais de superlotação","p":["Pasto rapado e solo descoberto.","Aumento do mato.","Animais que não ganham peso."]}],"rel":["Pastejo rotacionado","Matéria seca e consumo","Unidade animal"]},{"t":"Controle de plantas daninhas","a":"forrajes","r":"O mato rouba água, luz e adubo do pasto. Algumas plantas são tóxicas. Controlam-se melhor com um bom pasto do que com químicos.","s":[{"h":"Prevenção","p":["Não superpastejar: o pasto forte abafa o mato.","Adubar o pasto.","Esterco compostado, não fresco, para não espalhar sementes."]},{"h":"Controle","p":["Roçada ou corte antes de o mato soltar semente.","Arranque manual de plantas tóxicas.","Herbicidas seletivos conforme o rótulo, com equipamento de proteção e respeitando o tempo antes de soltar o gado."]},{"h":"Segurança","p":["Leia o rótulo: alguns herbicidas pedem dias sem pastejo.","Não lave equipamentos em córregos."]}],"rel":["Plantas tóxicas nos pastos","Pastejo rotacionado","Recuperar um pasto degradado"]},{"t":"Plantas tóxicas nos pastos","a":"forrajes","r":"Conhecer as plantas tóxicas da sua região evita mortes. O gado com fome come o que normalmente evitaria.","s":[{"h":"Comuns na América Central","p":["Samambaia (Pteridium).","Mamona.","Espirradeira (oleandro).","Outras conforme a região.","Mandioca-brava e sorgos rebrotados (cianeto)."]},{"h":"Quando há mais risco","p":["Animais com fome ou recém-chegados.","Pastos rapados na seca.","Depois de uma roçada, quando as plantas ficam à vista e murchas."]},{"h":"O que fazer","p":["Percorra e arranque as plantas tóxicas antes de soltar os animais.","Não jogue restos de jardinagem no pasto.","Se suspeitar de intoxicação, retire os animais e chame o veterinário com uma amostra da planta."]}],"rel":["Intoxicação por plantas e fungos","Controle de plantas daninhas"]},{"t":"Silagem: como fazer","a":"forrajes","r":"A silagem conserva a forragem em bom estado fermentando-a sem ar. Bem feita, dura meses e alimenta na seca.","s":[{"h":"O que ensilar","p":["Milho: o melhor, cortado quando o grão está no estado leitoso-pastoso (linha do leite na metade).","Sorgo forrageiro ou de duplo propósito.","Capins de corte, com um pouco de melaço para ajudar a fermentar."]},{"h":"Passos","p":["Corte e pique a 1 a 2 cm.","Encha o silo rápido, no menor tempo possível.","Compacte camada por camada (20 a 30 cm) com trator ou pisando muito.","Cubra com lona grossa sem furos no mesmo dia.","Ponha peso em cima: pneus ou sacos de terra."]},{"h":"Tipos de silo","p":["Silo trincheira ou de superfície (bunker).","Silo bolsa (bag).","Microssilos em sacos ou tambores: bons para poucos animais."]},{"h":"Tempos","p":["Espere pelo menos 3 a 4 semanas antes de abrir.","Bem fechado, dura muitos meses."]}],"rel":["Silagem: qualidade e problemas","Silagem na ração","Plano forrageiro para a seca"]},{"t":"Silagem: qualidade e problemas","a":"forrajes","r":"Uma silagem malfeita perde valor e pode adoecer. Aprenda a reconhecer uma boa e a evitar as perdas.","s":[{"h":"Silagem boa","p":["Cheiro agradável, a vinagre suave ou fruta fermentada.","Cor verde-amarelada ou verde-oliva.","Textura firme, úmida mas sem escorrer água."]},{"h":"Silagem ruim","p":["Cheiro de manteiga rançosa ou de amônia: má fermentação.","Cor marrom-escura ou preta, cheiro de tabaco: esquentou.","Mofo branco, azul ou verde.","Muito aguada e com mau cheiro: estava úmida demais."]},{"h":"Causas de perdas","p":["Má compactação: fica ar.","Lona rasgada ou mal vedada.","Forragem muito seca ou muito úmida.","Enchimento lento."]},{"h":"Ao abri-lo","p":["Retire de uma face do silo, por igual.","Retire todo dia pelo menos 15 a 20 cm da face para não esquentar.","Cubra o que não usar.","Descarte a camada com mofo."]}],"rel":["Silagem: como fazer","Silagem na ração","Intoxicação por plantas e fungos"]},{"t":"Feno: como fazer e guardar","a":"forrajes","r":"O feno é pasto secado ao sol. Guarda a qualidade do pasto novo para a seca.","s":[{"h":"Quando cortar","p":["Pasto novo, antes de florescer: mais folha e proteína.","Em dias secos e ensolarados, sem chuva prevista."]},{"h":"Secagem","p":["Vire o pasto para secar por igual.","Está pronto quando os talos quebram e não há umidade ao torcê-los (menos de 18 a 20 % de umidade).","Enfardar úmido produz mofo e pode pegar fogo."]},{"h":"Armazenamento","p":["Sob teto, sobre estrados, com ventilação.","Separado do chão e das paredes."]},{"h":"Qualidade","p":["Verde, com folhas, cheiro agradável, sem poeira.","O feno amarelo, marrom ou com poeira alimenta pouco e adoece."]}],"rel":["Feno e capim de corte na ração","Plano forrageiro para a seca","Depósito de ração"]},{"t":"Leguminosas e árvores forrageiras","a":"forrajes","r":"Plantas que fixam nitrogênio do ar e dão proteína barata ao gado. Melhoram o solo e o pasto.","s":[{"h":"Opções","p":["Leucena: muito rica em proteína; com limite pela mimosina.","Gliricídia: bancos forrageiros e cercas vivas.","Cratília: aguenta bem a seca.","Guandu, feijão-de-porco, amendoim forrageiro.","Amoreira e nacedero (não são leguminosas, mas ricas em proteína)."]},{"h":"Uso","p":["Bancos forrageiros perto do curral para cortar e dar picado.","Consorciadas com capins nos pastos.","Como complemento, não como alimento único: 20 a 30 % da ração no máximo."]},{"h":"Cuidados","p":["Adapte aos poucos para evitar timpanismo e toxicidade.","Leucena em excesso e sem adaptação dá queda de pelo e problemas de tireoide."]}],"rel":["Proteína na ração","Sistemas silvipastoris","Timpanismo (rúmen inchado)"]},{"t":"Cana-de-açúcar como forragem","a":"forrajes","r":"A cana produz muita energia por hectare e aguenta a seca no campo. É uma boa reserva viva.","s":[{"h":"Vantagens","p":["Alta produção de matéria verde.","Mantém a qualidade na seca: corta-se quando precisa.","Poucos cuidados depois de estabelecida."]},{"h":"Manejo","p":["Variedades forrageiras ou de açúcar com bom rendimento.","Colheita madura na seca.","Pique fino e dê no mesmo dia."]},{"h":"Limites","p":["Muito baixa em proteína e minerais.","Precisa de complementos para bons ganhos."]}],"rel":["Cana-de-açúcar na ração","Plano forrageiro para a seca"]},{"t":"Irrigação de pastos","a":"forrajes","r":"A irrigação mantém a produção de pasto na seca. Justifica-se em capins de corte de alto rendimento e perto de fontes de água.","s":[{"h":"Quando convém","p":["Capins de corte perto do curral.","Regiões com seca longa e água disponível.","Quando o custo da irrigação é menor que comprar forragem ou grão."]},{"h":"Sistemas","p":["Aspersão: fácil de mudar.","Por gravidade em sulcos: barato se o terreno permitir.","Gotejamento: eficiente, mas caro para pastos."]},{"h":"Regras","p":["Irrigue com constância: pouco e seguido é pior que menos vezes e bem feito.","Aduba junto com a irrigação para aproveitá-la.","Verifique as licenças de uso da água."]}],"rel":["Capins de corte","Plano forrageiro para a seca","Água: fontes, caixas e qualidade"]},{"t":"Plano forrageiro para a seca","a":"forrajes","r":"A seca se prepara nas chuvas. Calcular a forragem de que você vai precisar evita comprar caro ou perder peso.","s":[{"h":"Calcule o que precisa","p":["Quilos de forragem por animal por dia × número de animais × dias de seca.","Some 20 % por perdas.","Exemplo: 50 animais × 8 kg de silagem × 150 dias = 60.000 kg + 20 % = 72.000 kg."]},{"h":"Opções","p":["Silagem feita nas chuvas.","Feno.","Cana-de-açúcar em pé.","Capim de corte irrigado.","Compra de subprodutos ou palhadas."]},{"h":"Calendário","p":["Plantio de milho ou sorgo para silagem no início das chuvas.","Silagem e feno no meio e no fim das chuvas.","Revisão das reservas antes de terminar as chuvas."]},{"h":"No app","p":["O Rumi diz quanto alimento seus lotes consomem por mês."]}],"rel":["Silagem: como fazer","Ração para a época seca","Época seca"]},{"t":"Recuperar um pasto degradado","a":"forrajes","r":"Um pasto com pouco capim, solo descoberto e muito mato produz muito pouco. Dá para recuperar com um plano.","s":[{"h":"Sinais de degradação","p":["Menos da metade do solo coberta de capim.","Mato e plantas duras que o gado não come.","Solo compactado ou com voçorocas."]},{"h":"Plano","p":["Descanso do pasto.","Controle do mato.","Análise de solo, calcário e adubo.","Ressemeadura no início das chuvas se for preciso.","Voltar a pastejar com lotação moderada e rotação."]},{"h":"Prevenção","p":["Lotação adequada.","Rotação com descansos.","Adubação periódica."]}],"rel":["Formar um pasto","Controle de plantas daninhas","Lotação e amostragem de forragem"]},{"t":"Sistemas silvipastoris","a":"forrajes","r":"Combinar árvores, pastos e gado dá sombra, forragem, madeira e melhora o solo.","s":[{"h":"Tipos","p":["Árvores dispersas nos pastos.","Cercas vivas.","Bancos forrageiros.","Pastejo em faixas de leucena ou outras arbustivas."]},{"h":"Benefícios","p":["Sombra que reduz o estresse por calor.","Forragem extra rica em proteína.","Melhor solo e retenção de água.","Madeira, lenha e frutas."]},{"h":"Cuidados","p":["Não plantar árvores tóxicas.","Manejar a sombra para o pasto receber luz.","Proteger as árvores jovens do gado."]}],"rel":["Leguminosas e árvores forrageiras","Sombra","Estresse por calor"]},{"t":"Qualidade da forragem e idade de corte","a":"forrajes","r":"O mesmo capim pode ser bom alimento ou quase palha conforme a idade em que é cortado ou pastejado.","s":[{"h":"Pasto novo","p":["Mais folhas, mais proteína (10 a 14 %) e mais digestível.","Menos quantidade por corte."]},{"h":"Pasto velho","p":["Mais talo e fibra dura, proteína de 4 a 6 %.","Mais quantidade, mas alimenta muito menos.","O animal come menos porque demora a digerir."]},{"h":"Ponto ótimo","p":["Antes de florescer ou espigar.","Em capins de corte, 50 a 70 dias nas chuvas.","No pastejo, na altura de entrada recomendada."]},{"h":"Sinais de boa qualidade","p":["Muita folha verde e talos tenros.","O gado come sem deixar sobras.","Boa cor e cheiro."]}],"rel":["Capins de corte","Pastejo rotacionado","Matéria seca e consumo"]},{"t":"Análise de solo e calagem","a":"forrajes","r":"A análise de solo diz o que falta na sua terra. Assim você não gasta em adubo que não é necessário.","s":[{"h":"Como tirar a amostra","p":["Percorra o pasto em zigue-zague e tire 15 a 20 subamostras de 0 a 20 cm.","Misture-as e envie um quilo ao laboratório.","Uma amostra por pasto ou área diferente."]},{"h":"O que diz","p":["pH ou acidez.","Fósforo, potássio, cálcio, magnésio.","Matéria orgânica.","Às vezes alumínio e micronutrientes."]},{"h":"Calagem","p":["Os solos ácidos (pH menor que 5,5) limitam o pasto.","O calcário corrige a acidez e fornece cálcio.","Aplique-o meses antes de plantar ou adubar, conforme a recomendação."]}],"rel":["Adubar pastos","Formar um pasto"]},{"t":"Microssilos em sacos ou tambores","a":"forrajes","r":"Para poucos animais, ensilar em sacos plásticos grossos ou tambores é barato e fácil.","s":[{"h":"Materiais","p":["Sacos plásticos grossos (alta espessura) ou tambores com tampa hermética.","Picadeira e forragem no ponto (milho, sorgo, capim de corte com melaço)."]},{"h":"Passos","p":["Pique a forragem fina (1 a 2 cm).","Encha por camadas e aperte bem para tirar o ar.","Feche bem: amarre o saco tirando o ar ou tampe o tambor.","Guarde na sombra, longe de ratos e de objetos que furem."]},{"h":"Uso","p":["Abra depois de 3 a 4 semanas.","Use um saco inteiro em 1 a 2 dias.","Descarte sacos rasgados ou com mofo."]}],"rel":["Silagem: como fazer","Silagem: qualidade e problemas"]},{"t":"Bancos de proteína","a":"forrajes","r":"Pequenas áreas plantadas com leguminosas ou arbustos ricos em proteína, perto do curral, para cortar e dar.","s":[{"h":"Espécies","p":["Leucena, gliricídia, cratília, amoreira, nacedero, guandu."]},{"h":"Manejo","p":["Plantio denso em sulcos.","Corte a cada 60 a 90 dias a 1 metro de altura.","Aduba e controle o mato."]},{"h":"Uso","p":["Picado na ração, como parte da proteína.","Economiza farelo de soja e outras proteínas compradas."]}],"rel":["Leguminosas e árvores forrageiras","Proteína na ração"]},{"t":"Palhadas de colheita","a":"forrajes","r":"O que sobra de milho, sorgo ou arroz depois da colheita serve como forragem na seca se for melhorado.","s":[{"h":"Valor","p":["Muita fibra, pouca proteína (3 a 5 %) e pouca energia."]},{"h":"Como melhorá-las","p":["Pique para que comam mais.","Adicione melaço e uma fonte de nitrogênio bem formulada.","Complemente com minerais."]},{"h":"Cuidados","p":["Palhadas de milho e sorgo estressadas podem ter nitratos.","Verifique se não têm mofo nem restos de agrotóxicos recentes."]}],"rel":["Feno e capim de corte na ração","Intoxicação por nitratos e cianeto","Plano forrageiro para a seca"]},{"t":"Capins Brachiaria (Urochloa)","a":"forrajes","r":"As braquiárias são os capins mais plantados no trópico americano: aguentam solos pobres, seca e pisoteio. Hoje são classificadas como Urochloa.","s":[{"h":"Variedades comuns","p":["Brizantha (Marandu, Xaraés, Piatã): boa produção e resistência à cigarrinha em algumas.","Decumbens: rústica, mas pode causar fotossensibilização.","Humidícola: aguenta solos úmidos, mas tem pouca proteína.","Híbridos (Mulato II, Cayman, Cobra e outros): mais qualidade e produção."]},{"h":"Manejo","p":["Pastejar com 25 a 35 cm de altura e deixar um resíduo de 15 a 20 cm.","Descansos de 25 a 35 dias nas chuvas.","Adubar com nitrogênio na época de chuvas multiplica a produção."]},{"h":"Cuidados","p":["A cigarrinha-das-pastagens ataca várias braquiárias.","Animais jovens que não conhecem a decumbens podem se fotossensibilizar."]}],"rel":["Capins para pastagem no trópico","Fotossensibilização","Pastejo rotacionado"]},{"t":"Capins Panicum (colonião, Mombaça, Tanzânia)","a":"forrajes","r":"Os Panicum são capins de alta produção e boa qualidade, mas exigentes em fertilidade do solo. São ideais para pastejo intensivo rotacionado.","s":[{"h":"Variedades","p":["Mombaça: alto, de muita produção.","Tanzânia: um pouco mais baixo, boa qualidade.","Colonião comum: rústico e espalhado na região.","Massai: mais tolerante a solos pobres."]},{"h":"Manejo","p":["Entrar para pastejar com 70 a 90 cm (Mombaça) e sair com 30 a 40 cm.","Não deixar espigar: perdem qualidade rápido.","Precisam de adubação e boa drenagem."]}],"rel":["Capins para pastagem no trópico","Pastejo rotacionado","Adubar pastos"]},{"t":"Capins de corte Pennisetum","a":"forrajes","r":"O capim-elefante (King grass), o Cuba OM-22, o CT-115, a Maralfalfa e o Taiwan são capins de corte que produzem muita forragem por hectare para dar picada no cocho.","s":[{"h":"Produção","p":["Podem dar dezenas de toneladas de forragem verde por hectare por ano com boa adubação e água.","O melhor ponto de corte costuma ser entre 50 e 70 dias nas chuvas."]},{"h":"Qualidade","p":["Cortado novo: 8 a 12 % de proteína.","Velho e alto: menos de 6 % e muita fibra dura.","Picar a 2 a 5 cm para o animal não deixar os talos."]},{"h":"No seu confinamento","p":["São a base de muitas engordas em semiconfinamento.","Complemente com concentrado ou melaço com ureia para conseguir bom ganho."]}],"rel":["Capins de corte","Qualidade da forragem e idade de corte","Engorda em semiconfinamento"]},{"t":"Leucena","a":"forrajes","r":"A leucena é um arbusto leguminoso com folhas muito ricas em proteína. Em sistemas silvipastoris aumenta muito o ganho de peso a pasto.","s":[{"h":"Valor","p":["Folhas com 20 a 28 % de proteína.","Fixa nitrogênio do ar e melhora o solo.","Aguenta a seca e rebrota bem."]},{"h":"Cuidado: mimosina","p":["Tem uma substância chamada mimosina que em excesso causa queda de pelo e problemas de tireoide.","Recomenda-se que não passe de 30 % da dieta.","Em muitas regiões os animais já têm bactérias que a degradam."]},{"h":"Manejo","p":["Em faixas dentro do pasto, com capim entre as faixas.","Ramonear sem deixar crescer como árvore alta."]}],"rel":["Leguminosas e árvores forrageiras","Sistemas silvipastoris","Bancos de proteína"]},{"t":"Cratília, moringa e margaridão","a":"forrajes","r":"Além da leucena, há arbustos forrageiros que dão proteína na seca: cratília, moringa, margaridão (Tithonia), gliricídia e amoreira.","s":[{"h":"Cratília","p":["Leguminosa muito resistente à seca e a solos ácidos.","Boa para bancos de proteína de corte."]},{"h":"Gliricídia","p":["Comum em cercas vivas.","As folhas se oferecem murchas; no começo o gado as rejeita pelo cheiro."]},{"h":"Moringa e margaridão","p":["Folhas com muita proteína.","Precisam de bom manejo de corte para rebrotar."]},{"h":"No seu confinamento","p":["Misturar folhas desses arbustos com pasto sobe a proteína e baixa o custo do concentrado.","Comece com pouca quantidade para os animais se acostumarem."]}],"rel":["Leguminosas e árvores forrageiras","Bancos de proteína","Cercas"]},{"t":"Milho e sorgo para silagem","a":"forrajes","r":"O milho e o sorgo são as melhores culturas para ensilar: têm açúcar suficiente para fermentar bem e dão um alimento com boa energia para a seca.","s":[{"h":"Ponto de corte","p":["Milho: quando o grão está no estado leitoso a pastoso (linha do leite na metade), com 30 a 35 % de matéria seca.","Sorgo: quando o grão está pastoso."]},{"h":"Valor","p":["Silagem de milho boa: 7 a 9 % de proteína e boa energia.","Complementar com uma fonte de proteína."]},{"h":"No seu confinamento","p":["Um bom silo garante comida barata quando o pasto acaba.","Calcule quanto precisa com a calculadora de silagem do Rumi."]}],"rel":["Silagem: como fazer","Silagem: qualidade e problemas","Plano forrageiro para a seca"]},{"t":"Forragem verde hidropônica","a":"forrajes","r":"A forragem verde hidropônica é grão germinado em bandejas durante 8 a 12 dias. É oferecida como solução para a seca, mas convém fazer bem as contas.","s":[{"h":"O que é preciso saber","p":["Ao germinar, o grão perde parte de sua matéria seca e energia.","Dá forragem fresca e apetitosa, mas com muita água.","O custo por quilo de matéria seca costuma ser mais alto que o do próprio grão."]},{"h":"Quando pode servir","p":["Para poucos animais e quando não há outra forragem verde.","Como complemento, não como base da ração."]},{"h":"No seu confinamento","p":["Compare o custo por quilo de matéria seca com a silagem, o feno ou o grão.","Quase sempre sai mais barato ensilar ou guardar feno."]}],"rel":["Plano forrageiro para a seca","Custo da ração","Matéria seca e consumo"]},{"t":"Grama-estrela e outros capins rasteiros","a":"forrajes","r":"A grama-estrela, a pangola e outros capins rasteiros cobrem bem o solo e aguentam o pisoteio. Têm boa qualidade se manejados com rotação.","s":[{"h":"Características","p":["Crescem por estolões que cobrem o solo.","Boa qualidade quando novos.","A grama-estrela pode acumular nitratos ou cianeto com muita adubação e rebrota depois da seca."]},{"h":"Manejo","p":["Pastejo com 20 a 30 cm de altura.","Descansos de 21 a 30 dias nas chuvas."]}],"rel":["Capins para pastagem no trópico","Intoxicação por nitratos e cianeto"]},{"t":"Cigarrinha-das-pastagens","a":"forrajes","r":"A cigarrinha é um inseto que chupa a seiva dos capins e os seca. Suas ninfas se escondem numa espuma branca na base da planta.","s":[{"h":"Sinais","p":["Espuma branca na base dos capins.","Folhas amarelas que depois secam como queimadas.","Mais na época de chuvas e em braquiárias suscetíveis."]},{"h":"Controle","p":["Plantar variedades resistentes.","Pastejar para baixar o capim e expor as ninfas ao sol.","Fungos que atacam o inseto (controle biológico).","Inseticidas só com recomendação técnica e respeitando o tempo antes de pastejar."]}],"rel":["Capins Brachiaria (Urochloa)","Controle de plantas daninhas","Bom uso de agrotóxicos"]},{"t":"Conservar forragem das chuvas para a seca","a":"forrajes","r":"Na época de chuvas sobra pasto e na seca falta. Guardar o excedente como silagem ou feno é a forma mais segura de manter o ganho o ano todo.","s":[{"h":"Quanto guardar","p":["Calcule os dias de seca e o número de animais.","Um novilho de 350 kg come uns 8 a 9 kg de matéria seca por dia.","Guarde pelo menos 20 % a mais por perdas."]},{"h":"Opções","p":["Silagem de capim de corte, milho ou sorgo.","Feno de capins finos.","Pasto diferido em pé: vedar pastos no fim das chuvas."]},{"h":"No seu confinamento","p":["Planeje suas compras de gado conforme a forragem que terá na seca.","Registre sua forragem guardada no depósito do app."]}],"rel":["Plano forrageiro para a seca","Silagem: como fazer","Feno: como fazer e guardar","Microssilos em sacos ou tambores"]},{"t":"Herdabilidade","a":"genetica","r":"A herdabilidade diz que parte de uma característica passa de pais para filhos. Vai de 0 a 1: quanto mais alta, mais rápido se melhora com seleção.","s":[{"h":"Valores típicos","p":["Ganho diário de peso: 0,3 a 0,4 (médio).","Conversão alimentar: cerca de 0,3.","Rendimento e área de olho de lombo: 0,3 a 0,5.","Marmoreio: 0,4 a 0,5 (alta).","Temperamento: 0,3 a 0,4.","Fertilidade: 0,05 a 0,15 (baixa; depende mais do manejo)."]},{"h":"O que significa","p":["Herdabilidade alta: escolher bons pais dá filhos parecidos.","Herdabilidade baixa: o ambiente e o manejo pesam mais que a genética.","Nada é 100 % genético: a comida e o manejo sempre contam."]},{"h":"No seu confinamento","p":["Comprar bezerros de bons touros de corte dá animais que ganham mais.","Se você compra sempre do mesmo criador e vai bem, cuide dessa relação."]}],"rel":["Diferenças esperadas na progênie","Seleção genômica","Vigor híbrido ou heterose"]},{"t":"Vigor híbrido ou heterose","a":"genetica","r":"Quando se cruzam duas raças diferentes, os filhos costumam render mais que a média dos pais. Esse extra é o vigor híbrido, e é maior quanto mais diferentes forem as raças.","s":[{"h":"Quanto dá","p":["Nos cruzamentos zebu com europeu o vigor híbrido é muito alto.","Pode aumentar de 5 a 15 % o crescimento e mais a fertilidade e a sobrevivência.","O máximo está no primeiro cruzamento (F1)."]},{"h":"Por que se perde","p":["Se você cruza F1 com F1, parte do vigor se perde.","Os cruzamentos rotacionais ou as raças compostas mantêm uma parte."]},{"h":"No seu confinamento","p":["Novilhos F1 Brahman com Angus, Simmental ou Charolês são muito procurados para engorda.","Unem resistência ao calor com crescimento e carne."]}],"rel":["Raças compostas","Cruzamentos para corte no trópico","Adaptação do zebu ao trópico"]},{"t":"Cruzamentos para corte no trópico","a":"genetica","r":"Cruzar zebu com raças europeias de corte combina rusticidade e crescimento. A proporção ideal depende do clima e do manejo da fazenda.","s":[{"h":"Proporções","p":["50 % zebu e 50 % europeu (F1): o melhor equilíbrio e o maior vigor híbrido.","Mais de 50 % europeu: mais carne e marmoreio, mas sofre mais com o calor e os carrapatos.","Mais de 50 % zebu: mais rústico, um pouco menos de crescimento."]},{"h":"Raças europeias usadas","p":["Angus: marmoreio e precocidade.","Charolês e Simmental: tamanho e músculo.","Senepol e Romosinuano: raças taurinas adaptadas ao calor."]},{"h":"No seu confinamento","p":["No confinamento com sombra e boa comida, os cruzados com 50 a 75 % europeu rendem muito bem.","Em pasto quente e sem sombra, convém mais sangue zebu."]}],"rel":["Vigor híbrido ou heterose","Raças para engorda no trópico","Raças compostas","Raças crioulas e adaptadas"]},{"t":"Raças compostas","a":"genetica","r":"As raças compostas se formaram cruzando duas ou mais raças e fixando o resultado. Mantêm parte do vigor híbrido e são mais fáceis de manejar que os cruzamentos rotacionais.","s":[{"h":"Exemplos","p":["Brangus: cerca de 3/8 Brahman e 5/8 Angus.","Braford: Brahman com Hereford.","Santa Gertrudis: cerca de 3/8 Brahman e 5/8 Shorthorn.","Simbrasil/Simbrah: Simmental com Brahman.","Beefmaster: Brahman, Hereford e Shorthorn.","Canchim/Charbray: Charolês com zebu."]},{"h":"Vantagens","p":["Animais parelhos e adaptados ao calor moderado.","Bom crescimento e boa carne."]},{"h":"No seu confinamento","p":["Bezerros de raças compostas costumam engordar bem em confinamento e semiconfinamento.","Verifique se vêm de criadores com bom registro."]}],"rel":["Vigor híbrido ou heterose","Cruzamentos para corte no trópico","Raças para engorda no trópico"]},{"t":"Raças crioulas e adaptadas","a":"genetica","r":"As raças crioulas descendem do gado que os espanhóis trouxeram há cinco séculos. Adaptaram-se ao trópico e guardam genes valiosos de resistência.","s":[{"h":"Exemplos","p":["Romosinuano, Blanco Orejinegro, Costeño con Cuernos, Sanmartinero (Colômbia).","Reyna (Nicarágua).","Criollo Limonero (Venezuela).","Senepol (ilhas do Caribe), cruzamento de N'Dama e Red Poll."]},{"h":"Virtudes","p":["Toleram calor sem ser zebu: muitas têm o gene do pelo curto.","Boa fertilidade e temperamento tranquilo.","Carne mais macia que a do zebu."]},{"h":"No seu confinamento","p":["Cruzadas com zebu dão vigor híbrido sem perder adaptação.","São uma alternativa às raças europeias em regiões muito quentes."]}],"rel":["Gene do pelo curto (slick)","Cruzamentos para corte no trópico","Raças para engorda no trópico"]},{"t":"Gene do pelo curto (slick)","a":"genetica","r":"O gene do pelo curto, no receptor da prolactina, dá um pelo muito curto e brilhante que ajuda a eliminar calor. Veio de raças crioulas do Caribe e do Senepol.","s":[{"h":"O que faz","p":["Pelo muito curto e fino o ano todo.","Os animais com o gene mantêm menos temperatura e comem mais com calor.","É dominante: com uma cópia já se nota."]},{"h":"Como se usa","p":["Cruzando com Senepol ou crioulos que o têm.","Com teste de DNA se sabe quais animais o portam.","Também foi introduzido por edição genética; em 2022 as autoridades dos EUA o consideraram de baixo risco."]},{"h":"No seu confinamento","p":["Novilhos com o gene aguentam melhor o curral quente.","Pergunte ao criador se seus touros o portam."]}],"rel":["Raças crioulas e adaptadas","Pele e pelo","Edição genética em bovinos"]},{"t":"Diferenças esperadas na progênie","a":"genetica","r":"A DEP (EPD em inglês) prevê quanto melhores ou piores serão os filhos de um touro comparados com a média da raça. É a principal ferramenta para escolher touros.","s":[{"h":"Como se lê","p":["DEP de peso à desmama +10 kg: seus filhos pesarão em média 5 kg a mais (metade vem do touro).","Compare entre touros da mesma raça e do mesmo ano de avaliação.","Cada DEP traz uma acurácia: mais alta, mais confiável."]},{"h":"DEPs úteis para corte","p":["Peso à desmama e ao ano: crescimento.","Área de olho de lombo e rendimento: músculo.","Marmoreio e gordura: qualidade de carcaça.","Docilidade: temperamento."]},{"h":"No seu confinamento","p":["Mesmo sem criar, você pode preferir bezerros de criadores que usam touros com boas DEPs.","Esses bezerros costumam ganhar mais e mais por igual."]}],"rel":["Herdabilidade","Seleção genômica","Comprar gado para engorda"]},{"t":"Seleção genômica","a":"genetica","r":"Com uma amostra de pelo ou sangue se lê o DNA de um animal e se prevê seu valor genético desde o nascimento, sem esperar ver seus filhos.","s":[{"h":"O que oferece","p":["Mais precisão em touros jovens.","Detecta genes de defeitos, cor, chifres e qualidade de carne.","Confirma a paternidade."]},{"h":"Situação atual","p":["Já se usa nas principais raças de corte, incluindo Brahman e Nelore.","O custo dos testes baixou muito nos últimos anos."]},{"h":"No seu confinamento","p":["É sobretudo para criadores.","Você se beneficia ao comprar bezerros de rebanhos que a usam: mais parelhos e previsíveis."]}],"rel":["Diferenças esperadas na progênie","Herdabilidade","Edição genética em bovinos"]},{"t":"Edição genética em bovinos","a":"genetica","r":"A edição genética muda uma letra do DNA de forma precisa, sem colocar genes de outras espécies. É usada para copiar genes úteis que já existem em outras raças, como o pelo curto ou a ausência de chifres.","s":[{"h":"Exemplos","p":["Pelo curto para tolerar calor.","Animais sem chifres, para evitar a descorna.","Resistência a algumas doenças, em pesquisa."]},{"h":"Regras","p":["Cada país tem regras diferentes; alguns a tratam como melhoramento normal e outros como transgênico.","Seu uso comercial ainda é pequeno."]},{"h":"No seu confinamento","p":["Não é algo que você usará logo, mas pode mudar as raças nos próximos anos.","O que chega à sua fazenda são cruzamentos e touros com esses genes."]}],"rel":["Gene do pelo curto (slick)","Seleção genômica"]},{"t":"Dupla musculatura","a":"genetica","r":"Algumas raças como a Azul Belga e a Piemontesa têm uma falha no gene da miostatina, que normalmente freia o crescimento do músculo. Seus animais têm músculos enormes.","s":[{"h":"Vantagens","p":["Muito mais músculo e rendimento de carcaça.","Carne muito magra e macia."]},{"h":"Desvantagens","p":["Partos difíceis em raças puras.","Menos gordura, o que pode deixar a carne menos suculenta.","Mais sensíveis ao estresse e ao calor."]},{"h":"No seu confinamento","p":["Cruzamentos com essas raças podem dar novilhos muito musculosos.","No trópico são pouco usadas por sua baixa tolerância ao calor."]}],"rel":["Músculo: como cresce","Rendimento: o que aumenta e o que diminui"]},{"t":"Genética da qualidade da carne","a":"genetica","r":"A maciez e o marmoreio são herdados. Há testes de DNA que buscam variantes dos genes da calpaína e da calpastatina para escolher animais de carne mais macia.","s":[{"h":"Genes conhecidos","p":["Calpaína 1 (CAPN1) e calpastatina (CAST): maciez.","As variantes favoráveis são mais comuns em raças europeias que no zebu.","Marmoreio: muitos genes pequenos; melhora-se com DEPs e genômica."]},{"h":"No seu confinamento","p":["Se você vende carne de qualidade, peça animais testados ou cruzados com Angus.","Para o mercado comum, a idade e o manejo pesam mais que esses genes."]}],"rel":["Maciez da carne","Marmoreio e qualidade","Seleção genômica"]},{"t":"Genética e resistência a carrapatos","a":"genetica","r":"A resistência a carrapatos é moderadamente herdável. O zebu e alguns crioulos carregam muito menos carrapatos que as raças europeias.","s":[{"h":"Dados","p":["Herdabilidade de cerca de 0,2 a 0,4.","Um Brahman pode carregar uma fração dos carrapatos de um Holandês no mesmo pasto.","Os cruzados F1 têm resistência intermediária."]},{"h":"Por que importa hoje","p":["Os carrapatos ficaram resistentes a muitos carrapaticidas.","Usar animais mais resistentes reduz banhos e custos."]},{"h":"No seu confinamento","p":["Em pastos com muitos carrapatos, prefira animais com mais sangue zebu.","Combine genética, rotação de pastos e banhos estratégicos."]}],"rel":["Carrapatos","Resistência dos carrapatos aos carrapaticidas","Adaptação do zebu ao trópico"]},{"t":"Genótipo e ambiente","a":"genetica","r":"Um animal não rende igual em todo lugar. A raça que melhor ganha em um confinamento temperado pode ser a pior em um pasto quente. Isso se chama interação genótipo por ambiente.","s":[{"h":"Exemplos","p":["O Angus puro ganha muito em clima fresco, mas sofre no calor úmido.","O Brahman ganha menos em confinamento fresco, mas sobrevive e ganha no calor e com carrapatos.","Os cruzados ficam no meio."]},{"h":"No seu confinamento","p":["Escolha a genética conforme seu clima, suas instalações e sua comida.","Anote a raça no app e compare os lotes: seus dados dirão o que rende melhor na sua fazenda."]}],"rel":["Cruzamentos para corte no trópico","Comparar lotes no app","Raças para engorda no trópico"]},{"t":"Consanguinidade","a":"genetica","r":"A consanguinidade é o cruzamento entre parentes. Aumenta a probabilidade de defeitos e baixa a fertilidade e o crescimento.","s":[{"h":"Sinais em um rebanho","p":["Bezerros menores e mais fracos.","Defeitos de nascimento.","Menos fertilidade."]},{"h":"Como evitá-la","p":["Trocar o touro a cada 2 a 3 anos ou usar inseminação.","Manter registro de pais e mães."]},{"h":"No seu confinamento","p":["Se você compra sempre de um criador pequeno e vê animais atrasados, pergunte pelo touro dele.","Prefira lotes de rebanhos com bom manejo genético."]}],"rel":["Herdabilidade","Animais atrasados"]},{"t":"Defeitos genéticos","a":"genetica","r":"Alguns defeitos se devem a genes recessivos: só aparecem se o bezerro recebe uma cópia do pai e outra da mãe. As associações de raças os controlam com testes de DNA.","s":[{"h":"Como funcionam","p":["Um portador parece normal.","Se dois portadores cruzam, um quarto dos filhos tem o defeito.","Os testes de DNA detectam portadores."]},{"h":"No seu confinamento","p":["Verifique defeitos ao comprar: patas, mandíbula, hérnias e olhos.","Se vários animais de uma mesma origem saem com o mesmo problema, avise o criador."]}],"rel":["Defeitos a revisar na compra","Consanguinidade","Seleção genômica"]},{"t":"Chifres e genética mocha","a":"genetica","r":"A ausência de chifres (animais mochos) é dominante. Usar touros mochos evita a descorna, reduz pancadas e hematomas e melhora o bem-estar.","s":[{"h":"Como se herda","p":["Um touro mocho com duas cópias do gene dá todos os filhos mochos.","Com uma só cópia, dá cerca da metade mochos.","O teste de DNA diz quantas cópias tem."]},{"h":"No seu confinamento","p":["Novilhos mochos causam menos hematomas no curral e no caminhão.","Muitos compradores preferem animais sem chifres ou com pontas cortadas."]}],"rel":["Corte de pontas e descorna","Pancadas e hematomas","Herdabilidade"]},{"t":"Melhorar o lote que você compra","a":"genetica","r":"Mesmo sem criar, você pode melhorar a genética do que engorda escolhendo bem de quem compra e guardando dados de cada origem.","s":[{"h":"O que fazer","p":["Anote em cada lote do app de onde veio e a raça.","Compare ganho, conversão e rendimento por origem.","Volte a comprar dos criadores que dão melhores animais e pague um pouco mais se for preciso."]},{"h":"O que buscar ao comprar","p":["Animais parelhos em tamanho e raça.","Bom frame, lombo comprido e pernil cheio.","Temperamento tranquilo e pelo brilhante."]},{"h":"No seu confinamento","p":["Seus próprios dados valem ouro: depois de 3 ou 4 lotes você saberá qual origem deixa mais dinheiro. Veja na Análise do Rumi, Fornecedores."]}],"rel":["Comprar gado para engorda","Comparar lotes no app","Formar lotes"]},{"t":"Raças zebuínas em detalhe","a":"genetica","r":"O zebu (Bos indicus) inclui várias raças, cada uma com suas forças. Na América Central domina o Brahman e seus cruzamentos.","s":[{"h":"Brahman","p":["Formado nos EUA com várias raças zebuínas.","Vermelho ou cinza, grande porte e adaptação.","Base de muitas raças compostas."]},{"h":"Nelore","p":["Branco, do Brasil e de origem indiana (Ongole).","Muito rústico e resistente, carne magra.","O gado de corte mais numeroso do Brasil."]},{"h":"Gir e Guzerá","p":["Gir: mais leiteiro, orelhas compridas e cabeça abaulada.","Guzerá: duplo propósito, grande e com chifres em forma de lira.","Indubrasil: mistura brasileira de raças zebuínas."]},{"h":"No seu confinamento","p":["Novilhos Brahman e cruzados são os mais comuns e rendem bem a pasto.","Os de sangue leiteiro (Gir) têm menos musculatura para carne."]}],"rel":["Adaptação do zebu ao trópico","Raças para engorda no trópico","Novilhos de leite"]},{"t":"Raças europeias de corte","a":"genetica","r":"As raças europeias (Bos taurus) crescem rápido e dão boa carne, mas sofrem com o calor e os carrapatos do trópico. São usadas sobretudo em cruzamentos.","s":[{"h":"Britânicas","p":["Angus: preto ou vermelho, precoce e com muito marmoreio.","Hereford: cara branca, rústico e dócil.","Shorthorn: parte de várias raças compostas."]},{"h":"Continentais","p":["Charolês: branco, grande, muita carne.","Simmental: grande, bom crescimento e duplo propósito.","Limousin: muito músculo e rendimento."]},{"h":"No seu confinamento","p":["Cruzados F1 com essas raças crescem mais rápido no confinamento.","Precisam de sombra, água abundante e boa comida para mostrar seu potencial."]}],"rel":["Cruzamentos para corte no trópico","Vigor híbrido ou heterose","Zona de conforto térmico"]},{"t":"Projeto de currais","a":"instalaciones","r":"Um bom curral facilita o trabalho, reduz o estresse e ajuda a saúde. Pensar bem o projeto economiza dinheiro por anos.","s":[{"h":"Localização","p":["Terreno alto com boa drenagem e leve declive (2 a 4 %).","Longe de córregos e casas.","Com acesso para caminhões de ração e de gado.","Perto de água e eletricidade."]},{"h":"Distribuição","p":["Currais de engorda em fila com cochos voltados para um corredor de alimentação.","Corredor de manejo atrás que leva ao tronco.","Currais de recepção e de enfermos à parte.","Depósito perto do corredor de alimentação."]},{"h":"Medidas de referência","p":["10 a 15 m² por animal em terra, 3,5 a 5 m² em cimento.","30 a 45 cm de cocho por animal.","3 a 4 m² de sombra por animal.","Cercas de 1,5 a 1,8 m de altura."]},{"h":"Erros comuns","p":["Currais em partes baixas que alagam.","Cochos dentro do curral, onde se sujam.","Sem corredores: todo manejo é uma briga."]}],"rel":["Espaço por animal","Cochos","Pisos e drenagem"]},{"t":"Cochos","a":"instalaciones","r":"O cocho deve ser cômodo para o animal, fácil de limpar e evitar desperdício.","s":[{"h":"Tipos","p":["Linear de cimento: durável e fácil de limpar.","De madeira ou tubo cortado: mais barato.","Pneus cortados: só para poucos animais."]},{"h":"Medidas","p":["Largura de 60 a 70 cm e profundidade de 25 a 40 cm.","Borda do lado do animal a 50 a 60 cm do chão.","Fundo liso e arredondado, sem cantos onde a comida apodreça."]},{"h":"Barreira","p":["Tubo ou cabo sobre o cocho na altura do pescoço.","Evita que entrem, sujem ou joguem ração fora."]},{"h":"Localização","p":["Na borda do curral, com acesso pelo corredor.","Plataforma de cimento de 2 a 3 m na frente do cocho para não fazer lama.","Teto ou beiral em regiões de muita chuva."]}],"rel":["Espaço por animal","Desperdício de alimento","Leitura de cochos"]},{"t":"Bebedouros","a":"instalaciones","r":"Água limpa e suficiente é a base de tudo. Um bebedouro bem projetado enche rápido e se limpa fácil.","s":[{"h":"Tipos","p":["Tanque de cimento com boia.","Bebedouros plásticos ou metálicos.","Bebedouros automáticos de nível constante."]},{"h":"Medidas e capacidade","p":["Altura de 50 a 70 cm.","Espaço para 10 a 15 % do lote beber ao mesmo tempo.","Vazão suficiente para recuperar o nível em poucos minutos."]},{"h":"Localização","p":["Na sombra.","Separado do cocho para não cair comida.","Acessível de dois currais para economizar.","Com piso firme ao redor."]},{"h":"Manutenção","p":["Lavar toda semana.","Revisar boias e vazamentos todo dia.","Registro de dreno para esvaziar fácil."]}],"rel":["Água de bebida","Água: fontes, caixas e qualidade","Estresse por calor"]},{"t":"Sombra","a":"instalaciones","r":"A sombra é a forma mais barata de combater o calor. No trópico não é luxo: é parte da ração.","s":[{"h":"Quanta","p":["3 a 4 m² por animal.","Altura de 3 a 4 metros para o ar circular."]},{"h":"Materiais","p":["Telhado de chapa com isolante ou pintura branca por cima.","Sombrite ou tela de sombra de 70 a 80 %.","Árvores em currais de terra ou pastos."]},{"h":"Orientação","p":["Telhados de norte a sul fazem a sombra se mover e o piso secar.","Telhados de leste a oeste dão sombra fixa; o piso embaixo vira lama."]},{"h":"Erros comuns","p":["Sombras muito baixas que acumulam calor.","Pouca sombra: os animais se amontoam e se estressam."]}],"rel":["Estresse por calor","Golpe de calor","Sistemas silvipastoris"]},{"t":"Pisos e drenagem","a":"instalaciones","r":"Um curral com lama permanente adoece patas e pulmões e baixa o ganho. A drenagem se projeta antes de construir.","s":[{"h":"Declive","p":["2 a 4 % para fora do cocho.","Canais que levem a água para longe do curral."]},{"h":"Tipo de piso","p":["Terra compactada: barata, precisa de mais espaço e manutenção.","Cimento com acabamento áspero: fácil de limpar, precisa de menos espaço, mas esquenta e pode machucar as patas.","Plataforma de cimento na frente de cochos e bebedouros, sempre."]},{"h":"Manutenção","p":["Retire o esterco com frequência.","Preencha os buracos onde se junta água.","Montes de terra seca na época de chuvas para descansarem."]}],"rel":["Projeto de currais","Mancadeiras e problemas de casco","Manejo do esterco"]},{"t":"Tronco, brete e funil","a":"instalaciones","r":"O tronco é a ferramenta de trabalho mais usada. Um bom tronco torna o manejo rápido, seguro e sem pancadas.","s":[{"h":"Partes","p":["Curral de espera.","Funil ou curral de encerramento que leva ao tronco.","Seringa: corredor estreito onde os animais vão em fila.","Tronco de contenção no final para segurar a cabeça.","Balança e porteira de apartação na saída."]},{"h":"Medidas","p":["Largura da seringa de 70 a 80 cm para animais de engorda.","Paredes de 1,6 a 1,8 m, fechadas na parte de baixo para não se distraírem.","Comprimento para 4 a 6 animais em fila.","Seringa curva: aproveita que o animal quer voltar ao ponto de partida."]},{"h":"Segurança","p":["Passarela lateral para trabalhar por cima.","Porteiras que fechem sem a pessoa entrar na seringa.","Nada que corte ou fure."]}],"rel":["Trabalho no tronco","Manejo tranquilo do gado","Balança"]},{"t":"Balança","a":"instalaciones","r":"Sem balança se engorda às cegas. É o investimento que se paga mais rápido.","s":[{"h":"Tipos","p":["Balança de plataforma com gaiola individual.","Balança de barras sob uma gaiola na saída do tronco.","Balança para grupos (menos precisa por animal)."]},{"h":"Instalação","p":["Base firme e nivelada.","Protegida do sol e da chuva.","No fim do tronco para pesar um por um."]},{"h":"Calibração","p":["Confira com um peso conhecido de tempos em tempos.","Limpe esterco e pedras embaixo da plataforma.","Zere antes de pesar."]}],"rel":["Pesagem","Tronco, brete e funil","Estimar o peso sem balança"]},{"t":"Embarcadouro","a":"instalaciones","r":"Um bom embarcadouro torna a carga e a descarga rápidas e sem lesões.","s":[{"h":"Medidas","p":["Rampa com inclinação máxima de 20 a 25 graus.","Degraus ou ripas antiderrapantes a cada 20 a 30 cm.","Plataforma plana no final, no nível do caminhão.","Largura de 75 a 90 cm."]},{"h":"Regras","p":["Paredes laterais fechadas para não se distraírem.","Boa luz, sem sombras fortes.","Os caminhões não devem entrar nos currais."]}],"rel":["Transporte de gado","Manejo tranquilo do gado","Quarentena e biossegurança"]},{"t":"Depósito de ração","a":"instalaciones","r":"O depósito guarda um dos seus maiores gastos. Construí-lo bem reduz perdas por umidade e pragas.","s":[{"h":"Construção","p":["Piso de cimento mais alto que o terreno.","Telhado sem goteiras com bom beiral.","Paredes fechadas e ventilação com tela.","Portas que fechem bem, com cadeado."]},{"h":"Organização","p":["Estrados para sacos.","Área separada para minerais e aditivos.","Remédios e químicos em outro cômodo.","Área de mistura perto da porta."]},{"h":"Capacidade","p":["Suficiente para pelo menos 2 a 4 semanas de ração.","Mais se você compra grão na safra."]}],"rel":["Armazenamento do alimento","Controle de pragas no armazém","Misturador e equipamentos"]},{"t":"Cercas","a":"instalaciones","r":"As cercas mantêm os animais onde devem estar e permitem dividir pastos.","s":[{"h":"Cerca de curral","p":["Tubo, madeira tratada ou cabo: forte e sem partes que cortem.","Altura de 1,5 a 1,8 m."]},{"h":"Cerca de pasto","p":["Arame farpado de 4 a 5 fios com mourões a cada 2,5 a 3 m.","Cercas vivas de gliricídia ou outras: mais baratas e dão forragem e sombra."]},{"h":"Cerca elétrica","p":["Barata para dividir piquetes.","Eletrificador bem aterrado.","Limpe o mato que encosta no fio.","Ensine os animais a respeitá-la primeiro em um curral pequeno."]}],"rel":["Pastejo rotacionado","Manutenção de instalações"]},{"t":"Água: fontes, caixas e qualidade","a":"instalaciones","r":"Um confinamento precisa de muita água todos os dias. Garantir a fonte e a reserva evita emergências.","s":[{"h":"Quanto precisa","p":["40 a 70 litros por animal por dia, até o dobro com calor.","100 animais podem precisar de 5.000 a 10.000 litros por dia."]},{"h":"Fontes","p":["Poço, nascente, rio ou rede municipal.","Captação de água de chuva dos telhados em reservatórios."]},{"h":"Reserva","p":["Caixa-d'água elevada para pelo menos 2 a 3 dias de consumo.","Dá água por gravidade se a bomba falhar."]},{"h":"Qualidade","p":["Análise se for de poço: sais, nitratos, enxofre, bactérias.","Evite que o gado beba de rios e poças."]},{"h":"Bombeamento","p":["Bomba solar onde não há energia elétrica.","Revise filtros e boias toda semana."]}],"rel":["Água de bebida","Bebedouros","Irrigação de pastos"]},{"t":"Manejo do esterco","a":"instalaciones","r":"Um animal de engorda produz uns 20 a 30 kg de esterco por dia. Manejá-lo bem evita moscas, odores e problemas com vizinhos, e dá adubo.","s":[{"h":"Retirada","p":["Limpeza dos currais de tempos em tempos, mais seguida nas chuvas.","Raspagem das plataformas de cimento diária ou semanal."]},{"h":"Compostagem","p":["Amontoe o esterco longe de currais, casas e fontes de água.","Revire-o de tempos em tempos: o calor mata sementes e micróbios.","Aos 2 a 3 meses serve de adubo."]},{"h":"Outros usos","p":["Biodigestor para gás de cozinha.","Vermicomposto (húmus de minhoca)."]},{"h":"Regras","p":["Não jogue esterco em córregos.","Cuide para que o escoamento do curral não chegue às fontes de água."]}],"rel":["Moscas-dos-chifres e moscas-dos-estábulos","Adubar pastos","Ambiente e manejo de resíduos"]},{"t":"Galpão ou confinamento coberto","a":"instalaciones","r":"Currais cobertos com piso de cimento permitem engordar em pouco espaço e protegem da chuva e do sol.","s":[{"h":"Vantagens","p":["Menos lama e menos problemas de patas nas chuvas.","Melhor controle de moscas e limpeza.","Menos espaço por animal."]},{"h":"Requisitos","p":["Telhado alto (4 a 5 m) com boa ventilação.","Piso áspero com declive para o dreno.","Limpeza diária ou frequente.","Plano para o esterco."]},{"h":"Custos","p":["Investimento alto por animal.","Justifica-se com engordas contínuas e bom giro."]}],"rel":["Projeto de currais","Pisos e drenagem","Orçamento de instalações"]},{"t":"Orçamento de instalações","a":"instalaciones","r":"As instalações devem se pagar com os animais que você engorda. Calcular seu custo por cabeça evita investimentos que não rendem.","s":[{"h":"O que incluir","p":["Currais, cochos, bebedouros, sombra.","Tronco, balança, embarcadouro.","Depósito e equipamento de mistura.","Água e eletricidade."]},{"h":"Custo por animal","p":["Divida o investimento pelos anos de vida útil e pelos animais que você engorda por ano.","Exemplo: 200.000 de investimento, 10 anos, 300 animais por ano = uns 67 por animal."]},{"h":"Economizar","p":["Materiais locais e tratados.","Construir por etapas.","Primeiro o que mais rende: balança, bebedouros, sombra e cochos."]}],"rel":["Depreciação e investimentos","Projeto de currais","Escala do confinamento"]},{"t":"Manutenção de instalações","a":"instalaciones","r":"Um prego saído ou um bebedouro pingando custam mais do que parece. A manutenção preventiva é barata.","s":[{"h":"Revisão semanal","p":["Cercas, porteiras, dobradiças e cadeados.","Pregos, arames e tábuas quebradas.","Boias, tubulações e vazamentos.","Cochos quebrados ou com quinas."]},{"h":"Revisão antes das chuvas","p":["Telhados, calhas e drenos.","Pisos e pontos onde se junta água."]},{"h":"Registro","p":["Anote os gastos de manutenção no app como despesas gerais."]}],"rel":["Feridas e curativos","Cercas","Pisos e drenagem"]},{"t":"Misturador e equipamentos","a":"instalaciones","r":"O equipamento certo faz a ração sair uniforme e economiza horas de trabalho.","s":[{"h":"Equipamento básico","p":["Balança pequena para pesar ingredientes.","Picadeira de capim.","Moinho ou quebrador de grão.","Carroças ou carrinhos de mão para servir."]},{"h":"Misturador","p":["Horizontal ou vertical, estacionário ou de arrasto.","Tamanho conforme a ração diária.","Tempo de mistura conforme o fabricante."]},{"h":"Manutenção","p":["Limpeza diária de restos.","Afiação das facas da picadeira.","Revisão de correias, correntes e rolamentos."]},{"h":"Segurança","p":["Proteções nas partes que giram.","Nunca pôr as mãos com a máquina ligada.","Desligar e desconectar antes de limpar."]}],"rel":["Mistura da ração","Depósito de ração","Pessoal e segurança no trabalho"]},{"t":"Curral de recepção","a":"instalaciones","r":"Um curral especial para os recém-chegados facilita observá-los, tratá-los e evitar que contagiem o resto.","s":[{"h":"Como deve ser","p":["Separado dos currais de engorda, perto do tronco.","Sombra, água com boa vazão e cocho com feno.","Piso seco e sem lama.","Boa visão para observar os animais."]},{"h":"Uso","p":["Os animais passam aqui as primeiras 2 a 3 semanas.","Aqui se faz a adaptação ao concentrado.","Limpe e desinfete entre lotes."]}],"rel":["Recepção de gado","Quarentena e biossegurança","Curral de doentes"]},{"t":"Pedilúvio","a":"instalaciones","r":"Um tanque raso na entrada do tronco onde os animais passam as patas por uma solução desinfetante.","s":[{"h":"Para quê","p":["Prevenir e controlar infecções de casco quando há muitos casos."]},{"h":"Medidas","p":["Comprimento de 3 metros para cada pata entrar pelo menos duas vezes.","Profundidade da solução de 10 a 15 cm."]},{"h":"Manejo","p":["Solução indicada pelo veterinário e trocada conforme a sujeira.","Antes, uma passagem com água limpa para tirar a lama."]}],"rel":["Mancadeiras e problemas de casco","Tronco, brete e funil"]},{"t":"Captação de água de chuva","a":"instalaciones","r":"Os telhados de galpões e depósitos podem encher caixas e reservatórios com água para a seca.","s":[{"h":"Quanto se pode juntar","p":["Cada milímetro de chuva sobre um metro quadrado de telhado dá um litro.","Um telhado de 200 m² com 1.200 mm de chuva por ano pode dar uns 200.000 litros (menos perdas)."]},{"h":"Como","p":["Calhas e condutores limpos.","Descartar a primeira água que lava o telhado.","Caixas tampadas ou reservatórios cercados."]},{"h":"Uso","p":["Bebedouros na seca.","Limpeza de currais."]}],"rel":["Água: fontes, caixas e qualidade","Época seca"]},{"t":"Sombra de tela","a":"instalaciones","r":"Quando não há árvores, a tela de sombra (sombrite) é a forma mais rápida e barata de dar sombra no curral.","s":[{"h":"Como fazer","p":["Tela de 70 a 80 % de sombra.","2 a 4 m² por animal.","Altura de 3,5 a 4 m para o ar correr e os animais não alcançarem.","Orientação norte-sul para a sombra se mover e o piso secar."]},{"h":"Cuidados","p":["Postes firmes e cabos esticados: o vento a rasga.","Revisar depois de tempestades."]}],"rel":["Sombra","Sombra e radiação solar","Estresse por calor"]},{"t":"Aspersores e resfriamento","a":"instalaciones","r":"Molhar os animais ou o telhado em ondas de calor ajuda a baixar sua temperatura. É preciso fazer bem para não criar lama nem umidade excessiva.","s":[{"h":"Como","p":["Aspersores de gota grande que molhem a pele, não névoa fina que sobe a umidade.","Ciclos curtos: molhar 1 a 2 minutos a cada 10 a 15 minutos.","Com vento ou ventilador para a água evaporar."]},{"h":"Cuidados","p":["Boa drenagem para evitar lama.","Não molhar só alguns animais: todos se amontoam."]}],"rel":["Estresse por calor","Galpão ou confinamento coberto","Pisos e drenagem"]},{"t":"Bombas solares de água","a":"instalaciones","r":"As bombas com painéis solares tiram água de poços ou rios sem gasolina nem energia da rede. São cada vez mais baratas e comuns nas fazendas.","s":[{"h":"Vantagens","p":["Sem custo de combustível.","Bombeiam mais justo quando faz mais calor e o gado bebe mais água.","Pouca manutenção."]},{"h":"O que considerar","p":["Caixa de reserva para a noite e os dias nublados: pelo menos 2 dias de consumo.","Calcule a água que precisa: uns 50 a 70 litros por novilho por dia com calor.","Proteja os painéis contra roubo."]}],"rel":["Água: fontes, caixas e qualidade","Bebedouros","Captação de água de chuva"]},{"t":"Silo trincheira ou de superfície","a":"instalaciones","r":"O silo trincheira ou de superfície guarda silagem em grandes quantidades a baixo custo. O importante é compactar bem e cobrir sem deixar entrar ar.","s":[{"h":"Construção","p":["Terreno firme, com declive para a água escorrer.","Paredes de terra, madeira ou concreto na trincheira.","Lona grossa para cobrir e peso em cima (pneus, sacos de terra)."]},{"h":"Uso","p":["Frente de corte que avance pelo menos 15 a 30 cm por dia para não estragar.","Cortar por igual, sem afrouxar o resto."]}],"rel":["Silagem: como fazer","Silagem: qualidade e problemas","Microssilos em sacos ou tambores"]},{"t":"Comprar gado para engorda","a":"manejo","r":"O lucro da engorda começa na compra. Um bom animal a bom preço se engorda fácil; um ruim ou caro nunca se recupera.","s":[{"h":"O que buscar","p":["Animais sadios, alertas, com bom apetite.","Estrutura: patas retas, bom comprimento, peito amplo.","Idade de 12 a 24 meses para confinamento.","Peso de entrada de acordo com seu plano (comumente 250 a 350 kg).","Lotes parelhos em peso, idade e tipo."]},{"h":"O que evitar","p":["Magros por doença, com tosse, diarreia ou mancos.","Hérnias, olhos danificados, feridas ou bicheira.","Animais velhos com dentes gastos.","Muito nervosos ou agressivos.","Animais sem guia de trânsito nem origem clara."]},{"h":"O preço","p":["Compare sempre por quilo vivo, não por cabeça.","Calcule antes no Rumi o preço máximo que você pode pagar com seus custos.","Considere a quebra: o animal cheio pesa mais.","Some frete, comissões e perdas de viagem."]},{"h":"Origem","p":["Melhor poucas origens conhecidas do que muitas diferentes.","Pergunte se foram vacinados, vermifugados e desmamados.","Anote o fornecedor no lote: o app dirá qual fornecedor rende melhor."]},{"h":"Erros comuns","p":["Comprar o lote barato sem revisar animal por animal.","Pagar por cabeça sem pesar.","Encher o curral com animais de cinco fazendas diferentes.","Comprar sem ter a ração e a sanidade prontas."]}],"rel":["Preço máximo de compra","Defeitos a revisar na compra","Transporte de gado"]},{"t":"Comprar em leilão ou feira","a":"manejo","r":"O leilão permite comprar muitos animais num dia, mas mistura origens e traz mais risco de doenças.","s":[{"h":"Antes","p":["Decida quantos animais, de que peso e seu preço máximo por quilo.","Veja o calendário e o catálogo, se houver.","Leve a calculadora do Rumi pronta com seus custos."]},{"h":"No leilão","p":["Chegue cedo e olhe os lotes nos currais antes da venda.","Observe como caminham, respiram e se comem.","Evite lotes muito desparelhos ou com animais doentes.","Não se deixe levar pelos lances: respeite seu preço máximo."]},{"h":"Depois","p":["Transporte direto à sua fazenda, sem paradas longas.","Recepção com quarentena e plano sanitário completo.","Espere mais casos de pneumonia do que com animais de uma só fazenda."]}],"rel":["Comprar gado para engorda","Plano sanitário de entrada","Recepção de gado"]},{"t":"Transporte de gado","a":"manejo","r":"Uma viagem malfeita causa pancadas, perda de peso, doenças e mortes. Um bom transporte faz parte da engorda.","s":[{"h":"Antes de carregar","p":["Guia de trânsito em ordem, do serviço de sanidade animal do seu país (SENASA em Honduras).","Caminhão limpo, com piso antiderrapante e sem pregos ou chapas soltas.","Animais descansados e com água.","Jejum curto: não mais de 12 horas sem comida antes da viagem."]},{"h":"Carga","p":["Use rampa ou embarcadouro, com calma e sem choque elétrico demais.","Densidade certa: nem muito apertados (caem e se pisam) nem muito soltos (se machucam).","Separe animais de tamanhos muito diferentes ou com chifres."]},{"h":"Durante a viagem","p":["Dirija suave, sem freadas nem curvas rápidas.","Viaje nas horas frescas.","Em viagens longas, revise em paradas curtas e não deixe o caminhão parado ao sol."]},{"h":"Perdas esperadas","p":["Um animal perde 3 a 8 % do peso numa viagem de várias horas, sobretudo água e conteúdo do rúmen.","A maior parte se recupera em 1 a 2 semanas com bom manejo."]}],"rel":["Recepção de gado","Pneumonia ou complexo respiratório","Transporte: requisitos"]},{"t":"Recepção de gado","a":"manejo","r":"As três primeiras semanas decidem se o lote arranca bem. Receber com calma, água e boa comida vale tanto quanto as vacinas.","s":[{"h":"Ao descer do caminhão","p":["Descarregue devagar, sem gritos nem pancadas.","Conte os animais e confira a guia.","Separe logo os mancos, feridos ou abatidos."]},{"h":"Primeiras 24 horas","p":["Água limpa e abundante; deixe o bebedouro transbordar um pouco para que o encontrem.","Feno ou pasto seco de boa qualidade à vontade.","Descanso em curral de recepção com sombra.","Não misturar com outros lotes."]},{"h":"Dias 1 a 7","p":["Plano sanitário de entrada quando estiverem descansados.","Pesagem e brincos.","Início da ração de adaptação.","Revisão duas vezes por dia."]},{"h":"Dias 7 a 21","p":["Adaptação gradual ao concentrado.","Atenção à pneumonia: febre, muco, orelhas caídas.","Registro de doentes e tratamentos no app."]},{"h":"Metas","p":["Que comam bem em 3 a 5 dias.","Menos de 10 % de doentes nas primeiras 3 semanas.","Zero mortes."]}],"rel":["Plano sanitário de entrada","Ração inicial","Transporte de gado"]},{"t":"Identificação de animais","a":"manejo","r":"Identificar cada animal permite acompanhar seu peso, saúde e custo. Sem identificação você só tem médias.","s":[{"h":"Brincos","p":["Numerados, grandes e fáceis de ler à distância.","Colocam-se no centro da orelha, entre as veias grandes, com aplicador limpo.","Evite épocas de muitas moscas ou cure a ferida.","Use o mesmo número no app."]},{"h":"Marca a fogo","p":["Marca de propriedade registrada.","Um só lugar, rápido, com o ferro na temperatura certa.","Evite as pernas: danifica couro valioso.","Cure e vigie contra bicheira."]},{"h":"Foto do animal","p":["Uma foto na entrada ajuda a reconhecê-lo se perder o brinco.","No app você pode tirar a foto ao criar o lote ou pela ficha do animal."]},{"h":"Brinco perdido","p":["Identifique-o de novo o quanto antes com a foto, a cor e os sinais.","Edite o brinco no app para não perder seu histórico de pesos."]}],"rel":["Registros e rastreabilidade","Guia de trânsito e rastreabilidade","Pesagem"]},{"t":"Pesagem","a":"manejo","r":"Pesar é a única forma de saber se a engorda vai bem. Todo número importante sai do peso.","s":[{"h":"Para que pesar","p":["Calcular o ganho diário real.","Detectar animais atrasados.","Ajustar a ração e a dose de medicamentos.","Decidir quando vender.","Calcular a conversão e o custo por quilo ganho."]},{"h":"Com que frequência","p":["Na entrada, sempre.","A cada 21 a 30 dias durante a engorda.","Antes de vender."]},{"h":"Como pesar bem","p":["Sempre no mesmo horário, de preferência cedo antes de tratar.","Nas mesmas condições de água e comida.","Balança calibrada: confira com um peso conhecido.","Anote cada animal pelo brinco no app."]},{"h":"Erros comuns","p":["Pesar uns dias de manhã e outros à tarde.","Pesar logo depois de comerem ou beberem água.","Pesar só uma amostra e achar que é a média do lote.","Não anotar os pesos na hora."]}],"rel":["Estimar o peso sem balança","Balança","Animais atrasados"]},{"t":"Estimar o peso sem balança","a":"manejo","r":"Sem balança dá para estimar o peso com fita. Não é exato, mas é muito melhor que no olho.","s":[{"h":"Fita de pesagem","p":["Passe ao redor do peito logo atrás das patas dianteiras.","A fita já traz a escala em quilos ou libras.","Animal de pé e reto, com a cabeça normal."]},{"h":"Fórmula com fita métrica","p":["Meça o perímetro torácico e o comprimento do corpo (da ponta da paleta à ponta da nádega) em centímetros.","Peso aproximado em kg = perímetro × perímetro × comprimento ÷ 10.840.","Exemplo: perímetro 180 cm e comprimento 160 cm = 180 × 180 × 160 ÷ 10.840 ≈ 478 kg.","Use a calculadora do Rumi."]},{"h":"Precisão","p":["O erro pode ser de 5 a 10 %.","É melhor para acompanhar o ganho do mesmo animal do que para vender.","Para vender, pese sempre na balança."]}],"rel":["Pesagem","Balança","Vender em pé ou por carcaça"]},{"t":"Formar lotes","a":"manejo","r":"Agrupar animais parecidos facilita alimentar, manejar e vender. Um lote parelho come e ganha por igual.","s":[{"h":"Critérios","p":["Peso parecido: diferenças de no máximo 50 kg dentro do lote.","Mesmo sexo e condição (inteiros com inteiros, castrados com castrados).","Idade parecida.","Mesma origem quando possível."]},{"h":"Tamanho do lote","p":["De acordo com o curral e o espaço de cocho.","Lotes de 30 a 80 cabeças são fáceis de manejar.","Muito grandes: os tímidos comem menos."]},{"h":"Reagrupar","p":["Evite misturar lotes durante a engorda: brigam e baixam o ganho.","Se tiver que misturar, faça no início, com comida e espaço de sobra."]},{"h":"No app","p":["Cada lote tem nome, tipo, raça, fornecedor e ração.","Assim você compara lotes e sabe o que funcionou."]}],"rel":["Espaço por animal","Inteiros ou castrados","Comprar gado para engorda"]},{"t":"Manejo tranquilo do gado","a":"manejo","r":"O gado manejado com calma se estressa menos, adoece menos, ganha mais e é mais seguro para as pessoas.","s":[{"h":"Como o bovino vê e pensa","p":["Vê quase ao redor de si, mas tem um ponto cego bem atrás.","Assustam-no as sombras, os contrastes, os objetos que se mexem e os ruídos fortes.","Segue os companheiros: mova grupos, não animais soltos."]},{"h":"Zona de fuga e ponto de equilíbrio","p":["A zona de fuga é a distância em que o animal se afasta de você.","Entre nessa zona para ele avançar e saia para ele parar.","O ponto de equilíbrio fica na altura da paleta: se você se põe atrás dele, o animal avança; se se põe na frente, recua."]},{"h":"Regras","p":["Sem gritos, sem cães, sem paus.","Use bandeiras ou varas como extensão do braço, não para bater.","Mova grupos pequenos a passo.","Deixe que vejam para onde vão."]},{"h":"Benefícios","p":["Menos pancadas e hematomas na carcaça.","Menos acidentes de trabalhadores.","Melhor consumo depois do manejo."]}],"rel":["Trabalho no tronco","Bem-estar animal","Tronco, brete e funil"]},{"t":"Trabalho no tronco","a":"manejo","r":"O tronco é onde se pesa, vacina e trata. Trabalhar bem nele economiza tempo, pancadas e acidentes.","s":[{"h":"Preparação","p":["Confira se porteiras, trancas e o tronco de contenção funcionam.","Tenha prontos os produtos, as seringas e o app para anotar.","Trabalhe cedo, nas horas frescas."]},{"h":"Durante","p":["Encha a seringa sem apertar demais.","Um animal por vez na contenção, bem preso.","Trabalhe rápido mas sem pressa: cada passo anotado.","Solte com calma: um animal que sai correndo se machuca."]},{"h":"Segurança","p":["Nunca fique entre um animal e a parede sem saída.","Cuidado com os coices para a frente e as cabeçadas.","Não enfie os braços entre as tábuas.","Sempre pelo menos duas pessoas."]}],"rel":["Manejo tranquilo do gado","Tronco, brete e funil","Aplicação de injeções"]},{"t":"Castração","a":"manejo","r":"Castrar produz animais mais mansos e carne com mais gordura, mas reduz um pouco o ganho. Se for fazer, melhor jovem e com bom manejo.","s":[{"h":"Quando","p":["O ideal é antes dos 6 meses: menos estresse e menos perda de peso.","Em animais grandes, faça com o animal sadio e adaptado, não na chegada.","Em época de poucas moscas."]},{"h":"Métodos","p":["Cirúrgico (faca): seguro se feito com higiene; precisa de cuidado da ferida.","Elástico ou anel: em animais jovens; há risco de tétano.","Burdizzo: sem ferida; é preciso verificar se funcionou.","Consulte seu veterinário sobre o controle da dor."]},{"h":"Cuidados","p":["Vacina clostridial em dia.","Repelente e cura contra bicheira.","Vigie sangramento, inchaço e febre por uma semana."]},{"h":"Efeito na engorda","p":["O castrado ganha um pouco menos que o inteiro, mas engorda antes.","Alguns compradores pagam melhor o castrado pela qualidade da carne."]}],"rel":["Inteiros ou castrados","Bicheira (Cochliomyia)","Doenças clostridiais"]},{"t":"Corte de pontas e descorna","a":"manejo","r":"Os chifres causam pancadas e feridas nos companheiros e nos trabalhadores. Tirá-los ou cortar as pontas reduz danos na carcaça.","s":[{"h":"Quando","p":["A descorna é muito mais fácil e segura em bezerros jovens.","Em adultos, só cortar a ponta ou fazer com o veterinário."]},{"h":"Cuidados","p":["Faça em época de poucas moscas.","Controle o sangramento e aplique repelente.","Não faça ao mesmo tempo que outros manejos estressantes na chegada."]},{"h":"Alternativas","p":["Formar lotes separados de animais com chifres.","Cochos com espaço suficiente para não brigarem."]}],"rel":["Feridas e curativos","Espaço por animal","Bem-estar animal"]},{"t":"Inteiros ou castrados","a":"manejo","r":"Os tourinhos inteiros ganham mais e convertem melhor; os castrados são mais mansos e engordam antes. A melhor opção depende do seu mercado.","s":[{"h":"Inteiros","p":["Ganham de 5 a 15 % mais por dia.","Melhor conversão e mais músculo.","Mais brigas, montas e nervosismo.","Alguns compradores pagam menos por terem menos gordura."]},{"h":"Castrados","p":["Mais tranquilos e fáceis de manejar.","Engordam mais cedo: bom acabamento com menos peso.","Carne mais suave e com mais marmoreio."]},{"h":"Como decidir","p":["Pergunte ao comprador o que paga melhor.","Compare no app a margem de lotes de inteiros e castrados.","Não misture inteiros com castrados no mesmo curral."]}],"rel":["Castração","Animais que montam (buller)","Formar lotes"]},{"t":"Animais atrasados","a":"manejo","r":"Em todo lote há animais que ganham muito menos que a média. Encontrá-los a tempo evita que comam sua margem.","s":[{"h":"Como encontrá-los","p":["Pese por brinco: o app marca os que ganham menos de 70 % da média do lote.","Veja quem fica para trás no cocho.","Revise pelo, fezes, respiração e patas."]},{"h":"Causas comuns","p":["Doença passada, sobretudo pneumonia.","Parasitas.","Dentes ruins ou animal velho.","Animal dominado que não chega ao cocho.","Manqueiras."]},{"h":"O que fazer","p":["Revise e trate a causa se tiver conserto.","Passe para um curral com menos competição.","Se na próxima pesagem continuar atrasado, venda sem carências ativas.","Anote o fornecedor para avaliar compras futuras."]}],"rel":["Pesagem","Curral de doentes","Comprar gado para engorda"]},{"t":"Rotina diária da engorda","a":"manejo","r":"A engorda é disciplina: fazer o mesmo, bem, todos os dias. Uma rotina escrita evita esquecimentos.","s":[{"h":"Cedo","p":["Leitura de cocho.","Revisão dos animais: doentes, mancos, inchados.","Revisão de bebedouros e boias.","Primeiro trato."]},{"h":"Meio da manhã","p":["Tratamento dos doentes.","Mistura da ração para os próximos tratos.","Limpeza de cochos e bebedouros que precisem."]},{"h":"Tarde","p":["Segundo ou terceiro trato.","Outra revisão dos animais.","Anotar tudo no app: ração, tratamentos, mortes, despesas."]},{"h":"Toda semana","p":["Limpar os bebedouros a fundo.","Revisar cercas, porteiras e o depósito.","Revisar o estoque de ração e remédios."]},{"h":"A cada 3 a 4 semanas","p":["Pesagem.","Revisar os números de cada lote no app e ajustar."]}],"rel":["Leitura de cochos","Revisão diária dos animais","Registros e rastreabilidade"]},{"t":"Registros e rastreabilidade","a":"manejo","r":"O que não se anota não se pode melhorar. Os registros dizem onde você ganha e onde perde, e abrem mercados que pedem rastreabilidade.","s":[{"h":"O que anotar","p":["Entrada de cada lote: data, número de animais, peso, preço, fornecedor.","Ração fornecida a cada dia.","Pesagens.","Tratamentos e vacinas com carência.","Mortes e sua causa.","Despesas e vendas."]},{"h":"Para que servem","p":["Calcular ganho, conversão, custo por quilo e margem reais.","Decidir quando vender.","Comparar fornecedores, rações e épocas.","Demonstrar ao comprador e à autoridade o que cada animal recebeu."]},{"h":"Com o app","p":["Tudo fica salvo no celular e ele dá os números sozinho.","Baixe o backup toda semana e os dados para Excel quando precisar."]}],"rel":["Guia de trânsito e rastreabilidade","Registros econômicos","Identificação de animais"]},{"t":"Espaço por animal","a":"manejo","r":"Com pouco espaço os animais brigam, se sujam e comem menos. Com espaço demais, você desperdiça curral e investimento.","s":[{"h":"Curral","p":["Piso de terra: 10 a 15 m² por animal (mais na época de chuvas).","Piso de cimento: 3,5 a 5 m² por animal."]},{"h":"Cocho","p":["30 a 45 cm lineares por animal se todos comem ao mesmo tempo.","15 a 20 cm se sempre há comida disponível.","Animais com chifres precisam de mais."]},{"h":"Bebedouro","p":["Que possam beber 10 a 15 % do lote ao mesmo tempo.","Uns 3 cm lineares de bebedouro por animal, ou um bebedouro redondo a cada 20 a 25 animais."]},{"h":"Sombra","p":["3 a 4 m² por animal."]},{"h":"Calculadora","p":["No Rumi, Calculadoras, Espaço de curral e cocho, calcula para as suas cabeças."]}],"rel":["Projeto de currais","Cochos","Sombra"]},{"t":"Estresse por calor","a":"manejo","r":"No trópico o calor é um inimigo diário da engorda. Um animal com calor come menos, ganha menos e adoece mais.","s":[{"h":"Como reconhecer","p":["Ofegação e respiração rápida.","Amontoam-se na sombra e no bebedouro.","Deixam de comer nas horas quentes.","Baba e cabeça esticada."]},{"h":"Medidas no curral","p":["Sombra de 3 a 4 m² por animal, alta (3 a 4 metros) e orientada para o piso secar.","Água fresca de sobra, com mais bebedouros no verão.","Cortinas ou árvores que deem vento, sem tampar a ventilação.","Aspersão ou molhar o piso em dias extremos."]},{"h":"Medidas de manejo","p":["Não trabalhe o gado depois das 9 da manhã em dias quentes.","Pese e embarque cedo ou à tarde.","Sirva mais ração no fim da tarde.","Evite mudanças de ração em ondas de calor."]},{"h":"Animais mais sensíveis","p":["Raças europeias e cruzados com mais sangue europeu.","Animais pesados e gordos na terminação.","Animais escuros.","Doentes ou recém-chegados."]}],"rel":["Golpe de calor","Sombra","Alimentação com calor","Índice de calor"]},{"t":"Época de chuvas","a":"manejo","r":"A chuva traz lama, moscas, parasitas e doenças de patas e pulmões. Preparar-se evita perdas.","s":[{"h":"Currais","p":["Revise drenos e canais antes de começarem as chuvas.","Retire o esterco com mais frequência: com água vira lama.","Montes secos para os animais descansarem.","Reduza a lotação se o curral fizer muita lama."]},{"h":"Ração","p":["Proteja cochos e depósito da chuva.","Revise o grão: a umidade traz mofo.","Não deixe ração molhada no cocho de um dia para o outro."]},{"h":"Sanidade","p":["Vigie manqueiras e podridão do casco.","Mais controle de moscas e parasitas.","Pneumonias com mudanças bruscas de temperatura."]},{"h":"Pastos","p":["Bom momento para plantar e adubar pastos.","Faça silagem e feno para a seca com o pasto que sobra."]}],"rel":["Pisos e drenagem","Mancadeiras e problemas de casco","Silagem: como fazer"]},{"t":"Época seca","a":"manejo","r":"A seca traz pouco pasto, poeira e calor. É a época de maior custo de ração, mas também de gado barato para comprar.","s":[{"h":"Preparação","p":["Tenha a forragem guardada antes de começar: silagem, feno, cana.","Calcule a ração de todos os meses secos.","Garanta água: poços, caixas e bombas revisados."]},{"h":"Manejo","p":["Molhe o piso para baixar a poeira que irrita olhos e pulmões.","Reforce sombra e bebedouros.","Vigie a ceratoconjuntivite e a pneumonia por poeira."]},{"h":"Oportunidades","p":["Muitos pecuaristas vendem animais magros na seca: você pode comprar barato se tiver comida.","Calcule no Rumi o preço máximo de compra com seus custos de seca."]}],"rel":["Ração para a época seca","Plano forrageiro para a seca","Ceratoconjuntivite ou olho rosado"]},{"t":"Quando vender","a":"manejo","r":"Vender no momento certo é tão importante quanto comprar bem. Cada dia a mais custa ração, e os últimos quilos são os mais caros.","s":[{"h":"Sinais de que está pronto","p":["Chegou ao peso meta que seu comprador pede.","Tem o acabamento de gordura buscado.","Seu ganho diário começa a cair enquanto o consumo continua alto."]},{"h":"Números","p":["Compare o custo de um dia a mais de engorda com o que valem os quilos que ganhará nesse dia.","Se o custo do quilo ganho supera o preço de venda por quilo, a cada dia você perde.","O app mostra a data estimada de chegada à meta, a margem se vender hoje e, na Análise do Rumi, o dia que mais deixa."]},{"h":"Outros fatores","p":["Preço do mercado e temporada.","Carências de medicamentos pendentes.","Capacidade de curral para o próximo lote.","Fluxo de caixa."]},{"h":"Erros comuns","p":["Esperar um preço melhor com animais que já não ganham.","Vender com carência ativa.","Vender sem pesar."]}],"rel":["Preparar a venda","Grau de acabamento","Ponto de equilíbrio"]},{"t":"Preparar a venda","a":"manejo","r":"Como se prepara o embarque muda o peso que pagam e a qualidade da carcaça.","s":[{"h":"Antes","p":["Confira no app que o lote não tem carências ativas.","Combine com o comprador o preço, a forma de pesar, a quebra e a forma de pagamento.","Prepare a guia de trânsito."]},{"h":"Jejum e quebra","p":["O comprador costuma descontar uma porcentagem pelo enchimento (quebra), comumente 3 a 5 %.","Se pesar na fazenda, combine horas de jejum ou o desconto.","Um jejum muito longo baixa o rendimento e a qualidade."]},{"h":"Embarque","p":["Cedo, com calma, sem pancadas.","Caminhão limpo e em bom estado.","Não misture animais de lotes que não se conhecem no dia da venda."]},{"h":"Registro","p":["Anote a venda no app com cabeças, quilos, preço e comprador.","Assim o app calcula a margem real do lote."]}],"rel":["Quando vender","Vender em pé ou por carcaça","Transporte de gado"]},{"t":"Engorda em confinamento","a":"manejo","r":"O animal vive no curral e toda a comida é levada a ele. É o sistema de maior ganho diário e controle, mas com mais custo e trabalho.","s":[{"h":"Vantagens","p":["Ganhos de 1,2 a 1,8 kg por dia.","Ciclos curtos: 90 a 150 dias.","Controle total da ração e da saúde.","Pouca terra para muitos animais."]},{"h":"Desvantagens","p":["Alto custo de ração.","Mais risco de acidose e doenças pela densidade.","Precisa de capital, instalações e pessoal constante.","Manejo de esterco e moscas."]},{"h":"Chaves do sucesso","p":["Boa compra e recepção.","Adaptação ao concentrado.","Leitura de cocho e horários fixos.","Registros diários e pesagens.","Venda na hora certa."]}],"rel":["Projeto de currais","Ração de terminação","Planejamento do confinamento"]},{"t":"Engorda em semiconfinamento","a":"manejo","r":"Os animais pastam parte do dia e recebem ração no curral. Combina o barato do pasto com o ganho do concentrado.","s":[{"h":"Como funciona","p":["Pastejo nas horas frescas da manhã.","Curral com sombra, água e ração à tarde e à noite.","A ração cobre o que falta no pasto."]},{"h":"Vantagens","p":["Menos custo que o confinamento completo.","Melhor ganho que só pasto.","Aproveita os pastos próprios."]},{"h":"Chaves","p":["Pastos bem manejados com rotação.","Ração com boa energia e minerais.","Horário fixo de entrada no curral.","Controle de parasitas mais frequente que no confinamento."]},{"h":"Ganhos esperados","p":["0,8 a 1,2 kg por dia com boa ração e pasto."]}],"rel":["Suplementação no pasto","Pastejo rotacionado","Engorda a pasto"]},{"t":"Engorda a pasto","a":"manejo","r":"A engorda a pasto é a mais barata por dia, mas a mais lenta. Seu sucesso depende do manejo do pasto.","s":[{"h":"Ganhos","p":["Só pasto na época de chuvas: 0,4 a 0,7 kg por dia.","Com suplemento: 0,7 a 1 kg por dia.","Na seca sem suplemento pode ser zero ou perda."]},{"h":"Chaves","p":["Pastos melhorados e bem adubados.","Rotação de pastos com descanso suficiente.","Lotação ajustada à produção de pasto.","Sal mineral sempre.","Água em cada pasto ou perto."]},{"h":"Vantagens e desvantagens","p":["Baixo custo por dia e pouca mão de obra.","Ciclos longos: 1 a 2 anos.","Mais risco de parasitas e carrapatos.","Depende do clima."]}],"rel":["Pastejo rotacionado","Lotação e amostragem de forragem","Suplementação no pasto"]},{"t":"Raças para engorda no trópico","a":"manejo","r":"No trópico a raça deve aguentar calor, carrapatos e parasitas. Os cruzamentos bem feitos combinam resistência e carne.","s":[{"h":"Zebuínas","p":["Brahman, Nelore, Gir, Guzerá, Indubrasil.","Aguentam calor e carrapato, rústicas.","Ganho moderado e carne menos macia que as europeias."]},{"h":"Europeias de corte","p":["Angus, Charolês, Simmental, Hereford.","Muita carne e boa qualidade, mas sofrem com calor e carrapato.","Melhor usadas em cruzamentos."]},{"h":"Cruzamentos e compostas","p":["Brangus, Beefmaster, Simbrasil, Canchim.","Combinam resistência tropical com carne.","São muito procuradas para confinamento."]},{"h":"Leiteiras","p":["Holandesa, Pardo-Suíça, Jersey e seus cruzamentos.","Ganham rápido com boa ração, mas rendem menos em carcaça."]},{"h":"Com o app","p":["Anote a raça de cada animal ao criar o lote.","Compare ganho e margem por raça com seus próprios números. Veja também Guia, Tabelas de referência, Raças para engorda."]}],"rel":["Comprar gado para engorda","Novilhos de leite","Estresse por calor"]},{"t":"Idade pelos dentes","a":"manejo","r":"Os dentes da frente de baixo mudam com a idade. Servem para estimar a idade na compra.","s":[{"h":"Como são","p":["O bovino só tem dentes da frente embaixo: 8 incisivos.","Os de leite são pequenos; os permanentes são largos e grandes."]},{"h":"Troca de dentes","p":["Todos de leite: menos de 18 a 20 meses.","2 permanentes (primeiro par): cerca de 2 anos.","4 permanentes: cerca de 2,5 a 3 anos.","6 permanentes: cerca de 3 a 3,5 anos.","8 permanentes (boca cheia): 4 anos ou mais.","Varia conforme a raça e a alimentação."]},{"h":"Para o confinamento","p":["Animais de 2 a 4 dentes são os mais comuns no confinamento.","Boca cheia com dentes gastos: animal velho, converte pior.","Alguns compradores pagam conforme a dentição."]}],"rel":["Comprar gado para engorda","Qualidade da carcaça"]},{"t":"Pessoal e segurança no trabalho","a":"manejo","r":"Trabalhadores bem treinados e seguros cuidam melhor do gado. Os acidentes com gado são frequentes e graves.","s":[{"h":"Treinamento","p":["Ensine a ler cochos, revisar doentes e anotar no app.","Explique o manejo tranquilo e a segurança no brete.","Escreva a rotina e os protocolos."]},{"h":"Segurança","p":["Botas, luvas e roupa adequada.","Nunca trabalhe sozinho com animais bravos.","Cuidado com químicos: luvas, máscara e leitura dos rótulos.","Kit de primeiros socorros para pessoas."]},{"h":"Saúde","p":["Vacina antitetânica para os trabalhadores.","Lavar as mãos antes de comer.","Atendimento médico se tiverem febre depois de tocar animais doentes."]},{"h":"Motivação","p":["Reconheça os bons resultados: menos doentes, bom consumo.","Compartilhar os números do lote ajuda a envolvê-los."]}],"rel":["Doenças que passam para as pessoas","Trabalho no tronco","Segurança do trabalhador"]},{"t":"Bem-estar animal","a":"manejo","r":"Um animal bem tratado produz mais e melhor carne. O bem-estar é uma exigência crescente de compradores e mercados.","s":[{"h":"As cinco liberdades","p":["Livre de fome e sede: alimento e água suficientes.","Livre de desconforto: sombra, piso seco e espaço.","Livre de dor, lesões e doença: prevenção e tratamento rápido.","Livre para expressar seu comportamento normal: espaço e companhia.","Livre de medo e angústia: manejo tranquilo."]},{"h":"Na prática","p":["Sem pancadas, gritos nem choques desnecessários.","Transporte adequado.","Atenção rápida a doentes e lesionados.","Eutanásia humanitária quando não há recuperação."]},{"h":"Benefícios","p":["Melhor ganho e menos doenças.","Carcaças com menos hematomas.","Acesso a compradores exigentes."]}],"rel":["Manejo tranquilo do gado","Bem-estar na lei e no mercado","Transporte de gado"]},{"t":"Planejamento do confinamento","a":"manejo","r":"Planejar quantos animais, quando comprá-los e quando vendê-los permite usar melhor os currais e o dinheiro.","s":[{"h":"Perguntas-chave","p":["Quantos animais cabem nos meus currais e cochos?","Quanto alimento consigo comprar e armazenar?","Quanto capital tenho para comprar e alimentar?","Quando os compradores pagam melhor?"]},{"h":"Ciclo","p":["Duração do confinamento = (peso meta − peso de entrada) ÷ ganho diário.","Exemplo: de 300 a 460 kg a 1,4 kg por dia são cerca de 115 dias.","Giros por ano = 365 ÷ (dias de confinamento + dias de limpeza entre lotes)."]},{"h":"Escalonar","p":["Comprar lotes a intervalos regulares reparte o risco de preço.","Assim sempre há um lote sendo vendido e outro entrando."]},{"h":"No app","p":["O Rumi projeta cada lote e diz quando chega à meta.","O alimento do mês diz quanto comprar."]}],"rel":["Orçamento de um lote","Capital de giro","Quando vender"]},{"t":"Animais que montam (buller)","a":"manejo","r":"Alguns animais montam um companheiro repetidas vezes. O montado se machuca, não come e pode morrer.","s":[{"h":"Sinais","p":["Um animal com o lombo e a cauda sem pelo ou machucados.","Um grupo perseguindo o mesmo animal.","Um animal montado que se esconde num canto."]},{"h":"O que fazer","p":["Leve o animal montado para outro curral.","Se for um só montador, retire ele.","Revise feridas e mancadeiras."]},{"h":"Prevenção","p":["Não misture lotes no meio do confinamento.","Espaço suficiente.","Lotes uniformes em tamanho.","Revise implantes mal aplicados com o veterinário se o problema for frequente."]}],"rel":["Inteiros ou castrados","Formar lotes","Espaço por animal"]},{"t":"Novilhos de leite","a":"manejo","r":"Os machos de raças leiteiras são baratos e ganham peso rápido com boa ração, mas é preciso manejar suas diferenças.","s":[{"h":"Vantagens","p":["Preço de compra baixo.","Bom ganho diário e conversão no curral.","Disponíveis o ano todo perto de regiões leiteiras."]},{"h":"Desvantagens","p":["Rendem menos de carcaça (menos músculo, ossos longos).","Engordam diferente e alguns compradores pagam menos.","Os Holandeses puros sofrem mais com o calor."]},{"h":"Manejo","p":["Bezerros de leite precisam de bom início e cuidado com pneumonia e diarreia.","Rações com boa energia e proteína.","Calcule sua margem com o preço real que pagam por eles."]}],"rel":["Raças para engorda no trópico","Rendimento de carcaça","Preço máximo de compra"]},{"t":"Fêmeas no confinamento","a":"manejo","r":"Novilhas e vacas de descarte também são engordadas. Têm ciclos e preços diferentes dos machos.","s":[{"h":"Novilhas","p":["Ganham um pouco menos que os machos e engordam antes.","Podem estar prenhes: examine na compra.","O cio interrompe o consumo e causa montas."]},{"h":"Vacas de descarte","p":["Engorda curta de 60 a 90 dias para melhorar sua condição e seu preço.","Revise dentes, úbere, patas e prenhez.","Podem trazer brucelose ou tuberculose: compre com controle."]},{"h":"Manejo","p":["Lotes separados dos machos.","Ração de terminação curta e bem adaptada.","Anote o tipo no app para comparar a margem."]}],"rel":["Brucelose e tuberculose","Formar lotes","Grau de acabamento"]},{"t":"Segurança e roubo de gado","a":"manejo","r":"O abigeato (roubo de gado) causa grandes perdas. A identificação e os registros ajudam a prevenir e recuperar.","s":[{"h":"Prevenção","p":["Marca registrada e brincos em todos os animais.","Fotos dos animais no app.","Contagens frequentes, anotadas.","Cercas e porteiras em bom estado, com cadeado.","Iluminação nos currais perto de estradas."]},{"h":"Se acontecer","p":["Denuncie imediatamente à polícia e às autoridades pecuárias.","Apresente registros, fotos e guias.","Avise vizinhos e frigoríficos da região."]},{"h":"Compras","p":["Não compre animais sem guia de trânsito nem marca clara.","Comprar gado roubado também é crime."]}],"rel":["Identificação de animais","Guia de trânsito e rastreabilidade","Registro de marca e fazenda"]},{"t":"Desmame e pré-condicionamento","a":"manejo","r":"Os bezerros desmamados e preparados antes da venda chegam ao confinamento mais saudáveis e ganham desde o primeiro dia.","s":[{"h":"O que é pré-condicionar","p":["Desmamar 30 a 45 dias antes da venda.","Vacinar e dar reforços na fazenda de origem.","Acostumar ao cocho e ao bebedouro.","Castrar e descornar cedo, se for feito."]},{"h":"Vantagens para o confinador","p":["Menos pneumonias e mortes na recepção.","Começam a comer rápido.","Vale a pena pagar um pouco mais por animais pré-condicionados."]},{"h":"Perguntas ao vendedor","p":["Quando foram desmamados?","Quais vacinas e reforços têm?","Comem concentrado?"]}],"rel":["Comprar gado para engorda","Recepção de gado","Pneumonia ou complexo respiratório"]},{"t":"Checklist dos primeiros dias","a":"manejo","r":"Uma lista curta para não esquecer nada importante quando entra um lote novo.","s":[{"h":"Antes de chegarem","p":["Curral de recepção limpo, com sombra, água e feno.","Vacinas, vermífugos e equipamento prontos.","Brincos e o app prontos para criar o lote.","Ração inicial preparada."]},{"h":"Na chegada","p":["Contar, revisar a guia e os animais.","Água, feno e descanso.","Separar doentes e lesionados."]},{"h":"Dia 1 ou 2","p":["Pesar, colocar brinco, foto.","Plano sanitário de entrada.","Criar o lote no app com raça, cor e preço."]},{"h":"Semanas 1 a 3","p":["Revisar duas vezes ao dia.","Adaptar ao concentrado.","Anotar tratamentos e alimento.","Reforços de vacina aos 21 a 30 dias."]}],"rel":["Recepção de gado","Plano sanitário de entrada","Criar um lote no app"]},{"t":"Contar o gado","a":"manejo","r":"Contar com frequência detecta roubos, animais fugidos ou mortos que não foram vistos.","s":[{"h":"Como contar","p":["Faça os animais passarem por uma porteira ou pelo brete e conte um por um.","Conte em grupos de cinco para não se perder.","Duas pessoas contam separadamente e comparam."]},{"h":"Quando","p":["Ao entrar e sair da fazenda.","Em cada pesagem.","Toda semana em pastos grandes."]},{"h":"Se faltar um","p":["Revise cercas, grotas e pastos vizinhos.","Compare com a lista de brincos do app.","Se não aparecer, denuncie."]}],"rel":["Segurança e roubo de gado","Identificação de animais"]},{"t":"Animais bravos","a":"manejo","r":"Alguns animais são nervosos ou agressivos. São perigosos, se estressam mais e ganham menos.","s":[{"h":"Por quê","p":["Genética e temperamento.","Más experiências com pessoas.","Isolamento do grupo."]},{"h":"Como manejá-los","p":["Nunca sozinho: sempre duas pessoas.","Mova-os com o grupo.","Brete em bom estado e sem distrações.","Sem gritos nem pancadas: pioram o comportamento."]},{"h":"Decisão","p":["Se um animal põe as pessoas em risco, venda-o.","Na compra, evite animais que pulam ou atacam no brete."]}],"rel":["Manejo tranquilo do gado","Pessoal e segurança no trabalho"]},{"t":"Iluminação e horários do curral","a":"manejo","r":"Luz suave à noite e horários estáveis ajudam os animais a comer tranquilos e a vigiar.","s":[{"h":"Luz","p":["Uma luz fraca nos currais permite que comam à noite com calor e ajuda a vigiar.","Evite luzes que ofusquem no brete: o gado não avança em direção a uma luz forte de frente."]},{"h":"Horários","p":["Mesmos horários de comida e manejo todos os dias.","Trabalho de brete cedo.","Evite barulhos fortes à noite."]}],"rel":["Horários de alimentação","Estresse por calor","Segurança e roubo de gado"]},{"t":"Planejar o embarque","a":"manejo","r":"O dia da venda se prepara com dias de antecedência para evitar perdas e aborrecimentos.","s":[{"h":"Uma semana antes","p":["Revise no app as carências e os pesos.","Confirme comprador, preço, data e transporte.","Solicite a guia de trânsito."]},{"h":"O dia anterior","p":["Ajuste a ração: não mude de repente.","Jejum combinado com o comprador.","Prepare o brete e o embarcadouro."]},{"h":"O dia","p":["Embarque cedo e tranquilo.","Pesagem onde foi combinado.","Anote a venda no app."]}],"rel":["Preparar a venda","Transporte de gado","Registrar uma venda"]},{"t":"Confinar na seca ou nas chuvas","a":"manejo","r":"A época muda o custo do alimento, o preço do gado e a saúde do lote.","s":[{"h":"Época seca","p":["Gado magro mais barato.","Forragem escassa e cara.","Mais calor e poeira: cuidado com a ceratoconjuntivite e a pneumonia."]},{"h":"Época das chuvas","p":["Pasto abundante, gado mais caro.","Barro, moscas e problemas de cascos.","Bom momento para fazer silagem."]},{"h":"Como decidir","p":["Faça o orçamento com os preços da época.","Compare com seus lotes anteriores no app.","Escalone para não depender de uma só época."]}],"rel":["Época seca","Época de chuvas","Sazonalidade de preços"]},{"t":"Dicas para começar um confinamento","a":"manejo","r":"Começar pequeno, com números claros e bom manejo, é a forma mais segura de crescer.","s":[{"h":"Antes de comprar","p":["Curral com sombra, água e cocho prontos.","Ração e alimento garantidos.","Plano sanitário com um veterinário.","Orçamento do lote e preço máximo de compra."]},{"h":"Primeiro lote","p":["Um lote que você consiga manejar bem (por exemplo, 10 a 30 animais).","Animais uniformes e de uma só origem.","Anote tudo no app desde o primeiro dia."]},{"h":"Depois do primeiro lote","p":["Revise ganho, conversão, custo por quilo e margem.","Corrija o que deu errado antes de crescer.","Aumente aos poucos."]}],"rel":["Comprar gado para engorda","Orçamento de um lote","Engorda em confinamento"]},{"t":"Misturar lotes","a":"manejo","r":"Juntar animais de origens diferentes provoca brigas por hierarquia durante vários dias, mais estresse e mais doenças. Há formas de fazer isso com menos dano.","s":[{"h":"O que acontece","p":["Os animais brigam até definir quem manda.","Os mais fracos comem menos.","Micróbios de fazendas diferentes são compartilhados."]},{"h":"Como fazer melhor","p":["Misturar só no início, não no meio do confinamento.","Juntar animais de peso e tamanho parecidos.","Dar espaço suficiente e vários pontos de comida e água.","Misturar ao entardecer, com a comida servida."]},{"h":"Evitar","p":["Colocar animais novos num lote de touros inteiros.","Misturar lotes logo antes de embarcar para o frigorífico."]}],"rel":["Formar lotes","Comportamento natural do gado","Carne escura (corte escuro, DFD)"]},{"t":"Primeiros 30 dias do lote","a":"manejo","r":"O primeiro mês é quando mais animais adoecem e morrem. Um plano claro para esses dias faz diferença em todo o confinamento.","s":[{"h":"Dia 0 a 3","p":["Água limpa e forragem de qualidade na chegada.","Descanso antes de trabalhar no brete, se possível.","Revisão visual de cada animal: nariz, olhos, respiração, patas."]},{"h":"Semana 1 a 2","p":["Plano sanitário: vacinas, vermifugação, vitaminas.","Começar o concentrado aos poucos.","Revisar duas vezes ao dia e separar os abatidos."]},{"h":"Semana 3 a 4","p":["Reforço de vacinas.","Primeira pesagem de controle.","Ajustar a ração conforme o consumo."]},{"h":"No seu confinamento","p":["O app cria tarefas na agenda para esses dias quando você registra um lote novo."]}],"rel":["Recepção de gado","Checklist dos primeiros dias","Plano sanitário de entrada","Agenda de tarefas"]},{"t":"Registrar e aprender com as mortes","a":"manejo","r":"Cada morte é uma perda, mas também uma lição. Registrar a causa, a data e o lote permite encontrar padrões e evitar que se repita.","s":[{"h":"O que anotar","p":["Data, lote e brinco.","Dias desde a chegada.","Sinais prévios e tratamentos.","Resultado da necropsia, se foi feita."]},{"h":"O que procurar","p":["Mortes concentradas nos primeiros 30 dias: problema de recepção.","Mortes no final do confinamento: acidose, timpanismo ou calor.","Várias mortes da mesma origem: revise o fornecedor."]},{"h":"No seu confinamento","p":["O app calcula sua mortalidade por lote e o custo."]}],"rel":["Mortalidade","Morte de um animal","Mortalidade e seu custo","Registrar uma morte"]},{"t":"Animais de leilão","a":"manejo","r":"O gado de leilão costuma vir de várias origens, com mais estresse e mais contato com doenças. Precisa de um manejo de entrada mais cuidadoso.","s":[{"h":"Riscos","p":["Mistura de micróbios de muitas fazendas.","Horas sem água nem comida.","Histórico sanitário desconhecido."]},{"h":"Como recebê-los","p":["Quarentena separada dos seus outros lotes.","Plano sanitário completo na entrada.","Vigilância rigorosa de doenças respiratórias nas primeiras 3 semanas."]},{"h":"No seu confinamento","p":["Pague um pouco menos por eles para cobrir o risco maior.","Compare no app a mortalidade e o ganho de lotes de leilão contra lotes de fazenda."]}],"rel":["Comprar em leilão ou feira","Quarentena e biossegurança","Metafilaxia na entrada"]},{"t":"Confinamento com touros inteiros","a":"manejo","r":"Confinar touros inteiros aproveita seu maior crescimento e conversão, mas exige mais cuidado no manejo e na venda.","s":[{"h":"Vantagens","p":["Ganham de 5 a 15 % mais rápido.","Convertem melhor e fazem mais músculo.","Você economiza a castração e seu risco."]},{"h":"Desvantagens","p":["Montas, brigas e pancadas.","Mais risco de carne escura.","Alguns compradores pagam menos ou preferem castrados."]},{"h":"Como manejá-los","p":["Lotes fechados: não acrescente animais novos.","Longe das fêmeas.","Abate antes que fiquem muito maduros (menos de 24 meses).","Embarque sem misturar com outros lotes."]}],"rel":["Inteiros ou castrados","Animais que montam (buller)","Carne escura (corte escuro, DFD)"]},{"t":"Manejo em chuvas intensas","a":"manejo","r":"As chuvas fortes enchem os currais de barro, aumentam mancadeiras, doenças de pele e parasitas, e baixam o ganho.","s":[{"h":"Preparação","p":["Drenos limpos antes de começarem as chuvas.","Montes ou áreas altas e secas para deitar.","Telhado ou proteção para o alimento."]},{"h":"Durante","p":["Retire o barro de cochos e bebedouros.","Menos animais por curral.","Revise patas e pele toda semana."]},{"h":"Depois","p":["Vermifugação conforme exames.","Controle de moscas e carrapatos, que aumentam."]}],"rel":["Época de chuvas","Pisos e drenagem","Mancadeiras e problemas de casco"]},{"t":"Segurança ao trabalhar com gado","a":"manejo","r":"Coices, chifradas, esmagamentos e quedas são acidentes comuns. Com boas instalações e bons hábitos quase todos são evitados.","s":[{"h":"Regras básicas","p":["Nunca fique entre um animal e a parede sem saída.","Tenha sempre uma rota de fuga no brete e no curral.","Trabalhe com outra pessoa, não sozinho.","Cuidado com vacas com cria e com touros."]},{"h":"Equipamento","p":["Botas com biqueira e roupa que não enrosque.","Luvas ao aplicar medicamentos.","Agulhas descartadas em recipiente rígido."]}],"rel":["Pessoal e segurança no trabalho","Tronco, brete e funil","Segurança do trabalhador"]},{"t":"Plano de contingência","a":"manejo","r":"Ter um plano para seca, enchente, surto de doença ou queda de preços evita decisões de pânico.","s":[{"h":"O que incluir","p":["Reserva de forragem e água.","Contato de veterinário, comprador alternativo e transporte.","Reserva de dinheiro ou crédito aprovado.","Lista de animais que se vendem primeiro, se necessário."]},{"h":"No seu confinamento","p":["Revise o plano antes de cada época seca e de chuvas.","Veja a previsão e o clima no Rumi."]}],"rel":["Riscos do confinamento","El Niño, La Niña e o Corredor Seco","Planejamento do confinamento"]},{"t":"Engorda com capim de corte e melaço com ureia","a":"manejo","r":"É uma engorda muito comum em fazendas pequenas: capim de corte picado à vontade, melaço com ureia e um pouco de concentrado. Bem feita, consegue 0,7 a 1 kg por dia.","s":[{"h":"A base","p":["Capim de corte novo picado, 30 a 40 kg por animal por dia (conforme o peso).","Melaço com 2 a 3 % de ureia, 1 a 2 kg por animal.","Sal mineral à vontade."]},{"h":"Para ganhar mais","p":["Acrescentar 1 a 3 kg de concentrado ou milho quebrado.","Uma fonte de proteína verdadeira como farelo de soja, palmiste ou caroço de algodão."]},{"h":"Cuidados","p":["Adaptar à ureia em 10 a 15 dias; nunca dar ureia a animais famintos.","Misturar muito bem a ureia no melaço.","Cortar o capim na idade certa."]}],"rel":["Suplemento de melaço e ureia","Capins de corte Pennisetum","Engorda em semiconfinamento","Intoxicação por ureia"]},{"t":"Confinamento curto intensivo","a":"manejo","r":"O confinamento curto de 90 a 120 dias compra animais pesados (320 a 380 kg) e os termina no curral com ração de alta energia. Dá muitos giros por ano com menos risco por lote.","s":[{"h":"Como funciona","p":["Adaptação ao concentrado em 2 a 3 semanas.","Ração de terminação com 70 a 85 % de concentrado.","Ganhos de 1,2 a 1,6 kg por dia."]},{"h":"Chaves","p":["Comprar a bom preço: a margem de compra e venda pesa muito.","Ração com custo controlado.","Vender assim que estiverem terminados: os dias extras custam caro."]},{"h":"No seu confinamento","p":["Antes de comprar, calcule com o Rumi o preço máximo de compra e os dias até a meta."]}],"rel":["Engorda em confinamento","Ração de terminação","Preço máximo de compra","Giros por ano"]},{"t":"Quanto concentrado dar no pasto","a":"manejo","r":"Suplementar com concentrado no pasto aumenta o ganho. A quantidade depende da qualidade do pasto e da meta de ganho.","s":[{"h":"Referências","p":["0,3 a 0,5 % do peso: suplemento proteico ou energético leve; aumenta 150 a 300 g por dia.","0,5 a 1 % do peso: engorda a pasto com bom ganho (0,8 a 1 kg por dia).","Mais de 1 % do peso: o animal deixa de comer pasto e fica parecido com um confinamento."]},{"h":"O que dar","p":["Pasto pobre ou seco: priorizar proteína.","Pasto bom das chuvas: priorizar energia (milho, melaço)."]},{"h":"Cuidados","p":["Cochos com espaço para que todos comam ao mesmo tempo.","Mesmo horário todos os dias."]}],"rel":["Suplementação no pasto","Engorda a pasto","Energia das forragens tropicais"]},{"t":"Vender o lote por partes","a":"manejo","r":"Os animais de um lote não chegam à meta ao mesmo tempo. Vender primeiro os mais pesados e terminados e deixar os demais algumas semanas a mais melhora o preço e o uso do curral.","s":[{"h":"Como fazer","p":["Pese o lote inteiro e ordene por peso.","Venda os que já chegaram à meta e ao acabamento.","Os demais seguem até a próxima pesagem."]},{"h":"Vantagens","p":["Você não dá de graça quilos dos pesados nem vende magros os leves.","Libera espaço para outro lote."]},{"h":"No seu confinamento","p":["No app, em cada lote, você pode ordenar os animais por peso.","Registre a venda parcial e o lote segue com os que ficaram."]}],"rel":["Quando vender","Registrar uma venda","Uniformidade do lote"]},{"t":"Horários de trabalho conforme o clima","a":"manejo","r":"Trabalhar o gado nas horas frescas reduz o estresse, as perdas de peso e os acidentes.","s":[{"h":"Regras","p":["Brete, vacinas, pesagens e embarques: antes das 9 da manhã ou depois das 4 da tarde.","Nunca trabalhe o gado com ITU em perigo ou emergência.","Se for preciso, trabalhe lotes pequenos e rápido."]},{"h":"No seu confinamento","p":["Veja no Rumi o clima de hoje antes de planejar trabalhos no brete."]}],"rel":["Estresse por calor","Trabalho no tronco","Índice de temperatura e umidade (ITU)"]},{"t":"Classificar por peso na entrada","a":"manejo","r":"Separar os animais por peso na chegada forma lotes mais uniformes que comem melhor e saem juntos.","s":[{"h":"Como","p":["Pese todos na entrada.","Forme grupos com no máximo 30 a 40 kg de diferença.","Os muito leves ou atrasados vão para um curral à parte com mais atenção."]},{"h":"Benefícios","p":["Menos brigas e competição no cocho.","Ração ajustada a cada grupo.","Vendas mais organizadas."]}],"rel":["Formar lotes","Uniformidade do lote","Pesagem"]},{"t":"Fotos dos animais","a":"manejo","r":"Tirar uma foto de cada animal na chegada ajuda a identificá-lo, comparar sua mudança e tirar dúvidas se um brinco se perder.","s":[{"h":"Dicas","p":["Foto de lado, com o animal em pé e boa luz.","Que apareçam o brinco e as marcas ou manchas.","Repetir a foto no meio e no final do confinamento para ver a mudança."]},{"h":"No app","p":["Ao registrar cada animal você pode tirar a foto com a câmera principal.","As fotos ficam no seu celular e não gastam internet."]}],"rel":["Animais e fotos","Identificação de animais"]},{"t":"Compras conforme a época","a":"manejo","r":"O preço do gado e da comida muda com as épocas. Comprar no momento certo melhora a margem.","s":[{"h":"Padrões comuns na América Central","p":["Na seca muitos vendem por falta de pasto: o bezerro pode baixar de preço.","No início das chuvas todos querem comprar: o preço sobe.","O novilho gordo costuma pagar melhor quando há menos oferta, muitas vezes no fim da seca."]},{"h":"No seu confinamento","p":["Se você tem comida guardada, comprar na seca e vender na escassez pode dar boa margem.","Revise seus próprios registros de preços ano a ano."]}],"rel":["Sazonalidade de preços","Época seca","Plano forrageiro para a seca"]},{"t":"Como se ganha dinheiro no confinamento","a":"negocio","r":"O confinamento ganha em dois lugares: nos quilos que você produz a um custo menor do que lhe pagam, e na diferença de preço entre comprar e vender.","s":[{"h":"As três alavancas","p":["Comprar bem: bom animal a bom preço por quilo.","Produzir barato: boa conversão, poucas mortes, ração ao menor custo.","Vender bem: no peso e acabamento certos, ao melhor comprador e no bom momento."]},{"h":"Margem de produção","p":["Cada quilo que o animal ganha vale o preço de venda.","Se produzir esse quilo custa menos, você ganha em cada quilo.","Exemplo: você vende a 60 o quilo e produzir custa 45: ganha 15 por quilo ganho."]},{"h":"Margem de preço","p":["Muitas vezes o quilo do animal magro é comprado mais caro que o do gordo.","Essa diferença negativa é paga com os quilos produzidos.","Por isso comprar bem importa tanto."]},{"h":"Fórmula simples","p":["Margem = (peso de venda × preço de venda) − (peso de compra × preço de compra) − custos de alimento, sanidade, mão de obra e outros."]}],"rel":["Custo por quilo ganho","Preço máximo de compra","Margem de compra e venda"]},{"t":"Estrutura de custos","a":"negocio","r":"Saber quanto pesa cada custo mostra onde está a maior oportunidade de economia.","s":[{"h":"Custos típicos do confinamento","p":["Compra do animal: 60 a 75 % do custo total.","Alimento: 20 a 30 %.","Sanidade: 1 a 3 %.","Mão de obra: 2 a 5 %.","Frete, comissões, energia, manutenção e outros: o resto."]},{"h":"Custos variáveis e fixos","p":["Variáveis: mudam com o número de animais (compra, alimento, medicamentos).","Fixos: pagam-se igual com muitos ou poucos (salários fixos, instalações, vigilância).","Com mais animais, o custo fixo por cabeça baixa."]},{"h":"Custos escondidos","p":["Mortes: perde-se a compra e tudo o que comeu.","Desperdício de alimento.","Dias a mais no curral.","Juros do capital investido."]},{"h":"No app","p":["Anote todos os gastos, também os gerais, para que o custo seja real.","Os gráficos mostram para onde vai o dinheiro."]}],"rel":["Custo por quilo ganho","Escala do confinamento","Mortalidade e seu custo"]},{"t":"Custo por quilo ganho","a":"negocio","r":"É quanto custa produzir cada quilo que o animal ganha. Compará-lo com o preço de venda diz se o confinamento dá dinheiro.","s":[{"h":"Como se calcula","p":["Custo por quilo ganho = (alimento + sanidade + mão de obra + outros gastos do período) ÷ quilos ganhos.","Não inclui a compra do animal.","Só alimento: custo do quilo da mistura × conversão."]},{"h":"Exemplo","p":["Mistura a 8 por quilo e conversão de 7 para 1: 56 de alimento por quilo ganho.","Mais 6 de outros custos: 62 por quilo ganho.","Se você vende a 60 o quilo, cada quilo produzido perde 2."]},{"h":"Como baixá-lo","p":["Melhorar a conversão (ração, sanidade, desperdício).","Baixar o custo da mistura.","Reduzir mortes.","Vender antes que os quilos fiquem caros."]},{"h":"No app","p":["É calculado por lote com o alimento e os gastos que você anota.","Aparece em Hoje, em cada lote e em Gráficos."]}],"rel":["Conversão alimentar","Custo da ração","Ponto de equilíbrio"]},{"t":"Ponto de equilíbrio","a":"negocio","r":"É o preço de venda com o qual você não ganha nem perde. Sabê-lo antes de vender lhe dá poder para negociar.","s":[{"h":"Como se calcula","p":["Preço de equilíbrio = custo total do lote ÷ quilos vendidos.","O custo total inclui compra, frete, alimento, sanidade, mão de obra, mortes e gastos.","Considere a quebra: pagam menos quilos do que você pesa na fazenda."]},{"h":"Exemplo","p":["Custo total 500.000 e você vende 10.000 kg: equilíbrio de 50 por quilo.","Se oferecem 48, você perde 20.000.","Se oferecem 55, você ganha 50.000."]},{"h":"Usos","p":["Saber seu preço mínimo antes de negociar.","Decidir se vale a pena esperar ou vender já.","Comparar compradores."]},{"h":"No app","p":["Menu do Rumi, Dinheiro e vendas, Preço mínimo para não perder: calcula por lote vendendo na meta."]}],"rel":["Preço máximo de compra","Quando vender","Negociar com o comprador"]},{"t":"Preço máximo de compra","a":"negocio","r":"Antes de comprar, calcule quanto pode pagar no máximo sem perder. É a ferramenta mais importante para comprar bem.","s":[{"h":"O que você precisa","p":["Peso de compra e peso de venda esperado.","Preço de venda esperado por quilo.","Seu custo por quilo ganho.","Outros custos por cabeça: frete, sanidade, comissões, mortes esperadas.","A margem que você quer ganhar por cabeça."]},{"h":"Fórmula","p":["Valor de venda = peso de venda × preço de venda (com quebra).","Custo de engordar = (peso de venda − peso de compra) × custo por quilo ganho + outros custos.","Máximo a pagar por animal = valor de venda − custo de engordar − margem desejada.","Máximo por quilo = máximo por animal ÷ peso de compra."]},{"h":"Exemplo","p":["Compra 300 kg, venda 460 kg a 60: vale 27.600.","Ganhar 160 kg a 45 = 7.200, mais 800 de outros: 8.000.","Você quer ganhar 1.500: máximo 27.600 − 8.000 − 1.500 = 18.100 por animal, cerca de 60 por quilo."]},{"h":"No app","p":["Menu do Rumi, Dinheiro e vendas, Preço máximo de compra: coloque o peso e use seus custos reais."]}],"rel":["Comprar gado para engorda","Ponto de equilíbrio","Custo por quilo ganho"]},{"t":"Margem de compra e venda","a":"negocio","r":"A diferença entre o preço por quilo de compra e o de venda pode ajudar ou tirar muita margem.","s":[{"h":"Como funciona","p":["Os animais magros e leves costumam custar mais por quilo que os gordos.","Você paga mais por cada quilo que compra do que recebe por cada quilo que vende.","Essa diferença multiplicada pelo peso de compra é uma perda que os quilos produzidos devem pagar."]},{"h":"Exemplo","p":["Você compra 300 kg a 64 e vende 460 kg a 60.","Perde 4 por quilo nos 300 kg comprados: 1.200 por animal.","Os 160 kg ganhos devem deixar mais de 1.200 para o negócio valer."]},{"h":"Como manejá-lo","p":["Compre em épocas em que o gado magro está barato (início da seca em muitas regiões).","Compre animais um pouco mais pesados se o diferencial for muito alto.","Negocie por quilo, nunca por cabeça no olho."]}],"rel":["Como se ganha dinheiro no confinamento","Sazonalidade de preços","Preço máximo de compra"]},{"t":"Orçamento de um lote","a":"negocio","r":"Antes de comprar um lote, faça o orçamento completo. Ele diz se vale a pena e quanto dinheiro você precisa.","s":[{"h":"Receitas esperadas","p":["Cabeças que você espera vender (descontando as mortes esperadas).","Peso de venda com quebra.","Preço de venda esperado."]},{"h":"Custos","p":["Compra, frete e comissões.","Alimento: quilos por dia × dias × custo por quilo.","Sanidade de entrada e tratamentos.","Mão de obra e gastos gerais proporcionais.","Juros se você usa crédito."]},{"h":"Resultado","p":["Margem total e por cabeça.","Preço de equilíbrio de venda.","Capital máximo que você precisa e quando."]},{"h":"Cenários","p":["Calcule também com preço de venda 5 a 10 % mais baixo.","E com ganho diário menor que o esperado.","Se no cenário ruim você perde muito, pense duas vezes."]}],"rel":["Capital de giro","Riscos do confinamento","Planejamento do confinamento"]},{"t":"Capital de giro","a":"negocio","r":"O confinamento precisa de dinheiro para comprar e alimentar meses antes de receber. Ficar sem caixa no meio do confinamento sai muito caro.","s":[{"h":"Quanto você precisa","p":["A compra completa do lote no início.","O alimento e os gastos de todos os dias até a venda.","Uma reserva de 10 a 15 % para imprevistos."]},{"h":"Fluxo de caixa","p":["Anote quando o dinheiro sai e quando entra.","As vendas escalonadas de lotes ajudam a ter receitas mais seguidas.","Negocie prazos com fornecedores de alimento."]},{"h":"Erros comuns","p":["Comprar todo o gado sem ter o alimento garantido.","Vender às pressas por falta de caixa, com animais que ainda não estão prontos.","Misturar o dinheiro do confinamento com os gastos da casa."]}],"rel":["Financiamento e crédito","Orçamento de um lote","Planejamento do confinamento"]},{"t":"Financiamento e crédito","a":"negocio","r":"Um crédito pode fazer o confinamento crescer se a margem pagar os juros com folga.","s":[{"h":"Antes de pedir","p":["Faça o orçamento do lote com os juros incluídos.","Compare a taxa com sua margem esperada.","Revise o prazo: deve coincidir com a venda, não antes."]},{"h":"Custo do dinheiro","p":["Juros = valor × taxa anual × dias ÷ 365.","Exemplo: 500.000 a 18 % ao ano por 120 dias = cerca de 29.600.","Esse custo se soma ao custo por cabeça."]},{"h":"Fontes","p":["Bancos e cooperativas com linhas pecuárias.","Fornecedores de alimento com crédito.","Esquemas de engorda em parceria ou por serviço."]},{"h":"Com o app","p":["Baixe seus dados para Excel para mostrar seu histórico ao banco."]}],"rel":["Capital de giro","Riscos do confinamento","Engorda em parceria ou por serviço"]},{"t":"Riscos do confinamento","a":"negocio","r":"O confinamento tem riscos de preço, de produção e sanitários. Conhecê-los permite reduzi-los.","s":[{"h":"Risco de preço","p":["Queda do preço de venda durante o confinamento.","Alta do preço do alimento.","Redução: compras escalonadas, contratos com compradores, compra antecipada de grão."]},{"h":"Risco de produção","p":["Ganho menor que o esperado.","Seca que encarece a forragem.","Redução: boa ração, plano forrageiro, registros para detectar problemas cedo."]},{"h":"Risco sanitário","p":["Surtos de pneumonia, mortes.","Redução: compra cuidadosa, recepção, vacinas, quarentena."]},{"h":"Outros riscos","p":["Roubo, acidentes, mudanças na lei.","Não apostar tudo num só lote nem num só comprador."]}],"rel":["Orçamento de um lote","Sazonalidade de preços","Mortalidade e seu custo"]},{"t":"Canais de venda","a":"negocio","r":"A quem você vende muda o preço, a forma de pagamento e os requisitos.","s":[{"h":"Intermediário ou comprador na fazenda","p":["Cômodo: busca na fazenda.","Costuma pagar menos e às vezes no olho.","Negocie sempre com balança."]},{"h":"Leilão","p":["Preço pela concorrência do dia.","Custos de comissão e transporte.","Risco de preços baixos se houver muito gado nesse dia."]},{"h":"Frigorífico ou matadouro","p":["Pagamento por carcaça ou em pé com regras claras.","Exigem rastreabilidade, sem resíduos e animais dentro da faixa de peso e acabamento.","Podem pagar prêmios por qualidade."]},{"h":"Açougues e venda direta","p":["Melhor preço se você tiver clientes fixos.","É preciso abater em matadouro autorizado e cumprir as normas sanitárias."]}],"rel":["Vender em pé ou por carcaça","Negociar com o comprador","Qualidade da carcaça"]},{"t":"Vender em pé ou por carcaça","a":"negocio","r":"Em pé, pagam pelo animal vivo; por carcaça, pela carne com osso depois do abate. Comparar bem evita perder dinheiro.","s":[{"h":"Em pé","p":["Pagamento por quilo vivo, normalmente com desconto de quebra.","Você sabe o resultado no mesmo dia.","O risco de rendimento fica com o comprador."]},{"h":"Por carcaça","p":["Pagamento por quilo de carcaça quente ou fria.","A carcaça pesa 54 a 58 % do peso vivo em novilhos de confinamento bem terminados.","Convém se seus animais rendem bem (bom músculo e acabamento)."]},{"h":"Como comparar","p":["Preço por carcaça × rendimento = preço equivalente em pé.","Exemplo: 110 por quilo de carcaça × 0,56 = 61,6 por quilo vivo.","Compare com a oferta em pé depois da quebra."]},{"h":"Calculadora","p":["Menu do Rumi, Calculadoras, Comparar em pé e carcaça."]}],"rel":["Rendimento de carcaça","Qualidade da carcaça","Quebra (desbaste)"]},{"t":"Negociar com o comprador","a":"negocio","r":"Chegar à negociação com seus números claros muda o resultado.","s":[{"h":"Antes","p":["Conheça seu preço de equilíbrio.","Conheça o peso real do lote (pesado na balança).","Pesquise preços de outros compradores e do leilão."]},{"h":"O que combinar","p":["Preço por quilo e onde se pesa.","Porcentagem de quebra ou horas de jejum.","Descontos por pancadas, peso fora da faixa ou animais doentes.","Data e forma de pagamento.","Quem paga o frete."]},{"h":"Regras","p":["Coloque tudo por escrito, mesmo que seja numa mensagem.","Não venda no olho.","Tenha mais de um comprador para comparar."]}],"rel":["Ponto de equilíbrio","Preparar a venda","Canais de venda"]},{"t":"Qualidade da carcaça","a":"negocio","r":"A qualidade da carcaça define o preço nos frigoríficos que classificam. Ela se constrói durante todo o confinamento.","s":[{"h":"O que avaliam","p":["Peso da carcaça.","Conformação: quantidade e forma do músculo.","Cobertura de gordura.","Idade pela dentição.","Cor da carne e da gordura.","Hematomas, abscessos e lesões."]},{"h":"Como melhorá-la","p":["Boa genética e animais jovens.","Ração de terminação com acabamento correto.","Injeções no pescoço, nunca na perna.","Manejo tranquilo na fazenda, no transporte e no embarque.","Jejum e transporte adequados antes do abate."]},{"h":"Peça retorno","p":["Solicite ao frigorífico os dados de carcaça e condenações do seu lote.","Anote no app junto com a venda para aprender."]}],"rel":["Rendimento de carcaça","Grau de acabamento","Aplicação de injeções"]},{"t":"Sazonalidade de preços","a":"negocio","r":"Os preços do gado e do alimento sobem e descem em certas épocas. Aproveitar isso melhora a margem.","s":[{"h":"Padrões comuns","p":["Na seca muitos pecuaristas vendem animais magros: costumam baixar de preço.","O grão costuma estar mais barato na colheita.","A demanda de carne sobe em certas festas e no fim do ano."]},{"h":"Como aproveitar","p":["Compre animais quando estão baratos se tiver alimento garantido.","Planeje vender quando os preços costumam subir.","Compre grão na colheita se tiver bom armazém."]},{"h":"Registre seus preços","p":["Anote os preços de compra e venda no app.","Com os anos você verá o padrão da sua região."]}],"rel":["Margem de compra e venda","Planejamento do confinamento","Riscos do confinamento"]},{"t":"Registros econômicos","a":"negocio","r":"Levar as contas de cada lote diz o que funciona e o que não. Sem contas, se decide às cegas.","s":[{"h":"Por lote","p":["Compra: cabeças, quilos, preço, frete.","Alimento: quilos e custo.","Sanidade e gastos do lote.","Venda: cabeças, quilos, preço.","Margem total e por cabeça."]},{"h":"Gerais","p":["Salários, energia, manutenção, juros.","São repartidos entre os lotes conforme os dias e as cabeças."]},{"h":"Análise","p":["Compare lotes: ganho, conversão, custo por quilo, margem.","Compare fornecedores, raças, rações e épocas.","Procure o lote que mais ganhou e copie o que você fez."]},{"h":"No app","p":["Tudo o que você anota gera esses números sozinho.","Baixe para Excel para análises mais detalhadas."]}],"rel":["Registros e rastreabilidade","Indicadores-chave do confinamento","Como o app usa seus dados"]},{"t":"Mortalidade e seu custo","a":"negocio","r":"Cada animal morto leva o que custou mais tudo o que comeu. A mortalidade é dos custos mais caros e mais evitáveis.","s":[{"h":"Quanto custa","p":["Preço de compra + frete + alimento consumido + tratamentos.","Um animal que morre no meio do confinamento pode custar mais que seu preço de compra."]},{"h":"Referências","p":["Confinamento bem manejado: menos de 1 a 2 %.","Mais de 3 % indica um problema sério de compra, recepção ou sanidade."]},{"h":"Como baixá-la","p":["Compra cuidadosa.","Recepção e plano sanitário de entrada.","Revisão diária e tratamento precoce.","Adaptação ao concentrado.","Necropsias para aprender com cada morte."]},{"h":"No app","p":["Anote cada morte com sua causa.","O app calcula a mortalidade por lote e o custo na margem."]}],"rel":["Morte de um animal","Plano sanitário de entrada","Estrutura de custos"]},{"t":"Escala do confinamento","a":"negocio","r":"Com mais animais, os custos fixos se repartem melhor. Mas crescer sem controle multiplica os erros.","s":[{"h":"Vantagens de crescer","p":["Menos custo fixo por cabeça.","Melhor poder de compra de alimento e gado.","Mais interesse de compradores grandes."]},{"h":"Riscos","p":["Mais capital em risco.","Precisa de mais pessoal treinado e melhor organização.","Problemas sanitários afetam mais animais."]},{"h":"Como crescer","p":["Primeiro domine os números com lotes pequenos.","Cresça por etapas, preenchendo a capacidade do que já tem.","Invista no que mais rende: balança, água, sombra, cochos."]}],"rel":["Estrutura de custos","Orçamento de instalações","Capital de giro"]},{"t":"Mão de obra e produtividade","a":"negocio","r":"O trabalho é um custo importante, mas um bom trabalhador economiza muito mais do que custa.","s":[{"h":"Referências","p":["Um trabalhador bem organizado pode atender várias centenas de animais no curral com equipamento adequado.","Sem equipamento de mistura e distribuição, é preciso mais gente."]},{"h":"Como melhorar a produtividade","p":["Rotinas claras e escritas.","Equipamento adequado: misturador, carretas, balança no brete.","Instalações pensadas para o trabalho."]},{"h":"Custo por animal","p":["Some salários e encargos do mês e divida pelos animais atendidos.","Anote a folha no app como gasto geral."]}],"rel":["Pessoal e segurança no trabalho","Rotina diária da engorda","Estrutura de custos"]},{"t":"Depreciação e investimentos","a":"negocio","r":"As instalações e o equipamento se desgastam. Incluir seu custo anual mostra o verdadeiro resultado do confinamento.","s":[{"h":"Depreciação","p":["Custo anual = (valor de compra − valor final) ÷ anos de vida útil.","Exemplo: um misturador de 150.000 que dura 10 anos custa 15.000 por ano."]},{"h":"Vidas úteis de referência","p":["Currais de cimento e tubo: 15 a 25 anos.","Madeira tratada: 8 a 12 anos.","Equipamento mecânico: 8 a 12 anos.","Balança: 10 a 15 anos."]},{"h":"Decidir um investimento","p":["Quanto economiza ou produz por ano?","Em quantos anos se paga?","Há algo mais barato que dê o mesmo resultado?"]}],"rel":["Orçamento de instalações","Escala do confinamento"]},{"t":"Indicadores-chave do confinamento","a":"negocio","r":"Uns poucos números bem medidos dizem se seu confinamento vai bem. Revise-os em cada lote.","s":[{"h":"Produção","p":["Ganho diário de peso: meta de 1,2 a 1,6 kg no curral.","Conversão: 6 a 8 kg de alimento por kg ganho.","Consumo: 2,2 a 2,8 % do peso vivo em matéria seca.","Dias de confinamento."]},{"h":"Sanidade","p":["Mortalidade: menos de 1 a 2 %.","Doentes na recepção: menos de 10 %.","Animais atrasados por lote."]},{"h":"Economia","p":["Custo por quilo ganho frente ao preço de venda.","Margem por cabeça e por dia.","Preço de equilíbrio frente ao preço de mercado."]},{"h":"No app","p":["Hoje e cada lote mostram ganho, conversão e custo.","Gráficos compara lotes e períodos."]}],"rel":["Ganho médio diário","Conversão alimentar","Custo por quilo ganho"]},{"t":"Engorda em parceria ou por serviço","a":"negocio","r":"Há acordos em que um põe o gado e outro a fazenda e o trabalho. Bem feitos, repartem risco e benefício.","s":[{"h":"Tipos","p":["Em parceria: reparte-se o ganho de peso ou o lucro em porcentagens combinadas.","Por serviço (hotelaria): o dono paga uma taxa por animal por dia ou por quilo ganho."]},{"h":"O que combinar por escrito","p":["Quem põe o quê: animais, alimento, sanidade, mão de obra.","Como se pesa na entrada e na saída.","O que acontece com as mortes.","Como e quando se paga.","Duração do acordo."]},{"h":"Com o app","p":["Crie um lote para cada acordo e anote tudo para prestar contas claras."]}],"rel":["Financiamento e crédito","Registros econômicos"]},{"t":"Como o app usa seus dados","a":"negocio","r":"O app transforma seus registros em decisões: quando vender, quanto pagar, qual lote vai melhor.","s":[{"h":"O que calcula","p":["Ganho diário por lote e por animal.","Conversão e custo por quilo ganho.","Data estimada de chegada à meta.","Margem estimada e preço de equilíbrio.","Alimento necessário para o mês."]},{"h":"O que precisa de você","p":["Anotar o alimento todo dia.","Pesar a cada 3 a 4 semanas.","Registrar sanidade, mortes, gastos e vendas.","Colocar preços reais."]},{"h":"Decisões","p":["Vender um lote que já não ganha o suficiente.","Tirar animais atrasados.","Comprar a um preço que deixe lucro.","Trocar uma ração que converte mal."]}],"rel":["Registros econômicos","Indicadores-chave do confinamento","Quando vender"]},{"t":"Quando não convém confinar","a":"negocio","r":"Às vezes a melhor decisão é não comprar. Confinar com os números contra só é trabalhar para perder.","s":[{"h":"Sinais","p":["O preço máximo de compra que o Rumi dá é menor do que pedem pelo gado.","O custo por quilo ganho é maior que o preço de venda por quilo.","Você não tem alimento ou água garantidos para todo o ciclo.","Você não tem capital para terminar o confinamento."]},{"h":"Alternativas","p":["Esperar melhores preços de compra.","Confinar menos animais, mas bem.","Oferecer seus currais para engorda por serviço.","Engordar a pasto com menos custo."]}],"rel":["Preço máximo de compra","Custo por quilo ganho","Engorda em parceria ou por serviço"]},{"t":"Contratos com compradores","a":"negocio","r":"Combinar preço e condições antes de terminar o confinamento reduz o risco de o mercado cair.","s":[{"h":"O que pode incluir","p":["Preço fixo ou fórmula de preço.","Faixa de peso e acabamento.","Data aproximada de entrega.","Forma de pesagem e quebra.","Descontos e prêmios.","Forma e prazo de pagamento."]},{"h":"Vantagens","p":["Você sabe quanto vai receber.","Planeja a compra com mais segurança."]},{"h":"Cuidados","p":["Por escrito e assinado.","Conheça a seriedade do comprador.","Cumpra o combinado: a confiança vale muito."]}],"rel":["Negociar com o comprador","Riscos do confinamento","Canais de venda"]},{"t":"Seguro pecuário","a":"negocio","r":"Um seguro pode cobrir mortes por doença, acidentes ou roubo. É preciso ler bem o que cobre.","s":[{"h":"O que costuma cobrir","p":["Morte por doença ou acidente.","Às vezes roubo ou desastres naturais."]},{"h":"O que pedem","p":["Identificação dos animais.","Registros sanitários.","Aviso rápido quando morre um animal, às vezes com necropsia."]},{"h":"Como decidir","p":["Compare o prêmio com sua mortalidade histórica no app.","Pergunte ao seu banco ou cooperativa por seguros ligados ao crédito."]}],"rel":["Riscos do confinamento","Mortalidade e seu custo"]},{"t":"Preço mínimo por libra","a":"negocio","r":"Muitos negociam em libras. Saber seu preço mínimo por libra evita aceitar ofertas que fazem você perder.","s":[{"h":"Como calcular","p":["Preço mínimo por quilo = custo total do lote ÷ quilos vendidos.","Preço mínimo por libra = preço mínimo por quilo ÷ 2,2."]},{"h":"Exemplo","p":["Um mínimo de 50 por quilo equivale a 22,7 por libra."]},{"h":"No app","p":["Se você trabalha em libras, o Rumi dá direto por libra em Dinheiro e vendas, Preço mínimo para não perder."]}],"rel":["Ponto de equilíbrio","Unidades de peso e medida"]},{"t":"Custo de oportunidade","a":"negocio","r":"O dinheiro e os currais que você usa no confinamento poderiam estar rendendo em outra coisa. Considerar isso ajuda a decidir.","s":[{"h":"O que é","p":["O que você deixa de ganhar por usar seus recursos no confinamento.","Por exemplo, os juros que o dinheiro daria no banco ou o aluguel dos pastos."]},{"h":"Como usar","p":["Compare o retorno do confinamento com outras opções.","Se o confinamento rende menos que deixar o dinheiro seguro, revise seu modelo."]}],"rel":["Retorno do investimento","Capital de giro"]},{"t":"Valor do ganho","a":"negocio","r":"O valor do ganho é o que pagam por cada quilo que o animal sobe na sua fazenda. Calcula-se subtraindo o que o animal custou na entrada do que vale na saída e dividindo pelos quilos ganhos. Compará-lo com o custo por quilo ganho diz se o confinamento dá dinheiro.","s":[{"h":"Como se calcula","p":["Valor de venda do animal menos custo de compra.","Dividido pelos quilos que ganhou no confinamento.","Exemplo: você comprou por 18.000, vendeu por 31.500 e ganhou 180 kg: o valor do ganho é 75 por quilo."]},{"h":"Por que não é igual ao preço","p":["O animal leve costuma ser comprado mais caro por quilo que o pesado.","Essa diferença faz o quilo ganho valer menos que o preço de venda por quilo.","Se o preço de compra por quilo sobe muito, o valor do ganho baixa."]},{"h":"A regra de ouro","p":["Se o custo por quilo ganho é menor que o valor do ganho, você ganha dinheiro.","Se é maior, você perde mesmo que o animal engorde bem."]},{"h":"No seu confinamento","p":["O app mostra o custo por quilo ganho de cada lote.","Antes de comprar, use o preço máximo de compra para que os números fechem."]}],"rel":["Custo por quilo ganho","Preço máximo de compra","Margem de compra e venda","Diferença de preço por peso"]},{"t":"Diferença de preço por peso","a":"negocio","r":"Em quase todos os mercados o quilo do bezerro leve vale mais que o quilo do novilho pesado. Essa diferença define quanto convém comprar leve ou pesado.","s":[{"h":"Por que acontece","p":["O animal leve ainda tem todo seu ganho eficiente pela frente.","Há mais demanda de bezerros para engordar.","O animal pesado já tem menos margem para o próximo dono."]},{"h":"Como usar","p":["Se a diferença é pequena, convém comprar leve e engordar mais tempo.","Se é muito grande, às vezes convém comprar mais pesado e fazer confinamentos curtos.","Compare sempre com seu custo por quilo ganho."]},{"h":"No seu confinamento","p":["Anote preço e peso de cada compra no app para ver como a diferença muda na sua região.","O Rumi calcula a margem com seus números."]}],"rel":["Valor do ganho","Comprar mais leve ou mais pesado","Margem de compra e venda"]},{"t":"Comprar mais leve ou mais pesado","a":"negocio","r":"Comprar animais leves ou pesados muda o tempo de confinamento, o risco, a conversão e o capital que você precisa.","s":[{"h":"Leves (150 a 250 kg)","p":["Mais baratos por animal, mas mais caros por quilo.","Convertem melhor e têm mais crescimento compensatório.","Mais risco de doença e mais tempo na fazenda."]},{"h":"Pesados (300 a 380 kg)","p":["Mais capital por animal, mas confinamento curto.","Menos risco sanitário e mais giros por ano.","Pior conversão porque já estão engordurando."]},{"h":"Como decidir","p":["Compare a margem esperada por animal e por mês.","Considere sua comida disponível, seu capital e sua experiência.","Teste com um lote e compare no app."]}],"rel":["Diferença de preço por peso","Giros por ano","Capital de giro","Crescimento compensatório"]},{"t":"Análise de sensibilidade","a":"negocio","r":"Uma análise de sensibilidade responde: o que acontece com meu lucro se o preço de venda cair 10 %, ou a comida subir, ou os animais ganharem menos? Prepara você para os golpes do mercado.","s":[{"h":"Quais variáveis mexer","p":["Preço de venda.","Preço de compra.","Custo da ração.","Ganho diário e mortalidade."]},{"h":"Como fazer","p":["Calcule sua margem normal.","Mude uma variável por vez e veja quanto a margem baixa.","A variável que mais mexe o resultado é a que você mais deve vigiar."]},{"h":"No seu confinamento","p":["Quase sempre o preço de venda e de compra pesam mais que a comida.","Por isso negociar bem a compra é tão importante quanto engordar bem.","O Rumi pode projetar seu lote com preços diferentes."]}],"rel":["Riscos do confinamento","Ponto de equilíbrio","Orçamento de um lote","Projeções no app"]},{"t":"Fluxo de caixa do confinamento","a":"negocio","r":"O fluxo de caixa mostra quando o dinheiro sai e quando entra. No confinamento se paga muito no início (compra) e toda semana (comida), mas se recebe no final.","s":[{"h":"Por que importa","p":["Você pode ter um lote rentável e ficar sem dinheiro para comprar comida.","Vender às pressas por falta de caixa quase sempre sai caro."]},{"h":"Como manejar","p":["Calcule o custo de comida por semana e por todo o confinamento antes de comprar.","Escalone os lotes para que as vendas cheguem em meses diferentes.","Tenha uma reserva para emergências."]},{"h":"No seu confinamento","p":["O app mostra o custo acumulado de cada lote e a estimativa até a venda."]}],"rel":["Capital de giro","Financiamento e crédito","Orçamento de um lote"]},{"t":"Compras em grupo e cooperativas","a":"negocio","r":"Juntar-se a outros pecuaristas para comprar alimento, medicamentos e gado, ou para vender juntos, baixa custos e dá mais força para negociar.","s":[{"h":"Benefícios","p":["Melhores preços por volume em concentrado, sal e medicamentos.","Caminhões completos para transportar gado.","Venda de lotes grandes e uniformes a melhor preço."]},{"h":"Cuidados","p":["Acordos claros e por escrito.","Registros transparentes de quem contribuiu com o quê.","Regras sanitárias comuns para não misturar doenças."]}],"rel":["Canais de venda","Negociar com o comprador","Escala do confinamento"]},{"t":"Custos que não se veem","a":"negocio","r":"Muitos pecuaristas só contam a compra e o concentrado e esquecem custos que comem a margem: quebras, mortes, juros, depreciação, seu próprio trabalho.","s":[{"h":"Os mais esquecidos","p":["Quebra na compra e na venda.","Animais mortos e atrasados.","Juros do dinheiro ou o que você deixou de ganhar com ele.","Desgaste de instalações e equipamento.","Seu tempo e o da sua família."]},{"h":"No seu confinamento","p":["Registre gastos gerais no app para que entrem no custo.","O app desconta as mortes e calcula o custo real por quilo."]}],"rel":["Estrutura de custos","Depreciação e investimentos","Custo de oportunidade","Mortalidade e seu custo"]},{"t":"Decidir com dados","a":"negocio","r":"A diferença entre um confinamento que ganha e um que perde muitas vezes não é a comida nem a raça, mas decidir a tempo com números reais.","s":[{"h":"Perguntas que seus dados respondem","p":["Quanto ganha cada lote por dia comparado com a meta?","Quanto me custa o quilo ganho?","Quais animais estão ficando para trás?","Quando convém vender?"]},{"h":"Hábitos","p":["Pesar a cada 3 a 4 semanas.","Anotar a comida real, não a planejada.","Revisar os números toda semana com o Rumi."]},{"h":"No seu confinamento","p":["Depois de 3 ou 4 lotes você terá sua própria história: use-a para comprar e vender melhor."]}],"rel":["Indicadores-chave do confinamento","Quando vender","Registros econômicos","Dados e apps na engorda"]},{"t":"Guia de trânsito e rastreabilidade","a":"normas","r":"Mover gado exige documentos que dizem de onde vem e para onde vai. Protege contra roubos e doenças e é exigido pela autoridade e pelos compradores.","s":[{"h":"O que é","p":["Um documento oficial emitido pela autoridade sanitária (SENASA em Honduras) para transportar animais.","Indica origem, destino, número de animais, marca e proprietário."]},{"h":"Quando é necessário","p":["Ao comprar, vender ou transportar gado entre fazendas, para leilões ou frigoríficos.","Os requisitos exatos e o trâmite são definidos pelo SENASA; consulte o escritório local."]},{"h":"Rastreabilidade","p":["É poder seguir um animal desde a origem até o frigorífico.","Baseia-se em marca, brincos oficiais quando aplicável, guias e registros da fazenda.","Alguns mercados e frigoríficos só compram animais rastreáveis."]},{"h":"Boas práticas","p":["Guarde cópia de todas as guias.","Anote no app o fornecedor e a origem de cada lote.","Não compre animais sem guia."]}],"rel":["Registro de marca e fazenda","Transporte: requisitos","Registros e rastreabilidade"]},{"t":"Registro de marca e fazenda","a":"normas","r":"Registrar sua marca e sua fazenda identifica você como proprietário e facilita guias, programas sanitários e vendas.","s":[{"h":"Marca","p":["Registra-se na autoridade correspondente (prefeitura ou a que a lei local indicar).","Prova a propriedade do gado.","Cada marca é única."]},{"h":"Fazenda","p":["O registro no SENASA permite emitir guias e participar de programas oficiais.","Alguns compradores e exportadores exigem."]},{"h":"Conselho","p":["Consulte na sua prefeitura e no escritório do SENASA mais próximo os requisitos atuais."]}],"rel":["Guia de trânsito e rastreabilidade","Segurança e roubo de gado"]},{"t":"Carências e resíduos","a":"normas","r":"Um animal tratado não pode ir ao frigorífico até terminar o período de carência. Vender antes deixa resíduos na carne e é ilegal.","s":[{"h":"O que é a carência","p":["Dias desde a última aplicação de um medicamento até o animal poder ser abatido.","Está no rótulo de cada produto registrado.","É diferente para cada produto e às vezes para cada via de aplicação."]},{"h":"Regras","p":["Com vários produtos, vale a carência mais longa.","Se você usa um produto fora da bula por indicação do veterinário, a carência pode ser maior: pergunte.","Anote sempre a data e a carência."]},{"h":"Consequências de não respeitar","p":["Risco para a saúde de quem come a carne.","Condenações, multas e perda do comprador.","Fechamento de mercados para todo o país."]},{"h":"No app","p":["Ao anotar sanidade você coloca os dias de carência.","O app avisa em Hoje e na venda se o lote ainda está em carência."]}],"rel":["Uso responsável de antibióticos","Boas práticas pecuárias","Produtos proibidos na alimentação"]},{"t":"Boas práticas pecuárias","a":"normas","r":"São regras simples para produzir carne sadia e cuidar dos animais, das pessoas e do ambiente. Cada vez mais compradores as exigem.","s":[{"h":"Sanidade","p":["Plano sanitário com veterinário.","Medicamentos registrados, usados conforme a bula e com carências respeitadas.","Registros de tratamentos."]},{"h":"Alimentação","p":["Ingredientes de origem conhecida, sem contaminantes.","Armazém limpo, seco e sem pragas.","Nada de produtos proibidos."]},{"h":"Água","p":["Água limpa e suficiente.","Proteção das fontes de água."]},{"h":"Bem-estar","p":["Manejo tranquilo, sombra, espaço, transporte adequado."]},{"h":"Pessoas e ambiente","p":["Trabalhadores treinados e protegidos.","Manejo correto do esterco, cadáveres e embalagens de químicos."]},{"h":"Registros","p":["Identificação, movimentações, alimentos, sanidade e vendas."]}],"rel":["Carências e resíduos","Bem-estar na lei e no mercado","Ambiente e manejo de resíduos"]},{"t":"Bem-estar na lei e no mercado","a":"normas","r":"O bem-estar animal já não é só boa vontade: aparece em leis, em regras de transporte e em requisitos de compradores.","s":[{"h":"O que se exige cada vez mais","p":["Sem maus-tratos: sem pancadas, sem choques abusivos.","Água, alimento e sombra.","Transporte com densidade e tempos adequados.","Abate humanitário em matadouros autorizados."]},{"h":"Por que importa","p":["Grandes compradores e redes de supermercados auditam.","Mercados de exportação exigem.","Melhora a qualidade da carne."]}],"rel":["Bem-estar animal","Transporte: requisitos","Manejo tranquilo do gado"]},{"t":"Transporte: requisitos","a":"normas","r":"O transporte de gado deve ser feito com documentos em ordem e em condições que protejam os animais.","s":[{"h":"Documentos","p":["Guia de trânsito vigente.","Documentos do veículo e do motorista conforme a lei de trânsito."]},{"h":"Condições","p":["Veículo limpo e desinfetado.","Piso antiderrapante, sem partes cortantes.","Densidade adequada: nem amontoados nem soltos.","Animais doentes, fracos ou pesados demais para viajar não devem ser transportados."]},{"h":"Boas práticas","p":["Viagens nas horas frescas.","Paradas mínimas e sem deixar o caminhão no sol."]}],"rel":["Transporte de gado","Guia de trânsito e rastreabilidade","Bem-estar na lei e no mercado"]},{"t":"Programas oficiais de sanidade","a":"normas","r":"A autoridade sanitária mantém programas contra doenças que afetam todo o país. Participar protege sua fazenda e seus vizinhos.","s":[{"h":"Programas comuns","p":["Bicheira (Cochliomyia): vigilância e notificação de casos.","Raiva paralítica bovina: vacinação e controle do morcego-vampiro.","Brucelose e tuberculose: testes e certificação de rebanhos.","Vigilância de doenças exóticas (como a febre aftosa, que não está presente na América Central)."]},{"h":"O que fazer","p":["Notifique casos suspeitos ao SENASA.","Participe das campanhas de vacinação.","Colabore com os rastreamentos quando o frigorífico encontra lesões."]}],"rel":["Doenças de notificação obrigatória","Bicheira (Cochliomyia)","Raiva paralítica bovina"]},{"t":"Doenças de notificação obrigatória","a":"normas","r":"Algumas doenças devem ser notificadas à autoridade sanitária assim que houver suspeita, porque podem causar epidemias ou afetar o comércio.","s":[{"h":"Exemplos","p":["Raiva.","Antraz (carbúnculo hemático).","Bicheira (Cochliomyia).","Tuberculose e brucelose.","Qualquer doença com muitas mortes, bolhas na boca e nas patas ou sintomas nervosos estranhos."]},{"h":"Como notificar","p":["Ligue para o escritório local do SENASA ou para seu veterinário.","Não mova animais nem cadáveres até receber instruções.","Guarde as informações: datas, animais afetados, origem."]},{"h":"Conselho","p":["Tenha à mão o telefone do SENASA da sua região.","A lista oficial pode mudar: consulte a autoridade."]}],"rel":["Programas oficiais de sanidade","Antraz (carbúnculo hemático)","Morte de um animal"]},{"t":"Produtos proibidos na alimentação","a":"normas","r":"Há substâncias e materiais que não se podem dar ao gado porque prejudicam as pessoas ou o animal. Usá-los traz sanções e fechamento de mercados.","s":[{"h":"Exemplos","p":["Clembuterol e outros beta-agonistas não autorizados.","Hormônios não registrados.","Farinhas de carne, osso ou sangue de ruminantes para alimentar ruminantes (risco de vaca louca).","Antibióticos como promotores de crescimento onde não são permitidos.","Restos de comida com carne, lixo ou materiais contaminados."]},{"h":"Regras","p":["Use só produtos registrados e conforme a bula.","Peça ao fornecedor a composição do concentrado.","Guarde notas fiscais e rótulos."]},{"h":"Conselho","p":["As listas mudam: consulte o SENASA e seu comprador."]}],"rel":["Promotores de crescimento e implantes","Cama de frango","Carências e resíduos"]},{"t":"Ambiente e manejo de resíduos","a":"normas","r":"O confinamento produz esterco, águas sujas, cadáveres e embalagens de químicos. Manejá-los bem evita multas e problemas com vizinhos.","s":[{"h":"Esterco e águas","p":["Não despejar em córregos nem rios.","Compostagem ou biodigestores.","Distância de fontes de água."]},{"h":"Cadáveres","p":["Enterrar com cal longe da água, ou o que a autoridade indicar.","Nunca a céu aberto."]},{"h":"Embalagens de químicos","p":["Tríplice lavagem e perfuração.","Entregar a programas de recolhimento.","Nunca reutilizar para água ou alimento."]},{"h":"Solo e floresta","p":["Proteja nascentes e margens de córregos.","Reflorestar com sistemas silvipastoris."]}],"rel":["Manejo do esterco","Morte de um animal","Sistemas silvipastoris"]},{"t":"Segurança do trabalhador","a":"normas","r":"A lei trabalhista e o bom senso pedem proteger quem trabalha com o gado.","s":[{"h":"Obrigações básicas","p":["Equipamento de proteção: botas, luvas, máscaras para químicos.","Treinamento em manejo de animais e químicos.","Kit de primeiros socorros."]},{"h":"Riscos","p":["Pancadas e esmagamentos no brete.","Doenças transmitidas pelos animais.","Intoxicações por agrotóxicos.","Acidentes com máquinas."]},{"h":"Conselho","p":["Revise suas obrigações trabalhistas com a autoridade do trabalho ou um assessor."]}],"rel":["Pessoal e segurança no trabalho","Doenças que passam para as pessoas"]},{"t":"Abate autorizado","a":"normas","r":"A carne para venda deve vir de animais abatidos em matadouros ou frigoríficos autorizados, com inspeção sanitária.","s":[{"h":"Por quê","p":["Inspeção antes e depois do abate.","Detecção de doenças e resíduos.","Higiene da carne."]},{"h":"O que pedem","p":["Guia de trânsito.","Animais sadios e sem carências pendentes.","Identificação do proprietário."]},{"h":"Conselho","p":["Vender carne de animais abatidos na fazenda para comércio não é legal e é um risco sanitário."]}],"rel":["Canais de venda","Carências e resíduos","Guia de trânsito e rastreabilidade"]},{"t":"Receita e uso de medicamentos veterinários","a":"normas","r":"Os medicamentos veterinários devem ter registro oficial e ser usados conforme a bula ou a receita do veterinário. Os antibióticos exigem cada vez mais receita.","s":[{"h":"Regras","p":["Compre só produtos registrados no seu país.","Siga dose, via de aplicação e carência da bula.","Usar um produto fora da bula só com receita do veterinário, que fixa uma carência mais longa."]},{"h":"Registros","p":["Anote produto, lote do produto, dose, animais, data e carência.","Guarde notas e receitas."]},{"h":"No seu confinamento","p":["O app guarda cada tratamento com sua carência e avisa antes de vender."]}],"rel":["Carências e resíduos","Uso responsável de antibióticos","Sanidade e carências no app"]},{"t":"Bom uso de agrotóxicos","a":"normas","r":"Carrapaticidas, inseticidas e herbicidas são venenos. Usá-los bem protege as pessoas, o gado, a água e suas vendas.","s":[{"h":"Regras","p":["Só produtos registrados e para o uso indicado.","Equipamento de proteção ao misturar e aplicar.","Não lavar equipamentos nem jogar sobras em rios ou córregos.","Tríplice lavagem e entrega das embalagens vazias nos centros de recolhimento."]},{"h":"Carências","p":["Os banhos no gado têm dias de carência para carne.","Os herbicidas nos pastos têm dias antes de voltar a pastejar."]}],"rel":["Intoxicação por agrotóxicos","Ambiente e manejo de resíduos","Carências e resíduos"]},{"t":"Proteção de fontes de água","a":"normas","r":"Muitas leis protegem as nascentes e as margens de rios e córregos com faixas de mata. Além de obrigatório, cuida da água que seu gado bebe.","s":[{"h":"Boas práticas","p":["Cercar nascentes e margens para que o gado não entre.","Levar a água a bebedouros com bomba, gravidade ou carneiro hidráulico.","Manter árvores nas margens."]},{"h":"Benefícios","p":["Água mais limpa: menos diarreias e parasitas.","Menos erosão e barro.","Você cumpre a lei e pode acessar programas ambientais."]}],"rel":["Água: fontes, caixas e qualidade","Ambiente e manejo de resíduos","Pecuária regenerativa"]},{"t":"Normas de bem-estar no transporte","a":"normas","r":"Muitos países estabelecem regras para o transporte de gado: tempo máximo de viagem, espaço por animal e condições do veículo.","s":[{"h":"Pontos comuns","p":["Animais aptos para viajar: não doentes, mancos graves nem fêmeas prestes a parir.","Piso antiderrapante e sem saliências.","Carga conforme o peso dos animais.","Descansos com água em viagens longas."]},{"h":"No seu confinamento","p":["Peça ao transportador que cumpra essas regras: seu gado chega melhor e sem pancadas."]}],"rel":["Transporte: requisitos","Transporte de gado","Pancadas e hematomas"]},{"t":"Como funciona o rúmen","a":"nutricion","r":"O bovino não digere sozinho: milhões de micróbios no rúmen fermentam o alimento. Alimentar bem é alimentar esses micróbios.","s":[{"h":"Os quatro estômagos","p":["Rúmen (pança): o maior, onde os micróbios fermentam.","Retículo: ajuda a devolver o bolo para ruminar.","Omaso: absorve água.","Abomaso: o estômago verdadeiro, com ácido como o nosso."]},{"h":"O que os micróbios fazem","p":["Quebram a fibra do pasto que o animal sozinho não conseguiria digerir.","Transformam açúcares e amido em ácidos graxos que dão energia ao animal.","Fabricam proteína de alta qualidade a partir de nitrogênio, até da ureia.","Produzem vitaminas do complexo B e vitamina K."]},{"h":"A ruminação","p":["O animal devolve o bolo à boca e mastiga de novo.","A saliva produzida ao ruminar traz bicarbonato que acalma o ácido do rúmen.","Sem fibra longa não há ruminação, não há saliva e aparece a acidose."]},{"h":"Regras que vêm daqui","p":["Os micróbios precisam de tempo para se acostumar a uma ração nova: 2 a 4 semanas.","Mudanças bruscas matam os micróbios úteis.","Energia e proteína devem chegar juntas para os micróbios crescerem.","Água limpa e constante é indispensável para a fermentação."]}],"rel":["Fibra e forragem na ração","Adaptação ao concentrado","Acidose ruminal"]},{"t":"Matéria seca e consumo","a":"nutricion","r":"Todo cálculo de ração se faz em matéria seca: o que sobra do alimento sem a água. Sem isso os ingredientes são comparados errado.","s":[{"h":"O que é","p":["Matéria seca é o alimento sem sua água.","Um capim fresco pode ter 20 % de matéria seca: de 10 kg, só 2 kg são alimento seco.","Um grão como o milho tem cerca de 88 % de matéria seca."]},{"h":"Quanto comem","p":["Um novilho de confinamento come entre 2,2 e 2,8 % do seu peso vivo em matéria seca por dia.","Um animal de 350 kg come cerca de 8 a 9,5 kg de matéria seca.","No início, com calor ou doentes comem menos.","Rações com muita fibra de má qualidade baixam o consumo."]},{"h":"Como calcular","p":["Quilos como servidos = quilos de matéria seca ÷ fração de matéria seca.","Exemplo: 3 kg de matéria seca de silagem com 30 % MS = 3 ÷ 0,30 = 10 kg de silagem fresca.","A calculadora do Rumi dá o consumo conforme o peso."]},{"h":"O que baixa o consumo","p":["Calor forte e falta de sombra.","Água escassa ou suja.","Alimento com mofo ou mau cheiro.","Acidose subaguda.","Cochos sujos ou com pouco espaço.","Doenças e parasitas."]}],"rel":["Consumo baixo","Qualidade da forragem e idade de corte","Formular uma ração"]},{"t":"Energia na ração","a":"nutricion","r":"A energia é o que mais limita o ganho de peso no confinamento. Vem sobretudo de grãos, melaço e forragens de boa qualidade.","s":[{"h":"Como se mede","p":["NDT (nutrientes digestíveis totais): porcentagem do alimento que é digerida.","Energia líquida de ganho (ELg): a energia que realmente sobra para ganhar peso.","Uma ração de terminação costuma ter 72 a 80 % de NDT."]},{"h":"Fontes de energia","p":["Grãos: milho, sorgo, arroz quebrado.","Melaço e subprodutos com açúcar.","Polpa cítrica, casca de soja e outros com fibra digestível.","Gorduras em pouca quantidade (não mais de 5 a 6 % da ração total)."]},{"h":"Sinais de falta de energia","p":["Ganho baixo mesmo comendo bem.","Animais que não engordam no final.","Bom tamanho, mas magros."]},{"h":"Cuidados","p":["Mais energia por grão exige mais cuidado com a acidose.","Suba o grão aos poucos.","Equilibre sempre com proteína e minerais."]}],"rel":["Proteína na ração","Milho e outros grãos","Acidose ruminal"]},{"t":"Proteína na ração","a":"nutricion","r":"A proteína forma músculo e alimenta os micróbios do rúmen. Animais jovens e leves precisam de mais.","s":[{"h":"Quanta","p":["Inicial e animais leves: 13 a 15 % de proteína bruta na matéria seca.","Crescimento: 12 a 13 %.","Terminação: 11 a 12 %.","Dar mais do que o necessário é dinheiro jogado fora: o excesso sai na urina."]},{"h":"Tipos","p":["Proteína degradável: usada pelos micróbios do rúmen (inclui a ureia).","Proteína de escape ou by-pass: passa sem se degradar e é digerida no intestino.","Os animais jovens aproveitam mais a proteína de escape."]},{"h":"Fontes","p":["Farelo de soja, torta de palmiste, farelo de algodão.","Ureia (nitrogênio não proteico) em quantidade limitada.","Leguminosas: leucena, gliricídia, cratília, feijão-guandu.","Cama de frango: veja restrições e riscos antes de usar."]},{"h":"Sinais de falta de proteína","p":["Pouco consumo de forragens secas.","Ganho baixo em animais jovens.","Pelo feio e crescimento de esqueleto sem carne."]}],"rel":["Ureia na ração","Farelo de soja e outras proteínas","Energia na ração"]},{"t":"Fibra e forragem na ração","a":"nutricion","r":"Mesmo que a ração seja de concentrado, o animal precisa de fibra longa para ruminar e manter o rúmen sadio.","s":[{"h":"Para que serve","p":["Estimula a ruminação e a saliva, que acalma o ácido do rúmen.","Mantém o movimento do rúmen.","Forma uma camada de fibra que protege a parede do rúmen."]},{"h":"Quanto","p":["Inicial: 40 a 60 % de forragem.","Crescimento: 25 a 35 %.","Terminação: pelo menos 10 a 15 % de forragem efetiva.","Com menos, sobe o risco de acidose, abscessos de fígado e timpanismo."]},{"h":"Tamanho de picado","p":["Picado de 2 a 5 cm estimula a ruminação.","Picado muito fino (menos de 1 cm) perde o efeito de fibra.","Forragem muito longa é selecionada e desperdiçada."]},{"h":"Sinais de pouca fibra","p":["Poucos animais ruminando quando deitados.","Fezes soltas e brilhantes.","Consumo que sobe e desce.","Lambem ou comem terra, madeira ou cama."]}],"rel":["Acidose ruminal","Feno e capim de corte na ração","Mistura da ração"]},{"t":"Minerais principais","a":"nutricion","r":"Cálcio, fósforo, sal, magnésio, potássio e enxofre são necessários em grandes quantidades. Um núcleo mineral bem balanceado os cobre.","s":[{"h":"Cálcio e fósforo","p":["Formam osso e participam do metabolismo de energia.","Relação cálcio:fósforo de 1,5 a 2 para 1.","Rações com muito grão têm pouco cálcio e muito fósforo: é preciso acrescentar cálcio (calcário)."]},{"h":"Sal (sódio e cloro)","p":["Regula a água do corpo.","Melhora o consumo e o sabor.","0,25 a 0,5 % da ração."]},{"h":"Magnésio e potássio","p":["Importantes em animais estressados e com calor.","O potássio cai em rações com muito grão."]},{"h":"Enxofre","p":["Necessário para os micróbios fabricarem proteína, sobretudo com ureia.","Em excesso (mais de 0,4 % da ração) causa problemas nervosos."]},{"h":"Como fornecê-los","p":["No curral: núcleo mineral misturado na ração, geralmente 1,5 a 2 % da matéria seca, conforme o fabricante.","No pasto: sal mineral à vontade em cochos cobertos.","Confira o rótulo: fósforo mínimo de 6 a 8 % em sais para pastejo tropical."]}],"rel":["Microminerais e vitaminas","Cálculos urinários","Sal mineral e blocos"]},{"t":"Microminerais e vitaminas","a":"nutricion","r":"São necessários em quantidades muito pequenas, mas são chave para defesas, cascos, pelo e ganho.","s":[{"h":"Microminerais","p":["Zinco: pele, cascos, defesas.","Cobre: sangue, pelo, defesas.","Selênio: músculos e defesas; tóxico em excesso.","Cobalto: para o rúmen fabricar vitamina B12.","Iodo: tireoide.","Manganês: ossos e articulações."]},{"h":"Vitaminas","p":["Vitamina A: visão, pele e defesas; baixa em pastos secos e grãos velhos.","Vitamina D: ossos; o animal a forma com o sol.","Vitamina E: defesas e músculos.","As do complexo B são fabricadas pelo rúmen sadio."]},{"h":"Quando reforçar","p":["Na entrada, em animais estressados.","Na época seca, quando o pasto está seco e amarelo.","Com rações de grão armazenado por muito tempo."]},{"h":"Regras","p":["Use um núcleo mineral completo e confiável.","Não acrescente selênio nem cobre por conta própria.","Guarde os minerais secos e bem fechados."]}],"rel":["Minerais principais","Deficiências de minerais","Plano sanitário de entrada"]},{"t":"Água de bebida","a":"nutricion","r":"A água é o nutriente mais importante e o mais esquecido. Um animal sem água suficiente para de comer e de ganhar.","s":[{"h":"Quanto bebem","p":["Entre 40 e 70 litros por dia por animal de confinamento, conforme o peso e o clima.","Com calor forte podem beber o dobro.","Regra prática: 5 a 7 litros por quilo de matéria seca que comem, mais com calor."]},{"h":"Qualidade","p":["Limpa, sem cheiro, sem limo nem algas.","Fresca: a água quente é menos bebida.","Sem esterco nem urina.","Se for de poço, analise sais, nitratos e enxofre."]},{"h":"Bebedouros","p":["Lave os bebedouros toda semana e jogue fora a água suja.","Espaço para 10 a 15 % do lote beber ao mesmo tempo.","Revise boias e canos todos os dias.","Coloque os bebedouros na sombra e longe do cocho para não cair comida."]},{"h":"Sinais de falta de água","p":["O consumo de alimento cai.","Fezes secas e duras.","Animais amontoados no bebedouro.","Olhos fundos e pele que demora a voltar ao ser beliscada."]}],"rel":["Bebedouros","Golpe de calor","Consumo baixo"]},{"t":"Adaptação ao concentrado","a":"nutricion","r":"Passar do pasto para uma ração com grão exige 3 a 4 semanas. É o passo mais importante para evitar acidose e mortes.","s":[{"h":"Por que adaptar","p":["Os micróbios do rúmen que digerem pasto são diferentes dos que digerem grão.","Precisam de semanas para mudar.","A parede do rúmen também se adapta para absorver mais ácidos."]},{"h":"Programa de exemplo","p":["Dias 1 a 5: 60 % forragem, 40 % concentrado.","Dias 6 a 10: 45 % forragem, 55 % concentrado.","Dias 11 a 15: 30 % forragem, 70 % concentrado.","Dias 16 a 21: 20 % forragem, 80 % concentrado.","Dia 22 em diante: 10 a 15 % forragem, 85 a 90 % concentrado (terminação).","Passe para o próximo passo só se o cocho ficar limpo e não houver diarreia."]},{"h":"Outro método","p":["Manter a mesma ração e subir a quantidade servida aos poucos, 0,5 kg por animal a cada 2 a 3 dias.","Funciona se você lê bem os cochos."]},{"h":"Sinais de que vai rápido demais","p":["Fezes soltas e azedas.","Animais que deixam comida um dia e terminam no outro.","Mancadeiras e timpanismo.","Queda de consumo."]},{"h":"Erros comuns","p":["Dar ração de terminação desde o primeiro dia.","Pular passos quando o animal parece estar bem.","Mudar de ração e de curral no mesmo dia."]}],"rel":["Acidose ruminal","Leitura de cochos","Ração inicial"]},{"t":"Ração inicial","a":"nutricion","r":"A ração dos primeiros dias deve ser apetitosa, com boa fibra e mais proteína, para que os recém-chegados comam logo.","s":[{"h":"Objetivos","p":["Que o animal comece a comer nas primeiras 24 a 48 horas.","Recuperar a água e o peso perdidos na viagem.","Acostumar o rúmen ao concentrado sem risco."]},{"h":"Como é","p":["Feno ou capim seco de boa qualidade à vontade nos primeiros dias.","Concentrado de 13 a 15 % de proteína, aos poucos.","Forragem de 40 a 60 % da ração.","Minerais e vitaminas completos."]},{"h":"Manejo","p":["Sirva o feno em cima do concentrado para que o encontrem.","Cochos limpos e fáceis de ver.","Bebedouros com água correndo para que a escutem.","Observe quem não se aproxima para comer: costumam ser os primeiros doentes."]},{"h":"Números","p":["Um recém-chegado come 1,5 a 2 % do seu peso em matéria seca na primeira semana.","O consumo normal é alcançado em 2 a 3 semanas."]}],"rel":["Recepção de gado","Adaptação ao concentrado","Proteína na ração"]},{"t":"Ração de crescimento","a":"nutricion","r":"Etapa intermediária em que o animal cresce esqueleto e músculo. Busca bom ganho com custo moderado.","s":[{"h":"Quando","p":["Animais leves (menos de 300 kg) antes de passar à terminação.","Ou em semiconfinamento com pasto mais suplemento."]},{"h":"Como é","p":["Proteína de 12 a 13 %.","Forragem de 25 a 40 % da ração.","Energia média: 68 a 72 % de NDT."]},{"h":"Ganhos esperados","p":["1,0 a 1,3 kg por dia no curral com ração balanceada.","0,6 a 0,9 kg por dia no pasto com suplemento."]},{"h":"Quando passar à terminação","p":["Quando o animal chega a uns 350 kg ou faltam 90 a 120 dias para a venda.","Quando o preço do grão torna rentável acelerar o ganho."]}],"rel":["Ração de terminação","Crescimento compensatório","Suplementação no pasto"]},{"t":"Ração de terminação","a":"nutricion","r":"É a ração com mais energia, para ganhar peso rápido e dar boa cobertura de gordura antes da venda.","s":[{"h":"Como é","p":["Energia alta: 75 a 80 % de NDT.","Proteína de 11 a 12 %.","Forragem de 10 a 15 % para cuidar do rúmen.","Núcleo mineral completo, com cálcio extra por causa do grão."]},{"h":"Ganhos esperados","p":["1,3 a 1,8 kg por dia em novilhos cruzados bem adaptados.","Conversão de 6 a 8 kg de alimento por kg de ganho."]},{"h":"Duração","p":["Normalmente 60 a 120 dias, conforme o peso de entrada e a meta.","Mais dias que o necessário pioram a conversão: o animal põe gordura, que custa mais."]},{"h":"Cuidados","p":["Leitura de cochos diária.","Horários fixos.","Vigiar fezes, mancadeiras e consumo.","Sombra e água de sobra: a ração de terminação produz mais calor."]}],"rel":["Adaptação ao concentrado","Grau de acabamento","Conversão alimentar"]},{"t":"Formular uma ração","a":"nutricion","r":"Formular é combinar ingredientes para cobrir o que o animal precisa ao menor custo. O app faz isso por você com seus preços.","s":[{"h":"Passos","p":["Defina o animal: peso e ganho que você busca.","Calcule o que precisa: matéria seca, energia, proteína, cálcio, fósforo.","Liste os ingredientes que você tem, com preço e valor nutritivo.","Busque a mistura que cumpre tudo ao menor custo.","Revise limites: forragem mínima, ureia máxima, gordura máxima."]},{"h":"Dados de cada ingrediente","p":["Matéria seca.","Energia (NDT ou energia líquida).","Proteína bruta.","Cálcio e fósforo.","Preço por quilo na sua fazenda, com frete incluído."]},{"h":"Comparar ingredientes","p":["Compare o preço por unidade de nutriente, não por saco.","Exemplo: preço de um quilo de proteína = preço por quilo ÷ (proteína % ÷ 100).","Um ingrediente barato com pouca matéria seca pode sair caro."]},{"h":"No app","p":["Em Mais, Rações e dietas, Formular dieta.","Coloque o peso, o ganho, ative os ingredientes que você tem e corrija os preços.","Guarde a mistura como ração e use-a ao anotar alimento."]},{"h":"Regras","p":["Analise seus ingredientes quando possível: as tabelas são médias.","Revise a fórmula sempre que os preços mudarem muito.","Consulte um nutricionista para rações com subprodutos pouco comuns."]}],"rel":["Custo da ração","Análise de ingredientes","Matéria seca e consumo"]},{"t":"Milho e outros grãos","a":"nutricion","r":"Os grãos são a principal fonte de energia do confinamento. Como são processados muda quanto o animal aproveita.","s":[{"h":"Milho","p":["Alto em energia (cerca de 85 a 90 % de NDT) e baixo em proteína (8 a 9 %).","Inteiro é menos aproveitado: parte sai no esterco.","Quebrado ou laminado grosso é o mais usado; moído muito fino aumenta a acidose."]},{"h":"Sorgo","p":["Um pouco menos de energia que o milho e grão mais duro.","É preciso moer ou laminar: inteiro quase não é digerido.","Algumas variedades têm taninos que baixam a digestão da proteína."]},{"h":"Arroz e outros","p":["Arroz quebrado ou quirera: boa energia, fermenta rápido.","Trigo e cevada: fermentação muito rápida; usar com cuidado."]},{"h":"Qualidade","p":["Grão seco (menos de 14 % de umidade) para guardar.","Sem mofo, sem cheiro de umidade, sem carunchos.","Verifique micotoxinas em compras grandes."]},{"h":"Regras","p":["Misture grãos diferentes para baixar o risco de acidose e aproveitar preços.","Não passe de 70 a 80 % de grão na ração total sem assessoria.","Compre na colheita quando o preço está mais baixo, se tiver bom armazém."]}],"rel":["Energia na ração","Acidose ruminal","Armazenamento do alimento"]},{"t":"Farelo de soja e outras proteínas","a":"nutricion","r":"Os farelos de oleaginosas são a proteína vegetal mais usada. Escolher bem pelo preço por quilo de proteína economiza muito dinheiro.","s":[{"h":"Farelo de soja","p":["44 a 48 % de proteína, muito digestível e confiável.","Costuma ser o mais caro por saco, mas nem sempre por quilo de proteína."]},{"h":"Torta de palmiste","p":["14 a 18 % de proteína e bastante fibra e gordura.","Barata em regiões de palma; boa para crescimento."]},{"h":"Farelo de algodão","p":["35 a 40 % de proteína.","Contém gossipol, tóxico em excesso para animais jovens: limite o uso."]},{"h":"Outras","p":["DDGS ou grãos de destilaria: proteína e energia, verificar enxofre.","Farelo de gergelim e de amendoim: conforme disponibilidade e qualidade (cuidado com aflatoxinas no amendoim)."]},{"h":"Como decidir","p":["Calcule o preço por quilo de proteína de cada um.","Combine um de alta qualidade (soja) com outro barato.","Revise umidade e cheiro: farelos úmidos embolorecem."]}],"rel":["Proteína na ração","Subprodutos para a ração","Formular uma ração"]},{"t":"Ureia na ração","a":"nutricion","r":"A ureia é a proteína mais barata porque os micróbios a transformam em proteína. Bem usada economiza muito; mal usada mata.","s":[{"h":"Como funciona","p":["A ureia vira amônia no rúmen.","Os micróbios usam essa amônia junto com energia para fazer proteína.","Sem energia suficiente, a amônia passa para o sangue e envenena."]},{"h":"Limites","p":["Máximo 1 % da ração total em matéria seca.","Não mais de um terço da proteína total.","Em sais proteinados ou blocos, conforme a formulação do fabricante."]},{"h":"Como usar","p":["Adapte em 1 a 2 semanas começando com a metade.","Misture muito bem: primeiro com uma parte pequena do alimento.","Sempre com grão ou melaço e com enxofre.","Nunca na água de bebida."]},{"h":"Não use","p":["Em animais magros, em jejum ou doentes.","Em bezerros muito jovens.","Se não conseguir misturá-la por igual."]}],"rel":["Intoxicação por ureia","Proteína na ração","Melaço"]},{"t":"Melaço","a":"nutricion","r":"O melaço dá energia rápida, melhora o sabor e segura o pó da ração. É um bom aliado em quantidades moderadas.","s":[{"h":"Valor","p":["Cerca de 70 a 75 % de matéria seca, rico em açúcares.","Pouca proteína.","Fornece potássio e enxofre."]},{"h":"Quanto usar","p":["5 a 10 % da ração no curral é o mais comum.","Mais de 15 % pode dar diarreia e problemas se não for bem formulado."]},{"h":"Usos","p":["Melhorar o sabor de rações com subprodutos ou forragens grosseiras.","Reduzir o pó e evitar que o animal selecione.","Veículo para ureia em suplementos de pasto (melaço-ureia), com formulação correta."]},{"h":"Cuidados","p":["Guarde em tanque tampado para não cair água.","No frio fica espesso; dilua com pouca água ao misturar.","Não deixe melaço com ureia exposto à chuva."]}],"rel":["Energia na ração","Ureia na ração","Mistura da ração"]},{"t":"Subprodutos para a ração","a":"nutricion","r":"Os subprodutos da agroindústria podem baixar muito o custo da ração se forem conhecidos seus limites.","s":[{"h":"Polpa cítrica","p":["Energia parecida com um grão, mas com fibra digestível: menos risco de acidose.","Alta em cálcio.","Fresca estraga rápido; seca ou ensilada se conserva melhor."]},{"h":"Casca de soja","p":["Fibra muito digestível e energia moderada.","Boa para baixar o grão sem perder energia."]},{"h":"Farelo de trigo, farelo de arroz","p":["Energia média e proteína de 12 a 16 %.","Alto em fósforo: cuidar do cálcio.","O farelo de arroz ranceia rápido."]},{"h":"Banana de descarte","p":["Energia com muita água (pouca matéria seca).","Fornece-se picada, misturada com fonte de proteína e fibra.","Cuidado com o látex da verde e com o custo do transporte por causa da água."]},{"h":"Polpa e casca de café, cacau","p":["Têm cafeína, taninos ou teobromina: use em pouca quantidade e com assessoria.","Melhor ensiladas ou secas."]},{"h":"Regras","p":["Peça análise ou dados confiáveis de cada subproduto.","Calcule o custo por matéria seca, incluindo o frete.","Introduza-os aos poucos.","Verifique que não tragam contaminantes, plásticos nem químicos."]}],"rel":["Formular uma ração","Custo da ração","Análise de ingredientes"]},{"t":"Cama de frango","a":"nutricion","r":"São camas de aves usadas como proteína barata. Têm riscos sanitários e legais importantes que é preciso conhecer antes de usar.","s":[{"h":"Riscos","p":["Pode trazer restos de medicamentos das aves, metais, penas, vidro e terra.","Transmite salmonela, clostrídios e botulismo se não for tratada.","Em muitos países seu uso em ruminantes é proibido ou regulado pelo risco de encefalopatia (vaca louca) e de resíduos.","Alguns mercados e frigoríficos não compram animais alimentados com cama de aves."]},{"h":"Antes de usar","p":["Consulte a norma vigente com o SENASA e os requisitos do seu comprador.","Se permitido, só material tratado (compostado ou ensilado) e de origem conhecida.","Nunca cama de aves com restos de farinha de carne ou de ossos."]},{"h":"Alternativas","p":["Ureia bem usada com melaço ou grão.","Farelos vegetais e leguminosas forrageiras."]}],"rel":["Produtos proibidos na alimentação","Proteína na ração","Boas práticas pecuárias"]},{"t":"Silagem na ração","a":"nutricion","r":"A silagem de milho ou sorgo é uma forragem com boa energia que se guarda para o ano todo. Bem feita é a base de muitos confinamentos.","s":[{"h":"Valor","p":["Silagem de milho: 30 a 35 % de matéria seca e boa energia pelo grão.","Silagem de sorgo ou de capim: menos energia, mais fibra.","A proteína é baixa (7 a 9 %): é preciso completá-la."]},{"h":"Quanto dar","p":["No crescimento pode ser 40 a 60 % da matéria seca.","Na terminação é usada como a forragem da ração (10 a 25 %)."]},{"h":"Qualidade ao usar","p":["Cheiro agradável, de vinagre suave ou fruta.","Cor verde-amarelada, não marrom-escura nem preta.","Sem mofo branco ou azul, nem partes quentes.","Descarte as partes estragadas: dão diarreias, abortos e baixam o consumo."]},{"h":"Manejo no cocho","p":["Tire só o que será comido nesse dia.","Não deixe ao sol horas antes de servir.","Misture com o concentrado para que não selecionem."]}],"rel":["Silagem: como fazer","Silagem: qualidade e problemas","Fibra e forragem na ração"]},{"t":"Feno e capim de corte na ração","a":"nutricion","r":"A forragem picada dá a fibra que o rúmen precisa. Sua qualidade muda muito conforme a idade de corte e como é guardada.","s":[{"h":"Capim de corte fresco","p":["Capim King grass, Cuba OM-22, Maralfalfa, Taiwan: muita produção por hectare.","Corte com 50 a 70 dias na época de chuva: mais velho fica lenhoso e pobre.","Pique em 2 a 5 cm e sirva no mesmo dia: picado de um dia para o outro esquenta e fermenta."]},{"h":"Feno","p":["Capim cortado, seco ao sol e guardado em fardos.","Bom feno: verde, com folhas, cheiro agradável, sem pó nem mofo.","Feno amarelo, cheio de talos ou com cheiro de umidade alimenta pouco."]},{"h":"Restolhos e palhas","p":["Restolho de milho ou sorgo, palha de arroz: muita fibra e pouca proteína.","Servem como fibra efetiva na terminação, não como alimento principal.","Melhoram com melaço e ureia bem formulados."]},{"h":"Quanto","p":["Veja Fibra e forragem na ração: 10 a 15 % na terminação e mais no início.","Pese a forragem que serve: é fácil dar demais ou de menos no olho."]}],"rel":["Fibra e forragem na ração","Capins de corte","Feno: como fazer e guardar"]},{"t":"Cana-de-açúcar na ração","a":"nutricion","r":"A cana produz muita energia por hectare e aguenta a seca. Tem pouca proteína, então é preciso completá-la.","s":[{"h":"Valor","p":["Rica em açúcares, pobre em proteína (2 a 4 %) e minerais.","Sua fibra é pouco digestível."]},{"h":"Como usar","p":["Corte madura, com mais açúcar, na época seca.","Pique fina e forneça no mesmo dia: picada velha azeda.","Complete com fonte de proteína (ureia bem usada, farelos ou leguminosas) e minerais."]},{"h":"Limites","p":["Como parte da forragem no crescimento funciona bem.","Sozinha não permite ganhos altos.","Com ureia, siga as regras de adaptação e mistura."]}],"rel":["Cana-de-açúcar como forragem","Ureia na ração","Ração para a época seca"]},{"t":"Aditivos na ração","a":"nutricion","r":"Os aditivos não são alimento, mas melhoram a digestão ou previnem problemas. Use só com assessoria e produtos registrados.","s":[{"h":"Ionóforos","p":["Como a monensina ou a lasalocida: melhoram a conversão e ajudam contra coccídios e timpanismo.","Dose exata: em excesso são tóxicos, e mortais para cavalos e cães que comam a ração.","Mistura perfeita na ração e armazém separado."]},{"h":"Tamponantes","p":["Bicarbonato de sódio ou óxido de magnésio: ajudam a controlar o ácido do rúmen em rações com muito grão."]},{"h":"Leveduras e probióticos","p":["Podem melhorar o consumo e estabilizar o rúmen no início.","Resultados variáveis: meça nos seus lotes."]},{"h":"Sequestrantes de micotoxinas","p":["Argilas e outros produtos que prendem toxinas de fungos.","Não substituem um bom armazenamento."]},{"h":"Regras","p":["Produtos registrados e dose do fabricante.","Anote qual aditivo cada ração usa.","Nunca use substâncias proibidas para engordar."]}],"rel":["Acidose ruminal","Coccidiose","Produtos proibidos na alimentação"]},{"t":"Sal mineral e blocos","a":"nutricion","r":"No pasto, o sal mineral à vontade é a forma mais barata de corrigir a falta de minerais. Os blocos e sais proteinados acrescentam proteína.","s":[{"h":"Sal mineral","p":["Deve ter fósforo (6 a 10 % em regiões tropicais), cálcio e microminerais.","Consumo esperado: 60 a 100 gramas por animal por dia.","O sal branco sozinho não cobre o que falta."]},{"h":"Saleiros","p":["Cobertos para que não molhe nem endureça.","Perto da água e das áreas onde descansam.","Espaço para vários animais ao mesmo tempo.","Revise e reponha a cada poucos dias."]},{"h":"Blocos multinutricionais","p":["Mistura de melaço, ureia, minerais e um aglutinante.","Fornecem proteína e energia na época seca a animais no pasto.","O consumo é limitado pela dureza do bloco."]},{"h":"Sais proteinados","p":["Sal com fonte de proteína (ureia ou farelos) para pasto seco.","Seguem as regras da ureia: adaptar e não dar a animais magros ou em jejum."]}],"rel":["Minerais principais","Suplementação no pasto","Deficiências de minerais"]},{"t":"Leitura de cochos","a":"nutricion","r":"Revisar quanto sobra no cocho antes de servir diz se você está dando demais ou de menos. É a ferramenta mais útil do confinador.","s":[{"h":"Como fazer","p":["Revise no mesmo horário todo dia, antes da primeira entrega.","Olhe o cocho inteiro, de ponta a ponta."]},{"h":"Escala simples","p":["0: cocho limpo e lambido, animais esperando: suba a quantidade 5 %.","1: sobram migalhas espalhadas: está bem, mantenha.","2: sobra uma camada fina de alimento: baixe 5 %.","3: sobra muito alimento: baixe 10 % e verifique se há um problema.","No app você pode anotar a leitura em cada entrega."]},{"h":"Regras","p":["Ajuste em passos pequenos.","Não suba mais de 0,5 kg por animal por dia.","Se sobra comida vários dias seguidos, revise saúde, água, calor e a ração.","Se o cocho fica vazio por horas, o lote come com ansiedade e sobe o risco de acidose."]},{"h":"Erros comuns","p":["Encher o cocho até em cima 'para não faltar'.","Deixar a comida velha e jogar a nova por cima.","Mudar a quantidade todo dia sem critério."]}],"rel":["Acidose ruminal","Horários de alimentação","Desperdício de alimento"]},{"t":"Horários de alimentação","a":"nutricion","r":"Servir no mesmo horário todos os dias mantém estáveis o rúmen e o consumo. Os animais se acostumam aos horários.","s":[{"h":"Quantas vezes","p":["Duas a três entregas por dia é o mais comum.","Mais entregas reduzem a acidose e o alimento que esquenta no cocho."]},{"h":"Horário de exemplo","p":["Primeira entrega cedo, 6:00 a 7:00.","Segunda no meio da manhã ou ao meio-dia.","Terceira no fim da tarde, 15:00 a 16:00.","Com calor forte, carregue mais alimento cedo e à tarde."]},{"h":"Regras","p":["Mesma ordem de currais todo dia.","Não atrase mais de 30 minutos.","Distribua por igual ao longo do cocho.","No app você define seus horários em Mais, Configurações, e a tela Hoje diz quanto falta dar."]}],"rel":["Leitura de cochos","Rotina diária da engorda","Estresse por calor"]},{"t":"Mistura da ração","a":"nutricion","r":"Uma ração bem formulada mas mal misturada é outra ração. Cada bocado deve ter o mesmo.","s":[{"h":"Ordem de carga","p":["Primeiro os ingredientes em maior quantidade (grãos, forragem).","Depois os médios (farelos, subprodutos).","Os pequenos (núcleo mineral, ureia, aditivos) misturados antes com uma parte do alimento (pré-mistura).","O melaço ou líquidos por último, distribuídos."]},{"h":"Tempo","p":["Misturador: siga o tempo do fabricante, geralmente 3 a 6 minutos depois da última carga.","Misturar demais separa partículas e mói a forragem."]},{"h":"Mistura manual","p":["Em piso limpo, vire com pá pelo menos 3 a 4 vezes.","Faça bateladas pequenas para ficar uniforme.","Pese cada ingrediente: baldes e pás enganam."]},{"h":"Como revisar","p":["Veja que não haja bolos de minerais ou ureia.","A cor e a textura devem ser iguais em todo o cocho.","Se os animais fuçam e selecionam, a mistura não está uniforme ou a forragem está longa demais."]}],"rel":["Intoxicação por ureia","Misturador e equipamentos","Formular uma ração"]},{"t":"Armazenamento do alimento","a":"nutricion","r":"O armazém protege seu investimento. O alimento molhado, com mofo ou comido por pragas é dinheiro perdido e doença.","s":[{"h":"O armazém","p":["Telhado sem goteiras, piso de cimento e paredes que não deixem passar chuva.","Boa ventilação.","Sacos sobre paletes, afastados da parede pelo menos 30 cm.","Minerais, medicamentos e químicos em lugares separados do alimento."]},{"h":"Manejo","p":["Primeiro que entra, primeiro que sai.","Revise umidade, cheiro e temperatura dos grãos toda semana.","Não compre mais do que consegue guardar bem.","Feche bem os sacos abertos."]},{"h":"Sinais de problema","p":["Cheiro de umidade ou de mofo.","Grão quente, empedrado ou com teias.","Carunchos, traças ou fezes de ratos."]},{"h":"O que fazer com alimento estragado","p":["Não dê ao gado.","Separe o estragado do bom.","Se tiver dúvida, peça uma análise de micotoxinas."]}],"rel":["Controle de pragas no armazém","Intoxicação por plantas e fungos","Depósito de ração"]},{"t":"Controle de pragas no armazém","a":"nutricion","r":"Ratos, camundongos, aves e insetos comem o alimento, sujam e trazem doenças como leptospirose e salmonela.","s":[{"h":"Ratos e camundongos","p":["Vede buracos, coloque telas nas janelas e sob as portas.","Mantenha limpo ao redor do armazém, sem mato nem lixo.","Use armadilhas e iscas em estações fechadas, longe do alcance do gado, cães e crianças."]},{"h":"Aves","p":["Telas nos beirais e aberturas.","Não deixe alimento espalhado fora do armazém."]},{"h":"Insetos","p":["Carunchos e traças nos grãos: rotação do estoque e limpeza.","Tratamentos só com produtos autorizados para grãos e respeitando os prazos."]},{"h":"Registro","p":["Anote datas de colocação e revisão das iscas.","Revise toda semana."]}],"rel":["Armazenamento do alimento","Leptospirose","Depósito de ração"]},{"t":"Conversão alimentar","a":"nutricion","r":"A conversão diz quantos quilos de alimento o animal precisa para ganhar um quilo. É o número que mais define seu custo.","s":[{"h":"Como se calcula","p":["Conversão = quilos de alimento consumido ÷ quilos ganhos no mesmo período.","Calcula-se melhor em matéria seca.","Exemplo: comeram 700 kg e ganharam 100 kg: conversão de 7 para 1."]},{"h":"Valores de referência","p":["Terminação no curral com boa ração: 6 a 8 kg de alimento como oferecido por quilo ganho.","O início e os animais leves convertem melhor.","Animais pesados e muito gordos convertem pior."]},{"h":"Como melhorá-la","p":["Ração balanceada, sem excesso de proteína nem falta de energia.","Menos desperdício nos cochos.","Animais sadios, vermifugados e sem estresse.","Vender a tempo: os últimos quilos custam mais.","Água e sombra suficientes.","Processar bem o grão."]},{"h":"No app","p":["O app calcula a conversão de cada lote com o alimento que você anota e as pesagens.","Se você não anota todo o alimento, a conversão sai melhor do que a real."]}],"rel":["Custo por quilo ganho","Desperdício de alimento","Quando vender"]},{"t":"Consumo baixo","a":"nutricion","r":"Quando um lote come menos que o normal, algo está errado. É preciso encontrar a causa rápido.","s":[{"h":"Causas a revisar primeiro","p":["Água: bebedouro vazio, sujo, boia estragada.","Calor forte sem sombra suficiente.","Alimento com mofo, mau cheiro ou misturado diferente.","Mudança brusca de ração ou de ingrediente.","Acidose subaguda por excesso de grão.","Doença no lote (pneumonia, parasitas)."]},{"h":"Como investigar","p":["Compare com os dias anteriores no app.","Veja se é um animal ou o lote inteiro.","Cheire e olhe o alimento, revise o armazém.","Olhe as fezes e conte quantos ruminam deitados.","Meça a temperatura dos que não se aproximam."]},{"h":"O que fazer","p":["Corrija a água e o alimento primeiro.","Baixe a ração um passo se suspeitar de acidose e suba aos poucos.","Chame o veterinário se houver febre ou vários abatidos."]},{"h":"Aviso no app","p":["O app avisa em Hoje quando um lote comeu ontem menos que sua média da semana."]}],"rel":["Acidose ruminal","Água de bebida","Estresse por calor"]},{"t":"Suplementação no pasto","a":"nutricion","r":"No pasto, o capim dá a base e o suplemento cobre o que falta. Bem feito permite ganhar peso até na seca.","s":[{"h":"O que falta conforme a época","p":["Chuvas: o pasto tem água e proteína, falta energia e minerais.","Seca: pasto seco com pouca proteína; falta proteína, energia e minerais."]},{"h":"Opções","p":["Sal mineral sempre.","Sais proteinados ou blocos na seca.","Concentrado de 0,5 a 1 % do peso vivo para ganhar mais.","Semiconfinamento: pasto de dia e ração no curral à tarde."]},{"h":"Ganhos esperados","p":["Só pasto nas chuvas: 0,4 a 0,7 kg por dia.","Pasto mais suplemento bem feito: 0,7 a 1 kg por dia.","Semiconfinamento com boa ração: 0,9 a 1,2 kg por dia."]},{"h":"Regras","p":["Suplemente no mesmo horário todo dia.","Cochos suficientes para que todos comam ao mesmo tempo.","Calcule se o quilo extra ganho paga o suplemento."]}],"rel":["Engorda a pasto","Engorda em semiconfinamento","Sal mineral e blocos"]},{"t":"Crescimento compensatório","a":"nutricion","r":"Um animal que passou fome e depois come bem ganha mais rápido que um que sempre esteve bem. Dá para aproveitar na compra.","s":[{"h":"Como funciona","p":["Depois de um período de restrição, o animal come mais e converte melhor por um tempo.","O efeito dura de 1 a 3 meses."]},{"h":"Como aproveitar","p":["Comprar animais magros mas sadios, a bom preço por quilo.","Dar boa ração desde a adaptação.","Medir o ganho real no app nas primeiras pesagens."]},{"h":"Cuidados","p":["Um animal magro por doença ou parasitas não compensa igual.","Restrições muito longas ou muito fortes deixam animais pequenos para sempre.","Revise dentes, patas e saúde antes de comprar magros."]}],"rel":["Comprar gado para engorda","Ração de crescimento","Animais atrasados"]},{"t":"Grau de acabamento","a":"nutricion","r":"O acabamento é a cobertura de gordura do animal na venda. Define o rendimento de carcaça e o preço em muitos mercados.","s":[{"h":"Como se vê","p":["Costelas cobertas, que não aparecem.","Base da cauda com gordura dos lados.","Peito e paleta cheios.","Lombo largo e uniforme."]},{"h":"Condição corporal","p":["Escala de 1 (muito magro) a 9 (muito gordo) em gado de corte.","Para venda por carcaça busca-se 5 a 6, conforme o comprador.","Passar de 7 é colocar gordura cara que muitas vezes é aparada."]},{"h":"Por que importa","p":["Melhor rendimento de carcaça.","Carne com melhor apresentação.","Mas cada quilo de gordura custa mais alimento que um quilo de músculo."]},{"h":"Regra prática","p":["Pergunte ao seu comprador qual acabamento paga melhor.","Venda quando chegar a esse acabamento, não depois."]}],"rel":["Quando vender","Rendimento de carcaça","Ração de terminação"]},{"t":"Promotores de crescimento e implantes","a":"nutricion","r":"Existem produtos hormonais e não hormonais que aumentam o ganho. Seu uso depende da lei e do mercado para o qual você vende.","s":[{"h":"O que são","p":["Implantes: pequenas cápsulas colocadas sob o couro da orelha que liberam hormônios por semanas.","Outros promotores vão na ração."]},{"h":"Regras","p":["Só produtos registrados e permitidos no país.","Aplicação correta na orelha, com higiene.","Respeite os tempos de carência.","Alguns compradores e mercados de exportação não aceitam animais implantados: pergunte antes."]},{"h":"Proibidos","p":["O clembuterol e outros beta-agonistas não autorizados são proibidos: prejudicam a saúde das pessoas.","Usar substâncias proibidas traz condenações, multas e fechamento de mercados."]},{"h":"Recomendação","p":["Decida com seu veterinário e conforme seu mercado.","Um bom manejo, sanidade e ração dão mais resultado que qualquer produto."]}],"rel":["Produtos proibidos na alimentação","Carências e resíduos","Boas práticas pecuárias"]},{"t":"Ração para a época seca","a":"nutricion","r":"Na seca o pasto cai em quantidade e qualidade. Planejar a forragem e ajustar a ração evita perder o que foi ganho.","s":[{"h":"O que muda","p":["Pasto seco com pouca proteína e pouca digestibilidade.","Menos consumo se só houver pasto seco.","O calor aumenta a necessidade de água."]},{"h":"Opções de forragem","p":["Silagem de milho ou sorgo feita nas chuvas.","Feno guardado.","Cana-de-açúcar picada.","Capim de corte irrigado.","Restolhos melhorados com melaço e ureia."]},{"h":"Ajustes da ração","p":["Mais proteína para aproveitar a forragem seca.","Minerais e vitamina A reforçados.","Água de sobra e na sombra."]},{"h":"Plano","p":["Calcule no app quanto alimento precisa por mês e compre o grão na colheita.","Decida se compra animais no início da seca, quando costumam estar baratos, só se tiver a forragem garantida."]}],"rel":["Plano forrageiro para a seca","Época seca","Cana-de-açúcar na ração"]},{"t":"Alimentação com calor","a":"nutricion","r":"O calor baixa o consumo e o ganho. Ajustar horários e ração ajuda a que continuem comendo.","s":[{"h":"Ajustes","p":["Sirva 60 a 70 % da ração à tarde e à noite, quando refresca.","Evite servir ao meio-dia.","Não suba o grão em dias de calor forte.","Mantenha a fibra para que o rúmen não esquente com acidose."]},{"h":"Água e sais","p":["Mais bebedouros ou mais vazão.","Sal e potássio suficientes na ração.","Água fresca: tanques na sombra."]},{"h":"Sinais de que falta","p":["Consumo que cai nas tardes quentes.","Ofegância no cocho.","Animais amontoados na sombra sem comer."]}],"rel":["Estresse por calor","Golpe de calor","Horários de alimentação"]},{"t":"Análise de ingredientes","a":"nutricion","r":"As tabelas de nutrientes são médias. Uma análise de laboratório dos seus ingredientes torna a ração mais exata e economiza dinheiro.","s":[{"h":"O que analisar","p":["Matéria seca (umidade).","Proteína bruta.","Fibra (FDN e FDA).","Energia estimada.","Cálcio e fósforo.","Micotoxinas em grãos suspeitos."]},{"h":"Como tirar a amostra","p":["Pegue pedacinhos de vários sacos ou vários pontos do silo.","Misture e tire uma amostra de meio a um quilo.","Saco lacrado, sem ar, e leve logo ao laboratório.","Rotule com data, ingrediente e fornecedor."]},{"h":"Quando","p":["Cada silagem nova.","Cada troca de fornecedor de um subproduto.","Quando os animais não dão o ganho esperado."]},{"h":"Usar os resultados","p":["Corrija os valores na sua formulação.","Compare fornecedores por nutrientes, não só por preço."]}],"rel":["Formular uma ração","Subprodutos para a ração","Silagem: qualidade e problemas"]},{"t":"Custo da ração","a":"nutricion","r":"O alimento é o maior custo depois da compra de animais. Pequenas economias por quilo se multiplicam em centenas de animais.","s":[{"h":"Como calcular","p":["Custo por quilo de mistura = soma de (preço de cada ingrediente × sua porcentagem).","Inclua frete, moagem e perdas.","Custo de alimento por quilo ganho = custo por quilo de mistura × conversão."]},{"h":"Como baixá-lo","p":["Formule ao menor custo com seus preços reais.","Use subprodutos locais bem analisados.","Compre o grão na colheita se tiver armazém.","Reduza o desperdício nos cochos e no armazém.","Melhore a conversão: é mais poderoso que baixar o preço."]},{"h":"Cuidado","p":["A ração mais barata nem sempre dá o quilo ganho mais barato.","Se o ganho cai, sobe o custo fixo por dia de cada animal."]},{"h":"No app","p":["Formular dieta dá o custo por quilo e por animal por dia.","Os gráficos mostram o custo por quilo ganho de cada lote."]}],"rel":["Formular uma ração","Custo por quilo ganho","Desperdício de alimento"]},{"t":"Desperdício de alimento","a":"nutricion","r":"O alimento que cai no chão, molha ou é comido pelas pragas não engorda ninguém. Reduzi-lo é lucro direto.","s":[{"h":"Onde se perde","p":["Cochos sem barreira ou muito baixos: jogam no chão.","Chuva sobre cochos sem cobertura.","Alimento que esquenta e estraga no cocho.","Pássaros, ratos e cães.","Mistura ruim: selecionam e deixam o que não gostam.","Sacos rasgados no armazém e no transporte."]},{"h":"Como reduzir","p":["Barreira de tubo ou cabo sobre o cocho.","Cobertura ou cocho com beiral.","Servir a quantidade certa conforme a leitura de cocho.","Limpar sobras velhas antes de servir.","Controle de pragas."]},{"h":"Quanto custa","p":["Um desperdício de 5 % num lote de 100 animais que come 1.000 kg por dia são 50 kg diários: 1.500 kg por mês."]}],"rel":["Leitura de cochos","Cochos","Controle de pragas no armazém"]},{"t":"Polpa cítrica","a":"nutricion","r":"Subproduto da indústria de sucos. Dá energia parecida com um grão, mas com fibra digestível, o que baixa o risco de acidose.","s":[{"h":"Valor","p":["Energia alta (NDT cerca de 75 a 80 % na matéria seca).","Proteína baixa (6 a 7 %).","Rica em cálcio e pobre em fósforo."]},{"h":"Uso","p":["Pode substituir parte do grão: até 25 a 30 % da ração.","Boa na adaptação e em rações para o calor."]},{"h":"Cuidados","p":["Fresca estraga em poucos dias: use rápido ou ensile.","Seca ou peletizada se conserva melhor.","Ajuste o fósforo da ração."]}],"rel":["Subprodutos para a ração","Energia na ração","Minerais principais"]},{"t":"Torta de palmiste","a":"nutricion","r":"Subproduto do dendê, muito disponível em regiões de palma. Fornece proteína média, fibra e gordura.","s":[{"h":"Valor","p":["Proteína de 14 a 18 %.","Fibra alta e gordura de 6 a 10 % conforme o processo.","Energia média."]},{"h":"Uso","p":["Boa para crescimento e como parte da terminação.","Até 20 a 30 % da ração.","Pouco apetitosa sozinha: misture com melaço ou grão."]},{"h":"Cuidados","p":["A gordura ranceia: compre fresca e guarde seca.","Verifique que não traga casca dura em excesso."]}],"rel":["Farelo de soja e outras proteínas","Subprodutos para a ração"]},{"t":"Casca de soja","a":"nutricion","r":"A casca do grão de soja. Fibra muito digestível que dá energia sem o risco do amido.","s":[{"h":"Valor","p":["Energia próxima de 75 % de NDT.","Proteína de 10 a 12 %.","Fibra alta, mas muito digestível."]},{"h":"Uso","p":["Substitui parte do grão ou da forragem.","Útil em rações iniciais e com calor."]},{"h":"Cuidados","p":["Não é fibra efetiva: não substitui toda a forragem longa.","É leve: ocupa muito volume no armazém."]}],"rel":["Subprodutos para a ração","Fibra e forragem na ração"]},{"t":"Grãos de destilaria (DDGS)","a":"nutricion","r":"O que sobra do milho depois de fazer etanol. Rico em proteína, energia e gordura.","s":[{"h":"Valor","p":["Proteína de 26 a 32 %.","Energia alta pela gordura e pela fibra digestível.","Alto em fósforo e às vezes em enxofre."]},{"h":"Uso","p":["Até 20 a 30 % da ração no confinamento, conforme o enxofre.","Substitui parte do farelo de soja e do grão."]},{"h":"Cuidados","p":["O enxofre alto causa polioencefalomalácia: peça a análise.","Ajuste o cálcio pelo fósforo alto.","Verifique micotoxinas."]}],"rel":["Polioencefalomalácia","Farelo de soja e outras proteínas","Análise de ingredientes"]},{"t":"Banana e plátano de descarte","a":"nutricion","r":"Fruta de descarte que abunda em regiões bananeiras. Dá energia barata, mas com muita água.","s":[{"h":"Valor","p":["Verde: amido; madura: açúcares.","Só 18 a 25 % de matéria seca: a maior parte é água.","Muito baixa em proteína e minerais."]},{"h":"Uso","p":["Picada, misturada com fonte de proteína, fibra e minerais.","Pode ser uma parte importante da energia se o custo por matéria seca compensar."]},{"h":"Cuidados","p":["A verde tem látex que pode prender o intestino: misture bem.","Fermenta rápido: forneça no mesmo dia.","Calcule o preço por matéria seca, com frete incluído."]}],"rel":["Subprodutos para a ração","Matéria seca e consumo"]},{"t":"Mandioca e farinha de mandioca","a":"nutricion","r":"A raiz de mandioca é energia barata; a folha, proteína. É preciso manejar o cianeto de algumas variedades.","s":[{"h":"Raiz","p":["Rica em amido, pobre em proteína.","Seca e moída (farinha) ou picada e seca ao sol.","Substitui parte do grão."]},{"h":"Folha","p":["Proteína de 20 a 25 % na matéria seca.","É preciso secar ou ensilar para baixar o cianeto."]},{"h":"Cuidados","p":["A mandioca brava fresca pode intoxicar.","A secagem ao sol e a ensilagem baixam muito o risco.","Introduza aos poucos."]}],"rel":["Intoxicação por nitratos e cianeto","Energia na ração"]},{"t":"Gorduras e óleos na ração","a":"nutricion","r":"A gordura tem mais que o dobro da energia do grão. Em pouca quantidade ajuda; em excesso prejudica o rúmen.","s":[{"h":"Uso","p":["Sobe a energia sem mais amido.","Baixa o pó da ração.","Útil com calor: produz menos calor ao ser digerida."]},{"h":"Limites","p":["A ração total não deve passar de 5 a 6 % de gordura.","Mais gordura baixa a digestão da fibra e o consumo."]},{"h":"Fontes","p":["Óleos brutos, sebos, gorduras protegidas.","Farelos com gordura: palmiste, DDGS, farelo de arroz."]}],"rel":["Energia na ração","Alimentação com calor"]},{"t":"Concentrado comercial ou mistura própria","a":"nutricion","r":"Comprar concentrado pronto é cômodo; misturar na fazenda pode ser mais barato. A decisão depende dos seus números e da sua capacidade.","s":[{"h":"Concentrado comercial","p":["Qualidade constante e garantia do fabricante.","Sem necessidade de equipamento nem pessoal para misturar.","Mais caro por quilo."]},{"h":"Mistura própria","p":["Você pode usar ingredientes locais e subprodutos baratos.","Precisa de balança, misturador, armazém e controle.","Risco de erros se não pesar e misturar bem."]},{"h":"Como decidir","p":["Compare o custo por quilo de ganho, não o preço do saco.","Para poucos animais, o comercial ou um núcleo com grão costuma ser mais prático.","Com muitos animais, a mistura própria costuma pagar o equipamento."]},{"h":"Ler o rótulo","p":["Proteína bruta mínima.","Gordura e fibra.","Minerais e aditivos incluídos.","Data de fabricação: use antes de 30 a 60 dias."]}],"rel":["Formular uma ração","Custo da ração","Misturador e equipamentos"]},{"t":"Como ler as fezes","a":"nutricion","r":"O esterco é um relatório diário de como está o rúmen. Aprender a lê-lo avisa de problemas antes que os ganhos caiam.","s":[{"h":"Normal","p":["Formato de torta que se assenta, com leve afundamento no centro.","Cor marrom-esverdeada a marrom-escura conforme a ração."]},{"h":"Muito soltas","p":["Excesso de grão, acidose, proteína alta ou pasto muito novo.","Com bolhas e cheiro azedo: acidose."]},{"h":"Muito duras e em bolas","p":["Falta de água ou de proteína, forragem muito seca."]},{"h":"Com grãos inteiros","p":["Grão mal processado ou acidose.","Revise a moagem ou a laminação."]},{"h":"Com fibras longas","p":["Má digestão da fibra, falta de proteína ou passagem muito rápida."]},{"h":"Com sangue ou muco","p":["Coccidiose, infecção ou dano no intestino: consulte o veterinário."]}],"rel":["Acidose ruminal","Diarreia no confinamento","Milho e outros grãos"]},{"t":"Suplemento de melaço e ureia","a":"nutricion","r":"Uma mistura líquida ou em bloco para pastos secos. Dá energia e nitrogênio para que os animais aproveitem o pasto seco.","s":[{"h":"Como funciona","p":["A ureia dá nitrogênio aos micróbios.","O melaço dá a energia para usá-lo.","Assim digerem melhor o pasto seco e comem mais."]},{"h":"Uso","p":["Em cochos com boia ou blocos, à vontade com consumo controlado.","Formulação correta: a ureia não deve passar do limite recomendado.","Adaptação gradual."]},{"h":"Segurança","p":["Proteja da chuva: a ureia se concentra na água de cima.","Não dê a animais magros, em jejum ou doentes.","Sempre com minerais."]}],"rel":["Ureia na ração","Melaço","Sal mineral e blocos"]},{"t":"Uniformidade do lote","a":"nutricion","r":"Um lote uniforme come e ganha por igual. Quando há muita diferença, alguns animais atrasam e o lote não sai junto.","s":[{"h":"Como medir","p":["Compare o peso mais baixo e o mais alto do lote.","Veja quantos animais estão a mais de 10 % da média.","O app mostra a faixa de ganho do lote."]},{"h":"Causas de desuniformidade","p":["Compra de animais muito diferentes.","Pouco espaço de cocho: os dominantes comem mais.","Doenças em alguns animais."]},{"h":"Como melhorar","p":["Forme lotes por peso na compra.","Espaço de cocho suficiente.","Tire os atrasados para outro curral.","Venda por partes se não saírem juntos."]}],"rel":["Formar lotes","Animais atrasados","Espaço por animal"]},{"t":"Energia líquida e proteína degradável","a":"nutricion","r":"São formas mais precisas de medir o que o animal realmente aproveita. Os nutricionistas as usam para formular.","s":[{"h":"Energia líquida","p":["Energia líquida de manutenção: a que usa para viver.","Energia líquida de ganho: a que sobra para crescer e engordar.","As tabelas modernas (NRC) formulam com esses valores."]},{"h":"Proteína degradável e não degradável","p":["A degradável alimenta os micróbios do rúmen.","A não degradável passa para o intestino.","Uma ração precisa das duas conforme o peso e o ganho."]},{"h":"Para você","p":["O app já usa esses conceitos ao formular.","Se você trabalha com nutricionista, ele vai falar nesses termos."]}],"rel":["Energia na ração","Proteína na ração","Formular uma ração"]},{"t":"Ionóforos","a":"nutricion","r":"Os ionóforos, como a monensina e a lasalocida, são aditivos que mudam os micróbios do rúmen: sobem o ácido propiônico, baixam o metano e o risco de acidose e controlam a coccidiose.","s":[{"h":"O que conseguem","p":["Melhoram a conversão alimentar entre 5 e 8 % no curral.","No pasto podem subir o ganho uns 50 a 100 gramas por dia.","Reduzem timpanismo, acidose e coccidiose."]},{"h":"Como usar","p":["Sempre misturados por igual na ração ou no suplemento, na dose do rótulo.","Começar com dose baixa e subir em alguns dias.","Não são usados como antibióticos em pessoas, por isso muitos países os permitem."]},{"h":"Perigos","p":["São muito tóxicos para cavalos, burros, cães e aves de outras espécies: nunca deixe que comam ração com ionóforo.","Uma sobredose por mistura ruim pode matar bovinos."]},{"h":"No seu confinamento","p":["Pergunte ao fornecedor se o concentrado já traz ionóforo para não duplicar.","Guarde o produto longe dos cavalos."]}],"rel":["Aditivos na ração","Ácidos graxos voláteis","Coccidiose","Acidose ruminal"]},{"t":"Proteína de escape (by-pass)","a":"nutricion","r":"A proteína de escape é a parte da proteína do alimento que não se degrada no rúmen e chega direto ao intestino. É útil em animais jovens que crescem rápido.","s":[{"h":"Fontes","p":["Farelo de soja tostado ou tratado.","Grãos de destilaria (DDGS) e glúten de milho.","O farelo de algodão e a torta de palmiste têm uma parte de escape.","A farinha de peixe era comum, mas seu uso em ruminantes tem restrições em muitos países."]},{"h":"Quando convém","p":["Novilhos leves de 150 a 280 kg com ganho alto.","Rações com muita ureia, onde falta proteína verdadeira.","Animais recém-chegados que comem pouco."]},{"h":"No seu confinamento","p":["Primeiro cubra a proteína degradável, que é a mais barata.","Se seu lote é leve e o ganho não sobe, pergunte se falta proteína de escape."]}],"rel":["Proteína metabolizável","Farelo de soja e outras proteínas","Grãos de destilaria (DDGS)"]},{"t":"Amido e processamento de grãos","a":"nutricion","r":"O amido dos grãos é a principal fonte de energia das rações de confinamento. Como o grão é processado muda quanto amido é aproveitado.","s":[{"h":"Formas de processar","p":["Grão inteiro: digere-se menos; parte sai nas fezes, sobretudo em animais grandes.","Quebrado ou moído grosso: boa digestão e menos pó.","Moído fino: digere rápido, mas sobe o risco de acidose.","Floculado a vapor: a melhor digestão, mas precisa de equipamento industrial."]},{"h":"Velocidade de fermentação","p":["Trigo e cevada: muito rápidos, mais risco.","Milho: intermediário.","Sorgo: lento; precisa de moagem para ser aproveitado."]},{"h":"No seu confinamento","p":["Milho quebrado em 3 ou 4 pedaços é o mais prático para fazendas.","Se vir muito grão inteiro nas fezes, moa um pouco mais.","Moído fino como farinha, só com adaptação e boa fibra."]}],"rel":["Milho e outros grãos","Sorgo na ração","Acidose ruminal","Digestão no intestino"]},{"t":"Sorgo na ração","a":"nutricion","r":"O sorgo é um grão muito usado em regiões secas porque resiste à seca. Tem quase tanta energia quanto o milho, mas é pior digerido se não for bem moído.","s":[{"h":"Características","p":["Fornece cerca de 90 a 95 % da energia do milho quando bem processado.","O grão é duro e pequeno: inteiro escapa sem ser digerido.","Algumas variedades têm taninos que baixam a digestão da proteína."]},{"h":"Como usar","p":["Sempre moído ou quebrado.","Pode substituir todo ou parte do milho conforme o preço.","Prefira variedades de grão branco ou com poucos taninos."]},{"h":"Sorgo forrageiro","p":["A planta jovem e a rebrota depois da seca podem ter cianeto.","Espere a planta passar de 60 cm ou faça silagem para baixar o risco."]}],"rel":["Amido e processamento de grãos","Milho e outros grãos","Intoxicação por nitratos e cianeto"]},{"t":"Fibra efetiva","a":"nutricion","r":"Nem toda fibra faz ruminar. A fibra efetiva é a que tem comprimento e dureza suficientes para estimular a ruminação e a saliva, e assim proteger o rúmen.","s":[{"h":"Quanto é necessário","p":["Rações de confinamento intensivo: pelo menos 8 a 10 % de forragem na matéria seca, com partículas de 2 a 5 cm.","Rações iniciais: 30 a 50 % de forragem.","Menos fibra efetiva = mais risco de acidose e abscessos."]},{"h":"Fontes","p":["Feno ou capim picado grosso.","Restolho de milho ou sorgo picado.","Casca de algodão (fornece fibra efetiva apesar de ser pequena).","Os subprodutos finos como a casca de soja têm fibra, mas pouco efeito de ruminação."]},{"h":"No seu confinamento","p":["Conte os animais ruminando duas horas depois de comer: mais da metade deve estar ruminando.","Fezes muito líquidas e com bolhas indicam pouca fibra efetiva."]}],"rel":["Ruminação e saliva","Fibra e forragem na ração","Acidose ruminal","Casca de soja"]},{"t":"Gordura protegida","a":"nutricion","r":"A gordura protegida é tratada para que os micróbios do rúmen não a ataquem. Assim fornece muita energia sem prejudicar a digestão da fibra.","s":[{"h":"Tipos","p":["Sabões de cálcio de óleo de palma.","Gorduras hidrogenadas.","Caroço de algodão inteiro: sua casca protege parte do óleo."]},{"h":"Quando se usa","p":["Para subir a energia da ração sem mais grão.","Em épocas de calor: a gordura produz menos calor ao ser digerida que o amido ou a fibra.","É cara; usa-se mais na pecuária de leite que no confinamento."]},{"h":"No seu confinamento","p":["Se o preço permitir, 2 a 3 % de gordura extra na ração de terminação pode ajudar com o calor.","Não passe de 6 a 7 % de gordura total na ração."]}],"rel":["Gordura no rúmen","Gorduras e óleos na ração","Alimentação com calor"]},{"t":"Leveduras e probióticos","a":"nutricion","r":"As leveduras vivas e os probióticos são micróbios bons que se acrescentam à ração para estabilizar o rúmen e o intestino.","s":[{"h":"O que fazem","p":["As leveduras consomem oxigênio no rúmen e favorecem as bactérias que digerem fibra.","Podem estabilizar o pH e o consumo em animais recém-chegados.","Alguns probióticos competem com bactérias nocivas no intestino."]},{"h":"Resultados","p":["Os resultados são variáveis: melhores em animais estressados e na adaptação.","Raramente substituem um bom manejo."]},{"h":"No seu confinamento","p":["Podem ser úteis na ração de recepção.","Calcule se o custo se paga com menos doentes ou melhor consumo."]}],"rel":["Aditivos na ração","Ração inicial","Recepção de gado"]},{"t":"Óleos essenciais e extratos de plantas","a":"nutricion","r":"São compostos de plantas como orégano, alho, canela ou taninos estudados para melhorar a fermentação, baixar o metano e reduzir o uso de antibióticos.","s":[{"h":"O que se sabe","p":["Alguns baixam a degradação da proteína ou o metano.","Os taninos de leguminosas protegem a proteína e ajudam contra parasitas.","Os resultados variam muito entre produtos e doses."]},{"h":"No seu confinamento","p":["Peça provas de resultados em gado de corte antes de pagar por um aditivo caro.","As leguminosas e árvores forrageiras dão taninos naturais a baixo custo."]}],"rel":["Aditivos na ração","Leguminosas e árvores forrageiras","Aditivos que reduzem o metano"]},{"t":"Tamponantes e bicarbonato","a":"nutricion","r":"Os tamponantes, como o bicarbonato de sódio, ajudam a neutralizar o ácido do rúmen. Usam-se em rações com muito grão ou em épocas de calor.","s":[{"h":"Como se usam","p":["Bicarbonato de sódio: 0,5 a 1 % da matéria seca da ração.","Óxido de magnésio: complementa o bicarbonato.","Não substituem a fibra efetiva nem uma boa adaptação."]},{"h":"Quando ajudam","p":["Na transição para o concentrado.","Com calor, quando os animais ruminam menos.","Quando se veem fezes soltas em todo o lote."]}],"rel":["Acidose ruminal","Fibra efetiva","Adaptação ao concentrado"]},{"t":"Micotoxinas no alimento","a":"nutricion","r":"As micotoxinas são venenos produzidos por alguns fungos em grãos, silagens e subprodutos mal guardados. Baixam o consumo, danificam o fígado e as defesas, e algumas passam para o leite.","s":[{"h":"As mais comuns","p":["Aflatoxinas: em milho, amendoim e caroço de algodão com umidade e calor.","Fumonisinas e zearalenona: no milho.","Desoxinivalenol (vomitoxina): em grãos pequenos."]},{"h":"Sinais","p":["Queda de consumo sem razão clara.","Diarreia, pelo opaco e mais doenças.","Grão com mofo visível, cheiro de mofado ou pó verde ou preto."]},{"h":"O que fazer","p":["Compre grão seco (menos de 14 % de umidade) e guarde seco e ventilado.","Não use grão nem silagem mofados.","Existem sequestrantes de micotoxinas; ajudam, mas não consertam um grão muito contaminado.","Envie uma amostra ao laboratório se suspeitar."]}],"rel":["Armazenamento do alimento","Controle de pragas no armazém","O fígado do bovino","Silagem: qualidade e problemas"]},{"t":"Vitaminas A, D e E na época seca","a":"nutricion","r":"Quando o pasto seca, perde-se o caroteno que dá a vitamina A e a vitamina E. Depois de 2 a 4 meses de seca, muitos animais têm deficiência.","s":[{"h":"Sinais","p":["Olhos lacrimejantes, cegueira ao entardecer.","Pelo áspero e mais doenças respiratórias.","Menos ganho."]},{"h":"Como fornecê-las","p":["No sal mineral com vitaminas.","Pré-mistura vitamínica na ração.","Injeção de A, D e E na entrada ou a cada 2 a 3 meses na seca."]},{"h":"No seu confinamento","p":["O grão e o feno guardado têm pouca vitamina A e E.","No curral, sempre acrescente vitaminas à ração."]}],"rel":["Vitaminas no bovino","Época seca","Microminerais e vitaminas"]},{"t":"Selênio e vitamina E","a":"nutricion","r":"O selênio e a vitamina E trabalham juntos para proteger as células. Em regiões com solos pobres em selênio, sua falta baixa as defesas e danifica os músculos.","s":[{"h":"Sinais de falta","p":["Mais doenças e pior resposta às vacinas.","Músculos fracos, animais rígidos ou que se cansam fácil.","Em bezerros, doença do músculo branco."]},{"h":"Como fornecê-los","p":["No sal mineral ou na ração conforme a dose do fabricante.","Injetados na entrada, com receita."]},{"h":"Cuidado","p":["A margem entre o necessário e o tóxico é pequena.","Nunca some várias fontes sem calcular o total."]}],"rel":["Estresse oxidativo","Microminerais e vitaminas","Vitaminas A, D e E na época seca"]},{"t":"Enxofre na ração","a":"nutricion","r":"O enxofre é necessário para os micróbios fazerem proteína, mas em excesso causa polioencefalomalácia e bloqueia o cobre.","s":[{"h":"Quanto","p":["Necessário: cerca de 0,15 a 0,2 % da matéria seca.","Risco: acima de 0,3 a 0,4 % somando ração e água.","Com ureia acrescenta-se enxofre na relação de 10 a 15 partes de nitrogênio para 1 de enxofre."]},{"h":"Fontes de excesso","p":["DDGS e outros subprodutos do etanol.","Melaço de algumas usinas.","Água de poço com sulfatos."]},{"h":"No seu confinamento","p":["Se usa muito DDGS ou melaço, peça análise de enxofre.","Analise a água de poços novos."]}],"rel":["Polioencefalomalácia","Ureia na ração","Grãos de destilaria (DDGS)","Água: fontes, caixas e qualidade"]},{"t":"Cobalto e vitamina B12","a":"nutricion","r":"Os micróbios do rúmen usam o cobalto para fabricar vitamina B12, que o animal precisa para aproveitar a energia do ácido propiônico.","s":[{"h":"Sinais de falta","p":["Perda de apetite e de peso sem outra causa.","Pelo áspero e anemia.","Comum em solos arenosos ou vulcânicos pobres."]},{"h":"Como fornecê-lo","p":["Sal mineral com cobalto.","A injeção de B12 dá um efeito rápido, mas curto."]}],"rel":["Minerais no corpo","Microminerais e vitaminas","Glicose no ruminante"]},{"t":"Sódio e potássio com calor","a":"nutricion","r":"Com calor o animal perde potássio e sódio pelo suor e pela urina. Repô-los ajuda a manter o consumo e a hidratação.","s":[{"h":"O que acontece","p":["O suor do bovino é rico em potássio.","Com calor a necessidade de potássio sobe para 1,2 a 1,5 % da ração.","O sódio do sal mantém a sede e o consumo de água."]},{"h":"O que fazer","p":["Sal sempre disponível.","Rações com muito grão têm pouco potássio: a forragem e o melaço o fornecem.","Eletrólitos na água ao receber gado muito estressado ou em ondas de calor."]}],"rel":["Alimentação com calor","Estresse por calor","Desidratação e soros"]},{"t":"Energia das forragens tropicais","a":"nutricion","r":"Os capins tropicais têm menos energia que os grãos e que os pastos temperados. Saber quanto fornecem evita esperar ganhos impossíveis.","s":[{"h":"Valores aproximados","p":["Capim novo bem manejado: 55 a 62 % de nutrientes digestíveis totais.","Capim de corte na idade certa: 52 a 58 %.","Capim velho ou restolho: 42 a 50 %.","Milho grão: cerca de 85 a 90 %."]},{"h":"Que ganho permitem","p":["Só com capim velho: o animal mal se mantém.","Só com capim novo: 0,4 a 0,7 kg por dia.","Com 0,5 a 1 % do peso em concentrado: 0,7 a 1 kg por dia."]},{"h":"No seu confinamento","p":["Se sua meta é mais de 1 kg por dia, você precisa de concentrado ou forragens muito boas.","As calculadoras do Rumi dizem quanto suplemento é necessário."]}],"rel":["Pastos tropicais e temperados","Suplementação no pasto","Nutrientes digestíveis totais"]},{"t":"Ração conforme a etapa","a":"nutricion","r":"O confinamento se divide em etapas e cada uma precisa de uma ração diferente: recepção, crescimento e terminação. Mudar a ração com a etapa economiza dinheiro e evita problemas.","s":[{"h":"Recepção (2 a 3 semanas)","p":["Muita forragem de boa qualidade e um pouco de concentrado.","Proteína de 13 a 14 % para animais leves e estressados.","Vitaminas e minerais para as defesas."]},{"h":"Crescimento","p":["Mais energia aos poucos.","Proteína de 12 a 13 %.","O animal forma músculo: é a etapa de melhor conversão."]},{"h":"Terminação","p":["Máxima energia que o rúmen tolere, com fibra efetiva mínima.","Proteína de 11 a 12 %.","O animal faz gordura: a conversão piora."]},{"h":"No seu confinamento","p":["Guarde uma ração por etapa no app e troque de uma para outra em 5 a 7 dias.","O Rumi lembra você da adaptação ao concentrado."]}],"rel":["Ração inicial","Ração de crescimento","Ração de terminação","Adaptação ao concentrado"]},{"t":"Exigências por raça e clima","a":"nutricion","r":"O que um novilho precisa comer depende do peso, do ganho que você busca, da raça e do calor. O Rumi calcula a tabela completa em Guia, Tabelas de referência.","s":[{"h":"A raça","p":["O zebu (Brahman, Nelore) precisa de cerca de 10 % menos energia de manutenção que um europeu.","Os machos leiteiros (Holandês, Pardo-Suíço) precisam de cerca de 20 % a mais: gastam mais para se manter.","Os cruzamentos F1 ganham mais que os pais pelo vigor híbrido."]},{"h":"O clima","p":["Acima de 27 °C comem menos: de 5 a 15 % menos com calor e até 35 % menos com calor extremo sem noites frescas.","Ofegar gasta energia: a manutenção sobe de 7 a 20 % com calor.","Com frio (menos de 5 a 10 °C conforme o pelo) precisam de mais energia, cerca de 1 % a mais por grau abaixo da zona de conforto.","A água sobe muito com o calor: de 5 litros por quilo de matéria seca em clima temperado a 8 ou mais com calor."]},{"h":"Como usar a tabela","p":["Escolha o tipo de animal e o clima da sua fazenda.","Veja quanto devem comer em matéria seca e a proteína da ração para cada peso.","Se comem menos do que diz a tabela, procure a causa: calor, água, cochos, doença ou uma ração pouco apetitosa.","Para montar a mistura use Formular dieta."]}],"rel":["Exigências: tabelas modernas","Estresse por calor","Matéria seca e consumo","Água de bebida","Raças para engorda no trópico"]},{"t":"Preços de referência e como usá-los","a":"negocio","r":"Saber a faixa normal de preços do seu país ajuda a não vender barato nem comprar caro. O Rumi traz faixas orientativas por país e compara seu preço.","s":[{"h":"O que são","p":["Faixas de preço do boi gordo em pé e do gado para engorda, por país, de leilões, frigoríficos e relatórios públicos.","Mudam toda semana e conforme peso, sexo, raça, região e época."]},{"h":"Como usá-los","p":["Se uma oferta está muito abaixo da faixa, pergunte em outro frigorífico ou leilão antes de vender.","Se pedem muito mais que a faixa por gado magro, calcule seu preço máximo de compra antes de pagar.","Atualize seu preço de venda em Configurações sempre que o mercado mudar: com ele o Rumi calcula margens, risco e o valor do seu gado."]},{"h":"Cuidado com","p":["Comparar preço em pé com preço por carcaça: por carcaça o número é quase o dobro porque o animal rende cerca de 55 %.","Comparar libras com quilos ou arrobas: o app converte tudo, mas confira a unidade de cada oferta.","Em países com inflação alta, compare em dólares."]}],"rel":["Preços do gado e ciclo pecuário","Preço máximo de compra","Vender em pé ou por carcaça","Sazonalidade de preços","Câmbio e preço do gado"]},{"t":"Calendário sanitário conforme a região","a":"sanidad","r":"As vacinas de entrada são parecidas em todo lugar, mas os parasitas, as doenças e as épocas de risco mudam com o clima. O Rumi monta o calendário do seu país em Saúde.","s":[{"h":"Trópico úmido","p":["Carrapatos e doenças que transmitem (anaplasma e babesia) nas chuvas: controle a cada 21 a 28 dias e rotação de produtos.","Berne, mosca-dos-chifres, mancadeiras no barro.","Raiva paralítica onde há morcegos-vampiros: vacina anual."]},{"h":"Trópico seco e semiárido","p":["Falta de água e forragem, poeira e pneumonias, falta de vitamina A na seca.","Água com sais e sulfatos: faça uma análise."]},{"h":"Subtropical e temperado","p":["Complexo respiratório com as mudanças de temperatura, no outono e no inverno.","Moscas e ceratoconjuntivite no verão; barro e frio no inverno."]},{"h":"Sempre","p":["Vacina clostridial e respiratória na entrada, com reforço às 3 a 4 semanas.","Programas oficiais do seu país (aftosa, brucelose, tuberculose, bicheira).","As vacinas e doses são decididas pelo seu veterinário."]}],"rel":["Calendário sanitário do confinamento","Doenças por época do ano","Plano sanitário de entrada","Programas oficiais de sanidade","Carrapatos"]},{"t":"Beta-agonistas (ractopamina e zilpaterol)","a":"nutricion","r":"São aditivos dados nos últimos 20 a 42 dias para que o animal faça mais músculo e menos gordura. Sobem o ganho e o rendimento, mas são proibidos em muitos países e mercados.","s":[{"h":"O que fazem","p":["Desviam nutrientes da gordura para o músculo: mais ganho (5 a 15 %), melhor conversão e mais rendimento de carcaça.","Podem baixar a maciez da carne e aumentar o estresse por calor e os problemas de patas."]},{"h":"A lei","p":["Proibidos na União Europeia, China, Rússia e outros mercados, e em vários países da América Latina.","O clembuterol é proibido em quase todo o mundo pelo risco à saúde humana.","Se vende a um frigorífico exportador, pergunte o que exige; um só animal com resíduos pode fechar um mercado."]},{"h":"Se forem permitidos","p":["Só com receita e seguindo o rótulo à risca: dose, dias e carência.","Nunca em animais estressados ou com calor extremo."]}],"rel":["Promotores de crescimento e implantes","Produtos proibidos na alimentação","Carências e resíduos","Aditivos na ração"]},{"t":"Engorda de novilhas","a":"manejo","r":"As novilhas engordam mais devagar e acumulam gordura antes que os novilhos, mas são compradas mais baratas. Podem ser bom negócio se você ajustar a meta e a ração.","s":[{"h":"Diferenças em relação ao novilho","p":["Ganham cerca de 10 % menos por dia e convertem um pouco pior.","Chegam à gordura de terminação com menos peso: venda 30 a 50 kg mais leves.","As prenhes engordam mal e perdem valor no frigorífico: examine por palpação ou ultrassom na compra."]},{"h":"Manejo","p":["Não as misture com touros inteiros.","O cio baixa o consumo por alguns dias; é normal.","Com boa genética, alguma pode valer mais como reprodutora do que para carne."]}],"rel":["Formar lotes","Comprar gado para engorda","Quando vender"]},{"t":"Engorda de búfalos","a":"manejo","r":"O búfalo aproveita pastos e forragens pobres melhor que o bovino e aguenta a umidade. Sua carne é magra e se vende bem em alguns mercados.","s":[{"h":"Vantagens","p":["Bom ganho com forragens grosseiras e subprodutos.","Resiste a doenças de regiões úmidas e a carrapatos melhor que o bovino."]},{"h":"Cuidados","p":["Precisam de água ou lama para se refrescar: sem isso sofrem mais com o calor que o gado.","São inteligentes e se manejam melhor com calma e rotina.","Verifique se seu frigorífico compra búfalo e a que preço antes de engordar."]}],"rel":["Engorda a pasto","Estresse por calor","Canais de venda"]},{"t":"Engorda de machos leiteiros","a":"manejo","r":"Os bezerros machos de leite (Holandês, Pardo-Suíço, Jersey) são comprados baratos. Podem dar dinheiro se forem bem criados e engordados, mas rendem menos de carcaça.","s":[{"h":"O que esperar","p":["Ganham 1,2 a 1,5 kg por dia no curral com boa ração.","Rendem 2 a 4 pontos menos de carcaça que um zebu ou um cruzamento de corte.","Precisam de cerca de 20 % mais energia para se manter."]},{"h":"Chaves","p":["A criação do bezerro é o mais delicado: colostro, leite ou sucedâneo e desmame aos 2 meses.","Pneumonias e diarreias são o maior risco no início.","São mais sensíveis ao calor que o zebu: sombra e água."]}],"rel":["Desmame e pré-condicionamento","Pneumonia ou complexo respiratório","Rendimento: o que aumenta e o que diminui"]},{"t":"Exportação de gado em pé","a":"negocio","r":"Vender novilhos em pé para outro país pode pagar mais, mas exige sanidade, rastreabilidade e papéis em ordem. As fronteiras fecham rápido diante de uma doença.","s":[{"h":"O que pedem","p":["Registro da fazenda, brincos oficiais e guias de trânsito.","Testes de tuberculose e brucelose, e quarentena conforme o país comprador.","Livre de bicheira e carrapatos no embarque."]},{"h":"Riscos","p":["Fechamento de fronteiras por surtos (bicheira, aftosa).","O contrabando prejudica todos: pode fechar um mercado inteiro.","A taxa de câmbio mexe no seu preço."]}],"rel":["Fronteiras e comércio de gado","Guia de trânsito e rastreabilidade","Bicheira (Cochliomyia): a emergência desde 2023"]},{"t":"Qualidade da água: sais e sulfatos","a":"nutricion","r":"A água é o nutriente que mais consomem. Com muito sal, sulfatos ou nitratos baixam o consumo e o ganho, e podem adoecer.","s":[{"h":"O que medir","p":["Sólidos dissolvidos totais: menos de 3.000 ppm é seguro; mais de 5.000 baixa o ganho; mais de 7.000 não serve.","Sulfatos: menos de 500 ppm; com mais de 1.000 há risco de polioencefalomalácia (o animal cego que anda em círculos).","Nitratos: menos de 100 ppm de nitrato."]},{"h":"O que fazer","p":["Analise a água de poço pelo menos uma vez por ano, e na seca.","Se a água traz sulfatos, baixe o enxofre da ração (melaço, DDGS, sulfato de amônio).","Limpe os bebedouros toda semana: a água suja também baixa o consumo."]}],"rel":["Água de bebida","Água: fontes, caixas e qualidade","Polioencefalomalácia","Intoxicação por nitratos e cianeto"]},{"t":"Seca: plano para não perder o confinamento","a":"manejo","r":"Uma seca sobe o preço da forragem, baixa o do gado magro e aperta a água. Com um plano você decide a tempo em vez de vender às pressas.","s":[{"h":"Antes","p":["Guarde forragem (silagem, feno) da época de chuvas.","Garanta a água: poços, reservatórios e bombas.","Tenha claro quantos animais consegue alimentar com o que tem."]},{"h":"Durante","p":["Venda primeiro os animais prontos e os que ganham pouco.","Use subprodutos baratos: polpa, casca, restolhos, cana, com ureia e melaço bem manejados.","Revise o preço máximo de compra antes de colocar gado novo: o alimento custa mais."]},{"h":"Depois","p":["Os animais que passaram fome ganham rápido ao voltar a comer (ganho compensatório): podem ser bom negócio.","Adapte a dieta aos poucos para evitar acidose."]}],"rel":["Época seca","Ganho compensatório","Palhadas de colheita","Plano de contingência","Preço máximo de compra"]},{"t":"Composto e biodigestores com o esterco","a":"instalaciones","r":"Um novilho produz de 20 a 30 kg de esterco por dia. Bem manejado é adubo, gás e menos moscas; mal manejado é cheiro, moscas e água contaminada.","s":[{"h":"Compostagem","p":["Amontoe esterco com restolho ou serragem, vire a cada 1 a 2 semanas e em 2 a 3 meses você tem adubo.","O calor do composto mata ovos de mosca e sementes de plantas daninhas."]},{"h":"Biodigestor","p":["Produz gás para cozinhar ou esquentar água e um adubo líquido para pastos.","Funciona melhor com currais de piso de cimento onde se pode lavar o esterco."]},{"h":"Cuidar da água","p":["Não deixe a água dos currais chegar a rios ou poços.","Uma lagoa ou vala de retenção evita multas e problemas com vizinhos."]}],"rel":["Manejo do esterco","Nitrogênio, esterco e ambiente","Proteção de fontes de água","Moscas-dos-chifres e moscas-dos-estábulos"]},{"t":"Câmbio e preço do gado","a":"negocio","r":"O gado e o milho são cotados no mundo em dólares. Quando sua moeda se desvaloriza, o gado e o alimento importado sobem; quando se valoriza, baixam.","s":[{"h":"Como afeta você","p":["Se você exporta ou vende a um frigorífico exportador, uma moeda fraca paga mais.","O milho e a soja importados sobem com o dólar: seu custo por quilo ganho também.","Em países com inflação alta, compare preços em dólares para não se enganar."]},{"h":"O que fazer","p":["Compre alimento com antecedência quando o câmbio estiver a seu favor.","Revise sua margem com o simulador do Rumi: suba o custo do alimento e veja o que acontece."]}],"rel":["Preços do gado e ciclo pecuário","Riscos do confinamento","Análise de sensibilidade"]},{"t":"O gado como ativo na contabilidade","a":"negocio","r":"O gado em confinamento é um ativo biológico: seu valor muda a cada dia com o peso e o preço. A norma IAS 41 (CPC 29) pede avaliá-lo a preço de mercado menos os custos de venda.","s":[{"h":"Como o Rumentis o avalia","p":["Peso vivo de hoje, menos a quebra, vezes seu preço de venda.","Assim seu balanço mostra quanto vale de verdade seu confinamento, não só o que você pagou."]},{"h":"Por que importa","p":["Um banco olha seu balanço para emprestar: o gado bem avaliado mostra sua capacidade real.","Separar o que o animal ganhou (peso) do que o mercado ganhou (preço) diz se você é um bom confinador ou teve sorte."]}],"rel":["Como se ganha dinheiro no confinamento","Financiamento e crédito","Margem de compra e venda"]},{"t":"Estresse por frio","a":"manejo","r":"Em regiões temperadas ou de altitude, o frio com vento, chuva e barro faz o gado gastar mais energia para se aquecer e ganhar menos.","s":[{"h":"Sinais","p":["Pelo arrepiado, se amontoam, tremem.","Comem mais, mas ganham menos."]},{"h":"O que fazer","p":["Abrigo do vento e cama seca: um animal molhado sente frio a temperaturas muito mais altas.","Suba a energia da ração, cerca de 1 % por grau abaixo da zona de conforto.","Água sem congelar e currais sem barro."]}],"rel":["Exigências por raça e clima","Pisos e drenagem","Confinar na seca ou nas chuvas"]},{"t":"Ceratoconjuntivite (olho rosado)","a":"sanidad","r":"Infecção do olho que causa lacrimejamento, olho fechado, mancha branca e às vezes cegueira. É contagiosa e baixa o ganho.","s":[{"h":"Causas","p":["Uma bactéria (Moraxella) levada pelas moscas.","Poeira, pasto alto, sol forte e falta de sombra a favorecem.","As raças de cara branca (Hereford) são mais sensíveis."]},{"h":"O que fazer","p":["Separe os doentes e trate cedo com seu veterinário.","Tampões no olho protegem do sol e das moscas.","Controle de moscas e sombra para prevenir."]}],"rel":["Moscas-dos-chifres e moscas-dos-estábulos","Sombra","Revisão diária dos animais"]},{"t":"Raças de alto marmoreio","a":"genetica","r":"Wagyu e Angus têm gordura dentro do músculo (marmoreio) que dá carne suculenta e cara. Só compensam se você tiver um comprador que premie essa qualidade.","s":[{"h":"O que saber","p":["O Wagyu precisa de confinamentos longos (300 dias ou mais) e dietas especiais.","No trópico sofrem com o calor: usam-se em cruzamento com zebu ou crioulos.","Sem um mercado que pague por qualidade, custam mais do que deixam."]}],"rel":["Marmoreio e qualidade","Raças europeias de corte","Cruzamentos para corte no trópico"]},{"t":"Chuvas e épocas do confinamento por região","a":"manejo","r":"Saber quando chove e quando é seco na sua região diz quando comprar, quando vender e quando esperar problemas de saúde.","s":[{"h":"América Central e Caribe","p":["Chuvas de maio a outubro ou novembro, com a canícula (veranico) em julho e agosto; seca de novembro a abril.","O gado magro costuma estar mais barato no fim da seca; o gordo, mais caro no início das chuvas."]},{"h":"América do Sul tropical","p":["No Brasil central e no Chaco, chuvas de outubro a abril.","Na Colômbia e na Venezuela, duas estações chuvosas por ano em muitas regiões."]},{"h":"Regiões temperadas","p":["Quatro estações: o inverno baixa o ganho em currais abertos e o outono traz o complexo respiratório."]}],"rel":["Época de chuvas","Época seca","Compras conforme a época","Sazonalidade de preços"]},{"t":"Revisão diária dos animais","a":"sanidad","r":"Percorrer os currais com olho treinado, de manhã e à tarde, é o remédio mais barato do confinamento: encontra o doente antes que se complique.","s":[{"h":"Quando e como","p":["Revise duas vezes ao dia: cedo antes de servir e à tarde depois da última entrega.","Entre no curral devagar, sem cães nem gritos, e deixe os animais se levantarem sozinhos.","Olhe primeiro de longe o grupo inteiro e depois animal por animal.","Dedique pelo menos 10 a 15 minutos por curral nas primeiras três semanas depois da chegada."]},{"h":"Sinais de um animal sadio","p":["Aproxima-se do cocho quando você serve e come com vontade.","Rumina deitado e tranquilo boa parte do dia.","Orelhas levantadas, olhos brilhantes e focinho úmido e limpo.","Esterco em forma de torta, nem muito duro nem aguado.","Respira tranquilo, sem mexer muito os flancos nem abrir a boca.","Pelo uniforme e brilhante, sem áreas arrepiadas."]},{"h":"Sinais de alarme","p":["Fica para trás do grupo ou não se levanta ao entrar no curral.","Orelhas caídas, cabeça baixa, olhos fundos ou lacrimejamento.","Muco espesso, tosse, respiração rápida ou com a boca aberta.","Flanco esquerdo fundo (não está comendo) ou muito inchado.","Diarreia, fezes com sangue ou esterco muito seco.","Mancadeira, inchaços, feridas ou bicheira.","Lambe ou chuta a barriga, range os dentes ou se afasta do grupo."]},{"h":"Método DART para doença respiratória","p":["D de deprimido: cabeça baixa, orelhas caídas, pouco alerta.","A de apetite: não se aproxima do cocho ou come pouco.","R de respiração: rápida, com esforço ou com ruído.","T de temperatura: mais de 39,5 °C no termômetro.","Um animal com dois ou mais desses sinais deve ser separado para revisão no mesmo dia."]},{"h":"O que fazer ao encontrar um","p":["Leve-o com calma ao curral de doentes com água, sombra e feno.","Meça a temperatura antes de tratar; anote.","Ligue ou consulte o veterinário e siga o tratamento completo.","Anote no app o tratamento, o produto e os dias de carência.","Revise-o de novo todo dia até que coma e tenha temperatura normal."]},{"h":"Erros comuns","p":["Revisar só ao servir a comida: o doente se mistura ao grupo e não é visto.","Esperar que o animal pare de comer de vez para agir.","Tratar sem medir a temperatura nem anotar nada.","Não voltar a revisar o animal tratado."]}],"rel":["Sinais vitais e como medi-los","Pneumonia ou complexo respiratório","Curral de doentes"]},{"t":"Sinais vitais e como medi-los","a":"sanidad","r":"Temperatura, respiração, pulso e movimentos do rúmen dizem muito da saúde de um animal. Aprender a medi-los ajuda você a decidir rápido.","s":[{"h":"Valores normais em bovino adulto","p":["Temperatura: 38,0 a 39,3 °C; até 39,5 °C com calor ou depois de movimentá-lo.","Respiração em repouso: 10 a 30 por minuto; com calor forte pode subir muito.","Pulso: 60 a 80 batimentos por minuto.","Movimentos do rúmen: 1 a 2 por minuto, sentidos ao pressionar a fossa do lado esquerdo.","Mucosas (gengivas, pálpebra): rosadas e úmidas."]},{"h":"Temperatura","p":["Use termômetro digital no reto, lubrificado, apoiado contra a parede do reto, por um minuto ou até apitar.","Meça com o animal quieto no brete e na sombra.","Mais de 39,5 °C em repouso é febre; mais de 40,5 °C é febre alta.","Menos de 38 °C num animal abatido é grave: pode estar em choque ou muito fraco.","Limpe e desinfete o termômetro entre animais."]},{"h":"Respiração","p":["Conte quantas vezes o flanco sobe em 30 segundos e multiplique por dois.","Respirar com a boca aberta, esticar o pescoço ou gemer indica problema sério.","Diferencie a ofegância por calor (todo o grupo, nas horas quentes) da pneumonia (um animal, com febre e muco)."]},{"h":"Rúmen","p":["Coloque o punho na fossa do lado esquerdo e conte as contrações em dois minutos.","Sem movimentos: indigestão, acidose ou febre alta.","Rúmen muito inchado e duro do lado esquerdo: timpanismo, é urgência.","Um animal sadio rumina 7 a 10 horas por dia."]},{"h":"Mucosas e olhos","p":["Pálidas ou brancas: anemia (parasitas, anaplasmose, babesiose).","Amarelas: problema de fígado ou destruição de sangue (anaplasmose).","Azuladas: falta de oxigênio, pneumonia grave ou intoxicação.","Olhos fundos: desidratação; belisque a pele do pescoço, se demora a voltar há desidratação."]},{"h":"Regras práticas","p":["Sempre meça a temperatura antes de dar antibiótico.","Anote os valores no app ou num caderno com a data e o brinco.","Compare com outros animais sadios do mesmo curral no mesmo horário.","Se vários animais têm febre ao mesmo tempo, chame o veterinário no mesmo dia."]}],"rel":["Revisão diária dos animais","Pneumonia ou complexo respiratório","Golpe de calor"]},{"t":"Pneumonia ou complexo respiratório","a":"sanidad","r":"É a doença que mais mata e adoece animais no confinamento, sobretudo nas primeiras quatro semanas depois da chegada. Agir no primeiro dia muda tudo.","s":[{"h":"O que é","p":["Uma infecção dos pulmões causada por uma mistura de vírus (IBR, BVD, PI3, BRSV) e bactérias (Mannheimia, Pasteurella, Histophilus, Mycoplasma).","O estresse baixa as defesas e os vírus abrem a porta para as bactérias.","Também é chamada de febre do transporte porque aparece depois da viagem."]},{"h":"Por que aparece","p":["Viagens longas, jejum e desidratação.","Mistura de animais de muitas origens.","Desmame recente, castração ou descorna perto da chegada.","Poeira, mudanças bruscas de temperatura, currais mal ventilados ou com barro.","Falta de vacinas antes de chegar."]},{"h":"Sinais","p":["Orelhas caídas, cabeça baixa e olhos apagados.","Para de comer ou come muito pouco.","Febre de 40 °C ou mais.","Muco no nariz, lacrimejamento e tosse.","Respiração rápida, com esforço ou com a boca aberta nos casos graves.","Aparece mais entre os dias 5 e 21 depois da chegada."]},{"h":"O que fazer","p":["Separe o animal e meça a temperatura.","Trate no primeiro dia com o antibiótico que seu veterinário indicar; cada dia de espera baixa a chance de cura.","Termine o tratamento completo mesmo que melhore antes.","Se em 48 a 72 horas não melhorar (continua com febre ou sem comer), consulte de novo: pode precisar de outro produto.","Anote produto, dose, data e carência no app.","Se adoecerem mais de 5 a 10 % do lote, revise o manejo com o veterinário e considere tratar o grupo todo a critério dele."]},{"h":"Prevenção","p":["Compre animais vacinados e desmamados com antecedência quando possível.","Viagens curtas, com boa lotação e sem maus-tratos.","Na chegada: água, feno de boa qualidade e descanso antes de trabalhá-los.","Vacina respiratória conforme o plano do seu veterinário.","Currais com sombra, boa ventilação e sem poeira; molhe o piso na seca.","Não misture lotes novos com animais que já estão em confinamento."]},{"h":"Números-chave","p":["A maioria dos casos aparece nas primeiras 3 a 4 semanas.","Um animal que tem pneumonia pode ganhar 50 a 100 gramas a menos por dia durante todo o confinamento.","As recaídas são mais frequentes quando o tratamento começa tarde."]},{"h":"Erros comuns","p":["Esperar o animal tossir muito para tratar: a tosse chega tarde.","Trocar de antibiótico todo dia.","Suspender o tratamento quando o animal volta a comer.","Não respeitar a carência antes de vender."]}],"rel":["Plano sanitário de entrada","Recepção de gado","Uso responsável de antibióticos"]},{"t":"Acidose ruminal","a":"sanidad","r":"É o problema digestivo mais importante do confinamento com concentrado. Aparece quando os animais comem muito grão de uma vez e o rúmen fica ácido.","s":[{"h":"O que é","p":["O grão tem amido que fermenta muito rápido no rúmen e produz ácidos.","Se se produz mais ácido do que o rúmen consegue remover, o pH cai e morrem as bactérias boas.","Há acidose aguda (grave, em horas) e subaguda (escondida, baixa o ganho sem que se note)."]},{"h":"Causas","p":["Passar do pasto para o concentrado de uma vez, sem adaptação.","Cochos que ficam vazios muitas horas e depois os animais comem com fome.","Mudanças bruscas de ração ou de quantidade.","Pouca forragem ou forragem picada demais na ração.","Erros na mistura: bolsões de grão soltos, mistura desigual.","Dias de calor seguidos de noites frescas em que comem demais."]},{"h":"Sinais de acidose aguda","p":["Para de comer de repente, rúmen sem movimento.","Diarreia espumosa, com cheiro azedo e às vezes com grãos inteiros.","Desidratação, olhos fundos, cambaleia ou fica deitado.","Pode morrer em um ou dois dias."]},{"h":"Sinais de acidose subaguda","p":["O consumo do lote sobe e desce de um dia para o outro.","Fezes soltas, com bolhas ou com grão não digerido.","Mancadeiras (laminite) semanas depois.","Abscessos de fígado no frigorífico e menor ganho sem causa clara."]},{"h":"O que fazer","p":["Retire o concentrado dos animais afetados e dê feno de boa qualidade e água.","Chame o veterinário: os casos agudos precisam de tratamento urgente.","Revise a mistura e a quantidade servida; volte um passo na adaptação.","Anote no app o dia e o lote para ver se se repete."]},{"h":"Prevenção","p":["Adapte ao concentrado em 3 a 4 semanas, subindo aos poucos.","Mantenha pelo menos 10 a 15 % de forragem na ração de terminação.","Sirva no mesmo horário todos os dias, duas ou três vezes ao dia.","Leia os cochos e ajuste a quantidade em passos pequenos (5 a 10 %).","Evite que o cocho fique vazio mais de 2 a 3 horas.","Consulte seu nutricionista sobre o uso de aditivos que estabilizam o rúmen (por exemplo ionóforos ou bicarbonato)."]},{"h":"Erros comuns","p":["Dar mais grão para engordarem mais rápido sem adaptar.","Mudar de ração no mesmo dia em que se muda de curral.","Moer o grão fino demais.","Ignorar as fezes soltas e o consumo que varia."]}],"rel":["Adaptação ao concentrado","Leitura de cochos","Abscessos de fígado","Mancadeiras e problemas de casco"]},{"t":"Timpanismo (rúmen inchado)","a":"sanidad","r":"O rúmen se enche de gás que o animal não consegue eliminar. É uma urgência: pode matar em poucas horas pela pressão sobre os pulmões.","s":[{"h":"Tipos","p":["Gás livre: o gás está em cima e não sai porque algo tapa o esôfago ou o rúmen não se move.","Espumoso: o gás fica preso na espuma; é típico com leguminosas novas ou rações com muito grão fino.","Crônico: repete-se no mesmo animal por dano de nervos ou abscessos."]},{"h":"Sinais","p":["Lado esquerdo muito inchado, visível de trás do animal.","Desconforto, chuta a barriga, deita e levanta.","Respiração rápida, boca aberta, língua para fora.","Pode cair e morrer se não for atendido."]},{"h":"O que fazer imediatamente","p":["Chame o veterinário.","Faça o animal caminhar devagar e mantenha a cabeça no alto.","Se for gás livre, uma sonda pela boca até o rúmen o elimina; faça só se souber.","No espumoso usam-se antiespumantes pela boca indicados pelo veterinário.","Perfurar o rúmen (trocarte) é uma medida de último recurso e deve ser feita por alguém treinado."]},{"h":"Prevenção","p":["Adaptação correta ao concentrado e forragem suficiente na ração.","Não moer o grão fino demais.","Não soltar animais com fome em pastos de leguminosa nova ou molhada.","Sirva a ração em horários fixos para que não comam com ansiedade.","Separe e vigie os que incham com frequência; se se repetir, considere vendê-los."]},{"h":"Erros comuns","p":["Esperar para ver se passa sozinho.","Dar óleo ou remédios caseiros sem saber que tipo de timpanismo é.","Furar o rúmen com qualquer faca no lugar errado."]}],"rel":["Acidose ruminal","Adaptação ao concentrado","Leguminosas e árvores forrageiras"]},{"t":"Abscessos de fígado","a":"sanidad","r":"São bolsas de pus no fígado que aparecem quase sempre depois de acidose. Não se veem em vida, mas baixam o ganho e o frigorífico condena o fígado.","s":[{"h":"Por que aparecem","p":["A acidose danifica a parede do rúmen e as bactérias passam para o sangue e chegam ao fígado.","São mais comuns com rações muito altas em grão e pouca forragem.","Os cochos que esvaziam e as mudanças bruscas de ração os aumentam."]},{"h":"Como afetam","p":["Menor consumo e ganho diário.","Pior conversão alimentar.","Condenação de fígados e às vezes de partes da carcaça se houver aderências.","Abscessos grandes podem se romper e matar o animal."]},{"h":"Como saber se você os tem","p":["Peça ao frigorífico o relatório de fígados condenados do seu lote.","Se mais de 10 a 15 % dos fígados saem com abscessos, revise a ração e o manejo de cocho.","Um ganho mais baixo que o esperado na terminação pode ser sinal."]},{"h":"Prevenção","p":["Tudo o que previne a acidose: adaptação, forragem efetiva, horários fixos.","Consulte seu veterinário ou nutricionista sobre os aditivos autorizados que os reduzem.","Evite grãos moídos muito finos."]}],"rel":["Acidose ruminal","Fibra e forragem na ração","Qualidade da carcaça"]},{"t":"Diarreia no confinamento","a":"sanidad","r":"A diarreia é um sinal, não uma doença. É preciso buscar a causa: ração, parasitas, infecções ou água.","s":[{"h":"Causas mais comuns","p":["Mudanças bruscas de ração ou excesso de grão (acidose).","Alimento com mofo ou fermentado.","Parasitas internos e coccídios.","Infecções como salmonela ou diarreia viral bovina.","Água suja ou contaminada.","Pasto muito novo e molhado."]},{"h":"Como ler as fezes","p":["Espumosa, azeda, com grãos: problema de ração ou acidose.","Com sangue ou muco e esforço: coccidiose ou infecção; urgente.","Verde e aguada em pasto novo: excesso de água do capim.","Preta ou muito escura: pode ser sangramento no estômago.","Vários animais ao mesmo tempo: procure algo em comum (alimento, água)."]},{"h":"O que fazer","p":["Separe os mais afetados e dê água limpa à vontade e feno.","Revise a mistura, o grão e o alimento guardado.","Meça a temperatura: com febre costuma ser infecção.","Consulte o veterinário; um exame de fezes esclarece se são parasitas ou coccídios.","Os soros orais ajudam a repor água e sais em animais fracos."]},{"h":"Prevenção","p":["Mudanças de ração graduais.","Armazém seco para evitar mofo.","Bebedouros limpos toda semana.","Vermifugação conforme o plano do veterinário.","Currais sem poças nem barro acumulado."]}],"rel":["Acidose ruminal","Coccidiose","Parasitas internos","Armazenamento do alimento"]},{"t":"Coccidiose","a":"sanidad","r":"Parasita microscópico do intestino que ataca mais animais jovens e estressados, em currais úmidos e sujos.","s":[{"h":"Sinais","p":["Diarreia com muco ou sangue e esforço.","Cauda e patas traseiras sujas.","Perda de peso e desidratação.","Em casos graves: tremores ou sinais nervosos."]},{"h":"Quando aparece","p":["Nas primeiras semanas do confinamento, com o estresse de chegada.","Em currais com barro, esterco acumulado ou cochos rente ao chão.","Quando há muita densidade de animais."]},{"h":"O que fazer","p":["Consulte o veterinário para confirmar com exame de fezes.","O tratamento é com produtos específicos contra coccídios, conforme a indicação.","Separe os doentes e dê água e soros."]},{"h":"Prevenção","p":["Pisos secos e limpeza frequente do esterco.","Cochos e bebedouros elevados, que não se sujem com fezes.","Alguns aditivos na ração previnem coccídios; consulte seu nutricionista.","Evite a superlotação."]}],"rel":["Diarreia no confinamento","Pisos e drenagem","Recepção de gado"]},{"t":"Parasitas internos","a":"sanidad","r":"Vermes do estômago, intestino e pulmão roubam nutrientes e baixam o ganho. No trópico úmido são um problema constante, sobretudo em animais que vêm do pasto.","s":[{"h":"Principais parasitas","p":["Vermes do abomaso e do intestino (Haemonchus, Cooperia, Ostertagia, Trichostrongylus).","Vermes do pulmão (Dictyocaulus): causam tosse.","Fascíola do fígado (Fasciola) em regiões com poças e caramujos.","Tênias e coccídios em animais jovens."]},{"h":"Sinais","p":["Pelo opaco e arrepiado.","Baixo ganho de peso sem outra causa.","Diarreia e cauda suja.","Anemia: mucosas pálidas.","Edema embaixo da mandíbula ('papeira') em infestações fortes."]},{"h":"Vermifugação na entrada","p":["Vermifugue todos os animais na chegada, com o produto e a dose por peso que seu veterinário indicar.","Pese ou estime bem o peso: dar dose menor que a necessária favorece a resistência.","No curral fechado, com bom manejo, a reinfecção é baixa; no pasto repete-se conforme o plano."]},{"h":"Resistência a vermífugos","p":["Usar sempre o mesmo produto ou doses baixas faz os parasitas deixarem de morrer.","Rotacione o grupo químico (não só a marca) conforme indicar o veterinário.","Um exame de fezes antes e 10 a 14 dias depois do tratamento diz se o produto funciona."]},{"h":"Regras práticas","p":["Calcule a dose com o animal mais pesado do grupo ou pelo peso individual.","Respeite os dias de carência do rótulo antes de vender.","Anote no app o produto e a data.","Não misture vermífugos com outros produtos na mesma seringa."]}],"rel":["Vermifugação e resistência","Fascíola ou baratinha do fígado","Plano sanitário de entrada"]},{"t":"Fascíola ou baratinha do fígado","a":"sanidad","r":"Parasita em forma de folha que vive no fígado. Contagia-se em pastos úmidos onde há caramujos de água.","s":[{"h":"Como se contagia","p":["Os ovos saem no esterco, passam por um caramujo de água e a larva fica no pasto úmido.","Os animais a ingerem ao pastar perto de poças, córregos ou áreas alagadas."]},{"h":"Sinais","p":["Perda de peso e pelo ruim.","Anemia e edema embaixo da mandíbula.","Condenação de fígados no frigorífico, com ductos espessados."]},{"h":"O que fazer","p":["Consulte o veterinário: nem todos os vermífugos matam a fascíola.","Use um produto específico contra fascíola se houver histórico na região ou de onde vêm os animais.","Peça ao frigorífico o relatório de fígados."]},{"h":"Prevenção","p":["Cerque as áreas alagadas e as margens de córregos.","Dê água em bebedouros, não em poças.","Drene os pastos quando possível."]}],"rel":["Parasitas internos","Abscessos de fígado","Água de bebida"]},{"t":"Carrapatos","a":"sanidad","r":"Sugam sangue, transmitem anaplasmose e babesiose, danificam o couro e baixam o ganho. Seu controle deve ser planejado para não criar resistência.","s":[{"h":"Danos","p":["Perda de sangue e de peso.","Transmitem a tristeza parasitária (babesiose e anaplasmose).","Feridas que atraem moscas e bicheira.","Estresse e menos consumo de alimento."]},{"h":"Controle","p":["Banhe ou aplique o produto quando houver carrapatos visíveis, seguindo o rótulo.","Molhe bem todo o corpo: orelhas, entre as patas, úbere ou escroto e embaixo da cauda.","Use a dose e a diluição corretas; menos produto não mata e cria resistência.","Rotacione os grupos químicos conforme indicar o técnico.","Os produtos pour-on e injetáveis têm carências longas; revise antes de vender."]},{"h":"Resistência","p":["Se depois de um banho bem feito muitos carrapatos continuam vivos, pode haver resistência.","Um teste de resistência em laboratório indica quais produtos funcionam na sua fazenda."]},{"h":"Prevenção","p":["Revise os animais na chegada e trate-os antes de colocá-los no curral.","Mantenha o mato baixo ao redor dos currais.","No pasto, a rotação ajuda a quebrar o ciclo.","Os animais zebuínos e seus cruzamentos resistem melhor ao carrapato."]},{"h":"Segurança","p":["Use luvas, máscara e roupa de manga longa ao preparar e aplicar.","Não jogue restos de banho em córregos ou fontes de água.","Guarde os produtos trancados, longe do alimento."]}],"rel":["Anaplasmose","Babesiose (tristeza parasitária)","Uso responsável de antibióticos"]},{"t":"Moscas-dos-chifres e moscas-dos-estábulos","a":"sanidad","r":"As moscas incomodam, picam e sugam sangue. Um animal que passa o dia espantando moscas come e ganha menos.","s":[{"h":"Tipos","p":["Mosca-dos-chifres: pequena, agrupa-se no lombo e nos lados; vive sobre o animal.","Mosca-dos-estábulos: pica nas patas, cria-se em esterco misturado com alimento.","Mosca doméstica: não pica, mas suja e leva doenças."]},{"h":"Danos","p":["Estresse, menos tempo comendo e descansando.","Perda de peso e de sangue.","Transmitem doenças de olhos e pele."]},{"h":"Controle","p":["A chave é eliminar onde se criam: esterco e alimento molhado acumulados.","Limpe embaixo dos cochos e ao redor dos bebedouros toda semana.","Use inseticidas só quando houver muitas moscas e conforme o rótulo.","Armadilhas e iscas nas áreas de descanso ajudam.","Rotacione os produtos para evitar resistência."]},{"h":"Limiar prático","p":["Mais de 200 moscas-dos-chifres por animal justificam um tratamento.","Se vir os animais amontoados e chutando o dia todo, aja."]}],"rel":["Manejo do esterco","Bicheira (Cochliomyia)","Ceratoconjuntivite ou olho rosado"]},{"t":"Bicheira (Cochliomyia)","a":"sanidad","r":"A mosca põe ovos em feridas e as larvas comem carne viva. É uma praga de controle oficial: os casos são notificados ao SENASA.","s":[{"h":"Onde aparece","p":["Feridas de castração, descorna, brincos, marcação a ferro ou pancadas.","Umbigos de bezerros.","Feridas por carrapatos ou arame."]},{"h":"Sinais","p":["Ferida que cresce, com mau cheiro e líquido.","Larvas brancas visíveis dentro.","O animal se lambe, se coça e se afasta."]},{"h":"O que fazer","p":["Limpe a ferida, retire as larvas e aplique um produto larvicida e repelente de uso veterinário.","Revise a ferida todo dia até fechar.","Notifique o caso ao SENASA: faz parte do programa oficial de controle.","Guarde algumas larvas em álcool se o técnico pedir."]},{"h":"Prevenção","p":["Revise e trate toda ferida no mesmo dia.","Faça castrações, descornas e brincos na época de menos moscas e com repelente.","Conserte pregos, arames e tábuas que cortam nos currais.","Revise os animais novos antes de colocá-los com o resto."]}],"rel":["Feridas e curativos","Programas oficiais de sanidade","Castração"]},{"t":"Berne","a":"sanidad","r":"Larva de uma mosca que vive embaixo do couro formando bolinhas com um furo. Danifica o couro e incomoda o animal.","s":[{"h":"Sinais","p":["Caroços no lombo e nos lados com um orifício por onde a larva respira.","Coceira e incômodo.","Couros com furos no frigorífico."]},{"h":"O que fazer","p":["Os tratamentos contra parasitas externos ou os endectocidas os controlam; consulte qual usar.","Pode-se retirar a larva apertando o nódulo e desinfetando.","Não estoure a larva dentro do couro: causa infecção."]},{"h":"Prevenção","p":["Controle de moscas e do mato ao redor.","Revise os animais novos e trate-os na entrada se trouxerem bernes."]}],"rel":["Moscas-dos-chifres e moscas-dos-estábulos","Parasitas internos"]},{"t":"Anaplasmose","a":"sanidad","r":"Doença do sangue transmitida por carrapatos, moscas e agulhas sujas. Destrói glóbulos vermelhos e pode matar animais adultos.","s":[{"h":"Sinais","p":["Febre alta no início.","Mucosas pálidas e depois amarelas.","Fraqueza, cansaço, fica para trás.","Urina normal (diferente da babesiose).","Animais agressivos ou que caem ao serem manejados por falta de oxigênio."]},{"h":"O que fazer","p":["Consulte o veterinário imediatamente; o tratamento existe, mas deve ser a tempo.","Maneje o animal com muita calma: o esforço pode matá-lo.","Dê sombra, água e alimento por perto."]},{"h":"Prevenção","p":["Controle de carrapatos e moscas.","Use uma agulha limpa por animal ou por poucos animais ao vacinar ou injetar.","Desinfete os instrumentos de castração, descorna e brincos entre animais.","Os animais que vêm de regiões sem carrapato são mais suscetíveis."]}],"rel":["Babesiose (tristeza parasitária)","Carrapatos","Aplicação de injeções"]},{"t":"Babesiose (tristeza parasitária)","a":"sanidad","r":"Parasita do sangue transmitido pelo carrapato. Rompe glóbulos vermelhos e a urina fica vermelha ou marrom.","s":[{"h":"Sinais","p":["Febre alta.","Urina vermelha, marrom ou cor de café com leite.","Mucosas pálidas ou amarelas.","Em alguns casos, sinais nervosos: cambaleia, convulsões.","Morte rápida em animais sem imunidade."]},{"h":"O que fazer","p":["Chame o veterinário: há tratamento específico.","Não corra nem estresse o animal.","Separe e dê água, sombra e comida fácil de alcançar."]},{"h":"Prevenção","p":["Controle estratégico de carrapatos.","Cuidado especial com animais trazidos de regiões altas ou frias sem carrapato.","Pergunte por vacinas ou premunições disponíveis na sua região."]},{"h":"Diferenças com outras causas de urina vermelha","p":["Babesiose: febre e urina vermelha.","Anaplasmose: anemia e amarelidão, urina normal.","Leptospirose: urina vermelha, às vezes abortos em fêmeas.","Intoxicações por algumas plantas também dão urina escura."]}],"rel":["Anaplasmose","Carrapatos","Leptospirose"]},{"t":"Doenças clostridiais","a":"sanidad","r":"Grupo de doenças por bactérias que vivem no solo e matam muito rápido: carbúnculo sintomático, edema maligno, enterotoxemia e outras. Previnem-se com vacina.","s":[{"h":"Quais são","p":["Carbúnculo sintomático (manqueira): inchaço em músculos grandes que crepita ao tocar.","Edema maligno: inchaço em feridas ou locais de injeção.","Enterotoxemia: morte súbita, às vezes com diarreia, em animais bem alimentados.","Hemoglobinúria bacilar: urina vermelha e morte rápida.","Tétano: rigidez depois de feridas ou castrações."]},{"h":"Sinais","p":["Muitas vezes só se encontra o animal morto.","Mancadeira forte com inchaço quente e depois frio que crepita.","Febre e abatimento rápido.","Inchaço rápido ao redor de feridas."]},{"h":"O que fazer","p":["Chame o veterinário e não abra o cadáver se sangrar pelo nariz, boca ou ânus (descartar antraz).","Revise a vacinação do resto do lote.","O tratamento raramente funciona; a prevenção é o importante."]},{"h":"Prevenção","p":["Vacina polivalente contra clostrídios na entrada.","Reforço aos 21 a 30 dias; uma só dose protege pouco.","Agulhas limpas e aplicação no pescoço.","Cura rápida de feridas."]}],"rel":["Vacinação","Antraz (carbúnculo hemático)","Aplicação de injeções"]},{"t":"Antraz (carbúnculo hemático)","a":"sanidad","r":"Doença grave e contagiosa para as pessoas. Mata em horas. É de notificação obrigatória ao SENASA.","s":[{"h":"Sinais","p":["Morte súbita, às vezes de vários animais.","Sangue escuro que não coagula pelo nariz, boca ou ânus.","O cadáver incha muito rápido e não fica rígido."]},{"h":"O que fazer","p":["Não abra nem mova o cadáver: os esporos contaminam o solo por décadas.","Isole a área, retire os outros animais e chame o veterinário e o SENASA.","Não consuma nem venda carne desse animal.","Use luvas se teve contato e consulte o médico se tiver feridas ou espinhas na pele."]},{"h":"Prevenção","p":["Em regiões com histórico, vacinação anual conforme o programa oficial.","Destinação correta de cadáveres (enterro profundo com cal ou incineração conforme a autoridade)."]}],"rel":["Morte de um animal","Doenças clostridiais","Doenças que passam para as pessoas"]},{"t":"Raiva paralítica bovina","a":"sanidad","r":"É transmitida pelo morcego-vampiro. Não tem cura e passa para as pessoas. Previne-se com vacina e controle do morcego.","s":[{"h":"Sinais","p":["Mordidas pequenas que sangram no pescoço, lombo ou patas.","Mudanças de comportamento, babeira, dificuldade para engolir.","Paralisia que começa nas patas traseiras.","Morte em poucos dias."]},{"h":"O que fazer","p":["Não coloque a mão na boca de um animal que baba ou não engole: pode ser raiva.","Isole o animal e avise o veterinário e o SENASA.","Se alguém teve contato com saliva, que vá ao posto de saúde no mesmo dia."]},{"h":"Prevenção","p":["Vacinação antirrábica anual em regiões de risco.","Notifique mordidas de morcego ao SENASA para o controle do vampiro.","Revise os animais de manhã procurando mordidas frescas."]}],"rel":["Doenças que passam para as pessoas","Programas oficiais de sanidade","Vacinação"]},{"t":"Leptospirose","a":"sanidad","r":"Bactéria transmitida pela urina de animais infectados, incluindo ratos, na água e no barro. Afeta bovinos e pessoas.","s":[{"h":"Sinais em bovinos","p":["Febre, abatimento.","Urina vermelha ou escura em alguns casos.","Anemia e amarelidão.","Em fêmeas, abortos."]},{"h":"Prevenção","p":["Controle de ratos nos armazéns e currais.","Evite que o gado beba de poças e águas paradas.","Vacinação conforme a região e o critério do veterinário."]},{"h":"Cuidado com as pessoas","p":["Use botas e luvas ao trabalhar com urina, barro ou animais doentes.","Lave as mãos antes de comer.","Se tiver febre, dor no corpo e olhos vermelhos depois de trabalhar no barro, vá ao médico e diga que trabalha com gado."]}],"rel":["Babesiose (tristeza parasitária)","Doenças que passam para as pessoas","Controle de pragas no armazém"]},{"t":"Ceratoconjuntivite ou olho rosado","a":"sanidad","r":"Infecção do olho transmitida por moscas, poeira e pastos altos. Dói, baixa o consumo e pode deixar o animal cego.","s":[{"h":"Sinais","p":["Lacrimejamento abundante e olho fechado.","Olho vermelho e sensível à luz.","Mancha branca ou azulada no centro do olho.","Em casos graves, úlcera que pode estourar."]},{"h":"O que fazer","p":["Separe o animal e coloque-o na sombra.","Consulte o veterinário sobre o tratamento (colírios, pomadas ou injeções).","Um tampão no olho protege da luz e das moscas.","Trate cedo: a mancha branca que avança é mais difícil de curar."]},{"h":"Prevenção","p":["Controle de moscas.","Reduza a poeira molhando os currais na seca.","Evite pastos muito altos com espigas.","Isole os primeiros casos para que não contagiem."]}],"rel":["Moscas-dos-chifres e moscas-dos-estábulos","Sombra","Época seca"]},{"t":"Mancadeiras e problemas de casco","a":"sanidad","r":"Um animal manco caminha menos até o cocho e o bebedouro e ganha menos. As causas vão de pedras e barro até infecções e acidose.","s":[{"h":"Causas comuns","p":["Podridão do casco (pododermatite): infecção entre as unhas com mau cheiro e inchaço.","Piso com pedras, cimento áspero ou barro permanente.","Pregos, espinhos e feridas.","Laminite por acidose: mancadeira em várias patas semanas depois.","Pancadas no manejo ou brigas."]},{"h":"Sinais","p":["Apoia pouco uma pata ou caminha rígido.","Inchaço acima do casco.","Mau cheiro entre as unhas.","Fica deitado mais tempo."]},{"h":"O que fazer","p":["Levante a pata no brete e limpe para ver a causa.","Retire pedras ou espinhos e desinfete.","A podridão do casco precisa de tratamento indicado pelo veterinário.","Coloque o animal num curral seco e macio.","Anote no app para ver se se repete no lote."]},{"h":"Prevenção","p":["Pisos uniformes, secos e sem pedras soltas.","Pedilúvio na entrada do brete se houver muitos casos, com produto indicado.","Controle da acidose.","Manejo tranquilo, sem correrias."]}],"rel":["Pisos e drenagem","Acidose ruminal","Manejo tranquilo do gado"]},{"t":"Cálculos urinários","a":"sanidad","r":"Pedras que entopem a uretra dos machos, sobretudo castrados, quando a ração tem muito fósforo e pouco cálcio ou falta água.","s":[{"h":"Sinais","p":["Faz força para urinar e só saem gotas ou nada.","Chuta a barriga, levanta a cauda, se estica.","Cristais nos pelos do prepúcio.","Se a bexiga estoura: a barriga se enche de líquido e o animal parece melhorar antes de piorar."]},{"h":"O que fazer","p":["É urgência: chame o veterinário.","Muitas vezes é preciso cirurgia ou abate para aproveitar a carne se não houver carências."]},{"h":"Prevenção","p":["Relação cálcio:fósforo de pelo menos 2 para 1 na ração (peça ao seu nutricionista).","Sal na ração para que bebam mais água.","Água limpa, fresca e abundante sempre.","Aditivos acidificantes da urina só com indicação técnica."]}],"rel":["Minerais principais","Água de bebida","Castração"]},{"t":"Polioencefalomalácia","a":"sanidad","r":"Dano do cérebro por falta de vitamina B1 ou excesso de enxofre na ração ou na água. Aparece em animais com muito concentrado.","s":[{"h":"Sinais","p":["Cegueira: bate nas cercas.","Pressiona a cabeça contra a parede.","Olha para cima, tremores, convulsões.","Cai e pedala."]},{"h":"O que fazer","p":["Chame o veterinário imediatamente: a vitamina B1 injetada cedo pode salvá-lo.","Revise o enxofre da ração e da água (subprodutos, água de poço)."]},{"h":"Prevenção","p":["Adaptação correta ao concentrado.","Cuidado com ingredientes altos em enxofre (alguns subprodutos de destilaria, melaço em excesso).","Análise da água se for de poço."]}],"rel":["Acidose ruminal","Água de bebida","Subprodutos para a ração"]},{"t":"Intoxicação por ureia","a":"sanidad","r":"A ureia dá proteína barata, mas em excesso ou mal misturada vira amônia no sangue e mata em minutos ou horas.","s":[{"h":"Causas","p":["Mistura desigual: bolos de ureia na ração.","Animais sem adaptação que comem muito de uma vez.","Ureia dissolvida na água de bebida ou chuva sobre melaço com ureia.","Erros de pesagem: mais que o formulado."]},{"h":"Sinais","p":["Tremores musculares, especialmente na cara e nas orelhas.","Babeira, ranger de dentes, falta de coordenação.","Respiração rápida e dor de barriga.","Cai com convulsões e morre."]},{"h":"O que fazer","p":["Chame o veterinário imediatamente.","Retire o alimento com ureia.","Dar vinagre pela boca em grandes quantidades é uma medida de emergência usada no campo; pergunte antes ao veterinário."]},{"h":"Regras para usar ureia","p":["Não mais de 1 % da ração total nem mais de um terço da proteína.","Adapte em 1 a 2 semanas subindo aos poucos.","Misture primeiro com uma parte do alimento e depois com o resto.","Nunca na água.","Sempre com fonte de energia (grão, melaço) e enxofre.","Não dê a animais magros, em jejum ou doentes."]}],"rel":["Ureia na ração","Mistura da ração","Proteína na ração"]},{"t":"Intoxicação por plantas e fungos","a":"sanidad","r":"Plantas tóxicas do pasto e fungos no alimento guardado podem adoecer ou matar vários animais ao mesmo tempo.","s":[{"h":"Plantas de risco no trópico","p":["Folhas de mandioca e sorgo novo ou rebrotado depois de seca ou geada: podem dar cianeto.","Samambaia (Pteridium): urina com sangue e tumores com consumo prolongado.","Mamona: sementes muito tóxicas.","Plantas ornamentais como a espirradeira (oleandro): basta uma pequena quantidade.","Leucena em excesso sem adaptação: queda de pelo e problemas de tireoide.","Pastos com muito nitrato depois de adubação forte e seca."]},{"h":"Fungos e micotoxinas","p":["Milho, sorgo ou concentrado molhado que embolorece produz toxinas (aflatoxinas e outras).","Baixam o consumo, o ganho e as defesas; em excesso danificam o fígado.","Nem sempre se vê o mofo: o grão quebrado e úmido é de risco."]},{"h":"Sinais","p":["Vários animais doentes ou mortos ao mesmo tempo.","Tremores, babeira, respiração rápida, convulsões.","Diarreia, cólica, urina com sangue.","Queda de consumo sem causa clara em todo o lote."]},{"h":"O que fazer","p":["Retire os animais do pasto ou o alimento suspeito.","Chame o veterinário e guarde uma amostra do alimento ou da planta.","Dê água limpa e feno de confiança."]},{"h":"Prevenção","p":["Percorra os pastos e arranque plantas tóxicas antes de colocar o gado.","Não solte animais com fome em pastos novos.","Compre grão seco e guarde em armazém seco e ventilado.","Descarte alimento com cheiro de mofo, empedrado ou quente.","Peça análise de micotoxinas se comprar grão em grande quantidade."]}],"rel":["Armazenamento do alimento","Plantas tóxicas nos pastos","Milho e outros grãos"]},{"t":"Golpe de calor","a":"sanidad","r":"Quando o calor e a umidade superam a capacidade do animal de se resfriar, ele para de comer, ofega e pode morrer. Os animais gordos e de raças europeias sofrem mais.","s":[{"h":"Sinais","p":["Ofegância com a boca aberta e a língua para fora.","Babeira e cabeça esticada.","Amontoam-se na sombra ou junto ao bebedouro.","Param de comer nas horas quentes.","Tremores, caem: emergência."]},{"h":"O que fazer no momento","p":["Não os mova nem os trabalhe.","Molhe o piso e os animais com água, sobretudo a cabeça e o pescoço; melhor se houver vento.","Garanta água fresca de sobra e espaço no bebedouro.","Chame o veterinário se um animal estiver caído ou muito agitado."]},{"h":"Prevenção","p":["Sombra de 3 a 4 m² por animal.","Água fresca, limpa e com boa vazão; acrescente bebedouros no verão.","Sirva mais alimento cedo e no fim da tarde.","Trabalhe o gado só antes das 9 da manhã.","Veja o índice de calor na calculadora do Rumi."]},{"h":"Números-chave","p":["Índice de calor de 72 a 78: alerta.","79 a 83: perigo.","84 ou mais: emergência.","Um animal com calor pode beber o dobro de água."]}],"rel":["Estresse por calor","Sombra","Bebedouros","Índice de calor"]},{"t":"Feridas e curativos","a":"sanidad","r":"Uma ferida mal tratada atrai moscas, bicheira e infecções. A regra é tratar no mesmo dia e revisar até fechar.","s":[{"h":"Passos para tratar","p":["Contenha bem o animal no brete.","Lave com água limpa e sabão, retire pelos, terra e tecido morto.","Aplique um antisséptico de uso veterinário.","Coloque um produto cicatrizante e repelente de moscas.","Revise todo dia; repita o curativo se necessário."]},{"h":"Quando chamar o veterinário","p":["Ferida profunda, que sangra muito ou que deixa ver osso ou tendão.","Inchaço que cresce rápido, quente ou que crepita ao tocar.","Ferida com mau cheiro e o animal com febre.","Feridas em articulações ou no olho."]},{"h":"Abscessos","p":["São caroços com pus, muitas vezes em locais de injeção.","Quando estão moles, o veterinário os abre, drena e lava.","Se o abscesso está perto da venda, avise: é aparado no frigorífico."]},{"h":"Prevenção","p":["Conserte pregos, arames e tábuas que cortam.","Manejo tranquilo, sem paus nem ferrões.","Agulhas limpas e bem afiadas.","Castrações e descornas com higiene e na época de poucas moscas."]}],"rel":["Bicheira (Cochliomyia)","Aplicação de injeções","Manutenção de instalações"]},{"t":"Vacinação","a":"sanidad","r":"As vacinas previnem doenças que matam rápido ou que baixam muito o ganho. Só funcionam se forem bem guardadas, aplicadas e reforçadas.","s":[{"h":"Vacinas mais usadas no confinamento","p":["Clostridiais (polivalente): quase obrigatória em todo confinamento.","Respiratórias (IBR, BVD, PI3, BRSV e bactérias): conforme o risco e o veterinário.","Raiva: em regiões com morcego-vampiro.","Antraz: em regiões com histórico.","Leptospirose: conforme a região."]},{"h":"Como conservá-las","p":["Entre 2 e 8 °C, nunca congeladas.","Em caixa térmica com gelo ao levá-las ao curral, sem que o frasco toque direto o gelo.","Protegidas do sol.","Frasco aberto: use no mesmo dia e descarte a sobra."]},{"h":"Como aplicar","p":["Animais sadios, descansados e com água.","No pescoço (tábua do pescoço), nunca na perna nem na garupa.","Subcutânea ou intramuscular conforme o rótulo.","Uma agulha limpa a cada 10 a 15 animais ou antes se entortar ou perder o fio.","Dose exata com seringa calibrada."]},{"h":"Reforços","p":["Muitas vacinas precisam de segunda dose aos 21 a 30 dias para proteger bem.","Anote a data do reforço no app e cumpra.","A proteção leva 2 a 3 semanas para se formar depois da última dose."]},{"h":"Erros comuns","p":["Vacinar animais doentes ou recém-chegados sem água nem descanso.","Misturar vacinas na mesma seringa.","Aplicar na perna: deixa lesões em cortes caros.","Não aplicar o reforço.","Usar vacinas vencidas ou aquecidas."]}],"rel":["Plano sanitário de entrada","Aplicação de injeções","Doenças clostridiais"]},{"t":"Vermifugação e resistência","a":"sanidad","r":"Vermifugar bem é dar o produto certo, na dose certa, no momento certo. Fazer mal cria parasitas que já não morrem.","s":[{"h":"Grupos de produtos","p":["Lactonas macrocíclicas (ivermectina, doramectina e outras): vermes e alguns parasitas externos.","Benzimidazóis (albendazol, fenbendazol e outros): vermes; alguns agem sobre a fascíola.","Levamisol: vermes redondos.","Produtos específicos contra fascíola (por exemplo closantel ou outros).","Cada grupo mata de um jeito: trocar marcas do mesmo grupo não é rotacionar."]},{"h":"Como vermifugar","p":["Calcule a dose pelo peso real; se não pesar, use o peso do maior do grupo.","Confira a concentração do produto no rótulo.","Calibre a seringa ou a pistola antes de começar.","Aplique no local e pela via que o rótulo indica.","Anote produto, dose, data e carência."]},{"h":"Quando","p":["Sempre na entrada do confinamento.","No confinamento em curral fechado, muitas vezes basta uma vermifugação bem feita.","No pasto ou semiconfinamento, repita conforme o plano do veterinário e a época de chuvas."]},{"h":"Evitar resistência","p":["Não dê doses baixas.","Não vermifugue por costume se não houver necessidade.","Rotacione grupos químicos conforme o veterinário.","Faça contagem de ovos nas fezes para ver se o produto funciona."]},{"h":"Carências","p":["Alguns injetáveis de longa ação têm carências de mais de um mês.","Se vai vender logo, escolha um produto com carência curta.","O app avisa se você tentar vender um lote em carência."]}],"rel":["Parasitas internos","Fascíola ou baratinha do fígado","Uso responsável de antibióticos"]},{"t":"Uso responsável de antibióticos","a":"sanidad","r":"Os antibióticos salvam animais, mas mal usados criam bactérias resistentes e deixam resíduos na carne. Use só quando necessário e como o veterinário indicar.","s":[{"h":"Quando sim","p":["Infecções bacterianas diagnosticadas: pneumonia, podridão do casco, feridas infectadas.","Quando o veterinário indica para o lote em risco alto."]},{"h":"Quando não","p":["Diarreias por mudança de ração.","Animais magros sem diagnóstico.","Só vírus (não os matam).","Para engordar ou para que comam mais: é proibido em muitos países e não é boa prática."]},{"h":"Regras de uso","p":["Produto registrado, dose por peso, via indicada e duração completa.","Não misture antibióticos na mesma seringa.","Máximo 10 ml por local de injeção intramuscular, no pescoço.","Guarde o frasco na caixa, longe do sol."]},{"h":"Carências","p":["A carência é o tempo desde a última dose até o animal poder ir ao frigorífico.","Se usou vários produtos, vale a carência mais longa.","Anote sempre no app a carência: ele avisa antes de vender.","Vender em carência pode causar condenação, multas e perda do comprador."]}],"rel":["Carências e resíduos","Pneumonia ou complexo respiratório","Aplicação de injeções"]},{"t":"Aplicação de injeções","a":"sanidad","r":"Injetar bem cuida da saúde do animal e da qualidade da carne. Uma má injeção deixa abscessos, lesões e perdas na carcaça.","s":[{"h":"Onde","p":["Na tábua do pescoço: triângulo à frente da paleta, abaixo da crista e acima da veia do pescoço.","Nunca na perna, na garupa ou no lombo: são os cortes mais caros."]},{"h":"Vias","p":["Subcutânea: embaixo do couro, levantando uma prega; agulha curta.","Intramuscular: no músculo do pescoço, agulha mais longa.","Intravenosa: só o veterinário aplica.","Siga sempre a via indicada no rótulo."]},{"h":"Agulhas","p":["Calibre 16 a 18; comprimento de 1/2 a 3/4 de polegada para subcutânea e 1 a 1,5 polegada para intramuscular em adultos.","Troque a agulha a cada 10 a 15 animais ou se entortar, perder a ponta ou sujar.","Nunca endireite uma agulha torta.","Agulha quebrada dentro do animal: marque-o e avise o comprador."]},{"h":"Boas práticas","p":["Animal bem contido no brete.","Pele limpa e seca.","Máximo 10 ml por local intramuscular; separe os locais pelo menos um palmo.","Anote produto e data no app."]}],"rel":["Vacinação","Uso responsável de antibióticos","Tronco, brete e funil"]},{"t":"Farmácia do confinamento","a":"sanidad","r":"Ter à mão o necessário permite agir rápido. Uma farmácia organizada evita mortes e viagens.","s":[{"h":"Equipamento","p":["Termômetro digital (e um de reserva).","Seringas descartáveis de 3, 5, 10 e 20 ml, e seringa automática ou pistola.","Agulhas de diferentes comprimentos e calibres.","Luvas, tesoura, bisturi, pinças e cordas.","Lanterna, caderno ou celular com o app.","Sonda para timpanismo e trocarte (só para uso treinado)."]},{"h":"Insumos","p":["Antisséptico (iodo ou clorexidina) e sabão.","Produto para feridas com repelente e larvicida.","Soros orais para desidratação.","Vitaminas e os produtos que seu veterinário indicar para emergências.","Vermífugos e vacinas do plano, na devida conservação."]},{"h":"Ordem e segurança","p":["Guarde trancada, em lugar fresco e sem sol.","Revise as datas de validade todo mês.","Separe medicamentos de venenos e de alimento.","Tenha à mão o telefone do veterinário e do SENASA."]}],"rel":["Revisão diária dos animais","Uso responsável de antibióticos","Curral de doentes"]},{"t":"Plano sanitário de entrada","a":"sanidad","r":"O que você faz nas primeiras horas e semanas define a saúde de todo o lote. Um bom protocolo de entrada baixa doenças e mortes.","s":[{"h":"Na chegada","p":["Descarregue com calma, deixe descansar com água e feno de boa qualidade.","Revise um por um: mancos, feridos, magros ou doentes vão à parte.","Não faça o manejo sanitário se chegaram muito cansados; espere algumas horas ou até cedo no dia seguinte."]},{"h":"Dia 1 (ou no dia seguinte)","p":["Pese cada animal e coloque o brinco.","Vacina clostridial polivalente.","Vermífugo interno e externo conforme o veterinário.","Vacina respiratória se estiver no seu plano.","Vitaminas se o veterinário recomendar.","Anote tudo no app com o lote e a data."]},{"h":"Dias 1 a 21","p":["Revisão duas vezes ao dia com o método DART.","Meça a temperatura dos suspeitos.","Tratamento precoce dos doentes.","Adaptação gradual à ração."]},{"h":"Dias 21 a 30","p":["Reforço da vacina clostridial e da respiratória, se aplicável.","Primeira pesagem de controle para ver quem arranca e quem não.","Castração ou descorna, se forem feitas, quando o animal já estiver sadio e adaptado."]},{"h":"Regras","p":["Todo animal novo entra no curral de recepção, não com os que já estão.","Um protocolo escrito com seu veterinário, sempre igual, dá melhores resultados que improvisar.","Registre quantos adoeceram por lote e de qual origem."]}],"rel":["Recepção de gado","Vacinação","Pneumonia ou complexo respiratório","Quarentena e biossegurança"]},{"t":"Quarentena e biossegurança","a":"sanidad","r":"A biossegurança são as barreiras para que doenças não entrem na sua fazenda nem se espalhem dentro dela.","s":[{"h":"Animais que entram","p":["Compre de fornecedores conhecidos, com guia de trânsito e animais revisados.","Curral de quarentena separado, sem compartilhar bebedouros com os demais.","Observe 2 a 3 semanas antes de misturar.","Trate parasitas externos antes de entrarem."]},{"h":"Pessoas e veículos","p":["Os caminhões de gado não devem entrar nos currais; que carreguem pelo embarcadouro.","Visitas com botas limpas ou desinfetadas.","Limpe equipamento emprestado (bretes portáteis, balanças) antes de usar."]},{"h":"Dentro da fazenda","p":["Trabalhe primeiro com os animais sadios e por último com os doentes.","Agulhas e equipamento limpos entre animais.","Controle de ratos, cães e aves nos armazéns.","Retire e dê destino rápido aos cadáveres."]},{"h":"Água e alimento","p":["Água de bebedouros, não de poças ou córregos compartilhados.","Alimento guardado em armazém fechado.","Não use restos de comida da cozinha nem subprodutos de origem duvidosa."]}],"rel":["Plano sanitário de entrada","Curral de doentes","Morte de um animal"]},{"t":"Curral de doentes","a":"sanidad","r":"Um curral à parte para doentes e lesionados facilita tratá-los, os recupera melhor e protege o resto.","s":[{"h":"Como deve ser","p":["Perto do brete, mas longe dos currais de recepção.","Com sombra, piso seco e macio.","Bebedouro próprio com água limpa.","Cocho com feno de boa qualidade e um pouco da ração.","Espaço para o animal deitar confortável."]},{"h":"Manejo","p":["Anote cada animal que entra: data, brinco, temperatura e tratamento.","Revise duas vezes ao dia.","Devolva ao lote quando comer bem e tiver temperatura normal por dois dias.","Se não melhorar no tempo que o veterinário disse, decida se vende (sem carência) ou sacrifica."]},{"h":"Animais crônicos","p":["Os que adoecem várias vezes raramente recuperam o ganho.","Vendê-los a tempo (respeitando carências) costuma custar menos que continuar tratando."]}],"rel":["Revisão diária dos animais","Quarentena e biossegurança","Animais atrasados"]},{"t":"Morte de um animal","a":"sanidad","r":"Cada morte é uma perda de tudo o que foi investido. Saber por que morreu ajuda a salvar os demais.","s":[{"h":"O que fazer primeiro","p":["Veja se sangra pelo nariz, boca ou ânus: se sim, não abra e chame o veterinário (possível antraz).","Afaste o resto do lote do local.","Anote a morte no app com a causa provável."]},{"h":"Necropsia","p":["O veterinário abre o cadáver e examina pulmões, fígado, rúmen e intestinos.","Faça o quanto antes: depois de 12 horas com calor perde-se informação.","Se morreram vários, é ainda mais importante."]},{"h":"Destino do cadáver","p":["Enterro profundo, longe de fontes de água e de currais, com cal.","Ou incineração ou o que a autoridade indicar.","Não deixe cadáveres ao ar livre: atraem cães e urubus e espalham doenças.","Não consuma nem venda carne de animais mortos ou doentes."]},{"h":"Aprender com cada morte","p":["Revise todo mês no app as causas de morte por lote e por origem.","Se uma causa se repete, mude o manejo com seu veterinário.","Uma mortalidade acima de 1 a 2 % no confinamento indica um problema."]}],"rel":["Antraz (carbúnculo hemático)","Mortalidade e seu custo","Quarentena e biossegurança"]},{"t":"Problemas de pele","a":"sanidad","r":"Tinha, fotossensibilização, piolhos e sarna danificam o couro, causam coceira e baixam o ganho.","s":[{"h":"Tinha","p":["Manchas redondas sem pelo, com crosta cinza, sobretudo na cara e no pescoço.","Contagia-se entre animais e para pessoas.","É mais comum em animais jovens e currais úmidos e escuros.","Consulte o tratamento; melhora com sol e boa nutrição."]},{"h":"Fotossensibilização","p":["A pele branca queima ao sol, fica vermelha, incha e descasca.","Vem de algumas plantas ou de dano no fígado.","Tire os animais do sol e do pasto suspeito e consulte o veterinário."]},{"h":"Piolhos e sarna","p":["Coceira forte, se esfregam em postes, áreas sem pelo.","Mais comuns na época fresca e com superlotação.","Tratam-se com produtos antiparasitários externos conforme o rótulo."]},{"h":"Prevenção","p":["Controle de parasitas externos na entrada.","Currais com sol e ventilação.","Boa nutrição mineral e vitamínica."]}],"rel":["Carrapatos","Doenças que passam para as pessoas","Minerais principais"]},{"t":"Deficiências de minerais","a":"sanidad","r":"A falta de fósforo, cobre, zinco, selênio ou cobalto não mata rápido, mas freia o ganho e baixa as defesas.","s":[{"h":"Fósforo","p":["Muito comum em pastos do trópico.","Sinais: os animais lambem terra, ossos ou madeira; pouco ganho.","Corrige-se com sal mineral ou núcleo mineral com fósforo."]},{"h":"Cobre","p":["Pelo descolorido (preto que fica avermelhado), anemia, diarreia.","O excesso de molibdênio ou enxofre o bloqueia."]},{"h":"Zinco","p":["Pele grossa, queda de pelo, cascos fracos, mais infecções."]},{"h":"Selênio e vitamina E","p":["Fraqueza muscular, animais que se cansam ao caminhar.","O excesso de selênio é tóxico: não acrescente por conta própria."]},{"h":"Cobalto","p":["Necessário para a vitamina B12 que o rúmen fabrica.","Falta: pouco apetite, anemia, pelo feio."]},{"h":"Prevenção","p":["Núcleo mineral completo na ração de curral.","Sal mineral à vontade no pasto, em saleiros cobertos.","O sal branco sozinho não basta.","Análise de solo ou de forragem para saber o que falta na sua região."]}],"rel":["Minerais principais","Microminerais e vitaminas","Sal mineral e blocos"]},{"t":"Doenças virais respiratórias e BVD","a":"sanidad","r":"IBR, diarreia viral bovina (BVD), PI3 e BRSV são vírus que baixam as defesas e abrem caminho para a pneumonia.","s":[{"h":"IBR (rinotraqueíte)","p":["Febre, focinho vermelho com crostas, muco, lacrimejamento.","Contagia-se por contato e pelo ar."]},{"h":"BVD (diarreia viral bovina)","p":["Pode dar diarreia, feridas na boca e baixar muito as defesas.","Alguns animais nascem infectados para a vida toda (persistentemente infectados) e contagiam sem parar."]},{"h":"PI3 e BRSV","p":["Vírus respiratórios que complicam a pneumonia, sobretudo em animais jovens."]},{"h":"Controle","p":["Vacinas respiratórias conforme seu veterinário, idealmente antes ou na chegada ao confinamento.","Evite misturar muitas origens.","Bom manejo de recepção e menos estresse.","Se houver muitos casos, peça exames de laboratório para saber qual vírus circula."]}],"rel":["Pneumonia ou complexo respiratório","Vacinação","Recepção de gado"]},{"t":"Defeitos a revisar na compra","a":"sanidad","r":"Há problemas que, se você os compra, farão perder dinheiro em todo o confinamento. Revisá-los no leilão ou na fazenda de origem evita dores de cabeça.","s":[{"h":"Revise","p":["Hérnias de umbigo ou de escroto (caroço mole).","Olhos: manchas brancas, cegueira.","Patas e cascos: mancadeiras, articulações inchadas.","Boca: dentes gastos ou faltando em animais velhos.","Respiração: tosse, muco, respiração rápida.","Pele: tinha, sarna, carrapatos, feridas e bicheira."]},{"h":"Condição","p":["Animais magros demais podem estar doentes, não só mal alimentados.","Barriga muito cheia pode ser parasitas ou enchimento para pesar mais.","Animais nervosos ou agressivos engordam pior e são perigosos."]},{"h":"Documentos","p":["Guia de trânsito do SENASA.","Registro de vacinas e tratamentos se o vendedor tiver.","Origem dos animais."]},{"h":"Regra prática","p":["Se tiver dúvida sobre um animal, não compre ou baixe o preço.","Um animal problemático custa mais que seu desconto."]}],"rel":["Comprar gado para engorda","Hérnias e prolapsos","Guia de trânsito e rastreabilidade"]},{"t":"Hérnias e prolapsos","a":"sanidad","r":"São caroços por saída de tecido ou de órgãos. Alguns se podem manejar, outros obrigam a vender ou a chamar o veterinário rápido.","s":[{"h":"Hérnia de umbigo","p":["Caroço mole no umbigo que entra ao ser empurrado.","Se for pequena pode não dar problema; se crescer, endurecer ou doer, chame o veterinário.","Evite comprar animais com hérnias grandes."]},{"h":"Prolapso retal","p":["Sai parte do reto pelo ânus, vermelho e úmido.","Vem de tosse forte, diarreia, esforço ou implantes mal usados.","Proteja de pancadas e moscas, mantenha úmido e limpo e chame o veterinário logo."]},{"h":"O que decidir","p":["Se o problema se repete ou não tem conserto, venda o animal (sem carências) antes que perca mais.","Anote no app para não comprar de novo desse fornecedor se se repetir."]}],"rel":["Defeitos a revisar na compra","Diarreia no confinamento"]},{"t":"Urina vermelha ou escura","a":"sanidad","r":"A urina vermelha ou marrom é um sinal de alarme. Pode vir de várias doenças diferentes, e o tratamento muda conforme a causa.","s":[{"h":"Possíveis causas","p":["Babesiose (tristeza parasitária): febre e urina vermelha, transmitida pelo carrapato.","Leptospirose: urina escura, febre, anemia.","Hemoglobinúria bacilar (clostridial): morte rápida.","Samambaia (Pteridium) consumida por muito tempo: sangue na urina.","Algumas intoxicações por plantas ou cobre."]},{"h":"O que fazer","p":["Separe o animal, meça a temperatura e não o faça correr.","Chame o veterinário no mesmo dia.","Procure carrapatos no animal e no lote.","Revise o pasto procurando samambaia ou outras plantas."]},{"h":"Prevenção","p":["Controle de carrapatos.","Vacina clostridial completa.","Controle de ratos e água limpa.","Limpeza de plantas tóxicas."]}],"rel":["Babesiose (tristeza parasitária)","Leptospirose","Doenças clostridiais","Intoxicação por plantas e fungos"]},{"t":"Doenças que passam para as pessoas","a":"sanidad","r":"Várias doenças do gado passam para as pessoas. Proteger-se é parte do trabalho diário na fazenda.","s":[{"h":"As principais","p":["Raiva: pela saliva; mortal se a pessoa não for vacinada a tempo.","Antraz: por contato com cadáveres ou couros.","Brucelose: por fetos, placentas e leite cru.","Tuberculose: pelo ar e leite cru.","Leptospirose: por urina, barro e água contaminada.","Tinha: por contato com a pele."]},{"h":"Proteção","p":["Luvas ao tocar animais doentes, mortos, feridas ou fetos.","Não coloque a mão na boca de um animal que baba.","Lave as mãos antes de comer, beber ou fumar.","Não coma carne de animais mortos ou doentes nem leite cru de rebanhos sem controle.","Botas nos currais e no barro."]},{"h":"Se você adoecer","p":["Vá ao posto de saúde e diga que trabalha com gado.","Febre que vai e volta, dores e cansaço podem ser brucelose.","Se um animal suspeito de raiva mordeu ou babou em você, vá no mesmo dia."]}],"rel":["Raiva paralítica bovina","Antraz (carbúnculo hemático)","Brucelose e tuberculose","Leptospirose"]},{"t":"Brucelose e tuberculose","a":"sanidad","r":"São doenças sob programa oficial por seu risco para as pessoas e o comércio. No confinamento importam pela origem dos animais e pela venda.","s":[{"h":"Brucelose","p":["Causa abortos em fêmeas e problemas em touros.","Passa para as pessoas por placentas, fetos e leite cru.","As novilhas e vacas de descarte que entram no confinamento podem portá-la."]},{"h":"Tuberculose","p":["Doença lenta que emagrece o animal e danifica os pulmões.","Detecta-se com o teste de tuberculina e no frigorífico.","Um achado no frigorífico leva a rastrear a fazenda de origem."]},{"h":"O que fazer","p":["Compre de fazendas com controle ou certificação quando possível.","Participe dos programas do SENASA.","Se o frigorífico reportar lesões, colabore com o rastreamento."]}],"rel":["Programas oficiais de sanidade","Doenças que passam para as pessoas","Guia de trânsito e rastreabilidade"]},{"t":"Desidratação e soros","a":"sanidad","r":"Um animal desidratado enfraquece rápido. Reconhecer e dar líquidos a tempo salva vidas, sobretudo depois de viagens e diarreias.","s":[{"h":"Sinais","p":["Olhos fundos.","Prega de pele do pescoço que demora mais de 2 segundos para voltar.","Focinho e boca secos.","Fezes duras e pouca urina.","Fraqueza, não se levanta."]},{"h":"Causas","p":["Viagens longas sem água.","Diarreia.","Calor forte com pouca água.","Febre alta."]},{"h":"O que fazer","p":["Água limpa e fresca à vontade.","Soros orais para bovinos conforme o rótulo, em animais que ainda engolem.","Se está caído ou muito fraco, o veterinário pode dar soro na veia.","Sombra e descanso."]},{"h":"Prevenção","p":["Água na chegada e bebedouros suficientes.","Viagens nas horas frescas.","Atender diarreias cedo."]}],"rel":["Diarreia no confinamento","Recepção de gado","Água de bebida"]},{"t":"Tripanossomose","a":"sanidad","r":"Parasita do sangue transmitido por moscas picadoras e mutucas, e por agulhas compartilhadas. Causa anemia e perda de peso.","s":[{"h":"Sinais","p":["Febre que vai e volta.","Anemia e mucosas pálidas.","Perda de peso apesar de comer.","Lacrimejamento, inchaço nas patas ou na barbela."]},{"h":"Diagnóstico","p":["O veterinário confirma com uma amostra de sangue.","Confunde-se com anaplasmose: o diagnóstico evita tratar errado."]},{"h":"Prevenção","p":["Controle de moscas e mutucas.","Uma agulha limpa por animal quando houver casos na região.","Revisão de animais trazidos de regiões afetadas."]}],"rel":["Anaplasmose","Moscas-dos-chifres e moscas-dos-estábulos","Aplicação de injeções"]},{"t":"Actinomicose e actinobacilose (língua de pau)","a":"sanidad","r":"Infecções por bactérias que entram por feridas na boca. Dão caroços duros na mandíbula ou uma língua dura e inchada.","s":[{"h":"Actinomicose (mandíbula)","p":["Caroço duro no osso da mandíbula que cresce devagar e pode abrir com pus.","Vem de feridas por forragens duras ou espinhos."]},{"h":"Língua de pau","p":["Língua dura, inchada e que sai da boca.","Baba e não consegue comer bem."]},{"h":"O que fazer","p":["Consulte o veterinário: a língua de pau responde bem se tratada cedo.","A actinomicose avançada raramente se cura: considere vender o animal sem carências.","Revise a forragem: palhas e espinhos duros machucam a boca."]}],"rel":["Feridas e curativos","Defeitos a revisar na compra"]},{"t":"Verrugas ou papilomas","a":"sanidad","r":"Caroços na pele causados por um vírus. São comuns em animais jovens e costumam desaparecer sozinhos.","s":[{"h":"Como são","p":["Caroços cinzentos ou como couve-flor na cabeça, pescoço e paletas.","Contagiam-se por contato, cercas, bretes e agulhas."]},{"h":"O que fazer","p":["Quase sempre desaparecem em meses.","As muito grandes ou que sangram o veterinário pode retirar.","Separe os muito afetados se possível."]},{"h":"Prevenção","p":["Agulhas limpas e desinfecção de equipamento.","Revisão na compra: alguns compradores descontam animais com muitas verrugas."]}],"rel":["Problemas de pele","Defeitos a revisar na compra"]},{"t":"Tétano","a":"sanidad","r":"Doença clostridial que entra por feridas e causa rigidez dos músculos. Quase sempre é mortal.","s":[{"h":"Sinais","p":["Rigidez: caminha como cavalete, cauda levantada.","Orelhas eretas e terceira pálpebra visível.","Timpanismo porque não consegue arrotar.","Cai com as patas esticadas."]},{"h":"Quando aparece","p":["1 a 3 semanas depois de castrações, elásticos, descornas ou feridas profundas."]},{"h":"Prevenção","p":["Vacina clostridial que inclua tétano.","Higiene nas castrações e cura de feridas.","Cuidado com os elásticos em animais grandes."]}],"rel":["Doenças clostridiais","Castração","Feridas e curativos"]},{"t":"Intoxicação por nitratos e cianeto","a":"sanidad","r":"Alguns pastos e cultivos acumulam nitratos ou cianeto em certas condições. Podem matar em minutos ou horas.","s":[{"h":"Nitratos","p":["Pastos adubados com muito nitrogênio depois de seca, ou restolhos de milho e sorgo estressados.","Sinais: respiração rápida, mucosas e sangue cor de chocolate, fraqueza, morte."]},{"h":"Cianeto","p":["Sorgo novo ou rebrotado, sorgo depois de geada ou seca, mandioca brava, algumas folhas.","Sinais: respiração muito rápida, sangue vermelho brilhante, tremores, morte muito rápida."]},{"h":"O que fazer","p":["Retire os animais do pasto ou a forragem.","Chame o veterinário imediatamente: há tratamentos se agir rápido."]},{"h":"Prevenção","p":["Não paste sorgo com menos de 60 cm nem rebrotas novas.","A silagem baixa o cianeto; o feno bem curado também.","Análise de nitratos se suspeitar da forragem.","Adapte os animais a forragens novas aos poucos."]}],"rel":["Intoxicação por plantas e fungos","Plantas tóxicas nos pastos","Capins de corte"]},{"t":"Animal caído que não se levanta","a":"sanidad","r":"Um animal que não se levanta pode ter muitas causas. Quanto mais tempo fica deitado, mais se machuca.","s":[{"h":"Causas possíveis","p":["Pancadas, fraturas ou luxações.","Acidose ou intoxicações.","Anaplasmose ou babesiose com anemia forte.","Doenças nervosas (raiva, polioencefalomalácia).","Esgotamento depois da viagem."]},{"h":"O que fazer","p":["Não o arraste nem o levante à força.","Dê sombra, água e comida ao alcance.","Mude-o de lado a cada poucas horas se puder e coloque cama macia.","Chame o veterinário.","Se baba ou não engole, não coloque a mão na boca."]},{"h":"Decisão","p":["Se o veterinário não vê recuperação, a eutanásia humanitária evita sofrimento.","Nunca venda para consumo um animal caído ou doente."]}],"rel":["Morte de um animal","Bem-estar animal","Raiva paralítica bovina"]},{"t":"Coletar amostras para laboratório","a":"sanidad","r":"Um bom diagnóstico começa com uma boa amostra. Pergunte ao veterinário ou ao laboratório antes de coletar.","s":[{"h":"Fezes","p":["Do reto, com luva, um punhado.","Em saco limpo, sem ar, rotulado e refrigerado (sem congelar).","Para parasitas e coccídios."]},{"h":"Sangue","p":["O veterinário coleta em tubos especiais.","Para anemia, anaplasmose, babesiose, tripanossomas e testes de doenças."]},{"h":"Alimento e água","p":["Várias subamostras misturadas.","Saco ou frasco limpo, rotulado.","Para micotoxinas, nitratos, sais ou bactérias."]},{"h":"Regras","p":["Rotule com data, lote, brinco e o que se suspeita.","Entregue rápido, em caixa térmica.","Anote o resultado no app junto ao tratamento."]}],"rel":["Análise de ingredientes","Parasitas internos","Morte de um animal"]},{"t":"Estresse e defesas","a":"sanidad","r":"O estresse baixa as defesas do animal. Por isso quase todas as doenças do confinamento aparecem depois de viagens, misturas e manejos bruscos.","s":[{"h":"O que estressa","p":["Transporte e jejum.","Desmame recente.","Mistura com animais desconhecidos.","Castração, descorna ou manejo brusco.","Calor, barro, poeira e superlotação.","Mudanças de ração."]},{"h":"Como reduzir","p":["Uma mudança por vez: não castre, vacine e mude a ração no mesmo dia.","Manejo tranquilo.","Água, sombra e boa comida.","Lotes estáveis, sem misturas."]},{"h":"Resultado","p":["Menos pneumonias e mortes.","Melhor consumo e ganho.","Menos gasto com medicamentos."]}],"rel":["Manejo tranquilo do gado","Recepção de gado","Pneumonia ou complexo respiratório"]},{"t":"Febre aftosa e doenças exóticas","a":"sanidad","r":"A febre aftosa não está presente na América Central. Se aparecesse, fecharia mercados. Reconhecer seus sinais e avisar protege todo o país.","s":[{"h":"Sinais que obrigam a avisar","p":["Bolhas ou feridas na boca, língua, patas ou úbere.","Babeira abundante e mancadeira em vários animais ao mesmo tempo.","Febre e queda forte do consumo no lote."]},{"h":"O que fazer","p":["Não mova animais dentro nem fora da fazenda.","Avise imediatamente o SENASA.","Não deixe entrar nem sair pessoas e veículos sem desinfecção."]},{"h":"Prevenção","p":["Compre com guia e de origem conhecida.","Biossegurança na entrada da fazenda.","Não alimente com restos de comida de origem desconhecida."]}],"rel":["Doenças de notificação obrigatória","Quarentena e biossegurança","Programas oficiais de sanidade"]},{"t":"Picada de cobra","a":"sanidad","r":"As cobras venenosas podem matar ou deixar muito mal um animal, sobretudo se a picada for na cara ou no pescoço.","s":[{"h":"Sinais","p":["Inchaço grande e rápido, muitas vezes na cara, focinho ou patas.","Marcas de presas e sangramento.","Dificuldade para respirar se o inchaço for na cabeça."]},{"h":"O que fazer","p":["Mantenha o animal quieto e na sombra.","Chame o veterinário: existem soros e tratamentos.","Não corte nem chupe a ferida, não coloque torniquetes."]},{"h":"Prevenção","p":["Roce ao redor de currais e armazéns.","Controle ratos: atraem cobras."]}],"rel":["Inchaços: o que podem ser","Controle de pragas no armazém"]},{"t":"Inchaços: o que podem ser","a":"sanidad","r":"Nem todos os inchaços são iguais. Alguns são urgência e outros podem esperar.","s":[{"h":"Urgência","p":["Inchaço que cresce rápido, quente no início e frio depois, que crepita ao tocar: clostridial.","Inchaço na cara com dificuldade para respirar: picada ou alergia.","Flanco esquerdo inchado: timpanismo."]},{"h":"Pode esperar o veterinário","p":["Caroço mole no local de uma injeção: abscesso.","Caroço mole no umbigo que entra ao empurrar: hérnia.","Inchaço embaixo da mandíbula com animal magro: parasitas ou anemia."]},{"h":"Regras","p":["Anote onde está, quando apareceu e se cresce.","Meça a temperatura.","Não estoure caroços com faca."]}],"rel":["Doenças clostridiais","Feridas e curativos","Hérnias e prolapsos"]},{"t":"Fotossensibilização","a":"sanidad","r":"A fotossensibilização é uma queimadura da pele pelo sol, provocada por substâncias de algumas plantas ou por dano no fígado. Afeta a pele branca ou sem pelo.","s":[{"h":"Causas","p":["Capins do gênero Brachiaria (Urochloa), sobretudo decumbens, em certas condições: têm saponinas que danificam o fígado.","Algumas plantas tóxicas e fungos do pasto.","Dano no fígado por outras causas."]},{"h":"Sinais","p":["Pele vermelha, inchada e com crostas nas orelhas, focinho, lombo e partes brancas.","O animal procura sombra, se coça e para de comer.","Às vezes olhos lacrimejantes e icterícia (mucosas amarelas)."]},{"h":"O que fazer","p":["Retire os animais do pasto suspeito e coloque-os na sombra.","Chame o veterinário: o tratamento depende de o fígado estar danificado.","Os animais jovens e recém-chegados a esses pastos são os mais afetados."]}],"rel":["Intoxicação por plantas e fungos","Problemas de pele","O fígado do bovino"]},{"t":"Estomatite vesicular","a":"sanidad","r":"A estomatite vesicular é uma doença viral que causa bolhas na boca, nas patas e nos úberes. Parece-se muito com a febre aftosa, por isso sempre deve ser notificada.","s":[{"h":"Sinais","p":["Babeira abundante e parar de comer.","Bolhas e úlceras na língua, gengivas e entre as unhas.","Mancadeira."]},{"h":"O que fazer","p":["Notifique imediatamente o serviço veterinário oficial: só o laboratório a distingue da aftosa.","Separe os animais doentes e dê comida macia e água.","Use luvas: também pode afetar as pessoas."]},{"h":"Prevenção","p":["Controle de insetos, que a transmitem.","Quarentena de animais novos."]}],"rel":["Febre aftosa e doenças exóticas","Doenças de notificação obrigatória","Quarentena e biossegurança"]},{"t":"Língua azul","a":"sanidad","r":"A língua azul é uma doença viral transmitida por mosquitos pequenos (maruins). No trópico americano o vírus circula, mas em bovinos quase sempre passa sem sintomas.","s":[{"h":"Em bovinos","p":["A maioria não adoece, mas carrega o vírus.","Os ovinos sim sofrem a doença grave.","Importa para exportar animais vivos ou sêmen."]},{"h":"O que fazer","p":["Controle criadouros de maruins: poças, esterco úmido.","Se tiver ovelhas por perto, pergunte ao veterinário sobre a vacinação."]}],"rel":["Doenças de notificação obrigatória","Moscas-dos-chifres e moscas-dos-estábulos"]},{"t":"Rinotraqueíte infecciosa bovina (IBR)","a":"sanidad","r":"A IBR é causada por um herpesvírus. No confinamento provoca doença respiratória com febre alta e abre a porta para pneumonias bacterianas.","s":[{"h":"Sinais","p":["Febre alta, focinho vermelho e inflamado, secreção nasal.","Tosse, olhos lacrimejantes e queda de consumo.","Pode causar abortos em fêmeas."]},{"h":"Prevenção","p":["Vacina respiratória que inclua IBR, com reforço conforme o rótulo.","Vacinar antes ou na chegada ao confinamento, com o animal tranquilo."]},{"h":"Dado","p":["O vírus fica escondido no animal para a vida toda e pode se reativar com estresse."]}],"rel":["Doenças virais respiratórias e BVD","Pneumonia ou complexo respiratório","Vacinação"]},{"t":"Animais persistentemente infectados (BVD)","a":"sanidad","r":"Alguns bezerros se infectaram com o vírus da diarreia viral bovina antes de nascer e o carregam a vida toda. Espalham o vírus sem parar e adoecem os demais do lote.","s":[{"h":"Como se forma","p":["A mãe se infecta nos primeiros meses de prenhez.","O bezerro nasce com o vírus e seu corpo não o reconhece como inimigo.","Costuma crescer pouco e adoecer com frequência."]},{"h":"Efeito no confinamento","p":["Um animal assim num lote aumenta as doenças respiratórias dos companheiros.","Baixa as defesas de todo o grupo."]},{"h":"O que fazer","p":["Existem testes de laboratório com amostra de orelha para detectá-los.","Se um animal é sempre o mais atrasado e doentio, pergunte ao veterinário pelo teste.","Vacina contra BVD na entrada."]}],"rel":["Doenças virais respiratórias e BVD","Animais atrasados","Sistema imune do bovino"]},{"t":"Sarna","a":"sanidad","r":"A sarna é causada por ácaros que vivem na pele. Provoca coceira intensa, queda de pelo e crostas. É mais comum em animais magros, amontoados e na época seca.","s":[{"h":"Sinais","p":["Esfregar-se em postes e cercas.","Áreas sem pelo, com crostas e pele grossa no pescoço, cauda e lombo.","Perda de peso em casos fortes."]},{"h":"O que fazer","p":["O veterinário confirma com um raspado de pele.","Tratamento com produtos para ácaros em todo o lote, não só nos que se coçam.","Limpe postes e cochos onde se esfregam."]}],"rel":["Problemas de pele","Vermifugação e resistência"]},{"t":"Tinha ou fungos da pele","a":"sanidad","r":"A tinha é uma infecção por fungos que forma manchas redondas, cinzentas e sem pelo, sobretudo na cara e no pescoço. Passa para outros animais e para as pessoas.","s":[{"h":"Sinais","p":["Círculos de 2 a 5 cm sem pelo e com crosta cinza.","Mais comum em animais jovens, em currais úmidos e com pouco sol."]},{"h":"O que fazer","p":["Costuma curar sozinha em semanas ou meses.","Produtos antifúngicos na pele aceleram a cura.","Use luvas e lave as mãos: passa para as pessoas."]}],"rel":["Problemas de pele","Doenças que passam para as pessoas"]},{"t":"Dermatofilose","a":"sanidad","r":"A dermatofilose é uma infecção de pele por uma bactéria que aproveita a umidade e as picadas de carrapatos. Forma crostas grossas como pincel.","s":[{"h":"Sinais","p":["Crostas duras com pelos grudados no lombo, pescoço e patas.","Ao retirá-las fica a pele úmida e vermelha.","Piora na época de chuvas."]},{"h":"O que fazer","p":["Separar e manter o animal seco.","Tratamento antibiótico indicado pelo veterinário em casos extensos.","Controle de carrapatos."]}],"rel":["Problemas de pele","Carrapatos","Época de chuvas"]},{"t":"Vermes pulmonares","a":"sanidad","r":"Alguns vermes vivem nos brônquios e causam tosse e pneumonia. São mais comuns em animais jovens em pastos úmidos.","s":[{"h":"Sinais","p":["Tosse seca, sobretudo ao movimentar os animais.","Respiração rápida e perda de peso.","Vários animais jovens do mesmo pasto afetados."]},{"h":"O que fazer","p":["O veterinário confirma com exame de fezes especial.","A maioria dos vermífugos de amplo espectro os controla."]}],"rel":["Parasitas internos","Pneumonia ou complexo respiratório"]},{"t":"Intoxicação por chumbo","a":"sanidad","r":"O chumbo de baterias velhas, tinta e óleo queimado é uma das intoxicações mais comuns em bovinos, porque são curiosos e lambem tudo.","s":[{"h":"Sinais","p":["Cegueira, animal que bate em objetos.","Tremores, ranger de dentes, espuma na boca.","Convulsões e morte rápida."]},{"h":"O que fazer","p":["Chame o veterinário imediatamente.","Procure e retire a fonte: baterias, latas de tinta, óleo de motor."]},{"h":"Prevenção","p":["Nunca deixe baterias nem sucata em pastos ou currais.","Revise os lugares onde se queimou lixo."]}],"rel":["Intoxicação por plantas e fungos","Manutenção de instalações"]},{"t":"Intoxicação por agrotóxicos","a":"sanidad","r":"Carrapaticidas, inseticidas e herbicidas mal usados podem intoxicar o gado. Os organofosforados são os mais perigosos.","s":[{"h":"Sinais","p":["Babeira, lacrimejamento, diarreia e urinar muito.","Tremores musculares, pupilas pequenas e dificuldade para respirar."]},{"h":"O que fazer","p":["Chame o veterinário: existe antídoto para organofosforados.","Lave com água e sabão se foi um banho.","Guarde o rótulo do produto."]},{"h":"Prevenção","p":["Meça bem a dose e não misture produtos.","Não banhe animais com calor forte nem estressados.","Não paste em pastos recém-pulverizados antes do tempo indicado."]}],"rel":["Bom uso de agrotóxicos","Carrapatos","Intoxicação por plantas e fungos"]},{"t":"Intoxicação por sal e falta de água","a":"sanidad","r":"Quando os animais passam muitas horas sem água e depois bebem de uma vez, ou comem muito sal sem água, podem sofrer dano cerebral.","s":[{"h":"Sinais","p":["Animais cegos, que andam em círculos ou pressionam a cabeça contra a parede.","Convulsões depois de voltar a beber água."]},{"h":"O que fazer","p":["Dê água aos poucos a animais que passaram muito tempo sem beber.","Chame o veterinário."]},{"h":"Prevenção","p":["Água sempre disponível, sobretudo com rações salgadas.","Revise bombas, boias e canos todos os dias."]}],"rel":["Água de bebida","Bebedouros","Desidratação e soros"]},{"t":"Morte súbita: possíveis causas","a":"sanidad","r":"Encontrar um animal morto sem tê-lo visto doente assusta. As causas mais comuns são poucas e o veterinário pode identificá-las com uma necropsia.","s":[{"h":"Causas mais frequentes","p":["Doenças clostridiais (carbúnculo sintomático, enterotoxemia).","Timpanismo ou acidose aguda.","Antraz (carbúnculo hemático): não abra o cadáver.","Intoxicações: plantas, nitratos, ureia, chumbo.","Raios, golpe de calor, picada de cobra."]},{"h":"O que fazer","p":["Se sai sangue escuro pelo nariz, boca ou ânus e o corpo não fica rígido, suspeite de antraz: não abra e chame o veterinário oficial.","Nos outros casos, peça uma necropsia no mesmo dia.","Revise os demais animais e a comida do dia."]},{"h":"No seu confinamento","p":["Registre cada morte no app com a causa.","Várias mortes seguidas: pare as mudanças de ração e chame o veterinário."]}],"rel":["Morte de um animal","Doenças clostridiais","Antraz (carbúnculo hemático)","Timpanismo (rúmen inchado)"]},{"t":"Metafilaxia na entrada","a":"sanidad","r":"A metafilaxia é tratar com antibiótico todo um lote de alto risco na chegada, antes que adoeçam. Reduz a pneumonia, mas deve ser usada com critério para não criar resistência.","s":[{"h":"Quando se justifica","p":["Animais leves, recém-desmamados, de leilão e de várias origens.","Viagens longas e animais muito estressados.","Histórico de muitos doentes em lotes parecidos."]},{"h":"Quando não","p":["Animais pesados, de uma só origem, pré-condicionados e vacinados.","Como costume em todos os lotes."]},{"h":"No seu confinamento","p":["Decida com seu veterinário conforme o risco de cada compra.","Registre o tratamento e sua carência no app."]}],"rel":["Uso responsável de antibióticos","Recepção de gado","Pneumonia ou complexo respiratório","Desmame e pré-condicionamento"]},{"t":"Tristeza parasitária","a":"sanidad","r":"Chama-se tristeza parasitária o conjunto de anaplasmose e babesiose, duas doenças do sangue transmitidas por carrapatos e insetos. Matam animais adultos que chegam de regiões sem carrapatos.","s":[{"h":"Sinais","p":["Febre alta, abatimento e parar de comer.","Mucosas pálidas ou amarelas.","Urina escura na babesiose.","Animal agressivo ou que cai nos casos graves."]},{"h":"Quem está em risco","p":["Animais trazidos de regiões altas ou frias sem contato prévio.","Animais de raças europeias.","Lotes estressados com muitos carrapatos."]},{"h":"O que fazer","p":["Chamar o veterinário: o tratamento é diferente para cada uma.","Não tocar nem estressar o animal doente.","Controle de carrapatos e moscas."]}],"rel":["Anaplasmose","Babesiose (tristeza parasitária)","Carrapatos"]},{"t":"Protocolo de tratamento","a":"sanidad","r":"Um protocolo é um plano escrito, feito com o veterinário, que diz o que fazer com cada doença comum: qual produto, que dose, quantos dias e quando mudar se não melhorar.","s":[{"h":"O que inclui","p":["Como reconhecer a doença.","Primeiro tratamento e dose por peso.","O que fazer se não melhorar em 2 a 3 dias.","Carência para a venda."]},{"h":"Benefícios","p":["Todos na fazenda tratam igual.","Menos uso desnecessário de antibióticos.","Registros claros para compradores."]},{"h":"No seu confinamento","p":["Peça ao seu veterinário um protocolo para pneumonia, diarreia, mancadeira e anaplasma.","Anote cada tratamento no app."]}],"rel":["Uso responsável de antibióticos","Curral de doentes","Receita e uso de medicamentos veterinários"]},{"t":"Eutanásia humanitária","a":"sanidad","r":"Quando um animal sofre sem possibilidade de se recuperar, a decisão correta é terminar sua vida sem dor. Deve ser feita por um veterinário ou uma pessoa treinada.","s":[{"h":"Quando considerar","p":["Fraturas graves de patas.","Animal caído que não se levanta depois do tratamento.","Doença sem cura com muita dor."]},{"h":"Como fazer bem","p":["Com métodos aprovados e pessoal preparado.","Nunca deixar o animal sofrer por dias.","Dar destino ao cadáver conforme as normas."]}],"rel":["Animal caído que não se levanta","Morte de um animal","Bem-estar animal"]},{"t":"Calendário sanitário do confinamento","a":"sanidad","r":"Um calendário organiza vacinas, vermifugações e revisões desde a chegada até a venda, e evita esquecimentos e carências em cima da venda.","s":[{"h":"Na entrada","p":["Vacina clostridial e respiratória conforme o risco.","Vermifugação conforme exames.","Vitaminas A, D e E.","Controle de carrapatos e moscas."]},{"h":"Semana 3 a 4","p":["Reforço de vacinas.","Revisão de animais atrasados."]},{"h":"Durante o confinamento","p":["Controle de carrapatos conforme a carga.","Revisão diária e pesagens periódicas."]},{"h":"Antes de vender","p":["Verifique que nenhum tratamento esteja em carência.","O app avisa dos lotes em carência."]}],"rel":["Plano sanitário de entrada","Vacinação","Agenda de tarefas","Carências e resíduos"]},{"t":"Doenças por época do ano","a":"sanidad","r":"Cada época traz seus problemas. Preparar-se antes baixa as perdas.","s":[{"h":"Época seca","p":["Deficiência de vitamina A e de proteína.","Poeira e pneumonias.","Intoxicações por plantas que ficam verdes."]},{"h":"Início das chuvas","p":["Aumentam carrapatos, moscas e berne.","Timpanismo com pastos novos.","Clostridioses com mudanças de pasto."]},{"h":"Chuvas fortes","p":["Mancadeiras, problemas de pele, parasitas e fascíola.","Leptospirose por água parada."]},{"h":"Veranico e ondas de calor","p":["Estresse por calor e golpe de calor.","Queda de consumo."]}],"rel":["Época seca","Época de chuvas","Estresse por calor","Calendário sanitário do confinamento"]},{"t":"Biossegurança para visitas e veículos","a":"sanidad","r":"As doenças entram na fazenda em botas, pneus, caminhões e animais de fora. Umas regras simples fecham a porta.","s":[{"h":"Regras","p":["Caminhões de gado ficam fora dos currais quando possível.","Pedilúvio ou lavagem de botas na entrada.","Visitantes que vêm de outras fazendas ou frigoríficos não entram nos currais sem roupa limpa."]},{"h":"Animais","p":["Quarentena de 2 a 3 semanas para todo animal novo.","Cães e aves de outras fazendas longe da comida."]}],"rel":["Quarentena e biossegurança","Pedilúvio","Animais de leilão"]}];
